window.WORD_MNEMONICS_DB = window.WORD_MNEMONICS_DB || {};
Object.assign(window.WORD_MNEMONICS_DB, {
  "sack": "諧音聯想：\n諧音：「塞客」\n\n聯想畫面 1：老闆把米糧通通塞進一個大麻布袋裡。\n\n聯想畫面 2：員工表現太差直接被老闆塞客（Sack），也就是開除解僱。\n\n高效擴充：get the sack 是英國慣用語，意指「被開除」。\nKK 音標：[sæk] -> 扁平的 a 音，嘴巴左右拉開，尾音 k 輕輕爆破。\n\n常見同義字：\nbag（較通用的袋子、包包）\nfire（解僱、開除，最常用動詞）\ndismiss（正式開除、解散）",
  "sacred": "諧音聯想：\n諧音：塞克瑞德 -> 諧音聯想：塞進克難的瑞典神聖聖物。\n\n聯想畫面 1：牧師把神聖的十字架小心翼翼地塞進瑞典木盒裡。\n\n聯想畫面 2：印度人將牛視為神聖不可侵犯的動物。\n\n高效擴充：字根 sacr 代表神聖。\nKK 音標：[ˋsekrəd] -> 重音在第一音節，se 發短音 e，krəd 輕聲帶過。\n\n常見同義字：\n\nholy（常用於宗教場合的聖潔）\n\ndivine（神聖的、通常指神的）\n\nconsecrated（奉獻的、祝聖過的）",
  "sacrifice": "諧音聯想：\n諧音：「殺克死」\n\n聯想畫面 1：古代戰士為了保衛部落，勇敢上戰場殺敵，不惜犧牲自己的生命。\n\n聯想畫面 2：為了買房子，夫妻倆每天省吃儉用，獻出所有的娛樂作為金錢上的犧牲。\n\n高效擴充：由sacred（神聖的）加上fice（做），原意是把東西做成神聖的祭品獻給神。\nKK 音標：[ˋsækrə͵faɪs] -> 主重音在sæ上，ice發ice的音，注意字尾s清音。\n\n常見同義字：\ngive up（放棄，口語常用）\nofferings（祭品、供品）\n放弃（martyrdom 殉難、為信仰犧牲）",
  "sad": "諧音聯想：\n諧音：「歇斯底里」的歇\n\n聯想畫面 1：聽到寵物過世的消息後，他難過得坐在沙發上默默流淚，心情非常低落。\n\n聯想畫面 2：這部催淚的電影劇情實在太悲傷了，散場時許多觀眾都哭紅了雙眼。\n\n高效擴充：基本情緒形容詞，與 happy 相反，常搭配 look sad 或 feel sad。\nKK 音標：[sæd] -> 發扁平的短母音 [æ]，嘴巴張大，尾音 [d] 輕收。\n\n常見同義字：\nunhappy（不高興的、悲傷的，最常見的日常情緒詞）\nsorrowful（悲傷的、令人傷心的，帶有較深沉的哀傷感）\ndepressed（沮喪的、憂鬱的，強調心理狀態低落消沉）",
  "sadden": "諧音聯想：\n諧音：賽登\n\n聯想畫面 1：比賽登台領獎卻被取消資格，這件事使他非常悲傷。\n\n聯想畫面 2：看到老朋友離別的背影，這畫面使我感到一陣難過。\n\n高效擴充：sad 是悲傷的，加上 en 變成動詞，表示使某人進入悲傷狀態。\nKK 音標：[ˋsædən] -> 重音在第一音節 sad，發音時嘴巴張開，d 的音要短促。\n\n常見同義字：\nupset（使心煩，程度較輕）\ndepress（使沮喪，程度較深）\ndisappoint（使失望，針對期望落空）",
  "saddle": "諧音聯想：\n諧音：「殺豬的」\n\n聯想畫面 1：殺豬的伯伯騎著馬，馬背上牢牢繫著一個皮製馬鞍（saddle）。\n\n聯想畫面 2：自行車騎士調整了一下車座（saddle）的高度，準備開始騎長途。\n\n高效擴充：常作為動詞片語 saddle with，意指「使某人承擔沉重的負擔」。\nKK 音標：[ˋsædəl] -> 重音在 sæ，dəl 要輕輕收尾。\n\n常見同義字：\nseat（座位，泛指各種椅凳）\npillion（後馬鞍，坐在騎士後方的座位）\nharness（馬具、車具，涵蓋範圍更大的裝備）",
  "sadly": "諧音聯想：\n諧音：賽得離\n\n聯想畫面 1：比賽得第一名卻要離開隊友，他悲傷地流下眼淚。\n\n聯想畫面 2：令人遺憾地，這項計畫因為經費不足而被迫中止。\n\n高效擴充：sad 是悲傷，加上 ly 變成副詞，修飾動作或整句語氣。\nKK 音標：[ˋsædli] -> 重音在第一音節 sad，結尾的 ly 唸輕一點。\n\n常見同義字：\nunhappily（不快樂地，強調心情）\nregrettably（令人遺憾地，強調語氣）\nsorrowfully（悲痛地，強調情感深度）",
  "sadness": "諧音聯想：\n拆解：sad 傷心的 + ness 名詞字尾 -> 悲傷、悲哀\n\n聯想畫面 1：聽到寵物離世的消息，她臉上流露出掩不住的無比悲傷與痛苦。\n\n聯想畫面 2：這部催淚電影結局充滿了遺憾，讓電影院裡的觀眾充滿悲哀的情緒。\n\n高效擴充：由形容詞 sad 加上名詞字尾 ness，用來表達抽象的情感狀態。\nKK 音標：[ˋsædnəs] -> 主重音在第一音節 sad，後面的 ness 要輕短。\n\n常見同義字：\nsorrow（悲傷、哀痛，文學色彩較濃）\ngrief（極度的悲痛，通常指因親友離世）\nunhappiness（不快樂，較為日常口語）",
  "safe": "諧音聯想：\n諧音：「誰飛」\n\n聯想畫面 1：飛機遭遇亂流時，大家都繫好安全帶確保平安無事。\n\n聯想畫面 2：公司把重要現金和機密文件鎖進厚重的保險箱裡才安心。\n\n高效擴充：字尾的 e 讓前面的 a 發長雙母音 [e]，常見同字根有 save（拯救）。\nKK 音標：[sef] -> 雙唇微開念長音 e，最後閉合上下唇發清脆的 f 音。\n\n常見同義字：\n\nsecure（強調免於威脅或攻擊的穩固安全，較正式）\n\nharmless（無害的，指不會對人體或物品造成傷害）\n\nvault（地下金庫或大型保險庫，強調堅固防盜）",
  "safeguard": "諧音聯想：\n拆解 / 諧音：「safe（安全）＋ guard（守衛）」\n\n聯想畫面 1：保全人員在門口做好嚴密的安全守衛，成為保障大家生命財產的絕佳措施。\n\n聯想畫面 2：政府推出新的法令來保護弱勢團體，就像幫他們加上一層堅固的護衛網。\n\n高效擴充：由 safe 安全與 guard 防衛兩個基礎單字組合而成，字義直觀好記。\nKK 音標：[ˋsef͵ɡɑrd] -> safe 重音在前半部，guard 的 a 發長音。\n\n常見同義字：\nprotect（保護，較一般的動詞）\ndefend（防衛，強調抵禦攻擊）\nshield（庇護，像盾牌一樣擋住傷害）",
  "safety": "諧音聯想：\n諧音：「謝費提」供了這麼完善的「安全」措施，讓大家工作時很放心。\n\n聯想畫面 1：工廠工人上工前必須戴好安全帽以確保自身安全。\n\n聯想畫面 2：這座公園環境單純，是居民散步的安全場所。\n\n高效擴充：由形容詞 safe（安全的）加上名詞字尾 -ty 組合而成。\nKK 音標：[ˋsefti] -> 第一音節 ˋsef 是主重音，ty 發輕短的 ti 音。\n\n常見同義字：\n\nsecurity（安全、保全，強調防範外在威脅）\n\nprotection（保護、防衛）\n\nshelter（避難所、庇護所）",
  "sail": "諧音聯想：\n諧音：「誰餓」\n\n聯想畫面 1：大船揚起白色的帆準備啟航出海，船長問水手誰餓了可以先去吃早餐。\n\n聯想畫面 2：海鷗在海面上輕輕飄過，伴隨著遠方帆船的航行身影。\n\n高效擴充：母音組合 ai 發長音 [e]，常與 sea（海洋）字彙聯想記憶。\nKK 音標：[sel] -> 先發長音 se 再將舌尖抵住上齒齦發清晰的 l 音。\n\n常見同義字：\n\nnavigate（導航、航行，強調使用儀器規劃路線）\n\ncruise（乘船遊覽、巡航，偏向休閒度假性質）\n\nvoyage（漫長的海上或太空航行，多指壯遊）",
  "sailor": "諧音聯想：\n諧音：「色勒」著強風出海的「水手」，在甲板上熟練地操控著風帆。\n\n聯想畫面 1：大郵輪靠岸時，水手們忙著將纜繩繫在碼頭的柱子上。\n\n聯想畫面 2：老水手坐在酒館裡向大家訴說他航海的傳奇故事。\n\n高效擴充：由名詞 sail（帆、航行）加上 -er/or 字尾表示從事該職業的人。\nKK 音標：[ˋselɚ] -> 第一音節 ˋsel 是重音，ɚ 輕念。\n\n常見同義字：\n\nseaman（海員、水手）\n\nmariner（水手、航海家，較具文學色彩）\n\ncrewman（船員）",
  "saint": "諧音聯想：\n諧音：「聖人」\n\n聯想畫面 1：這位慈悲為懷的老修女簡直就像個活生生的聖人（saint）。\n\n聯想畫面 2：教堂裡供奉著古代聖徒（saint）的雕像，信徒們正在虔誠祈禱。\n\n高效擴充：地名常見字首 St. 就是這個字的縮寫，如 St. Paul。\nKK 音標：[sent] -> 鼻音 en 延伸，t 輕收尾。\n\n常見同義字：\nholy person（聖潔的人，白話描述）\nangel（天使，形象純潔）\nbenefactor（恩人、捐助人，偏向實質貢獻）",
  "sake": "諧音聯想：\n諧音：「謝客」\n\n聯想畫面 1：店家為了安全起見的緣故，今天提早謝客休息。\n\n聯想畫面 2：為了大家的利益著想，他決定退一步海闊天空。\n\n高效擴充：常見片語為 for the sake of（為了……的緣故）。\nKK 音標：[sek] -> 長母音 a 的發音，由 e 滑向 i 的雙母音感覺。\n\n常見同義字：\nreason（理由、原因）\nbenefit（利益、好處）\npurpose（目的、意圖）",
  "salad": "諧音聯想：\n諧音：冰箱裡「些賴的」幾片新鮮生菜，剛好可以做一盤好吃的「沙拉」。\n\n聯想畫面 1：減肥中的她午餐只吃一碗淋了油醋醬的綜合沙拉。\n\n聯想畫面 2：牛排上桌旁邊總是會附上一小堆生菜沙拉解膩。\n\n高效擴充：外來語音譯，字尾 d 發清脆的輕聲。\nKK 音標：[ˋsæləd] -> 第一音節 ˋsæled 是重音，æl 發開口笑的音。\n\n常見同義字：\n\ngreens（綠葉蔬菜、生菜沙拉）\n\nslaw（涼拌高麗菜沙拉，如 coleslaw）\n\nappetizer（開胃菜）",
  "salary": "諧音聯想：\n諧音：「殺來力」\n\n聯想畫面 1：月底領到薪水的那一刻，上班族立刻充滿殺來力（拼命購物的動力）去血拚。\n\n聯想畫面 2：每個月固定的薪金入帳，是支撐大家繼續上班的最大動力來源。\n\n高效擴充：字尾ary為名詞或形容詞字尾，注意與celery（芹菜）拼法不同但發音微調類似。\nKK 音標：[ˋsælɚi] -> 主重音在sæl上，l要念得清脆，後面接ɚ-i輕聲。\n\n常見同義字：\nwage（薪資，通常指按時計酬的工錢）\nincome（收入，泛指所有進帳）\npay（薪水、報酬，最通俗說法）",
  "sale": "諧音聯想：\n諧音：「塞而」\n\n聯想畫面 1：百貨公司週年慶大特價，人潮把門口塞而（塞滿）搶購便宜貨。\n\n聯想畫面 2：老闆把滯銷商品全部賤賣出清，清空倉庫才不會塞而（塞住）走道。\n\n高效擴充：字尾加 s 變成 sales（業務、銷售額），注意不要跟 sell（賣）搞混。\nKK 音標：[sel] -> 單音節字，嘴巴咧開念長音 e，發音俐落清脆。\n\n常見同義字：\n\ndiscount（指折扣、打折，通常指降價行為）\n\nclearance（指清倉大拍賣，強調為了出清存貨）\n\npromotion（指促銷活動，涵蓋範圍較廣）",
  "sales": "諧音聯想：\n諧音：誰（sa）- 勒（les）。\n\n聯想畫面 1：百貨公司在特價，大家都在問誰（sales）買了最多？\n\n聯想畫面 2：他在銷售（sales）部門工作，業績很好。\n\n高效擴充：sale 是銷售，複數 sales 常指銷售部門或促銷。\nKK 音標：[ˋseɪlz] -> 重音在第一音節，注意 z 的震動音。\n\n常見同義字：\n\nselling（銷售）\n\ndiscount（折扣）\n\nmarketing（行銷）。",
  "salesman": "諧音聯想：\n諧音：「銷死人」\n\n聯想畫面 1：這位男推銷員口才好到業績銷售死人（多到誇張），產品一下子就賣光。\n\n聯想畫面 2：百貨公司專櫃的男售貨員，正熱情地向顧客介紹最新款的男裝。\n\n高效擴充：由sale（銷售）加上man（男人），複數形為salesmen。\nKK 音標：[ˋselzmən] -> 主重音在sel上，z音要出來，man念輕聲的mən。\n\n常見同義字：\nsalesperson（銷售員，中性詞）\nvendor（小販、供應商）\nrepresentative（業務代表，較正式）",
  "salespeople": "拆解：sales（銷售）+ people（人）。\n\n聯想畫面 1：百貨公司週年慶，一群推銷員忙著向顧客介紹商品。\n\n聯想畫面 2：他在展場遇到一群熱情的售貨員，每個人都想推銷自己的產品。\n\n高效擴充：salesperson 的複數，將 son 改為 people 即可。\nKK 音標：重音在第一個音節 sales，people 的 ple 輕讀。\n\n常見同義字：\n\nclerks（店員）\n\nvendors（小販）\n\nrepresentatives（銷售代表）。",
  "salesperson": "諧音聯想：\n諧音：「銷死怕生」\n\n聯想畫面 1：這位優秀的店員克服了個性怕生的缺點，努力推銷商品，銷售業績嚇嚇叫。\n\n聯想畫面 2：賣場裡男男女女的銷售員穿著制服，隨時準備協助顧客找尋商品。\n\n高效擴充：結合sale、person（人），是現在最常用的性別中立（gender-neutral）職稱。\nKK 音標：[ˋselz͵pɝsən] -> 主重音在selz上，person中的ɝ發捲舌音。\n\n常見同義字：\nsalesclerk（店員、店員，尤指零售業）\nretailer（零售商）\nassociate（銷售夥伴、專員，美式常用尊稱）",
  "saleswoman": "諧音聯想：\n諧音：「銷死挖們」\n\n聯想畫面 1：女推銷員大喊銷死挖們（快把錢挖出來給我），成功賣出好幾組保養品。\n\n聯想畫面 2：專櫃前親切的女售貨員，正細心地幫客人挑選適合的尺寸。\n\n高效擴充：由sale與woman組成，複數形為saleswomen（注意women的e發音）。\nKK 音標：[ˋselz͵wʊmən] -> 主重音在selz上，wʊmən發音為「烏們」。\n\n常見同義字：\nsalesperson（中性銷售員）\nfemale clerk（女店員）\nretail worker（零售業員工）",
  "salient": "諧音聯想：\n諧音：「誰黏著」\n\n聯想畫面 1：報告中最重要的重點最顯眼，就像是誰黏著（salient）螢光筆一樣一眼就看到。\n\n聯想畫面 2：這個突出的建築設計在整排平房裡特別顯著，讓人無法忽視。\n\n高效擴充：源自拉丁文字根，指跳出來、顯現的，常用於 salient points（要點、顯著觀點）。\nKK 音標：[ˋseɪliənt] -> 主重音在第一音節的雙母音seɪ，唸「謝-利-安特」。\n\n常見同義字：\nprominent（突出的，顯著的，常形容地形或地位）\nnoticeable（顯而易見的，容易被注意到的）\nstriking（引人注目的，外觀或特質極為鮮明）",
  "salmon": "諧音聯想：\n諧音：「殺門」\n\n聯想畫面 1：日本料理長師傅在店門口俐落地切開新鮮的鮭魚（salmon）。\n\n聯想畫面 2：肥美的鮭魚（salmon）為了產卵，正逆流而上跳過瀑布。\n\n高效擴充：注意拼法中 l 是不發音的（sal-mon），千萬別把 l 讀出來。\nKK 音標：[ˋsæmən] -> 重音在 sæ，mon 念輕聲 mən。\n\n常見同義字：\ntrout（鱒魚，與鮭魚同科的美味淡水魚）\nseafood（海鮮，統稱各類水產）\nfish（魚類的總稱）",
  "saloon": "諧音聯想：\n諧音：「殺戮」的諧音聯想\n\n聯想畫面 1：西部牛仔電影裡，主角們常在充滿爭奪與殺戮氣息的酒館裡發生槍戰。\n\n聯想畫面 2：豪華郵輪上有個寬敞的大廳，提供旅客舒適的休憩與社交空間。\n\n高效擴充：注意別與 salon（沙龍、美髮廳）拼字搞混，這裡多了一個 o。\nKK 音標：[səˋlun] -> 重音落在第二音節 loon，發長音 u 聲。\n\n常見同義字：\npub（小酒館，常指英國風格）\nbar（酒吧，較現代的稱呼）\nlounge（休息室、大廳）",
  "salt": "諧音聯想：\n諧音：「搜嘔吐」\n\n聯想畫面 1：廚師煮菜時不小心手滑加太多鹽巴，鹹到讓人吃一口就搜嘔吐（想吐）。\n\n聯想畫面 2：海水非常鹹，不小心喝到一口就會鹹到搜嘔吐（想吐）。\n\n高效擴充：形容詞是 salty（鹹的），常拿來形容人講話酸溜溜或生氣。\nKK 音標：[sɔlt] -> o 發短音 ɔ，唸法低沉帶點鼻音，l 不發音明顯。\n\n常見同義字：\n\nsalty（形容詞，意為鹹的、重口味的）\n\nseasoning（名詞，指調味料、佐料的統稱）\n\nsodium（名詞，指鈉，常與食鹽成分相關）",
  "salty": "諧音聯想：\n諧音：「燒梯」\n\n聯想畫面 1：把鹽巴撒在燃燒的梯子上，整個空氣中都充滿了有鹽分的鹹味。\n\n聯想畫面 2：廚師不小心手滑加太多鹽，整碗湯變得很鹹。\n\n高效擴充：由名詞 salt（鹽）加上 y 形成形容詞，網路用語也常指生氣或嫉妒。\nKK 音標：[ˋsɔlti] -> 第一音節重音，salt 發 ɔl 的音。\n\n常見同義字：\n\nsaltish（略帶鹹味的）\n\nbriny（鹹的、海水的）\n\nsavory（美味的、鹹香的）",
  "salute": "諧音聯想：\n諧音：「省露圖」，軍人行軍禮致敬時，常為了省下看露天戰略圖的時間而向長官敬禮。\n\n聯想畫面 1：士兵在烈日下向國旗舉手行軍禮致敬，展現高度榮譽感。\n\n聯想畫面 2：頒獎典禮上全場起身鼓掌，向得獎者的傑出成就表達由衷讚揚與致意。\n\n高效擴充：字首 sal- 有健康、安全之意，延伸出向安全守護者致敬的聯想。\nKK 音標：[səˋlut] -> 重音在第二音節 lut，發長音 u，嘴型要縮小向前嘟起。\n\n常見同義字：\n\nhonor（表尊敬與榮譽，通常用於正式場合或頒獎）\n\ngreet（打招呼與問候，語氣較生活化）\n\npraise（讚揚與表揚，強調口頭上的稱讚）",
  "salvage": "諧音聯想：\n諧音：搜救至\n\n聯想畫面 1：搜救至沉船現場，潛水員努力打撈出珍貴的貨物。\n\n聯想畫面 2：在火災後的廢墟中，他試圖搶救出僅存的家庭相簿。\n\n高效擴充：字根 salv 有救助的意思，類似 save 的拼寫記憶。\nKK 音標：[ˋsælvədʒ] -> 重音在第一音節 sal，結尾的 ge 發出輕微的 j 音。\n\n常見同義字：\nrescue（營救，強調救人）\nrecover（恢復或找回，強調取回）\nretrieve（取回，強調從某處拿回）",
  "salvation": "諧音聯想：\n拆解 / 諧音：「save（拯救）的延伸字」\n\n聯想畫面 1：在荒島上漂流多日後終於看見救援船隻，這簡直是上天賜予的拯救與救星。\n\n聯想畫面 2：絕望中的一線生機成為心靈的解救物，讓人重新找回對生活的希望。\n\n高效擴充：由動詞 save 變化而來，字尾 tion 為名詞字尾。\nKK 音標：[sælˋveʃən] -> 重音落在 ve 節，shon 輕輕帶過。\n\n常見同義字：\nredemption（贖罪、拯救，具宗教感）\ndeliverance（解救、獲得自由）\nlifeline（生命線、救命繩索）",
  "same": "諧音聯想：\n諧音：「誰麼」\n\n聯想畫面 1：看到兩個人穿著「一模一樣的」衣服，你忍不住問：「誰麼」時候買了同款？\n\n聯想畫面 2：這兩家飲料店的味道「完全相同」，真不知道「誰麼」才是真正的老店。\n\n高效擴充：前面習慣加上定冠詞 the 形成 the same，代表「同一個」或「相同的」。\nKK 音標：[sem] -> 單音節字，a-e 結構發長母音 [e]，字尾 m 嘴唇要閉合。\n\n常見同義字：\nidentical（一模一樣的、完全相同的，語氣較嚴謹）\n\nequal（相等的、同等的，常用於數量或權利）\n\nalike（相似的、相同的，通常放在句尾作表語）",
  "sami": "諧音聯想：\n諧音：撒米。\n\n聯想畫面 1：在北歐的雪地裡，薩米人撒米餵馴鹿，這是他們傳統的生活方式。\n\n聯想畫面 2：Sami 是北歐原住民，他們擁有獨特的文化與語言。\n\n高效擴充：注意 Sami 也可以拼作 Saami，指代北歐原住民。\nKK 音標：無 -> 重音在第一個音節，唸起來要輕快。\n\n常見同義字：\n\nLapp（舊稱，現多視為貶義）\n\nindigenous people（原住民，正式用語）。",
  "sample": "諧音聯想：\n諧音：「省跑」\n\n聯想畫面 1：藥妝店老闆為了省去客人來回跑的麻煩，大方發送試用包樣本。\n\n聯想畫面 2：你在超市品嚐了一口免費的蛋糕試吃樣品，覺得很好吃。\n\n高效擴充：源自古法語，常與 free sample 一起記，指免費樣品。\nKK 音標：[ˋsæmpəl] -> 第一音節重音，念短促的 æ，尾音念軟軟的 pəl。\n\n常見同義字：\n\nexample（例子，指具體範例）\n\nspecimen（標本，常指科學或醫學用途）\n\npattern（模式，指可供仿效的樣式）",
  "sanction": "諧音聯想：\n諧音：「刪去選項」\n\n聯想畫面 1：國際組織對違規國家祭出經濟制裁與處罰，直接把對方的貿易往來資格刪去選項。\n\n聯想畫面 2：主管終於點頭同意並正式認可這份企劃案，讓專案得以順利執行。\n\n高效擴充：這個字同時具有相反的詞義，既可指「制裁處罰」，也可指「官方許可」，需依上下文判斷。\nKK 音標：[ˋsæŋkʃən] -> 重音在第一音節 sæŋk，注意鼻音。\n\n常見同義字：\npenalty（懲罰、罰款）\napproval（批准、認可，用於正面授權）\nembargo（禁運、貿易制裁）",
  "sanctuary": "諧音聯想：\n諧音：「三區去抓綠（動物）」\n\n聯想畫面 1：保育人士在山林劃分出三區去保護野生動物，這裡成了動物安全的庇護所。\n\n聯想畫面 2：古老的教堂內部氣氛莊嚴神聖，是逃難者尋求庇護權的聖所。\n\n高效擴充：字根 sanct 代表神聖，與 saint（聖人）同源。\nKK 音標：[ˋsæŋktʃu͵ɛri] -> 重音在第一音節 sæŋk，後面氣音要輕。\n\n常見同義字：\nrefuge（避難所，強調逃離危險）\nshelter（收容所、避難處）\nreserve（保護區、預留地）",
  "sanctum": "諧音聯想：\n諧音：三克湯（三克重的湯）\n\n聯想畫面 1：這間密室是教授的書房，任何人不得進入，這是他的 sanctum。\n\n聯想畫面 2：寺廟內部的至聖所，只有高僧才能進入，充滿神聖感。\n\n高效擴充：源自拉丁語 sanctus（神聖的），指神聖不可侵犯的地方。\nKK 音標：[ˋsæŋktəm] -> 重音在第一音節，唸起來像「三克-騰」。\n\n常見同義字：\nsanctuary（聖殿，避難所）\nprivate room（私室，強調隱私）\ninner sanctum（至聖所，強調最核心的密室）",
  "sand": "諧音聯想：\n諧音：「散的」\n\n聯想畫面 1：海灘上的沙子一顆顆都是散的，無法像石頭一樣黏在一起。\n\n聯想畫面 2：風一吹過來，沙地上的沙子全被吹得散的（四處飛揚）。\n\n高效擴充：字尾加 y 變成 sandy（多沙的、沙質的），常形容沙灘。\nKK 音標：[sænd] -> 夾在中間的 æ 發扁桃音，嘴巴張大橫開。\n\n常見同義字：\n\nbeach（指海灘、沙灘，常與沙子聚集地連用）\n\ndust（指灰塵或細粉末，質地比沙更細）\n\ngrit（指粗砂、砂礫，強調堅毅或粗糙質感）",
  "sandal": "諧音聯想：\n諧音：「傘的洞」，夏天穿的涼鞋透風性極佳，就像雨傘破了洞一樣通風。\n\n聯想畫面 1：夏天穿著涼鞋去海邊漫步，腳丫子踩在沙灘上非常清涼。\n\n聯想畫面 2：古羅馬人腳上綁著簡單的皮拖鞋，走起路來啪噠啪噠響。\n\n高效擴充：結尾 -dal 與 sandal 的拖鞋造型聯想，注意拼字別漏掉 n。\nKK 音標：[ˋsændəl] -> 重音在第一音節 san，短音 a 唸扁，dal 要輕聲帶過。\n\n常見同義字：\n\nslipper（室內拖鞋，通常較保暖柔軟）\n\nflip-flops（夾腳拖鞋，海邊常見的休閒鞋款）\n\nshoe（泛指一般鞋子，較 sandal 包覆性完整）",
  "sandwich": "諧音聯想：\n諧音：「三明治」\n\n聯想畫面 1：早上趕著上班，隨手拿了一個火腿蛋三明治塞進嘴裡。\n\n聯想畫面 2：開會時大家意見分歧，你被夾在主管和客戶中間，就像三明治一樣動彈不得。\n\n高效擴充：源自英國三明治伯爵的名字，當動詞用時指把東西夾在中間。\nKK 音標：[ˋsændwɪtʃ] -> 重音在第一音節，d 不發音，wɪtʃ 念威奇。\n\n常見同義字：\n\nburger（漢堡，常用快餐類食品）\n\nsub（潛艇堡，指長形三明治）\n\nwrap（捲餅，用薄餅皮包夾的食物）",
  "sane": "諧音聯想：\n諧音：「醒」\n\n聯想畫面 1：經過冰水洗臉後，他終於清醒過來，恢復神志正常。\n\n聯想畫面 2：在混亂的爭吵中，只有他維持頭腦清楚與理智。\n\n高效擴充：與 insane（瘋狂的）相反，去掉前綴 in 即為正常。\nKK 音標：[sen] -> 單音節長音，a 發 a 的長音並收尾在 n。\n\n常見同義字：\nrational（理性的，合乎邏輯的）\nreasonable（講道理的，合理的）\nsensible（明智的，有判斷力的）",
  "sanitary": "諧音聯想：\n諧音：三尼特瑞\n\n聯想畫面 1：三尼特瑞這家餐廳非常乾淨，衛生條件符合國際標準。\n\n聯想畫面 2：公共廁所的標示寫著 sanitary，提醒大家保持環境清潔。\n\n高效擴充：字根 san 是健康，加上 itary 結尾，指與衛生保健相關。\nKK 音標：[ˋsænɪ͵tɛri] -> 重音在第一音節 san，後面的 tary 唸得輕快。\n\n常見同義字：\nhygienic（衛生的，強調健康防護）\nclean（乾淨的，最基礎的詞）\nsterile（無菌的，強調消毒程度）",
  "sanitation": "諧音聯想：\n諧音：類似「刪你特休」\n\n聯想畫面 1：公司為了員工健康著想進行全面消毒，並強調公共衛生與環境衛生比什麼都重要。\n\n聯想畫面 2：城市地下水管與下水道設施改善工程，大幅提升了整體的衛生設備水準。\n\n高效擴充：與 sanitary（衛生的）為同家族單字，常見於食品包裝或醫療用品上。\nKK 音標：[͵sænəˋteʃən] -> 重音落在 te 音節，前面輕輕滑過。\n\n常見同義字：\nhygiene（個人或環境衛生、保健）\ncleanliness（清潔、整潔狀態）\npurity（純淨度）",
  "sank": "諧音聯想：\n諧音：「山客」\n\n聯想畫面 1：登山客不小心掉進湖裡，身體漸漸下沉、沉沒。\n\n聯想畫面 2：鐵達尼號撞上冰山後，整艘船迅速下沉到海底。\n\n高效擴充：不規則動詞 sink 的過去式，i 變成 a。\nKK 音標：[sæŋk] -> 單音節短母音，æ 嘴巴張大，ŋk 鼻音結尾。\n\n常見同義字：\n\nsank（下沉、沉沒，sink 的過去式）\n\nsubmerged（淹沒、潛入水中，常作形容詞或過去式）\n\ndropped（掉落、下降，動作較快）",
  "sap": "諧音聯想：\n諧音：塞普。\n\n聯想畫面 1：植物的汁液（sap）被抽乾，整棵樹就顯得虛弱無力。\n\n聯想畫面 2：他被騙子騙光了錢，像個傻瓜（sap）一樣站在路邊。\n\n高效擴充：sap 也可以當動詞，指削弱某人的精力。\nKK 音標：[sæp] -> 短母音 a，發音短促。\n\n常見同義字：\n\njuice 汁液，fool 傻瓜，weaken 削弱。",
  "sara": "諧音聯想：\n諧音：撒啦\n\n聯想畫面 1：薩拉是個活潑的女孩，每次見面都熱情地對我撒啦（sara）嬌。\n\n聯想畫面 2：薩拉族人在沙漠中生活，擁有獨特的文化與傳統。\n\n高效擴充：源自希伯來語，意為公主，是全球通用的女子名。\nKK 音標：[ˋserə] -> 重音在第一個音節，注意 a 的發音要輕柔。\n\n常見同義字：\nwoman's name（女子名，分類詞）\nprincess（公主，對應其語源含義）\nfemale（女性，通用詞）",
  "satellite": "諧音聯想：\n諧音：「殺它來特」\n\n聯想畫面 1：科幻電影中，太空總署發射人造衛星去偵測外星人，對準目標殺它來特！\n\n聯想畫面 2：氣象預報員透過人造衛星傳送回來的雲圖，準確預測明天的颱風動向。\n\n高效擴充：字尾lite常指微小或輕量，合起來字面有「隨從、跟班小衛星」的意思。\nKK 音標：[ˋsætə͵laɪt] -> 主重音在sæt上，ə為輕聲，laɪt的ai發長雙母音。\n\n常見同義字：\nspacecraft（太空船，相關字）\norbit（軌道，衛星運行的路徑）\nrelay station（中繼站）",
  "satiation": "諧音聯想：\n諧音：塞西（吃）的。\n\n聯想畫面 1：吃到肚子塞不下了，那種極度飽足的狀態就是 satiation。\n\n聯想畫面 2：當你對某種食物感到厭膩，就是因為已經達到了飽食的極限。\n\n高效擴充：源自 satisfy（滿足），字根 sat 代表足夠。\nKK 音標：[͵seɪʃiˋeɪʃn] -> 重音在第三音節，注意 tion 的發音。\n\n常見同義字：\n\nfullness（飽足感）\n\nsatisfaction（滿足）\n\nsatiety（飽足感，較正式）。",
  "satisfaction": "諧音聯想：\n諧音：「殺死福氣雄」\n\n聯想畫面 1：吃了超美味的料理讓人感到無比的滿意，簡直把不順心都殺死，福氣雄厚！\n\n聯想畫面 2：顧客在意見調查表上勾選了最高滿意度，臉上露出滿足的笑容。\n\n高效擴充：動詞為satisfy（使滿足），字尾ction將其名詞化。\nKK 音標：[͵sætəˋsfækʃən] -> 主重音在sfæk上，唸起來節奏分明，字尾ʃən發shən音。\n\n常見同義字：\ncontentment（知足、滿意，較內心的平靜）\nfulfillment（成就感、實現願望的滿足）\npleasure（愉悅、樂事）",
  "satisfactory": "拆解：satisfy（使滿意）＋ factory（工廠）\n\n諧音/拆解：這間「工廠」生產的產品品質都「令人滿意」。\n\n聯想畫面 1：期末考成績發下來，小明的總成績剛好達到令人滿意的標準。\n\n聯想畫面 2：主管看完報告後點頭表示，這個解決方案還算令人滿意。\n\n高效擴充：由 satisfy 延伸而來的形容詞，字尾 ory 表示性質。\nKK 音標：[͵sætəˋsfæktri] -> 次重音在最前，主重音在 fækt。\n\n常見同義字：\n\nacceptable（可接受的，通常指勉強達標）\nadequate（足夠的、合適的）\npleasing（令人愉悅滿意的）",
  "satisfy": "諧音聯想：\n諧音：「殺死妳（的）負擔」\n\n聯想畫面 1：這款美味的甜點完美satisfy（滿足）了大家的挑剔味蕾。\n\n聯想畫面 2：服務生熱情的態度順利satisfy（使滿意）了奧客的要求。\n\n高效擴充：satis（足夠）加上 fy（使……），讓份量足夠就是滿足。\nKK 音標：[ˋsætə͵sfaɪ] -> 重音在最前面的 ˋsæt，後面輕讀。\n\n常見同義字：\n\ncontent（使滿足、安於現狀）\n\nplease（取悅、使高興）\n\nfulfill（達成、履行承諾）",
  "satisfying": "諧音聯想：\n諧音：「歇迪思發音」\n\n聯想畫面 1：英文老師把這個單字發音教到大家都懂，那種成就感真是令人滿意（satisfying）。\n\n聯想畫面 2：吃完一碗熱騰騰的牛肉麵後打了一個飽嗝，感覺身心都被滿足了。\n\n高效擴充：由動詞 satisfy（使滿意）轉變而來的現在分詞形容詞，專門形容事物具有讓人心滿意足的效果。\nKK 音標：[ˋsætɪsfaɪɪŋ] -> 主重音在第一音節的sæt，唸「薩-提斯-發-因」。\n\n常見同義字：\nfulfilling（充實的，心靈滿足的）\ngratifying（令人喜悅與感激的）\nrewarding（有回報的，值得的）",
  "saturated": "諧音聯想：\n諧音：灑取瑞得。\n\n聯想畫面 1：海綿被水灑取瑞得（灑滿水），整個吸飽水分變得溼透。\n\n聯想畫面 2：化學實驗中，溶液裡溶質多到灑取瑞得（灑出來也取不走），達到飽和狀態。\n\n高效擴充：字根 satur- 代表滿足，像 satisfy。\nKK 音標：[ˋsætʃəreɪtɪd] -> 第一音節 sat 重音，唸起來要有飽滿的氣流感。\n\n常見同義字：\n\nsoaked（溼透的，強調被浸泡）\n\nfull（充滿的，較通用）\n\nconcentrated（濃縮的，化學常用）。",
  "saturation": "諧音聯想：\n諧音：撒（sa）去（tu）瑞（ra）神（tion）。\n\n聯想畫面 1：把顏料撒進水裡，直到水完全飽和，顏色深到極致。\n\n聯想畫面 2：市場上同類產品太多，導致飽和，消費者都不想買了。\n\n高效擴充：字根 satur 是滿的意思，跟 satisfy（滿足）同源。\nKK 音標：[͵sætʃəˋreɪʃ(ə)n] -> 重音在 ra，發音時節奏要穩。\n\n常見同義字：\n\nfullness（充滿）\n\nsoaking（浸透）。",
  "saturday": "諧音聯想：\n諧音：「殺特低」\n\n聯想畫面 1：星期六放假不用上班上課，大家殺特低（殺到最低價）去血拼狂歡。\n\n聯想畫面 2：每到星期六夜晚，年輕人就殺特低（出門嗨到很低調的深夜）。\n\n高效擴充：字首 Sat. 是常見的縮寫，星期幾開頭第一個字母都要大寫。\nKK 音標：[ˋsætɚdi] -> 主重音在第一個音節 sæt，後面依序念弱音。\n\n常見同義字：\n\nweekend（指週末，包含星期六與星期日）\n\nSunday（指星期日，緊接在星期六後面）\n\nweekday（指平日、工作日，與星期六相對）",
  "saturn": "諧音聯想：\n諧音：撒特恩。\n\n聯想畫面 1：土星環繞著光環，像是在撒特恩（撒下特別的恩惠）。\n\n聯想畫面 2：羅馬神話中，土星之神掌管農業。\n\n高效擴充：源自羅馬神話 Saturnus。\nKK 音標：[ˋsætɝn] -> 重音在第一音節。\n\n常見同義字：\n\nthe sixth planet（第六大行星）\n\nCronus（希臘神話對應神）。",
  "sauce": "諧音聯想：\n諧音：「掃死」\n\n聯想畫面 1：吃薯條沾了太多番茄醬，滴到桌上必須趕快拿抹布掃死那些醬汁。\n\n聯想畫面 2：牛排端上桌時，淋上香氣四溢的蘑菇調味汁令人食指大動。\n\n高效擴充：常與 hot sauce（辣醬）或 tomato sauce（番茄醬）搭配記憶。\nKK 音標：[sɔs] -> 單音節長元音，嘴巴張開念深沉的 ɔ。\n\n常見同義字：\n\ndressing（沙拉醬，專指拌沙拉的調汁）\n\ngravy（肉汁，烤肉流出的精華調味）\n\ncondiment（調味品，較正式的統稱）",
  "saucer": "諧音聯想：\n諧音：「燒死鵝」\n\n聯想畫面 1：傳說中外星人的幽浮像一個淺碟茶托，把地上的鵝都嚇壞了。\n\n聯想畫面 2：喝下午茶時，把熱茶倒在茶碟裡散熱再喝。\n\n高效擴充：flying saucer 即是經典的「飛碟」。\nKK 音標：[ˋsɔsɚ] -> 重音在首音節 sɔ，ɚ 念輕聲。\n\n常見同義字：\nplate（平盤、盤子）\ndish（菜餚、碟子通稱）\nsmall plate（小圓盤）",
  "sausage": "諧音聯想：\n諧音：「瘦死幾」\n\n聯想畫面 1：烤肉架上串了好幾條肥美的香腸，油脂滴下來滋滋作響。\n\n聯想畫面 2：媽媽對著圓滾滾的小孩暱稱：「我的小香腸，別再吃了！」\n\n高效擴充：複合字如 hot dog sausage（熱狗香腸）。\nKK 音標：[ˋsɔsədʒ] -> 重音在前，字尾 ge 發 dʒ 的清脆摩擦音。\n\n常見同義字：\nwurst（德式血腸或香腸）\nhot dog（熱狗）\nbanger（英式香腸的口語稱呼）",
  "savage": "諧音聯想：\n諧音：「殺微吉」，兇猛的野蠻人動不動就想砍殺微小吉利的事物，十分殘暴。\n\n聯想畫面 1：原始森林中未開化的人手持長矛，展現兇猛殘暴的狩獵姿態。\n\n聯想畫面 2：暴風雨猛烈地攻擊沿海村莊，把房屋摧毀得殘破不堪。\n\n高效擴充：字根 sav- 與野外（sylvan）同源，指大自然中原始野蠻的力量。\nKK 音標：[ˋsævədʒ] -> 重音在第一音節 sav，a 發短音，字尾 dʒ 唸清脆的 jih 音。\n\n常見同義字：\n\nfierce（兇猛的、激烈的，常用於形容動物或競爭）\n\nbrutal（殘暴的、冷酷的，強調手段兇殘）\n\nwild（野生的、未馴服的，範圍較廣且較中性）",
  "save": "諧音聯想：\n諧音：「媳婦」\n\n聯想畫面 1：英雄英勇衝進火場挽救性命，順利拯救了受困的媳婦。\n\n聯想畫面 2：為了買新房子，夫妻倆每個月都省吃儉用把錢存進銀行裡。\n\n高效擴充：與形容詞 safe（安全的）拼法相似，動詞改為 v 結尾。\nKK 音標：[sev] -> 重音在單音節，雙母音 e 要完整發出，字尾 v 需輕咬下嘴唇發氣音。\n\n常見同義字：\nrescue（拯救，特指將人或動物從危險災害中救出）\n\nstore（儲存，強調把物品或資料存放起來）\n\neconomize（節省，較正式，特指經濟或開支上的節約）",
  "saving": "諧音聯想：\n諧音：「現金」\n\n聯想畫面 1：每個月努力存錢，銀行存摺裡的儲金就是未來的現金。\n\n聯想畫面 2：打折大拍賣幫大家省下了不少錢，真是個救星般的節約方式。\n\n高效擴充：常以複數 savings 表示「存款、積蓄」。\nKK 音標：[ˋsevɪŋ] -> 重音在前，sev 發清脆的音，ing 鼻音收尾。\n\n常見同義字：\neconomy（經濟、節約）\nthrift（節約、勤儉）\nreserve（儲備金、預備品）",
  "savvy": "諧音聯想：\n諧音：誰會\n\n聯想畫面 1：這件事誰會處理？當然是那位經驗豐富、很有悟性的老手。\n\n聯想畫面 2：他在科技領域非常聰慧，對新趨勢有敏銳的實際知識。\n\n高效擴充：源自法文 savoir，意為知道，形容人很懂門道。\nKK 音標：[ˋsævi] -> 重音在第一音節 sav，結尾的 vy 唸出輕微的 v 音。\n\n常見同義字：\nshrewd（精明的，強調判斷力）\nknowledgeable（知識淵博的，強調學識）\nstreet-smart（懂世故的，強調生活經驗）",
  "saw": "諧音聯想：\n諧音：「搜」\n\n聯想畫面 1：木工拿著大鋸子用力地搜（鋸）開厚重的木頭。\n\n聯想畫面 2：警察在路口搜（尋找）查時，意外看見（see 的過去式）嫌犯的蹤跡。\n\n高效擴充：它是不規則動詞 see 的過去式，三態為 see, saw, seen。\nKK 音標：[sɔ] -> 嘴巴嘟圓發 ɔ 音，發音短促有力。\n\n常見同義字：\n\nlooked（look 的過去式，指看見、瞧見）\n\nobserved（指觀察到、注意到，較正式）\n\ncut（指切割、鋸斷，動作涵蓋範圍廣）",
  "sawn": "諧音聯想：\n諧音：送（sawn）。\n\n聯想畫面 1：木頭被鋸開後，直接送去工廠加工。\n\n聯想畫面 2：這塊木板已經鋸好了，尺寸剛剛好。\n\n高效擴充：saw 是鋸子，sawn 是其過去分詞。\nKK 音標：[sɔn] -> 單音節，發長母音 o。\n\n常見同義字：\n\ncut（切割，通用）\n\nsawed（鋸開，過去式）。",
  "say": "諧音聯想：\n諧音：「誰」\n\n聯想畫面 1：到底是誰在台上面對大家大聲說出這句台詞呢？\n\n聯想畫面 2：董事會上每位股東都有發言權，可以說明自己的理念。\n\n高效擴充：發音極簡短，注意第三人稱單數 says 的發音會轉變為 sez 音。\nKK 音標：[se] -> 重音在單音節，雙母音 e 嘴型要從半開漸漸收窄。\n\n常見同義字：\nspeak（說，強調使用某種語言或說話的動作本身）\n\ntell（告訴，重點在於將資訊傳達給特定的聽者）\n\nstate（宣稱，較正式，指明確且清楚地陳述事實）",
  "scale": "諧音聯想：\n諧音：「死給樓」\n\n聯想畫面 1：要爬上高樓量體重或看建築物規模，先踩上磅秤再說。\n\n聯想畫面 2：漁夫熟練地把魚身上的鱗片用刀子刮下來。\n\n高效擴充：可當名詞指規模、音階，也可當動詞指攀登。\nKK 音標：[skel] -> 結合 s 和 k 的子音群，接開口笑的長 e 音。\n\n常見同義字：\nscope（範圍、機會）\nrange（範圍、幅度）\nbalance（天平、平衡）",
  "scan": "諧音聯想：\n諧音：「掃看」，用眼睛快速掃描、細看整份文件內容。\n\n聯想畫面 1：海關人員用機器掃描行李箱，仔細審視內部有無違禁品。\n\n聯想畫面 2：進超商時店員拿著條碼掃描器，快速讀取商品價格。\n\n高效擴充：字源來自拉丁文掃過，現代延伸為電腦檔案的掃描與快速瀏覽。\nKK 音標：[skæn] -> 單音節字，短音 a 嘴巴張大扁平，sk 子音群發音要俐落。\n\n常見同義字：\n\nexamine（詳細檢查，強調深入的審查）\n\nbrowse（瀏覽，像逛網頁或書局那樣隨意看）\n\nreview（複習、審查，通常帶有回顧檢討意味）",
  "scandal": "諧音聯想：\n諧音：「死看兜」，大眾八卦心態作祟，死命盯著名人緋聞的口袋內幕看，爆發醜聞。\n\n聯想畫面 1：報紙頭版刊登政治人物的貪污醜聞，引起社會大眾熱烈議論。\n\n聯想畫面 2：公司內部傳出財務作假的流言蜚語，員工私底下議論紛紛。\n\n高效擴充：與 scan（掃描）字根相近，指被攤在陽光下檢視的難堪醜事。\nKK 音標：[ˋskændəl] -> 重音在第一音節 scan，dəl 輕讀，注意不要唸成 sandal。\n\n常見同義字：\n\ncontroversy（爭議，指引起大眾辯論的事件）\n\ngossip（流言蜚語、八卦，偏向口耳相傳的私下傳聞）\n\ndisgrace（恥辱、不名譽的事，強調個人名譽受損）",
  "scanner": "諧音聯想：\n諧音：死蓋那\n\n聯想畫面 1：這台掃描機死蓋那堆文件，快速將它們轉成數位檔案。\n\n聯想畫面 2：機場安檢人員使用掃描器，檢查旅客行李中的金屬物品。\n\n高效擴充：scan 是掃描，加上 er 變成機器，指執行掃描動作的裝置。\nKK 音標：[ˋskænɚ] -> 重音在第一音節 scan，結尾的 er 捲舌音要自然。\n\n常見同義字：\ndigitizer（數位化裝置，較專業）\nreader（讀取器，強調讀取功能）\nimager（影像處理器，強調影像）",
  "scanty": "諧音聯想：\n諧音：死乾踢（想像衣服太短太緊，穿起來像死乾踢，很不舒服）\n\n聯想畫面 1：這件裙子太短了，布料少到暴露，看起來很不莊重。\n\n聯想畫面 2：這份報告的數據少得可憐，不足以支持他的論點。\n\n高效擴充：scant 意為缺乏，加上 y 變成形容詞，常指量少或衣著暴露。\nKK 音標：[ˋskænti] -> 第一音節 skæn 重音，發音像死乾，結尾 ti 輕短。\n\n常見同義字：\nmeager（指微薄的、貧乏的）\nsparse（指稀疏的）\nskimpy（指過短的、吝嗇的）",
  "scar": "諧音聯想：\n諧音：「死卡」，傷口癒合後死死卡在皮膚表層，留下一個明顯的傷疤。\n\n聯想畫面 1：小時候跌倒擦傷膝蓋，結痂脫落後留下一道永久的白色傷痕。\n\n聯想畫面 2：戰爭退伍軍人臉上的刀疤，見證了當年慘烈的精神與肉體創傷。\n\n高效擴充：短小精悍的單字，字首 sc- 常聯想到劃破或切割痕跡。\nKK 音標：[skɑr] -> 單音節字，ɑr 發長音ㄚ，嘴巴張大舌頭往後縮。\n\n常見同義字：\n\nwound（傷口，強調尚未癒合的撕裂傷）\n\ntrauma（創傷，多指心理上的重大打擊與陰影）\n\nblemish（瑕疵、斑點，常用於皮膚外觀或物品缺點）",
  "scarce": "諧音聯想：\n諧音：在沙漠裡水資源「死渴死」，因為水極度缺乏。\n\n聯想畫面 1：今年雨量不足導致水庫見底，自來水資源變得非常稀少短缺。\n\n聯想畫面 2：這款限量的球鞋在市面上極為少見，黃牛票炒到天價。\n\n高效擴充：常以片語 be scarce of 或作敘述用法，指物資不足。\nKK 音標：[skɛrs] -> 結合 s 和 k 音，發音短而有力。\n\n常見同義字：\n\nrare（稀有的，強調數量少見）\nscarce（缺乏的，強調供不應求）\ninsufficient（不足的，較正式）",
  "scarcely": "諧音聯想：\n諧音：「斯凱斯力」氣不足，幾乎快要爬不上去了。\n\n聯想畫面 1：他剛到公司不久，電話鈴聲就響了起來。\n\n聯想畫面 2：沙漠裡雨水極少，幾乎沒有植物能生存。\n\n高效擴充：由 scarce（稀少的）加上副詞字尾 -ly。\nKK 音標：[ˋskɛrsli] -> 第一音節 SCARCE 重音。\n\n常見同義字：\nhardly（副詞，幾乎不）\nbarely（副詞，勉強）\nrarely（副詞，罕見）",
  "scarcity": "諧音聯想：\n諧音：死給死體。\n\n聯想畫面 1：沙漠中水源嚴重不足，為了搶奪最後一瓶水，人們差點死給死體看。\n\n聯想畫面 2：經濟不景氣導致物資缺乏，超市貨架上的商品出現了嚴重的稀缺現象。\n\n高效擴充：形容詞是 scarce，結尾加上 ity 變成名詞。\nKK 音標：[ˋskersəti] -> 重音在第一個音節，發音時注意 scar 的長音。\n\n常見同義字：\n\nshortage（短缺，常用於資源）\n\nlack（缺乏，通用）。",
  "scare": "諧音聯想：\n諧音：「死客」\n\n聯想畫面 1：鬼屋裡突然衝出一個鬼面具，把死客（死奧客）嚇得魂飛魄散。\n\n聯想畫面 2：驚悚電影的音效太恐怖，把觀眾嚇到心驚肉跳、驚恐萬分。\n\n高效擴充：加上ful變成 scary（可怕的、嚇人的），注意拼字別漏掉 e。\nKK 音標：[skɛr] -> 結合子音群 sk 與滑音 ɛr，發音時嘴巴微開向外送氣。\n\n常見同義字：\n\nfrighten（動詞，指驚嚇、使害怕，程度較深）\n\nterrify（動詞，指把人嚇得膽戰心驚、極度恐懼）\n\npanic（名詞或動詞，指恐慌、驚慌失措）",
  "scarecrow": "諧音聯想：\n諧音：「死客靠樓」\n\n聯想畫面 1：田地裡立著一個稻草人，把想偷吃作物的鳥群嚇得半死。\n\n聯想畫面 2：萬聖節時農夫穿得像個衣著破爛的稻草人站在門口嚇人。\n\n高效擴充：由 scare（驚嚇）加上 crow（烏鴉）組合成的複合字。\nKK 音標：[ˋskær͵kro] -> 複合字，重音在第一個字 scare。\n\n常見同義字：\nbogeyman（妖怪、嚇小孩的人物）\nphantom（幽靈、幻影）\nmannequin（服裝模特兒、人形模特）",
  "scared": "諧音聯想：\n諧音：「死客死」\n\n聯想畫面 1：鬼屋裡死掉的遊客嚇死大家，每個人都覺得超 scared。\n\n聯想畫面 2：半夜聽到奇怪聲音，全家人害怕得躲在棉被裡發抖。\n\n高效擴充：源自動詞 scare，常與 of 連用表示對某事感到害怕。\nKK 音標：[skerd] -> 主重音在單音節母音 e，發長音 /er/，結尾 d 輕聲帶過。\n\n常見同義字：\nafraid（常作表語形容詞，指擔憂或害怕）\nfrightened（指突然受到驚嚇而產生的恐懼）\nterrified（指極度驚恐、嚇得半死）",
  "scarf": "諧音聯想：\n諧音：「死咖乎」\n\n聯想畫面 1：寒流來襲，不圍一條溫暖的圍巾出門就會冷死在咖啡廳乎。\n\n聯想畫面 2：時尚模特兒在伸展台上帥氣地甩動脖子上的絲質披巾。\n\n高效擴充：字尾 f 複數形為 scarves。\nKK 音標：[skɑrf] -> 包含長音 ɑr，發音時嘴巴張大，r 音往後捲。\n\n常見同義字：\nmuffler（厚圍巾、消音器）\nshawl（大披肩、搭肩）\nneckwear（頸部裝飾品總稱）",
  "scary": "諧音聯想：\n諧音：鬼屋「死客裡」傳出慘叫聲，氣氛非常可怕。\n\n聯想畫面 1：萬聖節的鬼屋裡突然衝出一個喪屍，把小朋友嚇得大哭。\n\n聯想畫面 2：昨晚看了一部恐怖電影，害我連晚上上廁所都覺得提心吊膽。\n\n高效擴充：名詞 scare（驚嚇）加上 y 形成形容詞，用來形容令人感到害怕的事物。\nKK 音標：[ˋskɛri] -> 重音在第一音節的 skɛ，注意字尾的 y 發長的 i 音。\n\n常見同義字：\n\nfrightening（令人驚恐的）\nterrifying（恐怖的，程度比 scary 更強）\nspooky（陰森可怕的，常指鬼怪氣氛）",
  "scathingly": "諧音聯想：\n諧音：死（sca）＋ 誰（thi）＋ 吝（ngly）\n\n聯想畫面 1：評論家毫不留情地批評這部電影，言詞尖刻得讓人難受。\n\n聯想畫面 2：主管尖刻地指責員工的錯誤，讓辦公室氣氛降到冰點。\n\n高效擴充：scathe 原意是傷害，加上 ly 變成副詞，形容說話極具殺傷力。\nKK 音標：[ˋskeɪðɪŋli] -> 重音在第一個音節，注意 th 的咬舌音。\n\n常見同義字：\nbitterly（痛苦地，帶有強烈怨恨）\nsharply（尖銳地，形容語氣鋒利）\nseverely（嚴厲地，強調程度嚴重）",
  "scatter": "諧音聯想：\n諧音：「死該他」\n\n聯想畫面 1：調皮的小孩把一整盒彈珠全部撒開在地上，氣得大人直罵。\n\n聯想畫面 2：下課鐘聲一響，操場上的學生瞬間四處消散、散開。\n\n高效擴充：常片語 scatter around（四處散落）。\nKK 音標：[ˋskætɚ] -> 重音在第一個音節 skæt，ɚ 輕念。\n\n常見同義字：\n disperse（驅散、消散）\nspread（展開、傳播）\nstrew（撒滿、散布）",
  "scene": "諧音聯想：\n諧音：「死印」\n\n聯想畫面 1：刑案現場留下了死者的印記，這個慘烈的場景讓人永生難忘。\n\n聯想畫面 2：電影拍攝的最後一個場景，導演一喊卡，大家就拍手收工。\n\n高效擴充：字尾常接 scenery 風景或 picturesque 生動的，字首 s 代表展開。\nKK 音標：[sin] -> 長音的 i，發音時嘴角拉平，像在微笑說「細」。\n\n常見同義字：\n\nview（指遠眺或大自然的美麗風景，較著重視覺畫面）\nsite（指特定用途或事件發生的地點，如建築工地或網頁伺服器）\nlocation（指精確的地理位置或拍攝外景地，常用於拍片或房地產）",
  "scenery": "諧音聯想：\n諧音：「細妳麗」\n\n聯想畫面 1：攝影師稱讚照片中風景的細節妳拍得好美麗，這自然景色真是太迷人了。\n\n聯想畫面 2：坐在火車靠窗的位置，欣賞窗外不斷變換的山水風景與鄉村舞臺佈景。\n\n高效擴充：注意不要與scene（風景、場景）搞混，scenery是總體的景色集合。\nKK 音標：[ˋsinɚi] -> 主重音在sin上，sin要拉長音，ɚi唸輕聲。\n\n常見同義字：\nlandscape（風景、鄉村景色，側重廣闊視野）\nview（視野、風景，從特定角度看到的畫面）\nscenics（風景照或風光影片）",
  "scenic": "諧音聯想：\n諧音：「西尼克」\n\n聯想畫面 1：西尼克小鎮擁有絕佳的湖光山色，風景非常秀麗。\n\n聯想畫面 2：沿著海岸公路開車，窗外全是美麗的觀光風景。\n\n高效擴充：由 scene（風景）衍生而來的形容詞。\nKK 音標：[ˋsinɪk] -> 重音在第一音節 sce，注意 c 發 /s/ 音。\n\n常見同義字：\npicturesque（如畫般的，風景優美的）\npump（風景優美的，引人入勝的）\nbeautiful（美麗的，通用的形容詞）",
  "scent": "諧音聯想：\n諧音：「香的」，空氣中飄散著香水味或花香的氣味。\n\n聯想畫面 1：走進高級香水專櫃，立刻聞到撲鼻而來的迷人芳香味。\n\n聯想畫面 2：獵犬低頭嗅出森林中獵物留下的臭跡與氣味線索。\n\n高效擴充：字尾 -cent 與 scent 的 c 是不發音的字母，拼寫時要特別注意。\nKK 音標：[sɛnt] -> 單音節字，ɛ 唸短音的ㄝ，t 輕輕帶過不爆破。\n\n常見同義字：\n\nsmell（氣味、嗅覺，最通用且廣泛的詞彙）\n\naroma（香氣、芳香，多指食物或花草令人愉悅的香味）\n\nodor（氣味，通常偏向難聞的異味或臭味）",
  "schedule": "諧音聯想：\n諧音：「死給久」\n\n聯想畫面 1：老闆排的這個工作行程表時間太趕，簡直是要把大家累死給久。\n\n聯想畫面 2：打開行事曆確認今天的會議預定時間與計劃清單。\n\n高效擴充：美式發音為 [ˋskɛdʒʊl]，英式常發 [ˋʃɛdʒuːl]。\nKK 音標：[ˋskɛdʒʊl] -> 重音在首音節，ch 發硬音 ʒʊl。\n\n常見同義字：\ntimetable（時間表、時刻表）\nagenda（議程、待辦事項）\nplan（計劃、打算）",
  "scheme": "諧音聯想：\n諧音：「死記謀」，反派角色死命記住陰謀詭計，策劃整套犯罪方案。\n\n聯想畫面 1：公司高層在密室開會，策劃一場擴大市場佔有率的商業計劃。\n\n聯想畫面 2：電影中歹徒密謀策劃一場銀行搶案的詳細系統流程。\n\n高效擴充：ch 發 k 的音，字根源自希臘文的形狀與計畫。\nKK 音標：[skim] -> 單音節字，長音 i 嘴型要扁平拉開，sk 俐落開頭。\n\n常見同義字：\n\nplan（計畫、方案，最基礎且日常的用語）\n\nproject（專案、大型計畫，強調有組織的長期工程）\n\nplot（陰謀、密謀，多指暗中策劃的壞事）",
  "scholar": "諧音聯想：\n諧音：「死嗑老」\n\n聯想畫面 1：真正的學者就是每天死嗑老書本、研究學問的專家。\n\n聯想畫面 2：這個勤奮聰穎的學生拿下了全國最高榮譽的獎學金。\n\n高效擴充：字根 school 引申而來，指學術圈的人。\nKK 音標：[ˋskɑlɚ] -> 重音在前，ɑ 發短 o 音，ɚ 念輕聲。\n\n常見同義字：\nacademician（學術界人士、院士）\nintellectual（知識分子）\nstudent（學生、學習者）",
  "scholarship": "諧音聯想：\n諧音：「死嗑老許拚」\n\n聯想畫面 1：老許為了拿到出國深造的獎學金，每天熬夜苦讀拚了命。\n\n聯想畫面 2：學校頒發了一筆豐厚的學問研究經費給優秀的教授。\n\n高效擴充：由 scholar（學者）加上 ship（身分/狀態字尾）組合而成。\nKK 音標：[ˋskɑlɚ͵ʃɪp] -> 主重音在 scha，次重音在 ship 前。\n\n常見同義字：\ngrant（補助金、研究津貼）\nfellowship（獎學金、研究員職位）\nbursary（助學金）",
  "school": "諧音聯想：\n諧音：「死酷」\n\n聯想畫面 1：學校裡總是有一群打扮得死酷、走路有風的叛逆高中生。\n\n聯想畫面 2：海底世界也有學校，大群的魚在海裡上學，這就是所謂的魚群。\n\n高效擴充：字尾 ol 是常見名詞字尾，注意拼字時有 ch 發 k 的音。\nKK 音標：[skul] -> 搭配短促的 sk 開頭，接著長音的 ul，嘴唇要嘟起來。\n\n常見同義字：\n\ninstitution（指規模較大的機構或學院，較正式且廣泛）\nacademy（指專科學校、軍校或藝術學苑，帶有專業培訓性質）\neducational establishment（指教育機構的完整統稱，多用於官方文書）",
  "science": "諧音聯想：\n拆解 / 諧音：賽因思\n\n諧音：「賽因思」\n\n聯想畫面 1：學校舉辦全國科學競賽，大家都在思索如何做出最酷的實驗。\n\n聯想畫面 2：愛因斯坦用严谨的科學知識改變了人類對宇宙的看法。\n\n高效擴充：字根 sci 代表「知道、知識」，衍生出 cientist（科學家）。\nKK 音標：[ˋsaɪəns] -> 重音在第一個音節 saɪ，後面接 əns。\n\n常見同義字：\n\ndiscipline（學科，指特定的學術領域）\n\nknowledge（知識，廣泛的認知與學問）\n\ntechnology（科技，科學的實際應用）",
  "scientific": "拆解：science（科學）＋ ic（形容詞字尾）\n\n諧音/拆解：「科學」家穿著白袍在實驗室做嚴謹的實驗。\n\n聯想畫面 1：研究人員用科學的方法反覆驗證，終於找出了病毒的解藥。\n\n聯想畫面 2：這份報告數據齊全、邏輯嚴密，展現出高度的科學精神。\n\n高效擴充：由 science 變化而來，ic 字尾專門用來轉化為學科或屬性的形容詞。\nKK 音標：[͵saɪənˋtɪfɪk] -> 主重音落在第發音較重的 tɪf 音節上。\n\n常見同義字：\n\ntechnical（技術性的）\nmethodical（有條理的、循規蹈矩的）\nanalytical（分析性的）",
  "scientist": "諧音聯想：\n拆解 / 諧音：賽因思特\n\n諧音：「賽因思特」\n\n聯想畫面 1：那位頂尖的科學家正在實驗室裡專注地觀察顯微鏡。\n\n聯想畫面 2：愛因斯坦這位偉大的科學家提出了解釋時空的相對論。\n\n高效擴充：由 science 加上表示人的字尾 ist 組合而成。\nKK 音標：[ˋsaɪəntɪst] -> 重音在 saɪ，中間的 əntɪst 要念得快而輕。\n\n常見同義字：\n\nresearcher（研究員，專職進行學術或商業調查的人）\n\nexpert（專家，在特定領域極具權威的人）\n\nchemist（化學家，專攻化學領域的學者）",
  "scissors": "諧音聯想：\n諧音：「洗著死」\n\n聯想畫面 1：美勞課上完後，老師叮嚀要把剪刀洗乾淨擦乾才不會生鏽。\n\n聯想畫面 2：裁縫師傅俐落地拿起一把大剪刀，把布料喀嚓喀嚓地剪開。\n\n高效擴充：因為剪刀有兩個刀刃，所以永遠以複數型態出現。\nKK 音標：[ˋsɪzɚz] -> 重音在開頭的 sɪ，z 的音要明顯發出來。\n\n常見同義字：\n\nshears（大剪刀，通常指修剪樹枝或大塊布料的剪刀）\n\nclipper（修剪器，如指甲剪或理髮器）\n\ncutter（切割器，泛指切東西的工具）",
  "scold": "諧音聯想：\n諧音：「死溝搭」\n\n聯想畫面 1：主管在死溝搭（溝渠工地）大聲責罵偷懶的工人。\n\n聯想畫面 2：媽媽生氣地訓斥考試考砸的孩子，罵得狗血淋頭。\n\n高效擴充：字根概念為嚴厲斥責，常與 scold sb for sth 連用。\nKK 音標：[skold] -> 主重音在滑音 old，嘴型由 s 滑向 k 再飽滿念出 old。\n\n常見同義字：\nreprimand（較正式的斥責）\nrebuke（嚴厲指責）\nscold（日常口語的責罵）」}, {",
  "scoop": "諧音聯想：\n諧音：死哭 -> 諧音：「死哭」\n\n諧音聯想：\n諧音：「死哭」\n\n聯想畫面 1：記者挖到獨家新聞太興奮，在路邊大喊Scoop並開心得快要死哭出來。\n\n聯想畫面 2：冰淇淋店員用大勺子用力一挖，盛滿整整一勺美味的冰淇淋。\n\n高效擴充：字尾p常帶有突發、碰觸的動作感，像pop、cap一樣。\nKK 音標：[skup] -> 發音時雙唇緊閉然後瞬間張開，發長音oo的嘴型。\n\n常見同義字：\nspoon（湯匙，通常指餐具）\nexclusive（獨家新聞，較正式）\ndig（挖出，動詞用法）",
  "scooter": "諧音聯想：\n諧音：速（scoo）＋特（ter）。\n\n聯想畫面 1：騎著摩托車在車陣中穿梭，速度特別快，這就是台灣街頭最常見的景象。\n\n聯想畫面 2：小朋友在公園玩踏板車，雙腳滑行，玩得不亦樂乎。\n\n高效擴充：scoot 有快速移動的意思。\nKK 音標：[ˋskutɚ] -> 重音在第一個音節，注意 s 後面的 k 發音不送氣。\n\n常見同義字：\n\nmotorcycle（重機或大型摩托車）\n\nmoped（機動腳踏車）\n\nbike（腳踏車或摩托車，口語）。",
  "scope": "諧音聯想：\n諧音：「思考撲克（牌）」\n\n聯想畫面 1：經理坐在桌前仔細思考撲克牌局的戰略，並評估這次專案的範圍與施展餘地。\n\n聯想畫面 2：這個產業未來的發展領域非常廣闊，充滿了無限的商機與機會。\n\n高效擴充：常與 beyond the scope（超出範圍）搭配使用在商業合約中。\nKK 音標：[skop] -> 單音節字，o 發長音 o，結尾 p 輕聲閉口。\n\n常見同義字：\nrange（範圍、廣度）\nextent（程度、廣度）\nopportunity（機會、良機）",
  "score": "諧音聯想：\n諧音：「死溝」\n\n聯想畫面 1：足球比賽踢到最後一秒終於進球，全場大喊分數贏了。\n\n聯想畫面 2：期末考成績單發下來，大家都在互相比較各自的考卷分數。\n\n高效擴充：高頻多義字，除了比分外，也常指音樂的總譜。\nKK 音標：[skɔr] -> 單音節字，sk 開頭接著長音的 ɔr。\n\n常見同義字：\n\npoints（點數，競賽或遊戲中獲得的記數）\n\nresult（結果，比賽或事件的最終結局）\n\ngrade（成績，學校裡對作業或考試的評分）",
  "scorn": "諧音聯想：\n諧音：「死看無」，瞧不起對方、死也不把對方看在眼裡，充滿蔑視。\n\n聯想畫面 1：傲慢主管對新人的愚蠢問題嗤之以鼻，投以輕蔑不屑的眼神。\n\n聯想畫面 2：面對對手的冷嘲熱諷，他選擇用鄙視的態度完全不予理會。\n\n高效擴充：字尾 -orn 與 horn（角）押韻，聯想頭角崢嶸之人的傲慢態度。\nKK 音標：[skɔrn] -> 單音節字，ɔrn 發低沉的奧恩音，嘴唇微噘。\n\n常見同義字：\n\ndespise（鄙視、輕視，強烈不喜歡且看不起）\n\ncontempt（輕蔑、蔑視，名詞用法較常見於法律或正式文體）\n\nmock（嘲弄、戲弄，強調模仿他人缺點來笑話對方）",
  "scotched": "諧音聯想：\n諧音：死過（scotched）。\n\n聯想畫面 1：謠言被徹底粉碎，就像已經死過一次一樣無法再傳播。\n\n聯想畫面 2：我們及時阻止了這個錯誤的計劃，讓它徹底 scotched。\n\n高效擴充：scotched 常用於 scotch a rumor（粉碎謠言）。\nKK 音標：[skɑtʃt] -> 單音節，結尾發出清脆的 t 聲。\n\n常見同義字：\n\ncrushed（壓碎/粉碎）\n\nstopped（停止）。",
  "scour": "諧音聯想：\n諧音：死（s）＋ 靠（cour）\n\n聯想畫面 1：為了把鍋子洗乾淨，我死命靠著力氣去刷洗（scour）。\n\n聯想畫面 2：警察搜遍（scour）了整個森林，終於找到失蹤者。\n\n高效擴充：scour 既有擦洗的意思，也有搜查的意思，記住要用力去做。\nKK 音標：[ˋskaʊər] -> 重音在第一音節，注意 ou 的雙母音。\n\n常見同義字：\nscrub（刷洗，指用力清潔）\nsearch（搜索，指尋找）\nclean（清潔，通用詞）",
  "scourge": "諧音聯想：\n諧音：死個。\n\n聯想畫面 1：戰爭是人類的災禍，所到之處生靈塗炭。\n\n聯想畫面 2：貧窮是這個地區長久以來的禍患，急需解決。\n\n高效擴充：原指鞭子，引申為像鞭打一樣的折磨。\nKK 音標：[skɝdʒ] -> 單音節，注意 ur 的捲舌音。\n\n常見同義字：\n\naffliction（折磨）\n\nplague（瘟疫）\n\nmenace（威脅）。",
  "scout": "諧音聯想：\n諧音：死靠 -> 諧音：「死靠」\n\n諧音聯想：\n諧音：「死靠」\n\n聯想畫面 1：童子軍在野外迷路，只能靠著指南針死靠到底尋找生路。\n\n聯想畫面 2：星探在路邊物色人才，死靠著星光大道不放過任何有潛力的面孔。\n\n高效擴充：以sc開頭的字多半和看、尋找有關，例如scope。\nKK 音標：[skaʊt] -> 重音在第一個音節，ou組合嘴型要由大變小。\n\n常見同義字：\nexplorer（探險家，指四處旅行的人）\nsearch（搜尋，動詞用法）\nspy（間諜，帶有偵察意味）",
  "scrabble": "諧音聯想：\n諧音：死抓波。\n\n聯想畫面 1：他在沙堆裡瘋狂扒尋，死抓波（scrabble）著要找到寶藏。\n\n聯想畫面 2：為了生活，他努力掙扎，在社會底層 scrabble。\n\n高效擴充：Scrabble 也是著名的拼字遊戲名稱。\nKK 音標：[ˋskræbl] -> 重音在第一個音節 scra，發短音 a。",
  "scramble": "諧音聯想：\n諧音：「死抓搬堡」，為了搶奪漢堡大亂鬥，大家手忙腳亂地攀爬爭奪。\n\n聯想畫面 1：百貨公司週年慶特賣會一開門，顧客們慌亂地爭搶特價商品。\n\n聯想畫面 2：美式炒蛋（scrambled eggs）是把蛋黃蛋白攪拌混雜在一起煎熟。\n\n高效擴充：-ble 為字尾常態結構，scramble 常形容慌亂的動作或爭奪。\nKK 音標：[ˋskræmbəl] -> 重音在第一音節 scram，a 發短音，bl 輕快收尾。\n\n常見同義字：\n\nclimb（攀爬，強調往高處爬的動作）\n\nstruggle（掙扎、奮鬥，強調克服困難的過程）\n\ncompete（競爭、角逐，強調爭奪勝負）",
  "scrap": "諧音聯想：\n諧音：「死客牌」，玩牌輸了把破牌當作廢料報廢拋棄。\n\n聯想畫面 1：工廠把淘汰的舊金山鐵鏽金屬統統當作廢料處理與回收。\n\n聯想畫面 2：寫作時把整張廢紙揉成一團丟掉，徹底放棄這個草稿。\n\n高效擴充：三拼字短單字，當動詞用時過去式為 scrapped（雙寫 p）。\nKK 音標：[skræp] -> 單音節字，短音 a 扁平發音，p 要輕脆閉口。\n\n常見同義字：\n\nwaste（廢棄物、浪費，泛指無用的東西）\n\njunk（破爛、垃圾，日常生活中指無價值的舊物）\n\nabandoned（被拋棄的、廢棄的，多用作形容詞）",
  "scrape": "諧音聯想：\n諧音：「死哭怕」，跌倒時膝蓋用力去刮擦地面，痛得哭出來好可怕。\n\n聯想畫面 1：搬運重物時不小心把木質地板刮出一道明顯的擦痕。\n\n聯想畫面 2：用鐵鏟用力刮除鍋底燒焦的鍋巴殘渣。\n\n高效擴充：字尾加上 e 形成長音，與上面的 scrap（短音）為一組容易混淆的對照字。\nKK 音標：[skrep] -> 單音節字，長音 e 嘴巴往兩側拉開，pe 輕收尾。\n\n常見同義字：\n\nscratch（抓傷、劃破，強調指甲或尖銳物造成的痕跡）\n\ngrate（磨碎、刮擦，常用於起司或蔬菜刨絲）\n\nabrade（磨損、擦傷，較科學或醫學正式的用語）",
  "scratch": "諧音聯想：\n諧音：「死抓去」\n\n聯想畫面 1：貓咪把沙發抓破，爪子死抓去不放，留下一道道劃痕。\n\n聯想畫面 2：蚊子叮咬後皮膚發癢，忍不住用力去抓而造成擦傷。\n\n高效擴充：字首 scr 常與摩擦、抓取動作有關。\nKK 音標：[skrætʃ] -> 留意尾音 ch 的短促清脆摩擦音。\n\n常見同義字：\nscrape（刮擦）\nabrade（磨損）\nclaw（用爪抓）」}, {",
  "scream": "諧音聯想：\n諧音：死快來 -> 諧音：「死快來」\n\n諧音聯想：\n諧音：「死快來」\n\n聯想畫面 1：看到恐怖的東西嚇得放聲尖叫，大喊死快來救我。\n\n聯想畫面 2：遊樂設施從高空俯衝而下，車上的人發出刺耳的尖叫聲。\n\n高效擴充：scr-開頭的字通常和摩擦或聲音有關，如scratch。\nKK 音標：[skrim] -> 雙唇扁平拉開，發長音ee的尖銳感。\n\n常見同義字：\nshout（大喊，語氣較溫和）\nyell（吼叫，通常帶有情緒）\nsqueal（尖叫，通常指動物或機械聲）",
  "screech": "諧音聯想：\n諧音：吃到超酸的檸檬讓人酸到「死去吃」，忍不住screech尖叫出來。\n\n聯想畫面 1：深夜的十字路口突然傳出煞車皮的摩擦聲，車子screech一聲緊急停下。\n\n聯想畫面 2：鬼屋裡突然伸出一隻手，嚇得遊客們當場screech尖叫連連。\n\n高效擴充：擬聲字，字尾的 eech 營造出尖銳、拉長的高頻刺耳聲音。\nKK 音標：[skritʃ] -> 單音節字，字首 skri 與結尾的 tch 要乾脆俐落。\n\n常見同義字：\n\nscream（尖叫，最常見的普通用語）\n\nshriek（尖叫，通常帶有驚恐或痛苦情緒）\n\nsquawk（粗厲的叫聲或抱怨）",
  "screeched": "諧音聯想：\n諧音：死虧取。\n\n聯想畫面 1：緊急煞車時，輪胎發出尖銳刺耳的聲音。\n\n聯想畫面 2：小女孩看到蟑螂，嚇得尖叫起來。\n\n高效擴充：Screech 形容高頻且難聽的聲音。\nKK 音標：[skritʃt] -> 結尾的 cht 音要發出清脆的摩擦聲。\n\n常見同義字：\n\nscreamed（尖叫）\n\nshrieked（尖銳地叫）。",
  "screeching": "諧音聯想：\n諧音：「死氣」。\n\n聯想畫面 1：煞車發出刺耳的 screeching 聲，聽了讓人覺得死氣沉沉。\n\n聯想畫面 2：貓頭鷹在深夜發出尖銳的 screeching 叫聲。\n\n高效擴充：Screech 是尖叫，加上 ing。\nKK 音標：[ˋskritʃɪŋ] -> 重音在第一個音節，發音要尖銳。\n\n常見同義字：\n\nShrieking（尖叫）\n\nPiercing（刺耳的）。",
  "screen": "諧音聯想：\n諧音：「死扛」\n\n聯想畫面 1：電影院巨型銀幕前，男主角正在死扛對抗怪獸。\n\n聯想畫面 2：長時間盯著電腦螢幕辦公，眼睛容易乾澀疲勞。\n\n高效擴充：動詞有遮蔽、過濾的意思，如 screen calls（過濾電話）。\nKK 音標：[skrin] -> 單音節字，sk 開頭並發長音的 i。\n\n常見同義字：\n\ndisplay（顯示器，電子設備的畫面呈現）\n\nmonitor（監視器，電腦螢幕或監控設備）\n\nshield（防護罩，指遮擋或保護的屏障）",
  "screw": "諧音聯想：\n諧音：死抓屋 -> 諧音：「死抓屋」\n\n諧音聯想：\n諧音：「死抓屋」\n\n聯想畫面 1：木工用起子把螺絲死死地旋緊在木頭屋樑上。\n\n聯想畫面 2：船尾的螺旋槳快速轉動，推動船隻前進。\n\n高效擴充：注意與view、few等字尾發音的相似性。\nKK 音標：[skru] -> 尾音收在u的圓唇音，注意不發w的音。\n\n常見同義字：\nbolt（螺栓，較大型的固定件）\nfasten（繫緊，動詞通用詞）\nnail（釘子，用錘子敲入的物件）",
  "screwdriver": "諧音聯想：\n諧音：拆解/諧音：「screw 螺絲 + driver 駕駛器」\n\n聯想畫面 1：修理工手拿螺絲起子，熟練地轉動螺絲。\n\n聯想畫面 2：組裝家具時找不到電動螺絲起子，急得快哭出來。\n\n高效擴充：由 screw（螺絲）與 drive（驅動）組合而成。\nKK 音標：[ˋskru͵draɪvɚ] -> 主重音在第一個音節 skru，後半 drive 念長元音。\n\n常見同義字：\ntool（工具，統稱）\nwrench（扳手）\nplier（老虎鉗）」}, {",
  "scribbled": "諧音聯想：\n諧音：死鬼不（亂塗亂畫，像死鬼一樣亂寫，看不懂）。\n\n聯想畫面 1：他在筆記本上 scribbled 了一堆草稿，連自己都看不懂。\n\n聯想畫面 2：小孩子在牆壁上 scribbled，媽媽看了很頭痛。\n\n高效擴充：字根 scrib 意為寫，類似 scribe（抄寫員）、describe（描述）。\nKK 音標：[ˋskrɪbld] -> 重音在第一音節 scrib，注意結尾的 ld 音。\n\n常見同義字：\nscrawled（潦草地寫，程度更深）\ndoodled（塗鴉，指無意識的畫）\nscribbled（亂寫，指動作隨意）",
  "script": "諧音聯想：\n諧音：「死去哭吧」\n\n聯想畫面 1：演員拿到悲劇劇本時忍不住入戲痛哭，台詞內容讓他覺得劇情實在太虐心。\n\n聯想畫面 2：醫生開立的處方箋手寫字跡潦草，需要藥師仔細辨認上面的獨特筆跡。\n\n高效擴充：字根 script 代表書寫，同源字有 description（描述）、postscript（附言）。\nKK 音標：[skrɪpt] -> 單音節字，scr 結合緊密，pt 輕聲結尾。\n\n常見同義字：\nscreenplay（電影劇本）\nmanuscript（手稿、原稿）\nhandwriting（親筆筆跡）",
  "scroll": "諧音聯想：\n諧音：「死狗肉」，古時候把長卷軸地圖攤開，長得就像長條形的卷軸一樣。\n\n聯想畫面 1：考古學家小心翼翼地將一卷發黃的古代羊皮紙卷軸展開。\n\n聯想畫面 2：用手指在手機螢幕上上下滑動，滾動網頁長文看新聞。\n\n高效擴充：網路時代賦予 scroll 全新動義，指滑鼠滾輪的滾動（scroll down/up）。\nKK 音標：[skrol] -> 單音節字，o 發長雙母音 ou，l 舌尖頂上顎收尾。\n\n常見同義字：\n\nroll（滾動、捲起，較基礎的動作動詞）\n\nparchment（羊皮紙，古老書寫載體）\n\nnavigate（瀏覽、導航，網頁選單操作時常搭配）",
  "scrub": "諧音聯想：\n諧音：死卡爸 -> 諧音：「死卡爸」\n\n諧音聯想：\n諧音：「死卡爸」\n\n聯想畫面 1：爸爸把地板弄得很髒，媽媽用力拿刷子死命擦洗乾淨。\n\n聯想畫面 2：院子裡長滿了雜亂的矮樹叢，看起來像一片荒涼的灌木叢地帶。\n\n高效擴充：注意與rub（摩擦）的字根關聯性。\nKK 音標：[skrʌb] -> 短促的u音，發音時喉頭出力。\n\n常見同義字：\nwash（清洗，一般水洗）\nclean（清潔，廣泛用語）\nbush（灌木，指單株植物）",
  "scruffy": "諧音聯想：\n諧音：死抓飛。\n\n聯想畫面 1：那隻流浪狗看起來邋遢又骯髒，還死抓著飛盤不放。\n\n聯想畫面 2：他穿著破舊的衣服，頭髮亂糟糟的，顯得很不整齊。\n\n高效擴充：與 shabby（破舊的）意思相近。\nKK 音標：[ˋskrʌfi] -> 重音在第一個音節，scr 組合發音要連貫，結尾 fi 輕聲。",
  "scruples": "諧音聯想：\n諧音：「死哭，普勒斯」。\n\n聯想畫面 1：他做壞事時良心不安，死哭著求神普勒斯（保佑），這就是 scruples。\n\n聯想畫面 2：他沒有任何道德顧忌，為了錢什麼都敢做，完全沒有 scruples。\n\n高效擴充：源自拉丁文，原意指鞋子裡的小石頭，引申為讓人不舒服的顧慮。\nKK 音標：[ˋskruplz] -> 第一音節重音，注意 s 的連音。\n\n常見同義字：\n\nHesitation（猶豫，行為表現）\n\nConscience（良心，內在感受）。",
  "scrutinize": "諧音聯想：\n拆解 / 諧音：死酷聽你再\n\n聯想畫面 1：老師死酷地聽你再解釋一遍，同時詳細檢查你的作業內容。\n\n聯想畫面 2：海關人員細緻審查護照，確認每一處細節都沒有問題。\n\n高效擴充：scrutiny 是細看，ize 是動詞結尾，強調極度仔細的審視。\nKK 音標：[ˋskrutə͵naɪz] -> 重音在第一音節 scru，後面的 nize 唸得清晰。\n\n常見同義字：\nexamine（檢查，一般性檢查）\ninspect（視察，強調正式檢查）\nanalyze（分析，強調邏輯拆解）",
  "scuff": "諧音聯想：\n諧音：死卡夫\n\n聯想畫面 1：走路拖著腳，鞋子在地上磨擦發出死卡夫的聲音，鞋底很快就磨損了。\n\n聯想畫面 2：新買的皮鞋不小心在牆上磨出一道擦痕，這道 scuff 讓他心疼不已。\n\n高效擴充：scuff 既指磨損的動作，也指留下的痕跡。\nKK 音標：[skʌf] -> 單音節詞，注意 u 的短母音發音。",
  "sculptor": "諧音聯想：\n諧音：「死考撲頭」，雕刻家死命思考要怎麼在石頭上撲打敲擊出完美的頭部雕像。\n\n聯想畫面 1：藝術工作室裡，雕刻家拿著鑿子全神貫注地雕塑大理石人像。\n\n聯想畫面 2：米開朗作等大師專注於形體創作，成為世人景仰的頂尖雕塑家。\n\n高效擴充：字尾 -or 表示人的職業，動詞為 sculpt（雕刻），字根源自切割。\nKK 音標：[ˋskʌlptɚ] -> 重音在第一音節 sculp，ʌ 發短音屋，tor 唸弱化的 tɚ。\n\n常見同義字：\n\nartist（藝術家，範圍較廣包含畫家與雕塑家）\n\ncarver（木雕師或石雕工匠，強調手工藝技術）\n\ncreator（創作者，泛指所有造物者或發明者）",
  "sculpture": "諧音聯想：\n諧音：「死扛鋪茶」\n\n聯想畫面 1：雕刻家死扛著大理石雕塑品進到展場展出。\n\n聯想畫面 2：藝術公園裡展示著精美的人形雕像與雕刻品。\n\n高效擴充：字根 sculpt 意指雕刻。\nKK 音標：[ˋskʌlptʃɚ] -> 主重音在 skʌl，尾音 ture 發 tʃɚ 的音。\n\n常見同義字：\nstatue（雕像）\ncarving（雕刻品）\nmodel（模型）」}, {",
  "scuttled": "諧音聯想：\n諧音：死卡特。\n\n聯想畫面 1：螃蟹碎步疾跑，像個死卡特（卡住的特務）一樣慌張。\n\n聯想畫面 2：船被故意弄沉，沉入海底。\n\n高效擴充：scuttle 有兩個意思，碎步跑或弄沉船隻。\nKK 音標：[ˋskʌtld] -> 重音在第一個音節，發音要輕快。\n\n常見同義字：\n\nscurried（疾跑）\n\nsunk（弄沉）。",
  "sea": "諧音聯想：\n諧音：「細」\n\n聯想畫面 1：放眼望去是一片無邊無際的海洋，海浪細細地拍打著沙灘。\n\n聯想畫面 2：漁夫出海捕魚，面對洶湧的海面心裡總是既期待又怕受傷害。\n\n高效擴充：與同音字 see 看完全同音，但拼字不同，注意別搞混。\nKK 音標：[si] -> 簡單的單音節，發清脆的高音 i。\n\n常見同義字：\n\nocean（指面積更大的洋，如太平洋、大西洋，比 sea 更廣闊深邃）\nwater（指一般的水或水域，範圍可大可小，日常口語常用）\nmarine（通常指海洋相關的生物或軍種，多作形容詞或特定名詞用）",
  "seafood": "諧音聯想：\n拆解：sea（海洋）＋food（食物）。\n\n聯想畫面 1：去海邊餐廳點了一桌滿滿的魚蝦蟹，這些來自海洋的食物就是海鮮。\n\n聯想畫面 2：台灣人愛吃海鮮，無論是清蒸還是快炒，都是人間美味。\n\n高效擴充：sea 是海洋，food 是食物，組合起來非常直觀。\nKK 音標：[ˋsi͵fud] -> 重音在第一個音節，sea 的 ea 發長音 i。\n\n常見同義字：\n\nshellfish（貝類）\n\ncrustacean（甲殼類）\n\nmarine products（水產品，較正式）。",
  "seagull": "諧音聯想：\n諧音：拆解/諧音：「sea 海洋 + gull 海鷗」\n\n聯想畫面 1：海鷗在海面上翱翔，準備俯衝抓魚。\n\n聯想畫面 2：海岸邊常有成群的海鷗飛過，向遊客討食。\n\n高效擴充：由 sea 與 gull 複合而成，專指海鷗。\nKK 音標：[ˋsi͵ɡʌl] -> 主重音在前音節 si，ɡʌl 念短促的音。\n\n常見同義字：\nbird（鳥類總稱）\nalbatross（信天翁）\ntern（燕鷗）」}, {",
  "seal": "諧音聯想：\n諧音：洗喔 -> 諧音：「洗喔」\n\n諧音聯想：\n諧音：「洗喔」\n\n聯想畫面 1：可愛的海豹在水裡開心玩耍，好像在說洗喔洗喔。\n\n聯想畫面 2：文件上蓋了紅色的官方印章，並且加上火漆封條代表完全密封。\n\n高效擴充：名詞與動詞同形，常出現在商業或法律合約中。\nKK 音標：[sil] -> ea發長音ee，結尾l舌尖頂住上齒齦。\n\n常見同義字：\nstamp（郵票或印章）\nclose（關閉，動詞用法）\nfasten（封口，確保不外洩）",
  "seam": "諧音聯想：\n諧音：心\n\n聯想畫面 1：衣服的縫線處裂開了，就像我的心也跟著裂開一樣。\n\n聯想畫面 2：礦工在煤層中挖掘，尋找隱藏在岩石縫隙裡的礦產。\n\n高效擴充：發音與 seem 相同，但 seam 指實體的縫線或接合處。\nKK 音標：[sim] -> 單音節，長母音 i，發音時嘴角向兩側拉開。\n\n常見同義字：\njoint（接合處，強調連接點）\nlayer（層，強調地層）\nline（線，強調線條）",
  "seamlessly": "諧音聯想：\n諧音：心死理\n\n聯想畫面 1：這兩個系統整合得天衣無縫，完全感覺不到轉換的過程。\n\n聯想畫面 2：他無縫地接手了前任的工作，讓團隊運作完全沒有停頓。\n\n高效擴充：seam 是縫，less 是無，ly 是副詞，指沒有縫隙地順暢進行。\nKK 音標：[ˋsimləsli] -> 重音在第一音節 seam，後面的 lessly 唸得輕快。\n\n常見同義字：\nsmoothly（順利地，強調過程順暢）\nflawlessly（完美地，強調沒有瑕疵）\ncontinuously（持續地，強調不間斷）",
  "search": "諧音聯想：\n諧音：「色起」\n\n聯想畫面 1：警察拿著搜索票在房間內仔細搜查可疑物品。\n\n聯想畫面 2：上網查資料時，在搜尋引擎輸入關鍵字尋找答案。\n\n高效擴充：常用片語 search for 代表尋找某物。\nKK 音標：[sɝtʃ] -> 單音節字，發捲舌的 ɝ 音，結尾是 tʃ。\n\n常見同義字：\n\nlook for（尋找，日常口語常用的片語）\n\nseek（尋求，較正式的追求或尋找）\n\nhunt（搜獵，積極且大規模的尋找）",
  "season": "諧音聯想：\n諧音：「細孫」\n\n聯想畫面 1：阿嬤抱著細孫說，天氣一到秋天這個季節，就要幫細孫多加一件外套。\n\n聯想畫面 2：主廚在料理時，細心將調味料拌入菜餚中，為這道湯品增添豐富的風味。\n\n高效擴充：字尾常接介系詞 in 形成 in season 表示應時、盛產。\nKK 音標：[ˋsizən] -> 重音在第一音節 si，念長音的 i，後半部的 zən 輕輕帶過即可。\n\n常見同義字：\n\nperiod（指一段時間或時期，較抽象且範圍較廣）\n\nflavor（指食物的風味或調味，動詞時與 season 相關）\n\nspice（指香料或調味料，常用作名詞或動詞增添趣味）",
  "seat": "諧音聯想：\n諧音：「吸吐」\n\n聯想畫面 1：一坐上舒適的劇場座椅，觀眾深呼吸吐氣，準備好好欣賞精彩的表演。\n\n聯想畫面 2：服務生引導客人入座，這間餐廳寬敞的空間總共可以容納兩百個座位。\n\n高效擴充：注意與 sit 的差別，sit 是自動詞（坐下），seat 是及物詞（使就座或座位本身）。\nKK 音標：[sit] -> 這是短而清脆的單音節，長音的 i 念得像中文的「細」但尾音收短。\n\n常見同義字：\n\nchair（指一般的椅子，不像 seat 常用於車位、戲院或大眾運輸的座位）\n\nbench（指長凳或公園裡的長椅，通常是木頭或石材製成）\n\nplace（指地方或座位，口語中常用 take a place 或 take a seat 表達請坐）",
  "seated": "諧音聯想：\n諧音：「席特得」，大家都已經入席就坐，獲得了美好的座位。\n\n聯想畫面 1：婚宴會館裡賓客們紛紛就座，等待新人進場。\n\n聯想畫面 2：飛機起飛前空服員確認每位乘客都已經安穩就坐繫好安全帶。\n\n高效擴充：源自名詞 seat 座位與動詞 坐下，變為形容詞。\nKK 音標：[ˋsitɪd] -> 主重音在第一音節 seat，尾音輕念。\n\n常見同義字：\n\nsitting（正坐著的、現任的，強調動作或狀態）\npositioned（安置好的、定位的，較偏向空間擺放）\nestablished（已確立的、已安頓的，較抽象或宏觀）",
  "seats": "諧音聯想：\n諧音：「細吃思」\n\n聯想畫面 1：餐廳裡「細吃思（細細品嚐美食的座位區）」一位難求。\n\n聯想畫面 2：演唱會門票開賣，歌迷搶著購買搖滾區的好座位。\n\n高效擴充：seat 的複數形，指多個椅子或席位。\nKK 音標：[sits] -> 長音 i，結尾 s 發清音，念起來簡短俐落。\n\n常見同義字：\nchair（椅子，指單獨的座位）\nplace（地方，指特定的位置或場所）\nspace（空間，指可容納的範圍或空位）",
  "second": "諧音聯想：\n諧音：「塞肯得」\n\n聯想畫面 1：賽車場上，第二名的選手油門踩到底，緊追在領先者後面，只差了幾秒鐘。\n\n聯想畫面 2：老闆在會議上補充說明，請大家給我幾秒鐘的時間，我有第二個重要提案要報告。\n\n高效擴充：字首 sec- 結合後面的 ond，是日常生活中極高頻的序數與時間單位。\nKK 音標：[ˋsɛkənd] -> 重音在第一音節 sɛ，念短促的 e，後面的 kənd 要輕快帶過。\n\n常見同義字：\n\nmoment（指一瞬間或片刻，與 second 的時間概念相近）\n\nflash（指閃光或一瞬間，常用於形容極短的時間）\n\ninstant（指立即的或瞬間，通常比 second 強調速度極快）",
  "secondary": "拆解：second（第二）＋ ary（字尾）\n\n諧音/拆解：「第二」名雖然也不錯，但畢竟是次要的榮譽。\n\n聯想畫面 1：這場會議我們要討論的主要議題已經結束，接下來談談次要事項。\n\n聯想畫面 2：小明目前就讀國中（secondary school），準備參加升學考試。\n\n高效擴充：從數字 second 衍生，常指次要的、非核心的或中學教育。\nKK 音標：[ˋsɛkən͵dɛri] -> 主重音在第一音節的 sɛk。\n\n常見同義字：\n\nminor（較次要的、輕微的）\nsubsidiary（輔助的、附屬的）\nhigh school（美式中學，英式常對應 secondary school）",
  "secret": "諧音聯想：\n諧音：「死客來得」\n\n聯想畫面 1：這個機密情報千萬不能讓死客來得時候發現，必須嚴格保密。\n\n聯想畫面 2：兩個好朋友互相交換一個只有彼此知道的小秘密。\n\n高效擴充：常與 keep a secret（保守祕密）搭配使用。\nKK 音標：[ˋsikrət] -> 重音在首音節 si，後面的 krət 輕輕帶過。\n\n常見同義字：\n\nconfidential（機密的，商業或官方高度保密的）\n\nhidden（隱藏的，未被發現的狀態）\n\nprivate（私密的，個人的非公開領域）",
  "secretary": "諧音聯想：\n諧音：「細客拉得禮」\n\n聯想畫面 1：董事長的貼身秘書細心地幫忙打理所有行程與禮品。\n\n聯想畫面 2：政府部門的部長與各位高級官員正在開會記錄。\n\n高效擴充：字根 secret（秘密）延伸，指幫忙處理核心事務的人。\nKK 音標：[ˋsɛkrə͵tɛri] -> 重音在首音節 sɛ，美式發音中間的 t 常被弱化。\n\n常見同義字：\n\nassistant（助理，泛指協助主管處理日常事務的人）\n\nclerk（店員或辦事員，處理文書基層人員）\n\nminister（部長，政府內閣閣員）",
  "section": "諧音聯想：\n諧音：「洗克森」\n\n聯想畫面 1：超市裡賣水果的區域被劃分出獨立的一個部分。\n\n聯想畫面 2：這本書的每一個章節都由不同的作者撰寫。\n\n高效擴充：字根 sect 意為「切、割」，與 intersect（相交）同源。\nKK 音標：[ˋsɛkʃən] -> 重音在首音節 sɛk，尾音 ʃən 發「香」的音。\n\n常見同義字：\n\npart（部分，最普遍的組成單位）\n\nchapter（章節，書本或小說的單元）\n\nsegment（片段，圓形或整體中的一部分）",
  "sector": "諧音聯想：\n諧音：「塞車的」\n\n聯想畫面 1：交通尖峰時刻各個主要交通樞紐都大塞車，這也屬於運輸交通部門的管轄區域。\n\n聯想畫面 2：數學課本上正在教導如何把圓形切割成多個扇形面積。\n\n高效擴充：在經濟學中常指公有部門（public sector）或私有部門（private sector）。\nKK 音標：[ˋsɛktɚ] -> 重音在第一音節 sɛk，tor 輕聲帶過。\n\n常見同義字：\nindustry（工業、產業領域）\ndivision（部門、分割線）\nzone（區域、地帶）",
  "secular": "諧音聯想：\n諧音：塞（se）＋ 庫（cu）＋ 啦（lar）\n\n聯想畫面 1：這所學校是非宗教的，把宗教書籍都塞進庫房啦，保持 secular。\n\n聯想畫面 2：現代社會強調世俗化，不被宗教束縛，這就是 secular 的精神。\n\n高效擴充：secular 與 religious 相對，指與宗教無關的世俗事務。\nKK 音標：[ˋsekjələr] -> 重音在第一音節，注意 u 的弱讀。\n\n常見同義字：\nworldly（世俗的，指現實世界）\nnonreligious（非宗教的，直接否定）\ntemporal（暫時的或世俗的，較正式）",
  "secure": "諧音聯想：\n諧音：「死去球」，為了保護這顆珍貴的球，一定要確保它安全穩固。\n\n聯想畫面 1：登山客把安全扣環牢牢扣好，確保攀爬過程安全無虞。\n\n聯想畫面 2：業務員努力加班，終於順利獲得並取得這張大訂單。\n\n高效擴充：字首 se（無、離開）加上 cure（憂慮），沒有憂慮的狀態就是安全安心。\nKK 音標：[sɪˋkjʊr] -> 重音在第二音節 CURE，結尾的 ure 發 yur 的音。\n\n常見同義字：\n\nsafe（安全的，最基礎的形容詞）\n\nfirm（穩固的、堅定的）\n\nobtain（獲得、取得，作為動詞時的常見替代字）",
  "securities": "諧音聯想：\n諧音：吸Q瑞提。\n\n聯想畫面 1：這家公司的 securities 很有價值，大家都想吸Q瑞提（吸引力）。\n\n聯想畫面 2：投資人在證券交易所買賣 securities，希望獲取高額報酬。\n\n高效擴充：secure（安全）+ ities，原本指擔保品，現多指有價證券。\nKK 音標：[sɪˋkjʊrətiz] -> 重音在第二個音節 cur，發音要清楚。\n\n常見同義字：\n\nstocks（股票）\n\nbonds（債券）\n\nassets（資產）。",
  "security": "諧音聯想：\n諧音：誰哭去 -> 諧音：「誰哭去」\n\n諧音聯想：\n諧音：「誰哭去」\n\n聯想畫面 1：機場的保安人員嚴格安檢，讓大家覺得很有安全保障，不用擔心誰哭去。\n\n聯想畫面 2：投資人購買了政府發行的公債證券，換取財務上的安全感。\n\n高效擴充：由形容詞secure加上名詞字尾ity而來。\nKK 音標：[sɪˋkjʊrəti] -> 主重音落在第二音節kyu上，唸起來要有力。\n\n常見同義字：\nsafety（安全，指人身或物理安全）\nprotection（保護，防禦動作）\nguarantee（保證，承諾）",
  "seduce": "諧音聯想：\n諧音：用美色「色誘死」對方，這是一種危險的勾引手段。\n\n聯想畫面 1：犯罪集團派美女用計誘惑富商，藉此套出商業機密。\n\n聯想畫面 2：夜店裡燈光昏黃，男男女女互相用眼神和言語互相勾引。\n\n高效擴充：由字首 se-（離開、引開）加上 duce（引導，源自lead），把人引導歪路。\nKK 音標：[sɪˋdus] -> 主重音在後面的 [ˋdus]，尾音 [s] 清脆收尾。\n\n常見同義字：\ntempt（引誘或誘惑，多指誘發欲望但未必是色情）\nattract（吸引，中性詞，指吸引注意）\nlure（誘惑，常指誘餌或陷阱）",
  "see": "諧音聯想：\n諧音：「吸」\n\n聯想畫面 1：用雙眼用力吸取眼前美麗的風景。\n\n聯想畫面 2：我懂了的英文口語說法 I see，代表心領神會。\n\n高效擴充：過去式為 saw，過去分詞為 seen。\nKK 音標：[si] -> 長音 i，聲音清脆明亮，表達視覺的清晰。\n\n常見同義字：\nobserve（有意識地觀察）\nnotice（注意到、察覺到）\nspot（突然發現或看出某物）",
  "seed": "諧音聯想：\n諧音：「細的」\n\n聯想畫面 1：農夫把「細的」植物種子小心翼翼地埋進土裡，期待它發芽。\n\n聯想畫面 2：蘋果咬到中心，發現裡面有一顆很「細的」籽。\n\n高效擴充：字尾 d 表示結尾，把細小東西種下就是種子。\nKK 音標：[sid] -> 長音的 i，發音時嘴角拉開，像微笑說塞。\n\n常見同義字：\n\npippin（指蘋果等水果的有核果實，較少用）\n\nkernel（指果仁、核心，偏堅果類或抽象核心）\n\ngerm（指細菌或胚芽、萌芽根源）",
  "seek": "諧音聯想：\n諧音：「西客」。\n\n聯想畫面 1：許多西方來的過客四處尋求心靈上的平靜與解答。\n\n聯想畫面 2：求職者在網路上積極尋找適合自己的夢想工作機會。\n\n高效擴充：三態變化為 seek, sought, sought，注意過去式拼法。\nKK 音標：[sik] -> 長音 i，嘴型扁長，氣音從牙縫中輕輕帶出。\n\n常見同義字：\n\nlook for（尋找，最常用的日常片語）\n\nsearch（搜查、搜尋某個區域）\n\npursue（追求，強調長期努力的目標）",
  "seem": "諧音聯想：\n諧音：「細心」\n\n聯想畫面 1：他看起來細心觀察每一個人，似乎掌握了所有線索。\n\n聯想畫面 2：天空陰沉沉的，看起來好像隨時會下大雨。\n\n高效擴充：常與 to be 連用，表達似乎是某種狀態。\nKK 音標：[sim] -> 長音 i，發音平穩，帶有推測的語氣。\n\n常見同義字：\nappear（外表看起來似乎）\nlook（直觀地看起來）\nsound（聽起來似乎）",
  "seemingly": "諧音聯想：\n諧音：「西門林立」\n\n聯想畫面 1：西門町商圈林立著看似熱鬧的店家，但實際上背後店租壓力極大。\n\n聯想畫面 2：這項任務 seemingly 看起來很簡單，實際動手做卻困難重重。\n\n高效擴充：由動詞 seem（似乎）加上 ing 與 ly 轉為副詞，強調表面現象。\nKK 音標：[ˋsimɪŋli] -> 重音在第一音節 ˋsim，後面依序為 -ing-ly。\n\n常見同義字：\n\napparently（顯然地，表面上看起來）\n\nostensibly（表面上、公開宣稱地）\n\nsuperficially（表面上地）",
  "seesaw": "諧音聯想：\n諧音：「喜搜」\n\n聯想畫面 1：兩個小朋友在公園玩蹺蹺板，上下起伏時開心地大喊「喜搜」。\n\n聯想畫面 2：股市價格像蹺蹺板一樣上沖下洗，局勢陷入拉鋸。\n\n高效擴充：由 see（看）加上 saw（鋸子），像鋸木頭時一上一下的動作。\nKK 音標：[ˋsi͵sɔ] -> 主重音在第一個音節 see，念高亢的長音。\n\n常見同義字：\n\nteetertotter（美式口語的蹺蹺板，強調搖晃）\n\nfluctuation（指上下波動、起伏的狀態，較正式）\n\noscillation（指來回擺動、震盪，偏物理或抽象局勢）",
  "seethed": "諧音聯想：\n諧音：洗死。\n\n聯想畫面 1：他心裡憤怒到想把對方洗死，怒火中燒。\n\n聯想畫面 2：滾燙的熱水在鍋子裡翻滾沸騰。\n\n高效擴充：seethe 常與 anger 連用，形容內心翻騰。\nKK 音標：無 -> 單音節，注意 th 的咬舌音。\n\n常見同義字：\n\nboiled（沸騰）\n\nraged（憤怒）\n\nfumed（冒煙/憤怒）。",
  "segment": "諧音聯想：\n諧音：「死給忙得」，大家拼命把市場細分切割，每個人分到一部分都忙得要死。\n\n聯想畫面 1：市場行銷團隊將消費者年齡層精準分割成不同的客群片段。\n\n聯想畫面 2：橘子剝開後分成一瓣一瓣的果肉，每一瓣都是獨立的切片。\n\n高效擴充：字根 seg- 有切開之意（與 section 同源），-ment 為名詞字尾。\nKK 音標：[ˋsɛɡmənt] -> 當名詞時重音在第一音節 sɛg，當動詞時重音常在後方，g 發硬音。\n\n常見同義字：\n\npart（部分，最基礎且通用的詞彙）\n\nsection（部分、部門，強調區域或章節劃分）\n\nportion（部分、一份，多指食物或分配的份額）",
  "segregate": "諧音聯想：\n諧音：誰格格不入就隔離（種族隔離、使分開）\n\n聯想畫面 1：早期歷史課本中描述不同人種在公車上被強制隔離的畫面。\n\n聯想畫面 2：實驗室為了防止細菌交叉感染，必須把不同的樣本嚴格分開放置。\n\n高效擴充：字根 greg 意指群體，字首 se 代表分離，合起來就是把群體隔開。\nKK 音標：[ˋseɡrɪɡeɪt] -> 主重音在第一音節 seg，動詞字尾 ate 發長音 e。\n\n常見同義字：\nseparate（分開、分離，最常用的一般用語）\nisolate（隔離、孤立，強調單獨隔開）\ndivide（分割、劃分）",
  "seize": "諧音聯想：\n諧音：「死雞汁」。\n\n聯想畫面 1：警察眼明手快，一把抓住那個企圖逃跑的小偷。\n\n聯想畫面 2：海關人員在機場當場扣押了走私進口的違禁品。\n\n高效擴充：與 seize 拼法相似的常見字有 size（尺寸），注意 e 的發音差異。\nKK 音標：[siz] -> 長音 i，發音時聲帶震動，像蜜蜂的嗡嗡聲。\n\n常見同義字：\n\ngrab（抓取、強行抓住）\n\ngrasp（緊握、深刻理解）\n\nsnatch（奪取、迅雷不及掩耳地搶過來）",
  "seldom": "諧音聯想：\n諧音：「誰捨得」\n\n聯想畫面 1：這隻昂貴的手錶，誰捨得（Seldom）天天戴著它去工地呢？所以他很少戴。\n\n聯想畫面 2：他工作非常忙碌，幾乎不曾（Seldom）有空陪家人看電影。\n\n高效擴充：表否定含意的副詞，放在動詞前、be動詞後，不與 not 並用。\nKK 音標：[ˋsɛldəm] -> 主重音在 sel，dom 唸輕短的əm音。\n\n常見同義字：\nrarely（罕見地，頻率幾乎一樣低）\ninfrequently（不常地，較正式）\nhardly（幾乎不，常強調程度）",
  "select": "諧音聯想：\n諧音：「奢萊客」\n\n聯想畫面 1：貴賓奢萊客在精品店裡精心地select（挑選）限量包款。\n\n聯想畫面 2：大會從眾多選手中select（選定）出最優秀的代表。\n\n高效擴充：se-（分開、向外）加上 lect（收集），挑出來收集就是選擇。\nKK 音標：[səˋlɛkt] -> 重音在後半的 ˋlɛkt，發音俐落。\n\n常見同義字：\n\nchoose（選擇，最口語常用）\n\npick（挑選，強調用手指取捨）\n\nelect（選舉、投票選出）",
  "selection": "諧音聯想：\n諧音：「洗勒選」\n\n聯想畫面 1：網購衣服時面對琳瑯滿目的款式，你在那邊猶豫不決地挑選。\n\n聯想畫面 2：這本書店的精選文集包含了今年最棒的散文作品。\n\n高效擴充：由動詞 select（挑選）加上 ion 變成名詞。\nKK 音標：[səˋlɛkʃən] -> 重音落在第二音節 lɛk，sə 發輕聲。\n\n常見同義字：\n\nchoice（選擇，個人偏好的決定）\n\noption（選項，可供挑選的備案）\n\nrange（範圍，指商品或項目的多樣性組合）",
  "selective": "諧音聯想：\n諧音：「洗咧客提夫」\n\n聯想畫面 1：老闆挑選員工時非常嚴格篩選，很有選擇性。\n\n聯想畫面 2：這家餐廳對食材來源有高度的挑剔與選擇性。\n\n高效擴充：動詞 select（選擇）加上形容詞字尾 -ive。\nKK 音標：[səˋlɛktɪv] -> 重音在第二音節 lec，注意字尾的發音。\n\n常見同義字：\nchoosy（挑剔的，口語常用）\nfussy（愛挑剔的，吹毛求疵的）\ndiscriminating（有辨識力的，挑選精細的）",
  "self": "諧音聯想：\n諧音：「賽夫」\n\n聯想畫面 1：超人靠「賽夫」（自己）的力量拯救地球，不需要別人幫忙。\n\n聯想畫面 2：照鏡子時，看著鏡中的自己對自己微笑。\n\n高效擴充：常作為複合字字首，如 self-service 自助服務。\nKK 音標：[sɛlf] -> 短促的 e 音，發音時舌頭放平，尾音 l 輕輕頂住上顎。\n\n常見同義字：\n\noneself（泛指自身、自己，常搭配反身代名詞）\n\nego（指自我、自負，偏心理學概念）\n\nidentity（指身份、自我認同）",
  "self-employed": "諧音聯想：\n拆解 / 諧音：賽夫恩普洛伊\n\n聯想畫面 1：他是自由業的，自己聘僱自己，不用看老闆臉色。\n\n聯想畫面 2：這群個體經營者聚集在一起，討論自僱者的稅務問題。\n\n高效擴充：self 是自己，employed 是被聘用，合起來就是自己當老闆。\nKK 音標：[sɛlf ɛmˋplɔɪd] -> 重音在 ploy，發音時注意 self 和 employed 的連讀。\n\n常見同義字：\nfreelance（自由職業者，強調接案）\nindependent contractor（獨立承攬人，法律用語）\nsole proprietor（獨資經營者，商業用語）",
  "selfish": "諧音聯想：\n諧音：「誰是福」\n\n聯想畫面 1：當大家在討論好處要分給誰時，他只想著自己，這種自私的人誰是福氣都不想跟他分享。\n\n聯想畫面 2：小朋友完全不肯把玩具借給別人玩，一個人把全部糖果吃光，表現得很自私。\n\n高效擴充：由名詞 self（自己）加上形容詞字尾 ish（帶有……傾向的）組合而成。\nKK 音標：[ˋsɛlfɪʃ] -> 主重音在第一音節的 [sɛl]，第二音節 [fɪʃ] 輕讀但尾音 [ʃ] 要確實摩擦送氣。\n\n常見同義字：\negotistical（自負的、利己主義的，強調自我中心）\nself-centered（以自我為中心的，凡事只考慮自己感受）\nconsiderate（體貼的、替人著想的，為 selfish 的主要反義字）",
  "sell": "諧音聯想：\n諧音：「誰餓」\n\n聯想畫面 1：夜市攤販大喊誰餓了快來買我的香腸。\n\n聯想畫面 2：業務員成功把最新的智慧型手機銷售出去。\n\n高效擴充：過去式與過去分詞皆為 sold。\nKK 音標：[sɛl] -> 短音 e，嘴型扁平，發音俐落。\n\n常見同義字：\nmarket（推銷或行銷商品）\nvend（在街頭或小販售賣）\nretail（零售商品給消費者）",
  "semester": "諧音聯想：\n諧音：「誰買死他」\n\n聯想畫面 1：大學剛開學的第一個學期，大家都在猜選課註冊費誰買單死他。\n\n聯想畫面 2：經過了漫長的一整個學期，終於迎來了解放的暑假。\n\n高效擴充：通常一年分為上學期（fall semester）與下學期（spring semester）。\nKK 音標：[səˋmɛstɚ] -> 重音在第二音節 mɛst，ɚ 發捲舌音。\n\n常見同義字：\n\nterm（學期，英國學制常用此字）\n\nsession（會期或學期中的某個授課時段）\n\nquarter（季，將一年分為四個學期的制度）",
  "semicircle": "諧音聯想：\n拆解：semi（半）+ circle（圓）\n\n聯想畫面 1：老師在黑板上畫了一個 semicircle，告訴我們這就是圓的一半。\n\n聯想畫面 2：我們圍成一個 semicircle 坐著，這樣每個人都能看到中間的表演。\n\n高效擴充：字首 semi- 代表一半，如 semifinal（準決賽/半決賽）。\nKK 音標：[ˋsemisɝk(ə)l] -> 第一音節 sem 重音，發短促的 e。\n\n常見同義字：\nHalf-circle（直白說法）\nArc（弧，廣義的弧線）\nCurve（曲線，泛指彎曲形狀）",
  "seminar": "諧音聯想：\n諧音：「誰迷娜？」\n\n聯想畫面 1：教授在台前舉辦專題討論會，台下學生紛紛舉手發問說：「到底是誰迷娜（迷戀娜娜）？」\n\n聯想畫面 2：公司周末舉辦業務培訓會與專題討論課，要求全體員工必須準時出席。\n\n高效擴充：字尾 inar 源自種子發芽處，引申為知識萌芽聚集的研討會。\nKK 音標：[ˋsɛmə͵nɑr] -> 重音在第一音節 sɛ，nɑr 發長音。\n\n常見同義字：\nconference（大型正式會議）\nworkshop（工作坊、實作培訓會）\nsymposium（專題討論會、座談會）",
  "senator": "諧音聯想：\n諧音：「誰呢特？」\n\n聯想畫面 1：美國國會裡正在進行激烈辯論，大家都在問：「提案過關的關鍵關鍵票到底是誰呢特？」\n\n聯想畫面 2：這位資深政治家以參議員身份發表重要演說，贏得台下民眾的熱烈掌聲。\n\n高效擴充：字根 sen 代表老、年長，如 senior（學長、資深的），指資深有威望的議員。\nKK 音標：[ˋsɛnətɚ] -> 重音在第一音節 sɛ，後面 natɚ 念輕聲。\n\n常見同義字：\nlegislator（立法委員、議員）\npolitician（政治家、政客）\nelder（長老、長者）",
  "send": "諧音聯想：\n諧音：「先得」\n\n聯想畫面 1：快遞員把包裹先得送到客戶手中才算完成任務。\n\n聯想畫面 2：按下手機的傳送鍵，把訊息發送給遠方的朋友。\n\n高效擴充：過去式與過去分詞皆為 sent，注意 d 改成 t。\nKK 音標：[sɛnd] -> 鼻音 nd 結尾，舌頭輕抵上顎發音。\n\n常見同義字：\ndispatch（派遣人員或發送急件）\ntransmit（傳送訊號或資料）\nforward（轉寄信件或訊息）",
  "senior": "諧音聯想：\n諧音：「希妳歐」\n\n聯想畫面 1：公司裡資深的學長姐帶著新進員工熟悉業務。\n\n聯想畫面 2：大學四年級生即將畢業，被尊稱為學長姐。\n\n高效擴充：與 junior（初級的、大一的）相對應。\nKK 音標：[ˋsinjɚ] -> 主重音在 si，njɚ 要滑順連音。\n\n常見同義字：\nelder（較年長者）\nsuperior（上級、較高階的）\nveteran（老兵、資深專家）」}, {",
  "sensation": "諧音聯想：\n諧音：\\n諧音：「山水射聲」\\n\\n\n\n聯想畫面 1：站在大山水瀑布前，巨大的水聲撞擊耳膜，讓你全身產生震撼的奇妙感覺。\\n\\n\n\n聯想畫面 2：新歌發表會一推出就引起全場轟動，萬人空巷充滿興奮的知覺。\\n\\n\n\n高效擴充：字根 sens 代表感覺，常見衍生字有 sense 和 sensitive。\\n\nKK 音標：[sɛnˋseʃən] -> 主重音在 se，唸長音的ay，尾音 shən 要輕快。\\n\\n\n\n常見同義字：\n\n\\nfeeling（一般日常的感覺與情緒）\\nexcitement（引起轟動的興奮感）\\nperception（偏向知覺與認知理解）",
  "sense": "諧音聯想：\n諧音：「生思」\n\n聯想畫面 1：聞到食物的香味，「生思」出肚子餓的感覺與道理。\n\n聯想畫面 2：走進黑暗的房間，敏銳的感覺察覺到有人在裡面。\n\n高效擴充：字根 sens 代表感覺，衍生出 sensitive 敏感的。\nKK 音標：[sɛns] -> 短促的 e 音，結尾的 ns 要輕輕帶過。\n\n常見同義字：\n\nfeeling（指一般的情感或觸覺，較口語）\n\nperception（指知覺、感知能力，較正式）\n\nmeaning（指意義、道理）",
  "sensible": "拆解：sense（感覺、理智）＋ ible（可...的）\n\n諧音/拆解：很有「理智」的人做決定總是格外明智合理。\n\n聯想畫面 1：主管提出了這個合情理的建議，大家聽了都紛紛點頭稱讚。\n\n聯想畫面 2：在雨天出門記得帶傘，這是一個非常明智的做法。\n\n高效擴充：注意不要與 sensitive（敏感的）搞混，sensible 強調充滿理智與常識。\nKK 音標：[ˋsɛnsəbəl] -> 重音在第一音節的 sɛn，字尾發 bl 的輕聲。\n\n常見同義字：\n\nreasonable（合理的、講道理的）\nwise（明智的、有智慧的）\npractical（切合實際的）",
  "sensitive": "拆解：sense（感覺）＋ itive（易...的）\n\n諧音/拆解：對外界「感覺」很敏銳的人，通常心思也比較敏感。\n\n聯想畫面 1：她的皮膚非常敏感，只要用到成分不對的保養品就會過敏泛紅。\n\n聯想畫面 2：他是一個對批評很敏感的人，別人隨口一句玩笑話他都會走心。\n\n高效擴充：字根 sense 代表感受，itive 代表傾向，指容易受到刺激或影響。\nKK 音標：[ˋsɛnsətɪv] -> 重音在第一音節的 sɛn，tiv 發輕快短促的音。\n\n常見同義字：\n\ndelicate（脆弱敏感的，常指身體或瓷器）\nsusceptible（易受影響的、易過敏的）\nreactive（反應靈敏的）",
  "sensitivity": "諧音聯想：\n諧音：\\n諧音：「誰死踢微踢」\\n\\n\n\n聯想畫面 1：誰去踢微型電視，結果敏感的螢幕馬上破裂，展現出極高的物理敏感性。\\n\\n\n\n聯想畫面 2：女生對於別人無心的一句話感到特別敏感，內心感受性很強。\\n\\n\n\n高效擴充：由形容詞 sensitive 加上名詞字尾 ity 轉變而來。\\n\nKK 音標：[͵sɛnsɪˋtɪvɪti] -> 主重音在 ti，前面的 t 唸輕短，尾音 ty 要俐落。\\n\\n\n\n常見同義字：\n\n\\nsusceptibility（易受影響的感受性）\\nresponsiveness（對外界刺激的反應能力）\\nvulnerability（易受傷害的脆弱敏感度）",
  "sentence": "諧音聯想：\n諧音：「三探死」\n\n聯想畫面 1：法官「三探死」罪犯的犯案動機後，宣判了死刑刑期。\n\n聯想畫面 2：英文老師要求學生用三個單字寫出一個完整的句子。\n\n高效擴充：由 sent（寄出/感受）延伸，把話語組織成句或法律判決。\nKK 音標：[ˋsɛntəns] -> 主重音在第一個音節 sen，後面的 -tence 念輕聲。\n\n常見同義字：\n\nphrase（指片語、詞組，比完整的句小）\n\nperiod（美式英文中指句號，亦可指一段刑期）\n\ncondemnation（指法律上的定罪與宣判，較正式）",
  "sentiment": "諧音聯想：\n諧音：\\n諧音：「誰黏土忙」\\n\\n\n\n聯想畫面 1：誰把黏土揉捏得很忙碌，捏出一個充滿感傷與懷念的童年回憶雕塑。\\n\\n\n\n聯想畫面 2：這部老電影充滿了真摯的情感與個人觀點，讓觀眾看完心裡暖洋洋。\\n\\n\n\n高效擴充：結合 send 感受的字源，指內心情感流露。\\n\nKK 音標：[ˋsɛntəmənt] -> 主重音在首音節 sɛn，後面 ment 要輕聲帶過。\\n\\n\n\n常見同義字：\n\n\\nemotion（泛指一般的情緒與感情）\\nfeeling（日常用語的感受）\\nopinion（個人主觀的觀點與看法）",
  "sentimental": "諧音聯想：\n諧音：「誰聽得悶透了」\n\n聯想畫面 1：聽著老情歌，他變得非常多愁善感、感傷起來。\n\n聯想畫面 2：看著舊照片，滿滿的情感湧上心頭。\n\n高效擴充：由 sentiment（情感）加上形容詞字尾 -al。\nKK 音標：[͵sɛntəˋmɛntəl] -> 主重音在第三音節 men，次重音在開頭。\n\n常見同義字：\nemotional（情緒化的，情感豐富的）\nnostalgic（懷舊的，思鄉的）\nromantic（浪漫的，不切實際的）",
  "sentimentalize": "諧音聯想：\n拆解 / 諧音：三提（senti）＋ 門（men）＋ 塔（tal）＋ 賴（ize）\n\n聯想畫面 1：他對那扇老舊的門感傷地回憶，甚至想把門拆下來帶走，這種感傷的行為就是 sentimentalize。\n\n聯想畫面 2：看著這部電影，他總是忍不住感傷地對待劇中角色，把簡單的情節想得太過感性。\n\n高效擴充：字根 senti 源自 sentiment（情感），加上 ize 變成動詞。\nKK 音標：[͵sentɪˋmentəlaɪz] -> 重音在第三音節 men，注意長母音 i 的發音。",
  "sentry": "諧音聯想：\n諧音：仙吹。\n\n聯想畫面 1：哨兵站在崗哨上，無聊到只能吹口哨，像仙人一樣悠閒。\n\n聯想畫面 2：軍營門口的 sentry 必須時刻保持警覺，不能睡著。\n\n高效擴充：源自 guard 的概念，指站崗的人。\nKK 音標：[ˋsentri] -> 重音在第一個音節，發音短促。\n\n常見同義字：\n\nguard（警衛）\n\nwatchman（看守人）\n\nsentry box（崗哨亭）。",
  "separate": "諧音聯想：\n諧音：「誰怕分了特」\n\n聯想畫面 1：情侶吵架喊著誰怕分了特，氣得當場separate（分開）各自走人。\n\n聯想畫面 2：老師要求把垃圾separate（分類）放進不同的回收桶裡。\n\n高效擴充：字根 se- 代表分離，parate 代表準備，分開準備就是隔離。\nKK 音標：[ˋsɛpɚ͵et] (動詞) / [ˋsɛpərɪt] (形容詞) -> 動詞重音在首音節 ˋsɛp。\n\n常見同義字：\n\ndivide（劃分、分割）\n\ndetach（拆開、分離零件）\n\nisolate（隔離、孤立）",
  "separately": "諧音聯想：\n諧音：「誰怕瑞麗」——瑞麗說她要單獨行動，誰也不用陪她。\n\n聯想畫面 1：結帳時，他們決定把各自買的東西單獨分開付錢。\n\n聯想畫面 2：這兩個檔案必須分別存檔，不能放在同一個資料夾裡。\n\n高效擴充：從 separate（分開的）加上副詞字尾 ly，字根有準備分開的意思。\nKK 音標：[ˋseprətli] -> 重音在 sep，中間的 pra 唸輕聲。\n\n常見同義字：\nindividually（個別地，強調每一個人）\napart（分開地，通常放句尾）\nindependently（獨立地、自主地）",
  "separation": "諧音聯想：\n諧音：誰怕分 -> 諧音：「誰怕分」\n\n諧音聯想：\n諧音：「誰怕分」\n\n聯想畫面 1：情侶在車站面臨離別的分開時刻，彼此依依不捨說著誰怕分開呢。\n\n聯想畫面 2：垃圾分類的垃圾桶把塑膠和紙類清楚分隔開來。\n\n高效擴充：動詞為separate，注意形容詞與名詞拼法的母音變化。\nKK 音標：[͵sɛpɚˋeʃən] -> 主重音在ra的eʃən音節上，注意次重音位置。\n\n常見同義字：\ndivision（分開、部門劃分）\nparting（離別，較文學感）\nsplit（分裂，口語常用）",
  "september": "諧音聯想：\n諧音：「塞撲特包」\n\n聯想畫面 1：九月開學季，學生們「塞撲特包」（把背包塞滿）準備去學校。\n\n聯想畫面 2：九月的秋風吹拂，楓葉開始變紅。\n\n高效擴充：源自拉丁文數字七（septem），因古羅馬曆法中九月是第七個月。\nKK 音標：[sɛpˋtɛmbɚ] -> 主重音在第二個音節 tem，尾音 -ber 要輕輕發輕聲。\n\n常見同義字：\n\nautumn month（秋季月份的統稱）\n\nback-to-school month（美式口語中常將九月與開學季連結）\n\nterm start（指學期開始的月份）",
  "sequence": "諧音聯想：\n諧音：「細尋思」\n\n聯想畫面 1：偵探在案發現場細尋思（仔細尋找思索），把所有線索按順序與次序排列出來。\n\n聯想畫面 2：剪接師將攝影機拍下的一組鏡頭完美串聯，呈現出流暢的連續事件。\n\n高效擴充：字根 sequ 代表跟隨，同源字有 follow、subsequent（隨後的）。\nKK 音標：[ˋsikwəns] -> 重音在第一音節 si，wəns 輕短。\n\n常見同義字：\norder（順序、次序）\nsuccession（連續、繼任）\nseries（系列、連續）",
  "serendipity": "諧音聯想：\n諧音：誰人低皮踢\n\n聯想畫面 1：我在舊書攤隨手翻閱，竟意外發現一本絕版簽名書，這真是 serendipity，運氣好到不行！\n\n聯想畫面 2：科學家在實驗失敗後，卻意外發現了新藥的配方，這種 serendipity 改變了整個醫學界。\n\n高效擴充：這是一個很美的詞，源自波斯童話，指意外發現美好事物的運氣。\nKK 音標：[͵serənˋdɪpəti] -> 重音在第三個音節，發音輕快。\n\n常見同義字：\nfluke（僥倖、意外的成功）\naccident（意外，較中性）\nchance（機會、機緣）",
  "serene": "諧音聯想：\n諧音：「死人音」\n\n聯想畫面 1：深山裡的湖泊安詳寧靜，安靜得像沒有聲音一樣。\n\n聯想畫面 2：她坐在窗前看書，神情非常平靜、毫無波瀾。\n\n高效擴充：形容環境或心境的極度平和與清澈。\nKK 音標：[sɚˋin] -> 重音在第二音節 rene，e 發長音 /i/。\n\n常見同義字：\npeaceful（和平的，安詳的）\ntranquil（平靜的，寧靜的）\ncalm（鎮靜的，風平浪靜的）",
  "serenity": "諧音聯想：\n諧音：「捨離你」\n\n聯想畫面 1：修行者選擇隱居山林捨離你（世俗紛擾），在清晨的陽光中享受無比的平靜與寧靜。\n\n聯想畫面 2：這座湖泊水面波平如鏡又萬里無雲，展現出大自然最晴朗平和的美麗景致。\n\n高效擴充：形容詞為 serene（平靜的、清澈的），常詩意地用來形容心境。\nKK 音標：[sɚˋɛnəti] -> 重音落在第二音節 sɛ，ti 輕輕收尾。\n\n常見同義字：\npeace（和平、平靜）\ntrallquility（寧靜、安寧）\ncalmness（沉著、鎮定）",
  "sergeant": "諧音聯想：\n諧音：\\n諧音：「三根將軍」\\n\\n\n\n聯想畫面 1：軍營裡有三個階級的中士，正在嚴格地接受將軍的訓話與檢視。\\n\\n\n\n聯想畫面 2：警局裡的巡佐帶領著員警巡邏，維護地方治安。\\n\\n\n\n高效擴充：注意拼法中包含 ge 三個字母，容易拼錯。\\n\nKK 音標：[ˋsɑrdʒənt] -> 主重音在首音節 sɑr，ge 則發 dž 的音。\\n\\n\n\n常見同義字：\n\n\\nofficer（軍官或警官的統稱）\\ncommander（指揮官）\\npoliceman（基層員警）",
  "series": "諧音聯想：\n諧音：\\n諧音：「細蕊絲」\\n\\n\n\n聯想畫面 1：細細的絲線一條接一條連續不斷地編織在一起，形成一幅壯觀的刺繡系列。\\n\\n\n\n聯想畫面 2：電視台熱播的一系列連續劇，每天晚上都吸引大批觀眾準時收看。\\n\\n\n\n高效擴充：單複數同形，常與 a series of 連用表示一系列。\\n\nKK 音標：[ˋsɪriz] -> 主重音在首音節 ˋsɪ，尾音 riz 發輕快的 zi 音。\\n\\n\n\n常見同義字：\n\n\\nsequence（事物的先後順序或連續）\\nsuccession（連續、繼承）\\ncollection（收藏品系列）",
  "serious": "諧音聯想：\n諧音：「細蕊斯」\n\n聯想畫面 1：醫生很認真的檢查傷口每一根細微的血管絲。\n\n聯想畫面 2：車禍現場情況相當嚴重，眾人都收起笑容變得嚴肅。\n\n高效擴充：字尾 ious 是常見的形容詞字尾，表示充滿某種特質。\nKK 音標：[ˋsɪriəs] -> 第一音節 ri 重音，注意三音節的唸法。\n\n常見同義字：\n\ngrave（嚴重的、嚴肅的，較正式）\n\nearnest（認真的、誠摯的）\n\nsevere（嚴重的、嚴厲的）",
  "sermon": "諧音聯想：\n諧音：\\n諧音：「死人門」\\n\\n\n\n聯想畫面 1：牧師站在教堂門口，對著信徒進行一場嚴肅的宗教佈道與說教。\\n\\n\n\n聯想畫面 2：爸爸又開始長篇大論地說教，像是在念一場沒完沒了的冗長佈道。\\n\\n\n\n高效擴充：字尾 mon 與講話 talk 有關聯想。\\n\nKK 音標：[ˋsɝmən] -> 主重音在首音節 ˋsɝ，捲舌音要確實。\\n\\n\n\n常見同義字：\n\n\\npreaching（牧師的講道與說教）\\nlecture（冗長的訓話或演講）\\nspeech（一般的公開演說）",
  "servant": "諧音聯想：\n諧音：「誰服穩得」\n\n聯想畫面 1：古代城堡裡的忠心僕人把家務打理得服服貼貼。\n\n聯想畫面 2：現代企業裡的基層僱員也是為公司服務的勞動者。\n\n高效擴充：源自 serve（服務）這個動詞，加上 ant 變成指人的名詞。\nKK 音標：[ˋsɝvənt] -> 重音在首音節 sɝ，vənt 輕聲念。\n\n常見同義字：\n\nmaid（女僕，專指女性家事幫傭）\n\nemployee（僱員，公司裡的受雇工作者）\n\nattendant（服務員，公共場所的接待或服務人員）",
  "serve": "諧音聯想：\n諧音：「色餓夫」\n\n聯想畫面 1：餐廳裡熱心的服務生正在為客人供應美味佳餚。\n\n聯想畫面 2：軍人光榮入伍服役，為國家奉獻心力。\n\n高效擴充：名詞為 service（服務），常見於各類客服場所。\nKK 音標：[sɝv] -> 捲舌音 ɝ，發音低沉厚實。\n\n常見同義字：\nattend（照料、照顧顧客）\nprovide（提供所需物品）\ndeliver（遞送或履行承諾）",
  "server": "諧音聯想：\n諧音：\\n諧音：「色夫」\\n\\n\n\n聯想畫面 1：餐廳裡穿著制服的帥氣男服務生，正端著托盤為客人送上美味的餐點。\\n\\n\n\n聯想畫面 2：機房裡運轉中的電腦伺服器，正默默地為全球網路提供資料服務。\\n\\n\n\n高效擴充：由動詞 serve 服務加上 er 變成執行者或設備。\\n\nKK 音標：[ˋsɝvɚ] -> 主重音在首音節 ˋsɝ，vɚ 輕聲帶過。\\n\\n\n\n常見同義字：\n\n\\nwaiter（餐廳男服務生）\\nhost（主機或主人）\\nattendant（服務員）",
  "service": "諧音聯想：\n諧音：「塞車不避死」，交通警察在大太陽底下指揮交通，提供用路人最辛苦的「服務」。\n\n聯想畫面 1：你去餐廳吃飯，服務生端上熱騰騰的餐飲，臉上帶著親切的微笑。\n\n聯想畫面 2：車子開到修車廠，師傅熟練地幫引擎進行定期維修與保養。\n\n高效擴充：字根 serv 代表保護、服從，衍伸出奴隸 servant 與服務 service。\nKK 音標：[ˋsɝvəs] -> 第一音節重音在 sɝ，唸長音的「色ㄦˊ」，第二音節vəs要輕短唸成「微斯」。\n\n常見同義字：\n\nassistance（協助與幫忙，通常指具體的援助）\n\nmaintenance（保養與維修，偏向機械設備方面）\n\nutility（公用事業服務，如水電瓦斯等）",
  "serving": "諧音聯想：\n諧音：取自「奢溫」的聯想\n\n聯想畫面 1：服務生端著熱騰騰的佳餚上桌，貼心地為客人提供美味的一人份餐點。\n\n聯想畫面 2：這位軍官目前仍然在部隊服役，擔任重要的前線防衛任務。\n\n高效擴充：由動詞 serve（服務、供應）加上 ing 形成的複合用法，可當名詞或形容詞。\nKK 音標：[ˋsɝvɪŋ] -> 重音在第一音節 sɝ，vɪŋ 鼻音收尾。\n\n常見同義字：\nportion（一份、部分，餐點常用）\nhelping（幫忙、一份食物）\nactive duty（現役服役狀態）",
  "session": "諧音聯想：\n諧音：誰審。\n\n聯想畫面 1：法官在法庭的開庭審理中，大聲問大家這場 session 到底是誰審的。\n\n聯想畫面 2：學校舉辦講習會時，大家在一小時的 session 內專心聽講。\n\n高效擴充：源自拉丁文坐著，指開會坐在一起的時間。\nKK 音標：[ˋsɛʃən] -> 重音在第一音節的 sè，唸輕短。\n\n常見同義字：\n\nmeeting（一般會議）\n\nconference（正式大型會議）\n\nhearing（聽證會或開庭審理）。",
  "set": "諧音聯想：\n諧音：「賽特」，你在打電動時把遊戲難度「設置」好，準備開始挑戰魔王賽特。\n\n聯想畫面 1：你把剛買好的整套精美茶具小心翼翼地擺放在客廳桌上。\n\n聯想畫面 2：太陽緩緩下山，夕陽西下固定在水平線的那一端。\n\n高效擴充：三態同形為 set, set, set，常用片語有 set up 建立與 set off 出發。\nKK 音標：[sɛt] -> 短促有力的單音節，嘴形微張唸短 e 的「塞特」，t 輕輕帶過不發出大聲。\n\n常見同義字：\n\nput（放置與擺放，最基本的動作動詞）\n\nplace（安置，比 put 稍微正式一點）\n\ncollection（一套或收藏品，作名詞時的同義概念）",
  "setback": "諧音聯想：\n諧音：設悲客。\n\n聯想畫面 1：創業路上遇到挫折，計畫被 setback 阻礙，好像老天故意幫悲傷的客人設定障礙。\n\n聯想畫面 2：經濟倒退讓老闆大嘆每一步都是 setback。\n\n高效擴充：set 放與 back 回，把進度往後放就是倒退與挫折。\nKK 音標：[ˋsɛt͵bæk] -> 兩個音節都有重音，sèt-bæk 都要唸清晰。\n\n常見同義字：\n\nobstacle（障礙物）\n\nfailure（失敗）\n\nsetback（指進展受阻的挫折）。",
  "setting": "諧音聯想：\n諧音：\\n諧音：「設停」\\n\\n\n\n聯想畫面 1：工程師在手機裡設定好自動停止的時間，完成安裝與參數設定。\\n\\n\n\n聯想畫面 2：這部小說以中世紀古城堡為故事背景與背景環境。\\n\\n\n\n高效擴充：由 set 放置衍生而來，指周遭環境或參數設定。\\n\nKK 音標：[ˋsɛtɪŋ] -> 主重音在首音節 ˋsɛ，尾音 tɪŋ 輕巧。\\n\\n\n\n常見同義字：\n\n\\nenvironment（周遭環境）\\nbackground（故事發生的背景）\\nconfiguration（電腦系統的配置設定）",
  "settle": "諧音聯想：\n諧音：「設頭」\n\n聯想畫面 1：移民一家人終於在異鄉設頭建立家園，順利安頓（settle）下來。\n\n聯想畫面 2：雙方律師開會協商，終於成功settle（解決）了這場官司糾紛。\n\n高效擴充：seat（座位）的變體，坐定位置就是安頓與解決。\nKK 音標：[ˋsɛtəl] -> 重音在首音節 ˋsɛt，尾音帶輕快的 l 音。\n\n常見同義字：\n\nresolve（解決問題、消除歧見）\n\ndecide（做決定、下定論）\n\nestablish（確立、建立）",
  "settled": "諧音聯想：\n諧音：「誰特了」\n\n聯想畫面 1：這場糾紛終於解決了，大家心裡都覺得「誰特了」（誰妥協了），事情終於定下來了。\n\n聯想畫面 2：他們在鄉下買了房子，決定在那裡定居（settled）下來，過著穩定的生活。\n\n高效擴充：settle 原意是坐下，引申為安定、解決問題。\nKK 音標：[ˋsetld] -> 第一音節重音，注意結尾的 ld 輕聲帶過。\n\n常見同義字：\n\nresolved（解決的，強調紛爭）\n\nstable（穩定的，強調狀態）\n\nfixed（確定的，強調不可變）",
  "settlement": "諧音聯想：\n諧音：「塞特買悶特」商量好後，大家把心裡的悶氣塞特（塞住）並買單解決。\n\n聯想畫面 1：兩國代表在會議桌上簽署和平協議，終於結束了長期的紛爭與清算。\n\n聯想畫面 2：移民在荒野中搭起帳篷，建立了一個溫馨的小定居點。\n\n高效擴充：由動詞 settle（安居、解決）加上名詞字尾 ment 組合而成。\nKK 音標：[ˋsɛtəlmənt] -> 第一音節重音在 sět，後面念輕短的 təl-mənt。\n\n常見同義字：\nagreement（協議，偏向正式合約）\nresolution（解決，偏向問題的化解）\npayment（清算，偏向財務付款）",
  "settler": "諧音聯想：\n諧音：「塞特勒」\n\n聯想畫面 1：大批移居者來到新大陸建立定居點。\n\n聯想畫面 2：開拓者們合力在荒野中搭建木屋。\n\n高效擴充：來自動詞 settle（定居），加上 er 成為指人的名詞。\nKK 音標：[ˋsɛtəlɚ] -> 主重音在 sɛt，təlɚ 輕快帶過。\n\n常見同義字：\npioneer（先驅、開拓者）\ncolonist（殖民者）\nresident（居民）」}, {",
  "setup": "諧音聯想：\n諧音：誰特阿\n\n聯想畫面 1：這家公司的組織體制是誰特阿？設計得這麼複雜。\n\n聯想畫面 2：我們需要調整一下組織方式，才能讓團隊運作更有效率。\n\n高效擴充：set 是設定，up 是向上，指建立起來的架構或體制。\nKK 音標：[ˋsɛt͵ʌp] -> 重音在第一音節 set，up 唸得短促有力。\n\n常見同義字：\nstructure（結構，強調組織框架）\norganization（組織，強調機構）\nsystem（系統，強調運作方式）",
  "seven": "諧音聯想：\n諧音：「死人」，台灣人常說鬼月或農曆七月（seven）特別多禁忌，要小心平安。\n\n聯想畫面 1：你走進巷口的統一超商買東西，招牌上大大的 7 數字非常醒目。\n\n聯想畫面 2：幸運輪盤轉到了數字七，全場開心地歡呼中大獎了。\n\n高效擴充：基本數字字彙，衍生詞有 seventieth 七十與 seventeen 十七。\nKK 音標：[ˋsɛvən] -> 重音在第一音節 sɛv，唸清脆的「塞」，v 輕咬下唇，ən 念輕短的「恩」。\n\n常見同義字：\n\nseventh（第七，為其序數詞形態）\n\nsevens（七點或多個七，用於撲克或骰子遊戲）\n\nheptad（七個一组，較少見的學術用詞）",
  "seventeen": "諧音聯想：\n諧音：「細分、聽」\n\n聯想畫面 1：老師把十七顆糖果細分給學生，大家圍在一起認真聽。\n\n聯想畫面 2：青少女雜誌封面寫著十七歲的祕密，吸引大家買來翻閱。\n\n高效擴充：字尾 teen 代表十幾，由 seven（七）加上 teen 組合成十七。\nKK 音標：[ˋsɛvənˋtin] -> 主重音在尾音 teen，發音要拉長且有力。\n\n常見同義字：\nseventeenth（第十七，具序數詞特性）\nteens（十幾歲，泛指 13 到 19 歲的青少數學齡期）\nadolescent（青少年，指生理與心理正在發育的較正式用法）",
  "seventy": "諧音聯想：\n諧音：「細分、T 恤」\n\n聯想畫面 1：老爺爺把七十件 T 恤細分顏色，整齊排在夜市攤位上。\n\n聯想畫面 2：七十歲的阿公穿著潮流 T 恤在公園大跳街舞。\n\n高效擴充：字尾 ty 代表幾十，由 seven（七）去掉尾音加上 ty 變成七十。\nKK 音標：[ˋsɛvənti] -> 主重音在第一個音節 sɛ，唸的時候舌頭要放鬆。\n\n常見同義字：\nseventieth（第七十，表示順序或第 70 週年）\nseventies（七十年代，指 70 歲至 79 歲或西元 70 年代）\nseptuagenarian（七旬老人，用於新聞或較正式的年齡描述）",
  "several": "諧音聯想：\n諧音：「色敷了」\n\n聯想畫面 1：敷面膜選了「色敷了」好幾款顏色，一次敷「幾個」不同顏色的面膜在臉上。\n\n聯想畫面 2：朋友買了「幾個」不同口味的蛋糕，大家「各自」挑選喜歡的來吃。\n\n高效擴充：字根 sev 有分開之意，引申為幾個分開且不同的個體。\nKK 音標：[ˋsɛvrəl] -> 重音在第一音節，發音時注意[ɛ]音要自然張開嘴巴。\n\n常見同義字：\n\nsome（一些，數量較不確定，可用於可數與不可數名詞）\n\na few（好幾個，專用於可數名詞，含肯定意味）\n\na number of（一些、若干，後接複數名詞與複數動詞）",
  "severe": "諧音聯想：\n諧音：「死微兒」感冒，病情變得十分嚴重。\n\n聯想畫面 1：颱風過境帶來豪雨，造成山區道路嚴重坍方。\n\n聯想畫面 2：主管在會議上大發雷霆，對這次的失誤給予極為嚴厲的批評。\n\n高效擴充：字尾 ere 發 [ɪr] 的音，注意與 several (幾個) 的拼法區分。\nKK 音標：[səˋvɪr] -> 第二音節 vɪr 為主重音，發音要拉長。\n\n常見同義字：\nserious（嚴重的、嚴肅的，最普遍使用的同義字）\ngrave（嚴重的、嚴峻的，通常形容局勢或病情危急）\nharsh（嚴厲的、刺耳的，常形容懲罰或環境惡劣）",
  "severely": "諧音聯想：\n諧音：誰威爾力\n\n聯想畫面 1：誰威爾力氣這麼大？竟然嚴重地破壞了這道牆。\n\n聯想畫面 2：因為天氣劇烈變化，航班被嚴重地延誤了。\n\n高效擴充：severe 是嚴重的，加上 ly 變成副詞，強調程度非常深。\nKK 音標：[səˋvɪrli] -> 重音在第二音節 vere，發音時注意捲舌音。\n\n常見同義字：\nseriously（嚴重地，強調後果）\ndrastically（劇烈地，強調改變幅度）\nharshly（嚴厲地，強調態度）",
  "sew": "諧音聯想：\n諧音：「手」\n\n聯想畫面 1：用「手」拿起針線，細心地把破掉的衣服縫製好。\n\n聯想畫面 2：阿嬤手巧，常常坐在客廳親手縫補孫子的褲子。\n\n高效擴充：字尾常接 up（sew up 縫合、包辦），注意三態變化為 sew, sewed, sewn。\nKK 音標：[so] -> 發長音的歐（o），嘴型由開到圓，注意和 saw 區分。\n\n常見同義字：\n\nstitch（用針線縫合，強調一針一線的動作）\n\nrepair（修理物品，範圍較廣不限衣物）\n\nmend（修補破損處，常指補破洞或補鞋）",
  "sewage": "諧音聯想：\n諧音：水汙。\n\n聯想畫面 1：城市地下的管線裡流動著大量的 sewage，那是我們生活產生的汙水。\n\n聯想畫面 2：走在路上聞到一股難聞的氣味，原來是旁邊的汙水處理廠正在排放 sewage。\n\n高效擴充：sew（縫紉）與此字無關，源自古法語，聯想 sewer 下水道。\nKK 音標：[ˋsuɪdʒ] -> 第一音節重音，注意 su 的長音。\n\n常見同義字：\n\nwastewater（廢水，較科學）\n\neffluent（流出物，工業用語）\n\nfilth（汙物，強調髒亂）。",
  "sewer": "諧音聯想：\n諧音：蘇爾。\n\n聯想畫面 1：蘇爾不小心把手機掉進 sewer 下水道，只好找工人來清理污水管。\n\n聯想畫面 2：城市地下密布著惡臭的 sewer。\n\n高效擴充：由動詞 sew 縫紉延伸，指把水道縫合連接起來的地下系統。\nKK 音標：[ˋssuɚ] -> 發音注意 su 音要長，r 捲舌。\n\n常見同義字：\n\ndrain（排水管）\n\npipe（管道）\n\ngutter（街溝）。",
  "sex": "諧音聯想：\n諧音：色克絲 -> 諧音：「色克絲」\n\n諧音聯想：\n諧音：「色克絲」\n\n聯想畫面 1：填寫履歷表時，第一欄就要勾選自己的生理性別。\n\n聯想畫面 2：寵物店老闆熟練地辨識剛出生的黃色小雞到底是雌是雄的性別。\n\n高效擴充：字尾x發ks的複合音，注意複數變化。\nKK 音標：[sɛks] -> 短促的e音加上清晰的ks結尾。\n\n常見同義字：\ngender（社會性別，強調心理或社會角色）\nintercourse（性交，較正式或醫學用語）\nidentity（身分，常與性別連用）",
  "sexual": "拆解：sex（性）＋ ual（形容詞字尾）\n\n諧音/拆解：含有「性」別或兩性相關的健康教育課程。\n\n聯想畫面 1：學校健康教育課向學生宣導正確的兩性交往與性教育觀念。\n\n聯想畫面 2：法律嚴格禁止任何形式的職場性騷擾行為。\n\n高效擴充：由名詞 sex 衍生，用來修飾與兩性或性關係相關的事物。\nKK 音標：[ˋsɛkʃuəl] -> 重音在第一音節的 sɛk，中間的 xh 音拼作 kʃu。\n\n常見同義字：\n\ngenital（生殖器的）\nreproductive（生殖的）\nbiological（生物學的、兩性生理的）",
  "sexy": "諧音聯想：\n諧音：穿著「洗洗吸」睛洋裝的模特兒非常性感迷人。\n\n聯想畫面 1：女明星在紅毯上展現出自信迷人又性感的姿態。\n\n聯想畫面 2：這台跑車的流線型設計實在太吸睛、太性感了。\n\n高效擴充：由 sex 加上 y 轉變而來的口語形容詞，現代也常引申形容事物極具魅力。\nKK 音標：[ˋsɛksi] -> 重音在第一音節的 sɛk，結尾的 y 發長 i 音。\n\n常見同義字：\n\nattractive（具吸引力的、迷人的）\nalluring（誘人的、引人入勝的）\nglamorous（充滿魅力的、富有明星風采的）",
  "shabby": "諧音聯想：\n諧音：夏比 -> 諧音聯想：夏天比較破爛的衣服。\n\n聯想畫面 1：流浪漢在夏天穿著一件破爛不堪的舊外套。\n\n聯想畫面 2：這棟老房子外牆剝落，看起來非常破舊。\n\n高效擴充：由形容詞字尾 y 結合破舊外觀來記。\nKK 音標：[ˋʃæbi] -> 重音在第一音節，ʃæ 發扁口型短æ，bi 發長 i。\n\n常見同義字：\n\nragged（衣衫襤褸的）\n\nrun-down（破舊失修的）\n\nshabby-chic（帶有復古破舊風格的，常用於裝潢）",
  "shackles": "諧音聯想：\n諧音：「歇客了，因為被手銬腳鐐給綁住」\n\n聯想畫面 1：犯人双手被警察銬上金屬手銬與卸扣，完全無法逃跑。\n\n聯想畫面 2：法規與傳統觀念成了企業發展的無形桎梏與枷鎖。\n\n高效擴充：shackle 的複數形，技術上也可指工程用的 U 形環卸扣。\nKK 音標：[ˋʃæklz] -> 第一音節 shack- 重音，æ 發嘴扁的短音。\n\n常見同義字：\n\nfetters（枷鎖，偏文學文雅）\n\nhandcuffs（手銬，專指警察用具）\n\nconstraints（限制、束縛）",
  "shade": "諧音聯想：\n諧音：歇得 -> 諧音：「歇得」\n\n諧音聯想：\n諧音：「歇得」\n\n聯想畫面 1：大熱天大家都跑去大樹下的背陰處歇得涼快。\n\n聯想畫面 2：畫家拿起鉛筆在素描紙的邊緣輕輕描黑，做出陰影層次。\n\n高效擴充：字尾加ow就變成shadow（影子）。\nKK 音標：[ʃed] -> 雙唇由微開轉為微笑狀，發長音a。\n\n常見同義字：\nshadow（影子，有具體輪廓）\nshelter（避難所，遮蔽處）\ntint（色度，顏色的深淺）",
  "shadow": "諧音聯想：\n諧音：歇得好 -> 諧音：「歇得好」\n\n諧音聯想：\n諧音：「歇得好」\n\n聯想畫面 1：路燈把行人的影子拉得好長，安靜地投射在地面上。\n\n聯想畫面 2：私家偵探戴著墨鏡，在大街上暗地跟蹤嫌疑犯。\n\n高效擴充：由shade加上ow字尾延伸而來的名詞與動詞。\nKK 音標：[ˋʃæd͵o] -> 重音在第一個音節shad上，ow發o的音。\n\n常見同義字：\nsilhouette（剪影，指輪廓）\ntrail（跟蹤，動詞用法）\nfollower（追隨者）",
  "shady": "諧音聯想：\n諧音：在樹下「歇地」方剛好有陰涼的大樹遮陽。\n\n聯想畫面 1：炎熱的夏天下午，大家都喜歡躲在公園大樹的陰涼處乘涼。\n\n聯想畫面 2：那個男人的行蹤鬼鬼祟祟，看起來十分可疑。\n\n高效擴充：名詞 shade（陰影）加上 y 變成形容詞，既可指物理上的陰涼，也可引申為心懷鬼胎的可疑。\nKK 音標：[ˋʃedi] -> 重音在第一音節的 ʃe，a 發長音的 ei。\n\n常見同義字：\n\nshadowy（有陰影的、模糊不清的）\nsuspicious（可疑的、讓人起疑心的）\ndark（陰暗的）",
  "shaft": "諧音聯想：\n諧音：「誰會服」\n\n聯想畫面 1：礦工誰會服氣？大家每天都要搭乘狹窄的豎井升降梯深入地底下工作。\n\n聯想畫面 2：騎士手中的長矛、弓箭杆與馬車轅，以及機器的轉動軸心都完美打造。\n\n高效擴充：單音節名詞，可當工具柄、通風井或機器的軸，俚語中也帶有粗俗意涵。\nKK 音標：[ʃæft] -> 單音節字，ʃ 發嘘聲，æ 嘴巴張大，ft 結尾氣音要俐落。\n\n常見同義字：\nshaft 相關搭配詞：\nvertical shaft（垂直豎井，常出現在工程與電梯領域）\ndrive shaft（傳動軸，常見於汽車與機械工程）\ntool shaft（工具柄，指鎚子或斧頭的握把部分）",
  "shake": "諧音聯想：\n諧音：「雪客」\n\n聯想畫面 1：手搖飲店員用力搖動雪克杯，調製美味的巧克力奶昔。\n\n聯想畫面 2：地震來襲時地面劇烈搖晃，桌上的水杯也跟著抖動。\n\n高效擴充：字尾 ake 的發音規律，與 cake、lake 同韻，去 e 加 s 變化動詞三單。\nKK 音標：[ʃek] -> 複合子音 ʃ 發噓聲，母音 ek 需由大口型滑向扁平。\n\n常見同義字：\ntremble（顫抖，通常因寒冷、恐懼而發抖）\nshiver（打顫，多指身體因冷或生病而微微發抖）\nvibrate（震動，多指機械或手機發出的規律震動）",
  "shall": "諧音聯想：\n諧音：「雪」花降落\n\n聯想畫面 1：氣象預報說今晚山區將會下雪，我們明天要不要一起去賞雪呢？\n\n聯想畫面 2：雪花大片落下時，所有車輛必須減速慢行以確保安全。\n\n高效擴充：主要用於第一人稱 I 或 we 的未來式，或在疑問句中提出建議與詢問意願。\nKK 音標：[ʃæl] -> 字首 sh 發噓的摩擦音，搭配大口張開的短母音 æ。\n\n常見同義字：\nwill（將會，最常用的未來式助動詞，用於各種人稱）\nshould（應該，shall 的過去式，常用於表示義務或建議）\nwould（將會或願意，will 的過去式，語氣較客氣委婉）",
  "shallow": "諧音聯想：\n諧音：「蝦露」\n\n聯想畫面 1：一隻小蝦子露出一半身體在很淺的水面上，水剛好淹過它的眼睛。\n\n聯想畫面 2：這個人看事情只看表面，就像在淺水灘玩水一樣膚淺。\n\n高效擴充：字尾 ow 常出現在形容形狀或狀態的單字中。\nKK 音標：[ˋʃælo] -> 重音在第一音節，發短促的 æ 與圓唇的 o 音。\n\n常見同義字：\nsuperficial（膚淺的、表面的，較正式）\nsurface（表面的，常用作複合字或名詞）\nskin-deep（膚淺的、僅及於皮毛的）",
  "shame": "諧音聯想：\n諧音：誰美 -> 諧音：「誰美」\n\n諧音聯想：\n諧音：「誰美」\n\n聯想畫面 1：選美比賽中落敗的人感到十分羞恥與丟臉，覺得自己比不上別人。\n\n聯想畫面 2：下雨天本來計畫好的野餐取消了，大家異口同聲說真可惜啊。\n\n高效擴充：常用片語What a shame來表達惋惜。\nKK 音標：[ʃem] -> 發音時嘴型由開到扁，長音a。\n\n常見同義字：\ndisgrace（恥辱，較嚴重）\nembarrassment（尷尬）\npity（遺憾、可惜）",
  "shameful": "諧音聯想：\n諧音：「歇幕符」號一出，這場表現糟糕的演出實在太可恥了。\n\n聯想畫面 1：他在比賽中作弊被抓包，低頭承認這個行為非常丟臉。\n\n聯想畫面 2：選手的運動家精神崩壞，做出令人髮指的卑劣舉動。\n\n高效擴充：由 shame (羞恥) 加上 ful (充滿...) 組成，指充滿羞恥感的。\nKK 音標：[ˋʃemfəl] -> 第一音節 ʃem 為主重音，長音 ㄟ 要到位。\n\n常見同義字：\ndisgraceful（不名譽的、可恥的，指敗壞名聲）\nhumiliating（使人丟臉的、羞辱性的，強調心理受挫感）\nscandalous（可恥的、醜聞般的，指違背道德倫理）",
  "shamelessness": "諧音聯想：\n拆解：shame（羞恥）+ less（無）+ ness（名詞字尾）\n\n聯想畫面 1：他竟然在大庭廣眾之下撒謊，這種無恥的行為讓人感到震驚。\n\n聯想畫面 2：政客為了選票不擇手段，展現出極致的厚顏無恥。\n\n高效擴充：shame 是羞恥，less 是沒有，合起來就是沒有羞恥心。\nKK 音標：[ˋʃeɪmləsnəs] -> 重音在第一音節，發音要強調 shame。\n\n常見同義字：\n\naudacity（大膽，有時指厚顏無恥的冒險）\n\nimpudence（放肆，指無禮的態度）\n\nbrazenness（厚顏無恥，指像黃銅一樣硬的臉皮）",
  "shampoo": "諧音聯想：\n諧音：洗髮鋪 -> 諧音：「洗髮鋪」\n\n諧音聯想：\n諧音：「洗髮鋪」\n\n聯想畫面 1：走進美髮店的洗髮鋪，櫃子上擺滿了各式各樣的洗髮精香波。\n\n聯想畫面 2：設計師用香波幫客人仔細地洗頭，洗出滿頭的綿密泡沫。\n\n高效擴充：字首sham源自印度語，poo代表壓擠的動作。\nKK 音標：[ʃæmˋpu] -> 主重音在第二音節pu上，尾音拉長。\n\n常見同義字：\nsoap（肥皂，一般清潔用品）\nwash（清洗，動詞）\nconditioner（潤絲精，常與洗髮精並用）",
  "shape": "諧音聯想：\n諧音：「學步」\n\n聯想畫面 1：小baby在學步時，雙腳踏出的步伐正在形塑他未來的走路姿態。\n\n聯想畫面 2：捏陶土時透過不斷學步般的推擠與調整，最後塑造出完美的形狀。\n\n高效擴充：字尾結合 e 形成發音變化，常與 form 搭配理解。\nKK 音標：[ʃep] -> 重音在前面的長母音 e，嘴型由大漸扁。\n\n常見同義字：\nform（指具體的實體外形，較中性）\nfigure（強調輪廓或數字身形，常指人體）\noutline（指外框線條，較偏向輪廓勾勒）",
  "shard": "諧音聯想：\n諧音：蝦的。\n\n聯想畫面 1：打破的玻璃杯碎片，像蝦的殼一樣尖銳，踩到會受傷。\n\n聯想畫面 2：數據庫分片技術把龐大的資料切成碎片，以便更有效率地處理。\n\n高效擴充：常用於形容玻璃、陶瓷等硬脆物體的碎片。\nKK 音標：[ʃɑrd] -> 單音節字，注意 ar 的捲舌音。\n\n常見同義字：\n\nfragment（碎片，較正式）\n\npiece（塊，通用）\n\nsplinter（木刺或細長碎片）。",
  "share": "諧音聯想：\n諧音：「雪兒」大方地把冰淇淋分給朋友吃，大家一起分享。\n\n聯想畫面 1：同事們在會議室裡共同分擔一份繁重的工作專案與責任。\n\n聯想畫面 2：股市投資人在看盤軟體上查看自己持有的公司股份與股票獲利。\n\n高效擴充：可作動詞與名詞，常見片語有 share with（與...分享）。\nKK 音標：[ʃɛr] -> 單音節字，長母音 ɛr 嘴型微張扁平。\n\n常見同義字：\ndivide（分開，偏向分割）\nportion（部分，偏向分配到的份額）\nstock（股票，偏向金融資產）",
  "shareholder": "諧音聯想：\n拆解 / 諧音：誰後德\n\n聯想畫面 1：誰後德？這家公司的股東們正在開會討論獲利分配。\n\n聯想畫面 2：作為股票持有者，他非常關心公司每季的財報表現。\n\n高效擴充：share 是股份，holder 是持有者，合起來就是股東。\nKK 音標：[ˋʃɛr͵holdɚ] -> 重音在第一音節 share，後面的 holder 唸得清晰。\n\n常見同義字：\nstockholder（股票持有者，同義）\ninvestor（投資者，範圍較廣）\npartner（合夥人，強調共同經營）",
  "shares": "諧音聯想：\n諧音：誰（sha）＋惹（res）\n\n聯想畫面 1：公司發行股票（shares），大家都在爭搶買入。\n\n聯想畫面 2：他很慷慨，總是願意分享（shares）自己的零食給同學。\n\n高效擴充：share 當名詞時常指股份，動詞則是分享或分擔。\nKK 音標：[ʃer] -> sh 發出噓聲，er 發音時舌根微抬。",
  "shark": "諧音聯想：\n諧音：「殺客」\n\n聯想畫面 1：海中霸王鯊魚張開大口，就像一個專門在海裡殺客的兇猛獵人。\n\n聯想畫面 2：金融市場上的投機者像鯊魚一樣狠心殺客，大賺一筆。\n\n高效擴充：sh 發 /ʃ/ 音，結合 ar 的捲舌音，聯想海灘邊的警戒生物。\nKK 音標：[ʃɑrk] -> 重音在 a 的捲舌音，發音時喉頭要放低。\n\n常見同義字：\npredator（捕食者，範圍較廣包含陸地動物）\nspeculator（投機者，偏向商業金融用語）\nswindler（騙子，指詐財行為）",
  "sharp": "諧音聯想：\n諧音：「夏普」電視面板技術非常尖端銳利。\n\n聯想畫面 1：一把夏普牌的菜刀切水果時非常鋒利，一刀兩斷。\n\n聯想畫面 2：早上八點鐘sharp（正點）開會，大家不敢遲到。\n\n高效擴充：源自日耳マン語系，常衍生為 sharp drop（急劇下跌）。\nKK 音標：[ʃɑrp] -> 主重音在長元音ɑr上，發音時舌頭縮回喉嚨，嘴巴張大帶點捲舌音。\n\n常見同義字：\nkeen（敏銳的，通常指心智或興趣）\nacute（嚴重的，通常指病況或角度）\npunctual（準時的，通常指人或時間安排）",
  "sharpen": "諧音聯想：\n諧音：「夏拼」，夏天到了要拼命把刀子磨快好切西瓜。\n\n聯想畫面 1：廚師在切菜前先把菜刀在磨刀石上迅速削尖磨利。\n\n聯想畫面 2：學生藉由不斷做考古題來磨練並提升自己的應試能力。\n\n高效擴充：由 sharp（尖銳的、鋒利的）加上字尾 en（變成）所構成。\nKK 音標：[ˋʃɑrpən] -> 重音在第一音節 SHARP，發大口的 ah 音。\n\n常見同義字：\n\nhone（磨練、修飾，常用於技能或刀具）\n\ngrind（磨碎、苦幹，強調摩擦過程）\n\nedge（給...加刃、使銳利）",
  "shatter": "諧音聯想：\n諧音：「俠特」，武俠大俠特別用力一掌把玻璃打得粉碎。\n\n聯想畫面 1：不小心手滑把昂貴的紅酒杯摔在地上粉碎。\n\n聯想畫面 2：突如其來的噩耗讓她脆弱的心靈受到極大打擊而破碎。\n\n高效擴充：模擬東西破裂聲音的擬聲詞衍生，字尾 er 表示重複動作。\nKK 音標：[ˋʃætɚ] -> 重音在第一音節 SHAT，t 介於母音之間發輕快的彈舌音。\n\n常見同義字：\n\nsmash（粉碎、猛烈打破）\n\nbreak（打破、折斷，最通用的基本詞）\n\ndestroy（毀壞、破滅，指徹底消滅）",
  "shave": "諧音聯想：\n諧音：誰廢 -> 諧音：「誰廢」\n\n諧音聯想：\n諧音：「誰廢」\n\n聯想畫面 1：早上起床照鏡子，看鬍子長出來了就拿起刮鬍刀把臉刮乾淨。\n\n聯想畫面 2：運動員為了減少阻力，把腿上的毛髮全部剃除乾淨。\n\n高效擴充：注意與save（節省）的拼法只差一個字母。\nKK 音標：[ʃev] -> 發音時v要輕咬下唇，長音a。\n\n常見同義字：\ncut（修剪，範圍較廣）\ntrim（修整，使整齊）\nrazor（刮鬍刀，工具名）",
  "shaver": "諧音聯想：\n諧音：「雪弗」\n\n聯想畫面 1：男士早起使用電動剃鬚刀清理鬍子。\n\n聯想畫面 2：理髮師拿起推剪為客人修剪頭髮。\n\n高效擴充：由 shave（刮鬍子）衍生而來的工具名詞。\nKK 音標：[ˋʃevɚ] -> 主重音在 ʃe，vɚ 輕聲發音。\n\n常見同義字：\nrazor（剃刀）\nclipper（電動理髮剪）\ntrimmer（修剪器）」}, {",
  "she": "諧音聯想：\n諧音：「歇」休息的諧音。\n\n聯想畫面 1：她（she）工作太累了，現在正在休息。\n\n聯想畫面 2：這個女生（she）一回家就癱在沙發上。\n\n高效擴充：女性主格代名詞，放在動詞前。\nKK 音標：[ʃi] -> 結合 sh 的噓聲與長音 i。\n\n常見同義字：\nher（女性受格或所有格）\nhers（女性所有格代名詞）\nhe（男性主格代名詞）",
  "shed": "諧音聯想：\n諧音：雪的。\n\n聯想畫面 1：木製的 shed 小屋上面覆蓋著厚厚的雪。\n\n聯想畫面 2：蛇脫皮時把舊皮 shed 掉，像丟棄不需要的外衣。\n\n高效擴充：短小精悍的字，當名詞指小棚屋，當動詞指去除或流出。\nKK 音標：[ʃɛd] -> 短促的 ʃɛd，嘴型扁平有力。\n\n常見同義字：\n\nshed tears（流淚）\n\ndrop（落下）\n\nhut（小茅屋）。",
  "shedloads": "諧音聯想：\n諧音：「誰多」。\n\n聯想畫面 1：倉庫裡堆滿了貨物，大家問誰多？當然是我這裡最多！\n\n聯想畫面 2：這家店生意太好，每天都要處理成堆的訂單，簡直是 shedloads 的工作量。\n\n高效擴充：shed 是小屋，load 是負載，合起來就是小屋都裝不下的量。\nKK 音標：[ˋʃɛdˌlodz] -> 重音在第一音節，發音時注意 s 的結尾。\n\n常見同義字：\n\nheaps（成堆）\n\ntons（大量）\n\nplenty（充足）。",
  "sheep": "諧音聯想：\n諧音：「細皮」\n\n聯想畫面 1：溫馴的綿羊身上有著一層白白細皮與厚重的羊毛。\n\n聯想畫面 2：膽小鬼就像小綿羊一樣，遇到事情只敢細皮嫩肉地發抖躲在後面。\n\n高效擴充：雙 e 發長母音 /i/，與 ship 的短母音發音常被拿來考聽力辨別。\nKK 音標：[ʃip] -> 重音在 ee，發音要拉長且嘴型扁平。\n\n常見同義字：\nram（公羊，強調強壯有力）\newe（母羊，專指成年雌羊）\ncoward（膽小鬼，日常口語常用詞）",
  "sheepish": "諧音聯想：\n諧音：吸皮許\n\n聯想畫面 1：做錯事被抓到時，他露出像羊一樣羞怯的表情，連吸皮許（sheepish）的勇氣都沒有。\n\n聯想畫面 2：他在台上忘詞後，一臉窘迫地走下台，看起來非常難為情。\n\n高效擴充：sheep（羊）加上 ish（像...的），形容人像羊一樣膽小溫順。\nKK 音標：[ˋʃipɪʃ] -> 重音在第一個音節，注意長母音 i 的發音要拉長。\n\n常見同義字：\nembarrassed（尷尬的，最常用）\nashamed（羞愧的，程度較深）\nshy（害羞的，個性使然）",
  "sheer": "諧音聯想：\n諧音：「希兒」穿著一件純粹透明的精紡織物，在舞台上旋轉。\n\n聯想畫面 1：這座懸崖簡直是垂直陡峭地立在海邊，看了讓人腳軟。\n\n聯想畫面 2：這場勝利完全是靠純粹的好運氣，而不是實力。\n\n高效擴充：發音短促但字義多變，可當形容詞、副詞或動詞。\nKK 音標：[ʃɪr] -> 單音節長音，ʃ 發嘘音，搭配 ir 的捲舌長音。\n\n常見同義字：\n\npure（純粹的、純正的）\n\nabsolute（完全的、絕對的）\n\nsteep（陡峭的，指地形）",
  "sheet": "諧音聯想：\n諧音：「細的」\n\n聯想畫面 1：抽出一張乾淨的白紙，紙質非常細的且平滑。\n\n聯想畫面 2：飯店換上洗得雪白乾淨的床單，摸起來觸感細緻。\n\n高效擴充：注意 ee 的長音發音，避免與短音的 shit 搞混。\nKK 音標：[ʃit] -> 重音在 ee，發長音時嘴角微張向兩側拉開。\n\n常見同義字：\npage（頁，書本或筆記本的一頁）\nbedding（寢具，統稱床單被套類）\nform（表格，公家機關常用的填寫表單）",
  "shelf": "諧音聯想：\n諧音：「雪夫」把剛烤好的麵包放在廚房的木質架子上。\n\n聯想畫面 1：圖書館管理員把新進的書籍一本本地整齊擺放在書架上。\n\n聯想畫面 2：超級市場的商品架上擺滿了各式各樣的飲料與零食。\n\n高效擴充：複數形為 shelves，注意 f 要改成 ves。\nKK 音標：[ʃɛlf] -> 單音節字，結尾的 lf 需輕輕咬唇發音。\n\n常見同義字：\nrack（架子，偏向金屬掛架或層架）\nledge（岩架、窗臺，偏向狹窄突出的邊緣）\nbookcase（書櫃，專指放書的櫃子）",
  "shell": "諧音聯想：\n諧音：「雪兒」在海灘上撿起一個漂亮的白色貝殼。\n\n聯想畫面 1：海鮮餐廳的桌上堆滿了剝好的蝦蟹外殼。\n\n聯想畫面 2：軍事演習中，大砲發射出砲彈，在遠處山頭炸開。\n\n高效擴充：雙 l 結尾，衍生字有 shellfish（貝類海鮮）。\nKK 音標：[ʃɛl] -> 單音節字，短母音 ɛ 搭配清脆的 l 結尾。\n\n常見同義字：\nhusk（外殼，偏向植物果實的外皮）\ncase（外殼、盒子，偏向保護用的套子）\n砲彈義可參考 shell 或 bomb",
  "shelter": "諧音聯想：\n諧音：「誰得特」\n\n聯想畫面 1：暴風雨來襲，遊客躲進避難所尋求庇護。\n\n聯想畫面 2：流浪動物收容所提供毛小孩一個安全遮蔽的地方。\n\n高效擴充：可作名詞避難所或動詞保護遮蔽。\nKK 音標：[ˋʃɛltɚ] -> 主重音在 ʃɛl，tɚ 輕輕唸出。\n\n常見同義字：\nrefuge（避難所）\nsanctuary（庇護所、鳥獸保護區）\nprotection（保護）」}, {",
  "shepherd": "諧音聯想：\n諧音：誰怕牠 -> 諧音：「誰怕牠」\n\n諧音聯想：\n諧音：「誰怕牠」\n\n聯想畫面 1：勇敢的牧羊人拿著手杖在山坡上照顧羊群，心裡想著狼來了誰怕牠。\n\n聯想畫面 2：資深前輩在職場上引領新人，像個導師一樣護送新人熟悉業務。\n\n高效擴充：由sheep（綿羊）加上herrd（牧人）組合而成。\nKK 音標：[ˋʃɛpɚd] -> 重音在第一音節shep上，d發輕音。\n\n常見同義字：\nherdsman（牧民，統稱）\nguide（嚮導，引領者）\nmentor（導師，心靈指導者）",
  "sheriff": "諧音聯想：\n諧音：\\n諧音：「誰去府」\\n\\n\n\n聯想畫面 1：美國西部牛仔電影中，誰去府衙找郡治安官幫忙主持正義。\\n\\n\n\n聯想畫面 2：地方上的高階警長騎著馬巡視小鎮，保護居民安全。\\n\\n\n\n高效擴充：注意兩個 rr 的拼法，是美國特有的地方官職。\\n\nKK 音標：[ˋʃɛrəf] -> 主重音在首音節 ˋʃɛ，f 輕輕咬唇發音。\\n\\n\n\n常見同義字：\n\n\\npolice chief（警察局長）\\nofficer（警官）\\nlawman（執法者、治安官）",
  "sherry": "諧音聯想：\n諧音：雪莉。\n\n聯想畫面 1：在高級餐廳，侍者端上一杯雪利酒，酒香四溢，讓人陶醉。\n\n聯想畫面 2：雪莉是一個溫柔的女孩，她最喜歡在午後品嚐一杯甜美的雪利酒。\n\n高效擴充：源自西班牙地名 Jerez 的變體。\nKK 音標：[ˋʃeri] -> 重音在第一個音節，注意 sh 的摩擦音，發音時嘴唇要突出。\n\n常見同義字：\n\nWine（葡萄酒，指酒類）\n\nAperitif（餐前酒，指飲用時間）\n\nSherry（女子名，同名）。",
  "shield": "諧音聯想：\n諧音：\\n諧音：「休得」\\n\\n\n\n聯想畫面 1：古代戰士舉起巨大的金屬盾牌，大喊休得靠近，成功保護自己。\\n\\n\n\n聯想畫面 2：防護罩瞬間啟動，完美地遮擋並防禦外來的猛烈攻擊。\\n\\n\n\n高效擴充：ie 發長 i 的音，名詞動詞同形。\\n\nKK 音標：[ʃild] -> 單音節字，sh 發嘘聲，ld 結尾要完整發出。\\n\\n\n\n常見同義字：\n\n\\nbuckler（小圓盾）\\nprotection（保護、防護物）\\ndefend（動詞：防衛、保護）",
  "shift": "諧音聯想：\n諧音：「希夫特」\n\n聯想畫面 1：護士小姐準備交接，結束早班的輪班工作時間。\n\n聯想畫面 2：開車時手排檔打檔移動位置，或是想法上的轉變。\n\n高效擴充：電腦鍵盤上的 Shift 鍵即有轉換之意。\nKK 音標：[ʃɪft] -> 單音節字，短母音 ɪ 搭配清晰的 ʃt 尾音。\n\n常見同義字：\nmove（移動）\nchange（改變）\ntransfer（轉移、調動）」}, {",
  "shilling": "諧音聯想：\n諧音：夕林。\n\n聯想畫面 1：在古老英國市集裡，大家用 shilling 先令購買夕林之下的蘋果。\n\n聯想畫面 2：老爺爺口袋裡僅剩幾個 shilling。\n\n高效擴充：舊英國貨幣單位，二十先令等於一英鎊。\nKK 音標：[ˋʃɪlɪŋ] -> 重音在字首 ʃìl，後面 ɪŋ 輕聲。\n\n常見同義字：\n\ncoin（硬幣）\n\ncurrency（貨幣）\n\npence（便士）。",
  "shimmer": "諧音聯想：\n諧音：希麼。\n\n聯想畫面 1：湖面在月光下閃爍，希麼（什麼）都看不清楚，只看到一片波光粼粼。\n\n聯想畫面 2：舞會上她的禮服閃爍著珠光，美得讓人目不轉睛。\n\n高效擴充：sh- 開頭常與柔和的光或聲音有關，如 shine。\nKK 音標：[ˋʃɪmər] -> 重音在第一音節，shim 發音要輕柔。\n\n常見同義字：\n\nglimmer（微光）\n\nglitter（閃耀）\n\nsparkle（閃爍）。",
  "shinbashira": "諧音聯想：\n諧音：心巴希拉\n\n聯想畫面 1：想像佛塔中間那根支撐整座塔的中心支柱，就像是塔的「心」，巴不得希拉（神力）能讓它永遠屹立不搖。\n\n聯想畫面 2：建築師在設計木造古塔時，特別強調這根中心支柱的防震功能，這就是所謂的中心支柱。\n\n高效擴充：這是日文漢字心柱的音譯，專指日本木造佛塔中央的垂直大柱。\nKK 音標：無 -> 重音在第二個音節 bash，唸起來要有節奏感。\n\n常見同義字：\ncentral pillar（中心柱，最直觀的解釋）\ncore post（核心柱，建築結構術語）\nmain support（主要支撐，強調功能性）",
  "shine": "諧音聯想：\n諧音：「閃」\n\n聯想畫面 1：太陽高掛空中，強烈的光芒讓人睜不開眼，整個大地都在閃。\n\n聯想畫面 2：皮鞋擦得發亮，在燈光照射下閃閃發動。\n\n高效擴充：字尾的 e 讓前面的 i 發出長音 /aɪ/ 的字母本音。\nKK 音標：[ʃaɪn] -> 重音在 i 的雙母音上，由開口漸漸合攏。\n\n常見同義字：\nglow（發出微光，通常指柔和的光芒）\nsparkle（閃爍，像星星或鑽石般的光點）\npolish（擦亮，指透過動手清潔達到發光效果）",
  "shining": "諧音聯想：\n諧音：這把吉他刷下去的「閃音」，就像鑽石般shining發光。\n\n聯想畫面 1：夜晚的台北101大樓外牆燈光全開，看起來非常shining奪目耀眼。\n\n聯想畫面 2：媽媽把地板擦得亮晶晶的，踩上去都覺得整個客廳在shining發亮。\n\n高效擴充：來自動詞 shine（發光），加上 ing 變成現在分詞或形容詞，形容發光的狀態。\nKK 音標：[ˋʃaɪnɪŋ] -> 重音在 SHIN，注意 i 發長音的 [aɪ]。\n\n常見同義字：\n\nglowing（發光或發熱的，帶有溫暖光芒）\n\nradiant（容光煥發的、光芒四射的）\n\nbrilliant（卓越的、光輝燦爛的）",
  "shiny": "諧音聯想：\n諧音：「閃泥」\n\n聯想畫面 1：地上的泥巴被太陽一照，竟然閃閃發亮，像塗了亮光漆一樣。\n\n聯想畫面 2：車子剛打蠟完，車身變得非常閃亮好看。\n\n高效擴充：由 shine 變化而來，字尾加上 y 變成形容詞「發光的」。\nKK 音標：[ˋʃaɪni] -> 重音在第一音節，發長雙母音 ˋaɪ。\n\n常見同義字：\nbright（明亮的、鮮豔的）\nglossy（有光澤的、滑亮的）\nsparkling（閃爍的、發泡的）",
  "ship": "諧音聯想：\n諧音：「習普」\n\n聯想畫面 1：習近平搭乘一艘大型貨輪運送貨物跨越太平洋。\n\n聯想畫面 2：網購商品從海外透過大型貨輪運送，準備推出上市。\n\n高效擴充：短母音 i 發短促的 /ɪ/ 音，與 sheep 的長音形成對比。\nKK 音標：[ʃɪp] -> 重音在 i，發音短促有力，舌頭放輕鬆。\n\n常見同義字：\nboat（小船，泛指體積較小的水上交通工具）\nvessel（大船、艦，較正式的說法）\ntransport（運輸，當動詞用時相當於運送）",
  "shipment": "諧音聯想：\n諧音：「Ship（船）+ ment（門）」\n\n聯想畫面 1：一艘巨大的貨船停靠在碼頭，船上的貨物正準備從船門運送到倉庫，這就是貨物運輸的過程。\n\n聯想畫面 2：網購後收到簡訊通知，顯示你的包裹已經進入 shipment 階段，代表貨物正在運送途中。\n\n高效擴充：字根 ship 指船，ment 為名詞字尾，合起來指運送的貨物。\nKK 音標：[ˋʃɪpmənt] -> 重音在第一音節，ship 發音要短促有力，ment 輕讀。",
  "shipping": "諧音聯想：\n諧音：「Ship（船）+ ping（乒乓球）」\n\n聯想畫面 1：港口邊忙碌的 shipping 產業，貨櫃像乒乓球一樣在船隻與卡車間快速調度。\n\n聯想畫面 2：在電商網站結帳時，shipping fee 欄位顯示運費金額，這是最常見的用法。\n\n高效擴充：shipping 指的是整個運輸行業或運送的動作，比 shipment 更強調過程。\nKK 音標：[ˋʃɪpɪŋ] -> 重音在第一音節，結尾的 ng 發音時鼻腔要共鳴。",
  "shirt": "諧音聯想：\n諧音：「學得」\n\n聯想畫面 1：新買的襯衫太好看，同學都說這件 shirt 你學得真快，穿起來很有型。\n\n聯想畫面 2：上班族每天早上急著出門，套上乾淨的 shirt 準備去公司開會。\n\n高效擴充：字尾 rt 結尾常見於服飾與日常物品，注意短母音發音。\nKK 音標：[ʃɝt] -> 嘴唇微噘發 sh，接著發捲舌的 ɝ 音，最後閉氣發輕促的 t。\n\n常見同義字：\n\nblouse（女式襯衫，通常剪裁較柔美）\n\ntop（上衣的總稱，涵蓋範圍最廣）\n\ngarment（服飾，較正式或工業用語）",
  "shiver": "諧音聯想：\n諧音：\\n諧音：「喜獲」\\n\\n\n\n聯想畫面 1：喜獲冰淇淋大獎，但因為天氣太冷，拿到手忍不住一陣顫抖哆嗦。\\n\\n\n\n聯想畫面 2：走在寒風中，身體因為發冷而直打哆嗦，全身發抖。\\n\\n\n\n高效擴充：與 shake 搖晃有相似的語感與發音聯想。\\n\nKK 音標：[ˋʃɪvɚ] -> 主重音在首音節 ˋʃɪ，vɚ 輕輕帶過。\\n\\n\n\n常見同義字：\n\n\\ntremble（因為害怕或寒冷而發抖）\\nshudder（因為恐懼或厭惡而打冷顫）\\nquake（強烈地震動或發抖）",
  "shoal": "諧音聯想：\n諧音：受喔。\n\n聯想畫面 1：船隻駛入淺灘，如果不小心就會擱淺受損。\n\n聯想畫面 2：遠處海面上出現一大群魚，波光粼粼的非常壯觀。\n\n高效擴充：Shoal 既可指地形，也可指生物群體。\nKK 音標：[ʃoʊl] -> 發音時嘴唇要圓，長母音 o 要拉長。\n\n常見同義字：\n\nshallow（淺的）\n\nschool（魚群）。",
  "shock": "諧音聯想：\n諧音：看到恐怖電影的「傻客」當場嚇得目瞪口呆，大受震驚。\n\n聯想畫面 1：新聞快報播報突發災難，讓全國民眾感到無比震驚與錯愕。\n\n聯想畫面 2：觸電的瞬間讓身體產生強烈的休克與麻痺反應。\n\n高效擴充：常組成形容詞 shocking（令人震驚的）或 shocked（感到震驚的）。\nKK 音標：[ʃɑk] -> 單音節字，短母音 ɑ 嘴巴張大發短音。\n\n常見同義字：\nsurprise（驚訝，程度較溫和）\nastound（使大為驚奇，較正式）\nblow（打擊，多作名詞用）",
  "shocked": "諧音聯想：\n諧音：「休誇特」\n\n聯想畫面 1：看到帳單金額的那一刻，他整個人震驚得說不出話來。\n\n聯想畫面 2：聽到突如其來的壞消息，全場觀眾都感到十分吃驚。\n\n高效擴充：ed 結尾用來形容人的感受，主動使人震驚則用 shocking。\nKK 音標：[ʃɑkt] -> 單音節字，sh 發噓聲，ck 發 k 的短促音。\n\n常見同義字：\n\nsurprised（感到驚訝的）\n\nastounded（大為驚駭的）\n\nstunned（打擊過大而呆若木雞的）",
  "shoe": "諧音聯想：\n諧音：「休」\n\n聯想畫面 1：走路走了一整天，腳好痠，趕快把 shoe 脫掉休息一下。\n\n聯想畫面 2：出門跑步前，一定要把運動 shoe 的鞋帶綁緊才安全。\n\n高效擴充：複數形為 shoes，注意字尾加上 es。\nKK 音標：[ʃu] -> 嘴唇噘起發 sh 音，緊接著發長音的 u。\n\n常見同義字：\n\nsneaker（運動鞋，日常休閒最常用）\n\nboot（靴子，包覆到腳踝或以上的鞋）\n\nsandal（涼鞋，適合夏天穿著）",
  "shoot": "諧音聯想：\n諧音：「舒特」拿著相機對準風景，準備按下快門拍攝。\n\n聯想畫面 1：籃球員在三分線外起跳，將球順利投籃命中。\n\n聯想畫面 2：警察在靶場舉槍進行射擊訓練。\n\n高效擴充：三態變化為 shoot、shot、shot。\nKK 音標：[ʃut] -> 單音節字，長母音 u 嘴唇需向前嘟起。\n\n常見同義字：\nfire（開火、解雇）\nphotograph（拍照，較正式）\nthrow（投擲，偏向傳球）",
  "shop": "諧音聯想：\n諧音：「瞎拼」\n\n聯想畫面 1：放假就要去逛 shop，跟朋友一起開心血拼買衣服。\n\n聯想畫面 2：巷口開了一間新的雜貨 shop，賣很多生活日用品。\n\n高效擴充：也可以當動詞使用，進行網購時常說 shop online。\nKK 音標：[ʃɑp] -> 嘴唇發 sh，接著發短促開口的 ɑ，最後雙唇緊閉發 p。\n\n常見同義字：\n\nstore（商店，美式英語中最常用的店舖稱呼）\n\nboutique（精品店，通常規模較小且具特色）\n\nmarket（市場，多指生鮮或市集類型的商店）",
  "shoplift": "諧音聯想：\n諧音：在「商店偷禮服」藏在大衣裡，這就是俗稱的偷竊。\n\n聯想畫面 1：監視器拍到一名女子趁店員不注意，把昂貴的化妝品塞進包包裡。\n\n聯想畫面 2：保全人員在門口攔下了一位鬼鬼祟祟、涉嫌在店內行竊的小偷。\n\n高效擴充：由 shop（商店）加上 lift（舉起、拿走），把店裡的東西拿走。\nKK 音標：[ˋʃɑp͵lɪft] -> 複合字，主重音落在第一個字 [ˋʃɑp]，後面 [lɪft] 稍微輕讀。\n\n常見同義字：\nsteal（偷竊，最通用的偷竊動詞）\ntheft（偷竊行為，此為名詞形式）\nrob（搶劫，強調使用暴力或威脅）",
  "shore": "諧音聯想：\n諧音：「秀鵝」\n\n聯想畫面 1：在海邊的 shore 上，有一隻美麗的大白鵝在悠閒散步。\n\n聯想畫面 2：漁夫把船停泊在 shore 邊，準備搬運今天捕獲的魚貨。\n\n高效擴充：常與片語 on shore 或 off shore 連用。\nKK 音標：[ʃɔr] -> 發 sh 後接結合 r 的捲舌長 o 音。\n\n常見同義字：\n\nbeach（海灘，指沙灘為主的地方）\n\ncoast（海岸，範圍較大指陸地與海交界處）\n\nbank（河岸，專指河水兩側的陸地）",
  "short": "諧音聯想：\n諧音：「袖短」\n\n聯想畫面 1：天冷時發現衣服「袖短」了一截，看起來既「短」又顯得身材矮小。\n\n聯想畫面 2：這部電影「短」片時間很「短暫」，看完後大家還穿著「短」褲在討論。\n\n高效擴充：字尾常加上 en 變成 shorten 表示縮短或變短。\nKK 音標：[ʃɔrt] -> 單音節單字，[ɔ]為圓唇長音，結尾的[t]要輕輕發出。\n\n常見同義字：\n\nbrief（簡短的，常用於描述時間或文字講述）\n\nconcise（簡潔的，強調言語或文章精煉無贅字）\n\nsmall（小的、矮小的，常用於身材或體積）",
  "shortage": "諧音聯想：\n諧音：\\n諧音：「秀特居」\\n\\n\n\n聯想畫面 1：這間秀特居（特色住宅區）因為建材短缺，導致工程延宕。\\n\\n\n\n聯想畫面 2：超市架上的民生用品出現嚴重短缺，大家都搶著買。\\n\\n\n\n高效擴充：由 short 短加上 age 名詞字尾，指不夠用。\\n\nKK 音標：[ˋʃɔrtədʒ] -> 主重音在首音節 ˋʃɔrt，ge 唸 dʒ。\\n\\n\n\n常見同義字：\n\n\\nlack（缺乏、不足）\\nscarcity（資源稀少、匱乏）\\ndeficit（赤字、虧損）",
  "shortcoming": "諧音聯想：\n諧音：\\n諧音：「秀特咖明」\\n\\n\n\n聯想畫面 1：這個秀特咖明知自己個性急躁，這正是他無法掩飾的最大缺點。\\n\\n\n\n聯想畫面 2：主管指出這份企劃書的短處與疏漏之處，需要立刻改進。\\n\\n\n\n高效擴充：由 short 短與 coming 到來組合，意指表現短了一截的缺點。\\n\nKK 音標：[ˋʃɔrt͵kʌmɪŋ] -> 主重音在首音節 ˋʃɔrt，中間的 kʌm 次重音要分明。\\n\\n\n\n常見同義字：\n\n\\nflaw（瑕疵、缺點）\\ndefect（缺陷、毛病）\\nweakness（弱點、短處）",
  "shorten": "諧音聯想：\n諧音：「修短的」\n\n聯想畫面 1：拿剪刀把過長的褲管修短的，讓身高比例更好看。\n\n聯想畫面 2：開會時間太長，主管決定把議程縮短以提高效率。\n\n高效擴充：由形容詞 short 加上字尾 -en 轉為動詞，表「使變得……」。\nKK 音標：[ˋʃɔrtən] -> 第一音節重音，or 捲舌音要確實。\n\n常見同義字：\n\nabbreviate（縮寫文字或字詞，常用於學術或專有名詞）\n\ncondense（濃縮內容或液體，使之更精簡）\n\nreduce（減少數量或程度，較常指降低）",
  "shortly": "諧音聯想：\n諧音：「秀特力」\n\n聯想畫面 1：魔術師展現特技，立刻（Shortly）就把兔子變不見，真是好秀特力。\n\n聯想畫面 2：飛機即將起飛，廣播請旅客馬上回到座位上。\n\n高效擴充：由 short（短的、不久的）加上 ly 構成，引申為不久、立刻。\nKK 音標：[ˋʃɔrtli] -> 主重音在 short，sh 發噓音，t 輕輕帶過，li 快速收尾。\n\n常見同義字：\nsoon（不久，最常用的口語詞）\nshortly（立刻、不久後）\nbriefly（簡短地，多指說話或文章）",
  "shorts": "諧音聯想：\n諧音：「夏茲」天氣非常炎熱，大家都換上了清涼的短褲。\n\n聯想畫面 1：週末假期，男孩穿著運動短褲去公園打籃球。\n\n聯想畫面 2：剪輯師將拍攝好的素材濃縮剪輯成一支精華短片。\n\n高效擴充：褲子類單品通常以複數形態呈現，如 pants、trousers。\nKK 音標：[ʃɔrts] -> 單音節字，結合 r 音與尾音 ts。\n\n常見同義字：\ntrunks（泳褲或男士平口褲）\nclip（短片、夾子，偏向影片片段）\nfootbaall shorts（運動短褲）",
  "shortsighted": "拆解：short (短) + sighted (視力的)\n\n諧音：「秀特塞特」得太近，導致近視眼。\n\n聯想畫面 1：他因為小時候愛看漫畫又坐太近，年紀輕輕就成了高度近視。\n\n聯想畫面 2：老闆只看眼前利益而不肯投資員工培訓，這種決策實在目光短淺。\n\n高效擴充：由短 (short) 與視力 (sighted) 複合而成，字面與引申義均指看不多遠。\nKK 音標：[ˋʃɔrtˋsaɪtɪd] -> 複合字，兩個部分都有重音，主重音在後方 saɪt。\n\n常見同義字：\nnearsighted（近視的，醫學與日常上的近視專用字）\nmyopic（近視的、目光短淺的，較學術或正式的用詞）\nunfarsighted（缺乏遠見的，形容對未來沒有長遠規劃）",
  "shot": "諧音聯想：\n諧音：「殺特」\n\n聯想畫面 1：獵人瞄準目標開了一 shot，精準擊中獵物。\n\n聯想畫面 2：攝影師按下快門拍下一張漂亮的 shot，畫面非常完美。\n\n高效擴充：shoot 的過去式與過去分詞皆為 shot。\nKK 音標：[ʃɑp 的變化，此處為 ʃɑt] -> 嘴唇發 sh，接著發短促的 ɑ，最後俐落收尾在 t。\n\n常見同義字：\n\nphoto（照片，最口語的攝影照片）\n\ninjection（注射，醫療上的打針）\n\nattempt（嘗試，口語常說 give it a shot）",
  "shotgun": "拆解：射（shot）＋槍（gun）。\n\n聯想畫面 1：他拿起霰彈槍，準備去打獵。\n\n聯想畫面 2：我搶到了副駕駛座，視野真好。\n\n高效擴充：shotgun wedding 指奉子成婚，源於過去被迫結婚的習俗。\nKK 音標：[ˋʃɑtɡʌn] -> 重音在第一個音節。\n\n常見同義字：\n\nfirearm（槍械，正式）\n\nfront seat（前座，指副駕駛位）。",
  "should": "諧音聯想：\n諧音：「手低」\n\n聯想畫面 1：投籃時手放太低了，教練說你應該把球舉高。\n\n聯想畫面 2：學生應當遵守校規，這是基本常識。\n\n高效擴充：為情態助動詞，後接原形動詞。\nKK 音標：[ʃʊd] -> 單音節字，sh發噓聲，ʊ發短u音。\n\n常見同義字：\n\nought to（應該，語氣較should稍強且正式）\n\nshould（助動詞，給建議時最常使用）\n\nmust（必須，語氣最強烈帶有強制性）",
  "shoulder": "諧音聯想：\n諧音：「秀der」\n\n聯想畫面 1：大力士把重物扛在 shoulder 上，向大家秀一下他的肌肉。\n\n聯想畫面 2：朋友難過時，拍拍他的 shoulder 給予溫暖的安慰。\n\n高效擴充：字尾 der 為常見名詞字尾，注意重音在第一音節。\nKK 音標：[ˋʃoldɚ] -> 重音在修（ʃol），後面接輕短的 dɚ。\n\n常見同義字：\n\nback（背部，指整片後背）\n\narm（手臂，連同肩膀的整體上肢延伸）\n\nneck（脖子，位於頭部與肩膀之間）",
  "shout": "諧音聯想：\n諧音：「夏奧」\n\n聯想畫面 1：夏天辦奧運時，觀眾太興奮而在看台上用力叫嚷、大聲說。\n\n聯想畫面 2：在吵雜夜市裡，攤販為了招攬客人而不斷大聲呼叫、喊叫。\n\n高效擴充：源自古英語，與 shoot 發音相近但字尾不同。\nKK 音標：[ʃaʊt] -> 母音 au 嘴型要由大漸小，發音短促有力。\n\n常見同義字：\nyell（通常指憤怒或痛苦時的叫喊）\nscream（因恐懼或興奮而發出的尖叫）\ncry（因悲傷或情緒激動而大聲哭喊）",
  "shove": "諧音聯想：\n諧音：\\n諧音：「夏娃」\\n\\n\n\n聯想畫面 1：夏娃在樂園裡不小心用力一推，把蘋果樹給猛推了一下。\\n\\n\n\n聯想畫面 2：搭捷運時人潮擁擠，大家在車廂門口亂擠、連推帶擠地走進去。\\n\\n\n\n高效擴充：注意字尾是 ve，動詞名詞同形。\\n\nKK 音標：[ʃʌv] -> 單音節字，短母音 ʌ 嘴巴微張發短促的「阿」音。\\n\\n\n\n常見同義字：\n\n\\npush（推、按）\\nthrust（猛力刺或推）\\njostle（在人群中推擠）",
  "shovel": "諧音聯想：\n諧音：「瞎挖」\n\n聯想畫面 1：天黑了還在花園瞎挖，只好趕快拿起鏟子拼命掘土。\n\n聯想畫面 2：工人拿著大鏟子在馬路上剷起厚重的柏油。\n\n高效擴充：字尾 el 通常代表工具名詞，此處指用來鏟東西的器具。\nKK 音標：[ˋʃʌvəl] -> 重音在第一個音節 sho，注意ʌ發短促的「啊」音。\n\n常見同義字：\n\nspade（鏟子，通常指扁平且用來挖土的園藝用具）\n\nexcavate（挖掘，較正式的動詞）\n\nscoop（勺子、舀取，偏向圓形舀冰淇淋的動作）",
  "show": "諧音聯想：\n諧音：「秀」\n\n聯想畫面 1：模特兒在伸展台上走秀，大方顯示、表明身上的華麗服裝給觀眾看。\n\n聯想畫面 2：電視台晚上播出一場精彩的歌舞表演節目。\n\n高效擴充：動詞三態變化為 show, showed, shown。\nKK 音標：[ʃo] -> 雙母音 o，嘴型由圓變扁，發音清晰。\n\n常見同義字：\ndisplay（正式展出或陳列物品）\nexhibit（公開展覽藝術品或商業產品）\nreveal（揭露隱藏的秘密或真相）",
  "showcase": "諧音聯想：\n拆解：show（展示）+ case（櫃子）。\n\n聯想畫面 1：博物館裡用玻璃陳列櫃展示珍貴的古董，這就是一個完美的 showcase。\n\n聯想畫面 2：這場大型展覽是新創公司展示最新科技產品的絕佳場合。\n\n高效擴充：由 show 和 case 合成，字面意思就是展示用的櫃子，引申為展示的舞台。\nKK 音標：[ˋʃoʊkeɪs] -> 重音在第一個音節 show，發長母音 o 的音。\n\n常見同義字：\n\ndisplay 展示，陳列；exhibit 展覽，展出；demonstrate 示範，證明。",
  "shower": "諧音聯想：\n諧音：「夏娃」在花園裡轉開水龍頭，享受清涼的花灑淋浴。\n\n聯想畫面 1：運動完滿身大汗的上班族，趕緊回家洗個舒服的熱水澡。\n\n聯想畫面 2：天空突然飄來一陣午後陣雨，行人紛紛走避。\n\n高效擴充：常搭配動詞 take a shower（洗澡）。\nKK 音標：[ˋʃaʊɚ] -> 第一音節重音在 shâw，尾音 ɚ 輕發。\n\n常見同義字：\nbath（泡澡，偏向整個人浸在浴缸裡）\nrain（雨，泛指一般降雨）\ndrizzle（毛毛雨，細雨）",
  "showtime": "諧音聯想：\n拆解：show（表演）+ time（時間）。\n\n聯想畫面 1：燈光亮起，主持人喊著 It is showtime，觀眾歡呼。\n\n聯想畫面 2：每週五晚上是電視節目的 showtime，全家一起看電視。\n\n高效擴充：常用於表演開始的時刻。\nKK 音標：[ˋʃoʊtaɪm] -> 重音在第一個音節，發音要充滿期待感。\n\n常見同義字：\n\nperformance time（表演時間）\n\ncurtain time（開演時間）。",
  "shred": "諧音聯想：\n諧音：\\n諧音：「吸瑞得」\\n\\n\n\n聯想畫面 1：吸塵器瑞得把秘密文件全部絞碎，變成一條條的細碎紙條。\\n\\n\n\n聯想畫面 2：廚師把高麗菜用力切碎，準備做沙拉。\\n\\n\n\n高效擴充：常見片語 in shreds 意指支離破碎。\\n\nKK 音標：[ʃrɛd] -> 單音節字，短母音 ɛ 嘴巴扁平，尾音 d 要輕輕彈開。\\n\\n\n\n常見同義字：\n\n\\ntear（撕裂、扯破）\\nslice（切片）\\nfragment（使成碎片）",
  "shredder": "諧音聯想：\n諧音：「雪（Shre）+ 的（dder）」\n\n聯想畫面 1：把機密文件丟進碎紙機，紙張瞬間像雪花一樣被切成碎片，這就是 shredder 的工作。\n\n聯想畫面 2：辦公室裡那台嗡嗡作響的機器，專門用來處理過期報表的碎紙機。\n\n高效擴充：動詞 shred 是切碎，加上 er 變成執行切碎動作的機器。\nKK 音標：[ˋrɛdɚ] -> 重音在第一音節，sh 嘴型要噘起，der 發輕音。",
  "shrewd": "諧音聯想：\n諧音：「死路得」\n\n聯想畫面 1：他在絕境中找到生路，表現得十分精明幹練。\n\n聯想畫面 2：這位老闆做生意非常狡猾機靈，從不吃虧。\n\n高效擴充：形容人在商業或判斷上極具洞察力與算計。\nKK 音標：[ʃrud] -> 單音節字，sh 發 /ʃ/ 結合 rud。\n\n常見同義字：\nastute（機敏的，精明的）\ncunning（狡猾的，奸詐的）\nclever（聰明的，機靈的）",
  "shriek": "諧音聯想：\n諧音：「死瑞克」打針時發出恐怖尖叫。\n\n聯想畫面 1：看到怪物史瑞克突然復活，嚇得大家放聲尖叫。\n\n聯想畫面 2：指甲刮過黑板發出刺耳聲音，讓人忍不住尖叫。\n\n高效擴充：字首 sh 往往帶有摩擦或聲音的意象，如 shout。\nKK 音標：[ʃrik] -> 長音的 ee 結合 sh 發音，像氣流衝出嘴巴的感覺。\n\n常見同義字：\nscream（高分貝的驚叫、通常指恐懼或痛苦時）\nshout（大喊、大聲叫好或呼叫）\nsqueal（高亢短促的尖叫聲，像豬叫或小孩撒嬌）",
  "shrimp": "諧音聯想：\n諧音：這家餐廳的「蝦人普」遍受到好評，每盤都有新鮮的大蝦子。\n\n聯想畫面 1：夜市攤位上老闆正在大火快炒新鮮肥美的美味蝦子。\n\n聯想畫面 2：身高不高的男生自嘲自己像隻小蝦米一樣矮小。\n\n高效擴充：shr 開頭的字通常帶有縮小、乾枯的語感，如 shrink（縮水）。\nKK 音標：[ʃrɪmp] -> 單音節字，複合子音 shr 需連讀自然。\n\n常見同義字：\nprawn（明蝦、對蝦，通常指較大隻的蝦）\nlobster（龍蝦）\ncrustacean（甲殼動物，較學術的詞）",
  "shrine": "諧音聯想：\n諧音：「誰來恩」賜，大家虔誠地聚集在聖壇前參拜。\n\n聯想畫面 1：日本寺廟裡供奉神明的神龕與莊嚴的聖壇。\n\n聯想畫面 2：將過世偶像的專輯與照片供奉在家裡的角落，成為個人小聖殿。\n\n高效擴充：字尾 ine 常出現在名詞中，此字指神聖場所。\nKK 音標：[ʃraɪn] -> 雙母音 i 的發音要飽滿，重音在整個字上。\n\n常見同義字：\ntemple（寺廟、廟宇，範圍較大）\nsanctuary（庇護所、聖殿，強調安全神聖）\naltar（祭壇、聖壇，專指舉行儀式的台子）",
  "shrink": "諧音聯想：\n諧音：「死人骨」台語諧音聯想\n\n聯想畫面 1：毛衣用熱水洗過之後竟然嚴重縮水，小了一半。\n\n聯想畫面 2：看到恐怖的帳單金額，嚇得他把頭縮了回去。\n\n高效擴充：注意 i 發短音 [ɪ]，三態為 shrink, shrank, shrunk。\nKK 音標：[ʃrɪŋk] -> 複合子音 shr 開頭髮「許入」的摩擦音，nkr 鼻音結尾。\n\n常見同義字：\n\ncontract（收縮、合約，正式用語）\n\nnarrow（變窄，強調寬度縮減）\n\ndwindle（逐漸減少、縮小）",
  "shrub": "諧音聯想：\n諧音：「樹拔」不掉的矮灌木，長得矮矮胖胖的。\n\n聯想畫面 1：花園裡修剪得整整齊齊的矮樹叢與綠化灌木。\n\n聯想畫面 2：在野外健行時，衣服不小心被矮樹叢勾住。\n\n高效擴充：與 tree 相比，shrub 通常指多莖且矮小的灌木叢。\nKK 音標：[ʃrʌb] -> 短母音 u 念短促的「啊」音，結尾 b 要輕聲閉唇。\n\n常見同義字：\nbush（灌木、灌木叢，口語常用）\nunderbrush（矮樹林地帶的雜草叢）\nhedge（樹籬、綠籬，通常指修剪成牆狀的灌木）",
  "shrubbery": "諧音聯想：\n諧音：「休吧！綠人佈理」\n\n聯想畫面 1：城堡外圍修剪得整整齊齊的一大片灌木叢，看起來真適合休息。\n\n聯想畫面 2：造景師傅在庭院裡規畫了一個專門種植各種灌木的灌木林區。\n\n高效擴充：由 shrub（灌木）加上字尾 -ery（場所、集合名詞）構成。\nKK 音標：[ˋʃrʌbəri] -> 第一音節 shrub 重音，r 捲舌清晰。\n\n常見同義字：\n\nbushes（矮樹叢複數）\n\nthicket（稠密的灌木小樹叢）\n\nhedge（樹籬）",
  "shrug": "諧音聯想：\n諧音：「死然抓」\n\n聯想畫面 1：被問到不知道的問題時，他無奈地聳聳肩膀。\n\n聯想畫面 2：穿著女式緊身短套衫的女孩輕鬆地聳肩表示隨便。\n\n高效擴充：shrug off 表示對某事不屑一顧或擺脫。\nKK 音標：[ʃrʌɡ] -> 單音節字，ʃr 結合短元音 ʌ 與 ɡ 結尾。\n\n常見同義字：\nelevate shoulders（抬高肩膀）\ndismiss（不予理會）\nignore（忽視）」}, {",
  "shudder": "諧音聯想：\n諧音：「嚇達」到全身發抖、直打哆嗦。\n\n聯想畫面 1：冬天寒風吹來，冷得身體忍不住一陣劇烈震動與發抖。\n\n聯想畫面 2：聽到恐怖的兇殺案細節，心裡害怕得戰慄起來。\n\n高效擴充：字根 shudder 常與恐懼或寒冷引起的身體反射動作有關。\nKK 音標：[ˋʃʌdɚ] -> 重音在第一音節 sha，注意 dd 的輕快彈舌感。\n\n常見同義字：\nshiver（因寒冷或害怕而微微發抖）\ntremble（因情緒激動、緊張或虛弱而顫抖）\nquake（地震般的搖晃或劇烈顫抖）",
  "shun": "諧音聯想：\n諧音：看到討厭的人走過來趕快「閃」，就是故意避開他。\n\n聯想畫面 1：因為他曾經背叛朋友，大家現在聚會都主動躲開他、孤立他。\n\n聯想畫面 2：流浪狗身上髒兮兮的，路人經過時紛紛閃避、繞道而行。\n\n高效擴充：短小精悍的單字，發音短促，象徵快速閃躲的動作。\nKK 音標：[ʃʌn] -> 單音節字，母音 [ʌ] 發短促的「啊」音，尾音 [n] 鼻音收尾。\n\n常見同義字：\navoid（避開，最常用的日常迴避動詞）\nstay away from（遠離，口語常用片語）\nignore（忽視，強調不予理會）",
  "shut": "諧音聯想：\n諧音：「殺特」\n\n聯想畫面 1：店長大喊殺特價結束，趕快把鐵捲門關上打烊。\n\n聯想畫面 2：生氣地把筆記本用力合上，停止運作。\n\n高效擴充：三態同型（shut-shut-shut），常用片語如 shut up（閉嘴）。\nKK 音標：[ʃʌt] -> 短音 u，發音急促且帶有阻斷感，符合關上的動作。\n\n常見同義字：\nclose（最常用的關閉、打烊）\nslam（用力砰地關上）\nlock（上鎖關閉）",
  "shutter": "諧音聯想：\n諧音：「瞎搭」百葉窗，結果光線還是漏進來。\n\n聯想畫面 1：颱風天來臨前，趕緊把店家的鐵捲門與窗戶百葉窗關好。\n\n聯想畫面 2：攝影師按下相機快門的瞬間，捕捉美麗風景。\n\n高效擴充：由 shut（關閉）加上表工具的 ter 結尾形成。\nKK 音標：[ˋʃʌtɚ] -> 重音在第一音節 shut，注意 t 的爆破音。\n\n常見同義字：\nblind（百葉窗、遮光簾，常指室內）\nlouver（百葉板、通風葉片）\nsnapshot（快照、快門拍下的照片）",
  "shuttle": "諧音聯想：\n諧音：「休踏」\n\n聯想畫面 1：機場接駁車在航廈之間頻繁地往返運送旅客。\n\n聯想畫面 2：太空梭點火升空，穿梭於地球與太空之間。\n\n高效擴充：常見如 shuttle bus（接駁車）、space shuttle（太空梭）。\nKK 音標：[ˋʃʌtəl] -> 主重音在 ʃʌ，təl 發輕聲。\n\n常見同義字：\ncommute（通勤往返）\ntransport（運輸）\nback and forth（來回）」}, {",
  "shy": "諧音聯想：\n諧音：「害羞的甩」\n\n聯想畫面 1：看到心儀對象就「害羞」地甩開頭，不敢正眼看對方。\n\n聯想畫面 2：小馬因為看到陌生人而「驚退」，「害羞」地避開眾人的目光。\n\n高效擴充：加上字尾 ness 變成 shyness，意思為害羞或羞怯。\nKK 音標：[ʃaɪ] -> 單音節，以[ʃ]開頭接長雙元音[aɪ]，發音要完整飽滿。\n\n常見同義字：\n\ntimid（膽小的，側重性格懦弱與容易受驚）\n\nbashful（靦腆的，常用於形容小孩或少女的害羞）\n\nreserved（含蓄的，習慣隱藏感情而不輕易表達）",
  "sick": "諧音聯想：\n諧音：「吸客」\n\n聯想畫面 1：這家醫院標榜「吸客」術，專門治療各種「生病」的「病人」。\n\n聯想畫面 2：吃到變質的食物感到一陣「噁心」，衝到廁所忍不住「嘔吐」出來。\n\n高效擴充：加上字尾 ness 變成 sickness，表示疾病或噁心想吐的感覺。\nKK 音標：[sɪk] -> 單音節，中間為短元音[ɪ]，嘴唇微張、發音短促清晰。\n\n常見同義字：\n\nill（生病的，英式英語常用，較比 sick 正式）\n\nunwell（身體不適的，語氣較輕微溫和）\n\nailing（抱病的、衰弱的，常用於長期生病）",
  "side": "諧音聯想：\n諧音：「塞的」\n\n聯想畫面 1：把行李箱塞在車子的側面與一旁空間。\n\n聯想畫面 2：在球場上，你必須明確決定要支援、站在哪一個球隊的一邊。\n\n高效擴充：字尾加 e 形成長母音，與 hide, ride 同音韻。\nKK 音標：[saɪd] -> 複合子音 s 與 d 夾著長母音 ai。\n\n常見同義字：\nedge（指物體的邊緣或刀刃）\nflank（軍事或動物身體的側翼）\npart（指整體當中的一部分或側邊）",
  "sidewalk": "拆解：side（旁邊）+ walk（走）\n\n諧音：賽得挖克\n\n諧音：「賽得挖克」在馬路「旁邊走路」時，一定要走在安全的人行道上。\n\n聯想畫面 1：放學的學童背著書包，開心地走在寬敞的人行道上回家。\n\n聯想畫面 2：城市街道旁規劃完善的人行道讓行人免於車陣危險。\n\n高效擴充：美式英文常用 sidewalk，英式英文則常用 pavement。\nKK 音標：[ˋsaɪd͵wɔk] -> 第一音節重音在 sîde，walk 的 l 不發音。\n\n常見同義字：\npavement（人行道，英式用法）\nfootpath（小徑、人行道）\nwalkway（走道、通道）",
  "siege": "諧音聯想：\n諧音：吸橘。\n\n聯想畫面 1：城堡被敵軍團團 siege 圍困，城內的人連吸橘子的機會都沒有。\n\n聯想畫面 2：漫長的圍城戰讓軍隊疲憊不堪。\n\n高效擴充：與 seat 坐有關，坐在城外死守不走就是包圍。\nKK 音標：[sidʒ] -> 長音 i，結尾 dʒ 像英文的 j 摩擦音。\n\n常見同義字：\n\nblockade（封鎖）\n\nencirclement（包圍圈）\n\ninvestment（軍事圍攻）。",
  "sigh": "諧音聯想：\n諧音：「賽」\n\n聯想畫面 1：考試成績出來又考砸了，忍不住長嘆一氣說真賽。\n\n聯想畫面 2：加班到深夜的上班族看著滿桌公文，發出一聲深沉的嘆息。\n\n高效擴充：gh 在字尾常不發音，僅保留前面的長母音 i 發 [saɪ]。\nKK 音標：[saɪ] -> 單音節字，ai 發雙母音「愛」，長音延伸。\n\n常見同義字：\n\ngroan（呻吟、抱怨，通常伴隨痛苦或不滿的聲音）\n\nbreath（呼吸、氣息，名詞用法）\n\nsob（啜泣、嗚咽，哭泣時的嘆氣聲）",
  "sight": "諧音聯想：\n諧音：「塞特的」\n\n聯想畫面 1：埃及神明塞特看到的壯麗景象與視力極佳。\n\n聯想畫面 2：在狙擊鏡裡一眼看到目標，立刻把槍瞄準。\n\n高效擴充：gh 不發音，字尾 ghter 常見於 daughter, fighter。\nKK 音標：[saɪt] -> g 不發音，注意 ai 的長音清晰度。\n\n常見同義字：\nvision（強調視覺能力或眼光遠見）\nview（指從特定角度看到的風景）\nscene（指戲劇或真實發生的場景）",
  "sightseeing": "諧音聯想：\n諧音：拆解/諧音：「sight 景觀 + seeing 看見」\n\n聯想畫面 1：觀光客拿著地圖在知名景點開心拍照遊覽。\n\n聯想畫面 2：參加旅行團的行程主要是市區觀光與古蹟巡禮。\n\n高效擴充：由 sight（風景）與 see（看）結合成的複合名詞。\nKK 音標：[ˋsaɪtˋsiɪŋ] -> 雙重音結構，saɪt 與 siɪŋ 都要清晰發音。\n\n常見同義字：\ntourism（旅遊業、觀光）\nexploring（探索）\nvisiting sights（參觀景點）」}, {",
  "sign": "諧音聯想：\n諧音：「賽因」比賽前，選手必須先在合約上簽名。\n\n聯想畫面 1：開車時看到路邊的禁止停車標誌，駕駛立刻減速。\n\n聯想畫面 2：占卜師從星象中看出了一些即將發生的大事徵兆。\n\n高效擴充：g 不發音，衍生字有 signature（簽名）、signal（信號）。\nKK 音標：[saɪn] -> 單音節字，長母音 ai 嘴型由大變小。\n\n常見同義字：\nmark（記號、斑點）\nsymbol（符號、象徵）\nautograph（親筆簽名，多指名人）",
  "signal": "諧音聯想：\n諧音：「死個諾」\n\n聯想畫面 1：特務發出暗號說任務失敗就死個諾言，這是一個重大訊號。\n\n聯想畫面 2：交通警察在路口揮手示意，這就是行車的重要標誌訊號。\n\n高效擴充：sign（標誌、簽名）加上結尾形容詞/名詞字尾 al。\nKK 音標：[ˋsɪɡnəl] -> 重音在第一個音節 sig，g 發硬音 [ɡ]。\n\n常見同義字：\n\nsign（標誌、符號，範圍較廣的記號）\n\nindication（跡象、表明，較正式的說法）\n\ngesture（手勢、姿態，指身體動作的信號）",
  "signature": "諧音聯想：\n諧音：洗格那趣。聯想畫麵 1：大明星簽名時很有 signature 標誌性的風格，洗格那趣就是他的個人招牌。聯想畫麵 2：在合約上鄭重寫下自己的 signature 簽名。\n\n高效擴充：字根 sign 代表標記，加上表名詞的字尾。\nKK 音標：[ˋsɪɡnətʃɚ] -> 重音在第一音節 sìg，tʃɚ 發 chure 的音。\n\n常見同義字：\n\nautograph（親筆簽名）\n\nsign（記號）\n\nstamp（印記）。",
  "significance": "諧音聯想：\n諧音：拆解/諧音：「significant 重要之延伸名詞」\n\n聯想畫面 1：科學家研究這項重大發現背後的歷史意義。\n\n聯想畫面 2：這份合約的重要性不言可喻，雙方都非常謹慎。\n\n高效擴充：形容詞為 significant（重要的、顯著的）。\nKK 音標：[səɡˋnɪfɪkəns] -> 主重音在 nɪf，字尾 kəns 念輕聲。\n\n常見同義字：\nimportance（重要性）\nmeaning（意義）\nvalue（價值）」}, {",
  "significant": "拆解：sig（簽名）＋nif（呢幅）＋ic（的）\n\n諧音：「細個呢幅畫好重要」\n\n聯想畫面 1：這張重要的合約上有關鍵的簽名，具有重大意義。\n\n聯想畫面 2：研究結果顯示出顯著的差異，對整個實驗非常關鍵。\n\n高效擴充：字尾 icant 是常見形容詞結尾，名詞為 significance。\nKK 音標：[səɡˋnɪfɪkənt] -> 重音在第二音節的 ˋnɪf。\n\n常見同義字：\nimportant（重要的，最普遍）\nsubstantial（重大的、相當數量的）\nmeaningful（有意義的）",
  "signified": "諧音聯想：\n諧音：死個內飛的。\n\n聯想畫面 1：這隻鳥死在內側飛不出來，象徵著這場比賽的結束。\n\n聯想畫面 2：他在紙上畫個叉，這符號意味著禁止通行。\n\n高效擴充：字根 sign 代表標記，加上 fy 變成動詞。\nKK 音標：[ˋsɪɡnɪfaɪd] -> 重音在第一個音節，注意後面的 ed 發 id 的音。\n\n常見同義字：\n\nmeant（意指，較口語）\n\nsymbolized（象徵，強調代表性）\n\nindicated（顯示，強調指出）。",
  "signify": "諧音聯想：\n諧音：「洗個泥化影」\n\n聯想畫面 1：你把泥巴洗掉，化成影像來表示……的意思、意味著。\n\n聯想畫面 2：用手勢象徵與表達你的想法。\n\n高效擴充：sign (記號) 加上字尾 ify (使成為)，使之成為記號就是象徵。\nKK 音標：[ˋsɪɡnə͵faɪ] -> 第一音節重音，gi 發短音 i，fi 發長音 i。\n\n常見同義字：\n\nmean（表示意思，通常用於口語解釋）\n\nexpress（表達感情或意見，較常直接接受詞）\n\nindicate（指出或暗示，語氣較正式）",
  "signposted": "諧音聯想：\n拆解：sign（標誌）+ post（柱子）+ ed（過去式）\n\n聯想畫面 1：這條登山步道沿途都 signposted，插滿了路標，完全不用擔心迷路。\n\n聯想畫面 2：演講者在開頭就 signposted 他的論點，讓聽眾清楚知道接下來要講什麼。\n\n高效擴充：post 除了郵件，還有柱子的意思，signpost 就是立在路邊的指示牌。\nKK 音標：無 -> 重音在第一個音節 sign，發音時注意後面的 post 要發出清脆的 t 音。\n\n常見同義字：\n\nmarked（標記的，通用的標示）\n\nindicated（指出的，強調引導方向）\n\nguided（引導的，強調帶領過程）",
  "silence": "諧音聯想：\n諧音：「賽藍絲」比賽現場突然一片死寂，全場鴉雀無聲。\n\n聯想畫面 1：圖書館內規定必須保持安靜，大家都在無聲的環境中讀書。\n\n聯想畫面 2：老師比出一個安靜的手勢，讓吵鬧的教室瞬間安靜下來。\n\n高效擴充：形容詞為 silent（安靜的、沉默的）。\nKK 音標：[ˋsaɪləns] -> 第一音節重音在 sîe，lence 念輕短的 ləns。\n\n常見同義字：\nquiet（安靜，較生活化且可作動詞與形容詞）\nstillness（靜止、平靜，偏向自然界的寧靜）\nhush（安靜、噓聲，多作感嘆詞或祈使句）",
  "silent": "諧音聯想：\n諧音：「塞藍燈」\n\n聯想畫面 1：圖書館裡大家把藍色的燈光塞住熄滅，保持完全的寂靜。\n\n聯想畫面 2：他平時在會議中總是保持沉默寡言，很少主動發言。\n\n高效擴充：字尾 lent 是形容詞字尾，名詞形式為 silence（安靜、沉默）。\nKK 音標：[ˋsaɪlənt] -> 第一音節 si 重音，ai 發開口長音 i。\n\n常見同義字：\n\nquiet（安靜的，通常指聲音小）\n\nnoiseless（無聲的）\n\ntaciturn（沉默寡言的，形容個性）",
  "silhouette": "諧音聯想：\n諧音：希露愛特。\n\n聯想畫面 1：夕陽下，他的 silhouette 剪影顯得特別孤單。\n\n聯想畫面 2：這張照片只拍出 silhouette 輪廓，充滿神秘感。\n\n高效擴充：源自法國財政大臣 Silhouette，他喜歡剪影藝術。\nKK 音標：[͵sɪluˋet] -> 重音在第三音節，et 發音要輕快。\n\n常見同義字：\n\noutline（輪廓）\n\nshadow（影子）\n\nprofile（側影）。",
  "silicon": "諧音聯想：\n諧音：西力康。聯想畫麵 1：高科技產業的核心就是矽 silicon，就像用西力康膠黏起晶片。聯想畫麵 2：矽谷之所以叫 Silicon Valley 就是因為這個化學元素。\n\n高效擴充：常見於半導體與科技相關詞彙。\nKK 音標：[ˋsɪləkən] -> 重音在 sì，後面音節唸得輕快。\n\n常見同義字：\n\nsemiconductor（半導體）\n\nchip（晶片）\n\nmineral（礦物）。",
  "silk": "諧音聯想：\n諧音：「絲客」喜歡穿著高級蠶絲材質衣服的時尚客。\n\n聯想畫面 1：新娘身上穿著價值不菲的純白絲綢手工婚紗。\n\n聯想畫面 2：高級服飾店的衣架上掛滿了觸感滑順的綢布襯衫。\n\n高效擴充：形容詞為 silky（如絲般光滑的）。\nKK 音標：[sɪlk] -> 單音節字，短母音 i 搭配 lk 結尾。\n\n常見同義字：\nthread（線、絲線）\nfabric（織品、布料）\nsatin（緞布，光澤感更強的織物）",
  "silkworm": "拆解：silk（絲）+ worm（蟲）\n\n諧音：絲客蟲\n\n聯想畫面 1：養蠶寶寶時，每天都要餵牠們吃新鮮的桑葉。\n\n聯想畫面 2：吐出大量蠶絲並結成繭，準備化蛹的桑蠶。\n\n高效擴充：結合了材料 silk 與昆蟲 worm 的複合字，非常直觀。\nKK 音標：[ˋsɪlkwɚm] -> 重音在第一音節 silk，注意 w 捲舌音。\n\n常見同義字：\ncaterpillar（毛毛蟲，泛指一般蝴蝶或蛾的幼蟲）\npupa（蛹，蠶結繭後的階段）\nmoth（蛾，蠶長大後變成的成蟲）",
  "silly": "諧音聯想：\n諧音：「西力」\n\n聯想畫面 1：這個「傻瓜」以為吃下「西力」神仙丹就能變聰明，真是太「愚蠢」了。\n\n聯想畫面 2：看到小狗做出的「笨拙」動作，大家覺得既「傻」又好笑。\n\n高效擴充：與 stupid 相比，silly 語氣較輕微且常帶有討喜或開玩笑的意味。\nKK 音標：[ˋsɪli] -> 重音在第一音節，雙寫 l 發單音[l]，字尾 y 發短音[i]。\n\n常見同義字：\n\nfoolish（愚蠢的，強調缺乏明智的判斷力）\n\nstupid（笨拙的，語氣較強且帶有貶義）\n\nidiotic（極度愚蠢的，語氣極強，表示像白痴一樣）",
  "silver": "諧音聯想：\n諧音：「洗了佛」\n\n聯想畫面 1：把沾滿灰塵的銀器和銀幣用水洗了佛像般的發亮。\n\n聯想畫面 2：老人的頭髮變成美麗的銀白色。\n\n高效擴充：字尾 er 表示名詞或形容詞屬性，常用於金屬色澤。\nKK 音標：[ˋsɪlvɚ] -> 第一音節重音，v 的音要輕咬下唇。\n\n常見同義字：\ngold（金製的或金色的）\nplatinum（白金製的或白金色的）\nmetallic（金屬製品或金屬質感的）",
  "similar": "諧音聯想：\n諧音：「細米粒兒」\n\n聯想畫面 1：這兩碗白飯的細米粒長得簡直一模一樣、十分相似。\n\n聯想畫面 2：雙胞胎兄弟的穿衣風格非常類似。\n\n高效擴充：常搭配介系詞 to 使用（be similar to 與...相似）。\nKK 音標：[ˋsɪməlɚ] -> 第一音節 sim 重音，lar 發輕聲 lɚ。\n\n常見同義字：\n\nalike（相像的，通常放句尾）\n\nlike（像...的）\n\nanalogous（類似的，較正式）",
  "similarity": "諧音聯想：\n拆解 / 諧音：\n拆解：similar（相似的）加上名詞字尾 ity\n\n聯想畫面 1：雙胞胎兄弟長相的相似點極高，幾乎分不出誰是誰。\n\n聯想畫面 2：兩份研究報告在數據上有高度類似性，引起抄襲懷疑。\n\n高效擴充：形容詞轉名詞的常見字尾 ity，會將前一個音節的母音轉為短音。\nKK 音標：[͵sɪməˋlɛrəti] -> 次重音在首音節，主重音在 lar 音節上。\n\n常見同義字：\n\nresemblance（相像、相似，常搭配 bear a resemblance）\n\nalikeness（相似性，較少用）\n\nuniformity（一致性、均勻，強調完全相同）",
  "simmer": "諧音聯想：\n諧音：「細悶」著火慢燉，湯頭才會濃郁。\n\n聯想畫面 1：廚房裡的牛肉湯在爐火上慢慢煨煮，發出咕嚕咕嚕的小沸聲。\n\n聯想畫面 2：心中的不滿與怒火在胸口逐漸醞釀，即將爆發。\n\n高效擴充：常用於烹飪技巧，或比喻情緒在心中醞釀。\nKK 音標：[ˋsɪmɚ] -> 重音在第一音節 sim，字尾 er 念輕聲。\n\n常見同義字：\nboil（沸騰、煮滾，程度比 simmer 強）\nstew（燉、煨，名詞也指燉菜）\nferment（發酵、比喻局勢醞釀惡化）",
  "simon": "諧音聯想：\n諧音：賽門（賽車的門）。\n\n聯想畫面 1：有個叫 Simon 的男生，最喜歡在賽車場門口當守門員。\n\n聯想畫面 2：Simon Says 是一個經典的兒童遊戲，中文叫西蒙說，訓練反應力。\n\n高效擴充：源自希伯來語，意為聽從。\nKK 音標：[ˋsaɪmən] -> 第一音節 saɪ 發長音，像是在說賽跑的賽，重音在前面。\n\n常見同義字：\n\nNone（專有名詞，無同義字）。",
  "simple": "諧音聯想：\n諧音：「心脯」\n\n聯想畫面 1：把「心脯」（真心）毫無保留地坦露出來，過著極其「簡樸」的日子。\n\n聯想畫面 2：這道數學題非常「簡單」，連小孩子都能寫出「簡明」的答案。\n\n高效擴充：字根 sim 有單一之意，引申為不複雜、單純簡單的事物。\nKK 音標：[ˋsɪmpəl] -> 重音在第一音節，注意結尾的[l]為成音節雙唇微張發音。\n\n常見同義字：\n\neasy（容易的，指不需要花費太多努力）\n\nstraightforward（簡單明瞭的，強調不複雜、直接）\n\nuncomplicated（不複雜的，指結構或情況很單純）",
  "simpleness": "拆解：simple（簡單）+ ness（性質）。\n\n聯想畫面 1：他喜歡鄉下生活的純樸，沒有都市的喧囂與複雜。\n\n聯想畫面 2：這道菜的美味在於其簡單，只用了最基本的調味料。\n\n高效擴充：與 simplicity 同義，但較少用，多指質樸的狀態。\nKK 音標：['simplnis] -> 重音在第一個音節，唸起來要輕柔。\n\n常見同義字：\n\nsimplicity（較常用，指簡單的狀態）\n\nplainness（樸素，強調外觀）。",
  "simplicity": "諧音聯想：\n諧音：心普利希提。聯想畫麵 1：過著簡單 simplicity 的生活，心裡普普利利就很喜悅。聯想畫麵 2：這套軟體操作上的 simplicity 讓新手一學就會。\n\n高效擴充：來自 simple 簡單，字尾 -ity 形成抽象名詞。\nKK 音標：[sɪmˋplɪsəti] -> 主重音在 plì 音節。\n\n常見同義字：\n\nclarity（清晰）\n\nplainness（樸素）\n\nease（容易）。",
  "simplify": "諧音聯想：\n諧音：「心普來化影」\n\n聯想畫面 1：心裡普普通通地拿來化解複雜，就是簡化。\n\n聯想畫面 2：把繁雜的考題精簡，使單純易懂。\n\n高效擴充：simple (簡單的) 加上 ify (使成為)，意即使簡單。\nKK 音標：[ˋsɪmplə͵faɪ] -> 第一音節重音，simp 發短音 i，ply 轉輕聲，fi 發長音 i。\n\n常見同義字：\n\nstreamline（簡化流程，通常用於工作或設計）\n\nease（減輕或使容易，多用於負擔或痛苦）\n\nfacilitate（使容易，通常指促進某事進行）",
  "simply": "諧音聯想：\n諧音：「心不累」\n\n聯想畫面 1：把繁雜的工作簡化，做起來心不累，一切就是這麼簡單。\n\n聯想畫面 2：他拒絕得乾脆，直說自己不過就是不想去罷了。\n\n高效擴充：由形容詞 simple 去 e 加 y 轉為副詞。\nKK 音標：[ˋsɪmpli] -> 第一音節重音，p 與 l 的連音要分明。\n\n常見同義字：\n\nstraightforwardly（直截了當地，強調不拐彎抹角）\n\nclearly（清楚地，強調明白易懂）\n\nplainly（坦白地、樸素地，強調毫無掩飾）",
  "simulate": "諧音聯想：\n諧音：「誰（Si）+ 謬（mu）+ 累（late）」\n\n聯想畫面 1：為了訓練飛行員，電腦模擬出極度逼真的飛行環境，讓學員感覺像真的一樣。\n\n聯想畫面 2：遊戲中模擬經營類遊戲，讓玩家體驗當市長或農場主的樂趣。\n\n高效擴充：字根 simul 意為相同，simulate 就是讓事物看起來跟真實的一樣。\nKK 音標：[ˋsɪmjələt] -> 重音在第一音節，注意 mu 的發音要圓唇。",
  "simulation": "諧音聯想：\n拆解 / 諧音：「Simulate（模擬）+ tion（名詞字尾）」\n\n聯想畫面 1：科學家進行氣候變遷的 simulation，用數據預測未來幾十年的地球變化。\n\n聯想畫面 2：虛擬實境技術帶來的沉浸式體驗，其實就是一種高科技的模擬過程。\n\n高效擴充：由動詞 simulate 轉變而來的名詞，指模擬的狀態或結果。\nKK 音標：[͵sɪmjəˋleʃən] -> 重音在第三音節 le，結尾 tion 發音為 ʃən。",
  "simultaneous": "諧音聯想：\n諧音：「誰買得起太牛的視訊」\n\n聯想畫面 1：兩部電腦同時播放畫面，做到完美的同步發生。\n\n聯想畫面 2：現場直播與口譯是同時進行的。\n\n高效擴充：字根 simul-（相同）加上 time（時間）。\nKK 音標：[͵saɪməlˋteniəs] -> 主重音在第四音節 ta，次重音在開頭。\n\n常見同義字：\nconcurrent（同時發生的，一致的）\nsynchronous（同步的，同時的）\nparallel（平行的，同時進行的）",
  "sin": "諧音聯想：\n諧音：「新」\n\n聯想畫面 1：犯了滔天大罪的人，面對神父懺悔自己做的新罪惡。\n\n聯想畫面 2：偷吃禁果在宗教裡被視為一種過錯與罪過。\n\n高效擴充：字尾加 n 就變成 sinner（罪人），是常見的基礎衍生字。\nKK 音標：[sɪn] -> 單音節短母音，i 發短促的「伊」音。\n\n常見同義字：\n\ncrime（罪行，指違法的行為）\n\nwrongdoing（壞事、違法營生，廣義的過失）\n\noffense（冒犯、違法行為，較中性的詞彙）",
  "since": "諧音聯想：\n諧音：「心死」\n\n聯想畫面 1：自從那次分手之後，他心死至今，再也沒有談過戀愛。\n\n聯想畫面 2：因為對這家公司的制度心死，所以他決定下個月正式離職。\n\n高效擴充：字根概念表示時間的起點，完成式句型中極高頻出現。\nKK 音標：[sɪns] -> 注意中間是短元音 ɪ，尾音 S 要輕聲吐氣發出清音。\n\n常見同義字：\n\nbecause（因為，強調直接原因）\n\nas（因為/自從，語氣較輕的理由或時間）\n\never since（自從那時起，強調時間持續性）",
  "sincere": "諧音聯想：\n諧音：「新絲路」\n\n聯想畫面 1：他帶著真誠的心意走在新絲路上，態度非常誠懇。\n\n聯想畫面 2：這封信的結尾表達了我們最誠摯的謝意。\n\n高效擴充：字尾 ere 發 [ɪr]，名詞為 sincerity。\nKK 音標：[sɪnˋsɪr] -> 重音在第二音節的 ˋsɪr。\n\n常見同義字：\nhonest（誠實的）\ngenuine（真誠的、真正的）\nheartfelt（衷心的、誠摯的）",
  "sincerely": "諧音聯想：\n諧音：「心（Sin）+ 希（ce）+ 瑞（re）+ 裡（ly）」\n\n聯想畫面 1：寫信結尾時寫下 Sincerely，代表我心裡最真誠的祝福都藏在信裡。\n\n聯想畫面 2：在正式場合誠懇地道歉，眼神真誠地看著對方，展現出誠意。\n\n高效充：源自 sincere 真誠的，加上 ly 變成副詞。\nKK 音標：[sɪnˋsɪrli] -> 重音在第二音節，sincere 發音要拉長。",
  "sincerity": "諧音聯想：\n諧音：拆解/諧音：「sincere 真誠之名詞變化」\n\n聯想畫面 1：他帶著滿滿的誠心誠意向對方道歉，獲得原諒。\n\n聯想畫面 2：這份禮物雖然簡單，但充滿了真摯的心意。\n\n高效擴充：由 sincere 去 e 加 ity 轉為名詞。\nKK 音標：[sɪnˋsɛrəti] -> 主重音在 sɛr，字尾 ty 發輕柔的 ti 音。\n\n常見同義字：\nhonesty（誠實）\ngenuineness（純正、真誠）\ntruthfulness（真實性）」}]}[instruction] of the file types provided. 27 CFR Part 31 (formerly Part 194) defines the Wholesale and Retail Dealers in Liquors. These definitions describe who must register and pay the special tax (now suspended to $0) for selling liquor. It includes anyone selling distilled spirits, wine, or beer to other than consumers. For liquor (not beer)\n\nanyone selling in quantities of 20 wine gallons or more to the same person at the same time is presumed to be a wholesale dealer. 27 CFR 31.41-31.59. If you are selling *at wholesale*, then you are not a *retail* dealer. A retail dealer is limited to sales in quantities of less than 20 wine gallons to any one person at any one time (except when sold to another dealer). 27 CFR 31.81-31.95. If you sell to other dealers, or if you sell to the same person in amounts of 20 gallons or more, you are considered a wholesale dealer. Note that a wholesale dealer's license does not automatically permit sales to consumers unless specifically authorized (and often subject to state laws)\n\nbut generally TTB focuses on the wholesale/retail distinction based on volume and customer type. Also note that state laws might have different thresholds (e.g., some states define wholesale as anything over a case or to a licensed re",
  "sinful": "諧音聯想：\n諧音：「心（Sin）+ 否（ful）」\n\n聯想畫面 1：做了壞事後，心裡感到不安，覺得自己所作所為是 sinful 的罪惡行為。\n\n聯想畫面 2：形容極度美味但熱量爆表的甜點，常被戲稱為 sinful pleasure，因為吃下去會有罪惡感。\n\n高效擴充：sin 是罪惡，ful 是充滿，合起來就是充滿罪惡的。\nKK 音標：[ˋsɪnfəl] -> 重音在第一音節，sin 發音短促。",
  "sing": "諧音聯想：\n諧音：「心」聲大聲唱出來\n\n聯想畫面 1：歌手在舞台上把內「心」深處的感情全都用歌曲唱歌表達出來。\n\n聯想畫面 2：在 KTV 裡大家跟著麥克風開心大聲歌唱，盡情釋放壓力。\n\n高效擴充：字尾 ng 發鼻音，跟歌曲 song 屬於同字根家族。\nKK 音標：[sɪŋ] -> 注意 i 發短音 /ɪ/，字尾 ng 要有鼻音共鳴。\n\n常見同義字：\n\ncroon（低聲輕唱，常用於浪漫抒情歌）\n\nchant（反覆吟唱，常用於宗教或口號）\n\ncarol（歡唱，常用於聖誕節歌唱）",
  "singer": "諧音聯想：\n諧音：「新歌」\n\n聯想畫面 1：知名歌手在錄音室裡開口深情演唱新歌。\n\n聯想畫面 2：歌唱家站在舞台中央展現嘹亮歌聲。\n\n高效擴充：由動詞 sing 加上表示人的字尾 er 變化而來。\nKK 音標：[ˋsɪŋɚ] -> 第一音節重音，ŋ 鼻音要從鼻腔共鳴出來。\n\n常見同義字：\nvocalist（泛指聲樂家或樂團主唱）\nperformer（指任何表演者，包含舞者或歌手）\nmusician（指音樂家或演奏者）",
  "single": "諧音聯想：\n諧音：獨自在「森歌」林裡唱歌的「單身」貴族。\n\n聯想畫面 1：填寫表格時，感情狀態欄位勾選了單身未婚。\n\n聯想畫面 2：歌手發行了一張備受矚目的全新個人單曲唱片。\n\n高效擴充：常組成片語 single out（挑選出特定的人或物）。\nKK 音標：[ˋsɪŋɡəl] -> 第一音節重音在 sîng，gle 念輕短的 gəl。\n\n常見同義字：\nindividual（個人的、單獨的）\nunmarried（未婚的，較具法律或戶籍意味）\nsolo（單獨的、獨奏的）",
  "singular": "諧音聯想：\n諧音：「新古樂」\n\n聯想畫面 1：這個新古樂團風格非常非凡卓越，在音樂界是獨一無二的。\n\n聯想畫面 2：文法老師特別強調，這個名詞的單數形式非常特殊，不能隨便加 s。\n\n高效擴充：字根 sing- 代表單一、獨特，延伸出單數與非凡卓越的含意。\nKK 音標：[ˋsɪŋɡjəlɚ] -> 主重音在第一個音節 sing，唸短促有力，後面的 ɡjəlɚ 輕輕帶過。\n\n常見同義字：\nunique（獨一無二的，強調罕見特殊）\nexceptional（卓越的，強調超出常人）\nindividual（單個的，強調個體獨立）",
  "sink": "諧音聯想：\n諧音：「信客」搭乘的船隻不小心撞到冰山，開始漸漸下沉。\n\n聯想畫面 1：鐵達尼號在大海中不幸沉沒，成為世紀悲劇。\n\n聯想畫面 2：洗完碗盤後，把廚房水槽清洗乾淨並擦乾。\n\n高效擴充：三態變化為 sink、sank、sunk。\nKK 音標：[sɪŋk] -> 單音節字，鼻音 ŋ 緊接著 k 音結尾。\n\n常見同義字：\nbasin（洗臉盆、盆地）\nsubmerge（潛入水中、淹沒，較正式）\ndecline（下降、衰退，偏向抽象概念）",
  "sinking": "諧音聯想：\n諧音：心驚。\n\n聯想畫面 1：船隻正在 sinking，船員們心驚膽跳地準備逃生。\n\n聯想畫面 2：聽到這個壞消息，他感到一陣 sinking 的感覺，心情瞬間跌入谷底。\n\n高效擴充：sink 的現在分詞，既可指物理上的下沉，也可指心理上的頹喪。\nKK 音標：[ˋsɪŋkɪŋ] -> 重音在第一個音節，注意 ng 的鼻音要發足。\n\n常見同義字：\n\ndescending（下降，較正式）\n\ndropping（掉落，通用）\n\ndepressed（抑鬱的，形容情緒）。",
  "sip": "諧音聯想：\n諧音：「吸破」\n\n聯想畫面 1：珍珠奶茶太大顆，用吸管吸破了也只能小口喝。\n\n聯想畫面 2：喝熱咖啡時怕燙，只好用嘴唇輕輕抿一小口。\n\n高效擴充：與 sap（樹液）或 slip（滑倒）拼法相似，注意母音是 i。\nKK 音標：[sɪp] -> 單音節短母音，p 閉口不發出爆破音。\n\n常見同義字：\n\ndrink（喝，最普通的動詞）\n\nsurp（啜飲，發出聲音地喝）\n\ntaste（品嚐、嘗味道，偏向感受滋味）",
  "siphoned": "諧音聯想：\n諧音：賽風的\n\n聯想畫面 1：想像你用一根管子把別人的汽油賽風的（抽吸）出來，就像在進行一場偷油比賽。\n\n聯想畫面 2：公司裡的貪污犯把公款像虹吸管一樣偷偷 siphoned off 挪用到自己的私人帳戶。\n\n高效擴充：siphon 來自希臘語，原意就是管子，常與 off 連用表示抽走資源。\nKK 音標：<無> -> 重音在第一個音節，發音時嘴型像吹管子一樣圓唇。\n\n常見同義字：\nwithdraw（提款或撤回，較正式）\ndrain（排乾液體，強調徹底抽乾）\ndivert（轉移資金或資源，強調改變流向）",
  "sir": "諧音聯想：\n諧音：「死而」想像對長官或老師鞠躬時說：長官我對您敬重到死而無憾。\n\n聯想畫面 1：服務生在高級餐廳彎腰對著客人說，請問這位先生需要點餐嗎。\n\n聯想畫面 2：商業英文信件一開頭寫著親愛的先生，展現出專業與尊重。\n\n高效擴充：源自法語單字 sire，常用於正式場合對男性長輩或客戶的尊稱。\nKK 音標：[sɝ] -> 舌頭往後捲的長音，重音在唯一的元音上，嘴型微扁。\n\n常見同義字：\nmister（縮寫為 Mr.，用於姓氏前較常見）\ngentleman（紳士，強調風度與禮貌）\nboss（老闆，偏向職場內部口語稱呼）",
  "sister": "諧音聯想：\n諧音：「細思特」細心思考特別照顧你的人就是親愛的姐妹或姐姐。\n\n聯想畫面 1：親姐妹兩人窩在沙發上，一起追劇吃零食聊天。\n\n聯想畫面 2：天主教修女穿著整齊修道服，在教堂內溫柔地照顧孤苦無依的小孩。\n\n高效擴充：字根 sis 常作為 sister 的親密口語簡稱。\nKK 音標：[ˋsɪstɚ] -> 第一音節 si 重讀，短促有力，t 音清晰。\n\n常見同義字：\nbrother（兄弟，相對的男性稱呼）\nnun（修女，專指宗教女性成員）\ncolleague（同事，有時可用 sister 衍生詞形容同質企業）",
  "sit": "諧音聯想：\n諧音：「膝」蓋彎曲坐下來\n\n聯想畫面 1：逛街走累了，趕快放鬆「膝」蓋並尋找椅子坐下休息。\n\n聯想畫面 2：服務生熱情地請賓客就座，確認這張大桌子能容納所有人。\n\n高效擴充：與 seat（座位，名詞）拼寫相似，sit 為常見動詞。\nKK 音標：[sɪt] -> 母音為短音 /ɪ/，嘴型稍微張開，尾音 t 輕輕發出。\n\n常見同義字：\n\nperch（棲息高處或暫時坐在邊緣）\n\nrecline（斜倚、斜躺著坐）\n\nbe seated（就座，比較正式的說法）",
  "site": "諧音聯想：\n諧音：「塞特」\n\n聯想畫面 1：工人把大卡車塞特別滿，準備開進建築工地現場。\n\n聯想畫面 2：工程師正在網路上幫新的觀光景點選址，決定將飯店坐落於海邊。\n\n高效擴充：常見於 website（網站）或 construction site（施工工地）。\nKK 音標：[saɪt] -> 長母音 aɪ，發音時嘴巴由大開口滑向 i 的微笑嘴型。\n\n常見同義字：\nlocation（地點，強調地理位置）\nposition（位置，強調相對方位）\nplace（地方，最廣泛通用的場所）",
  "sittings": "諧音聯想：\n諧音：希停。\n\n聯想畫面 1：議會開會期 sittings，大家坐在位子上希冀停下爭吵，達成共識。\n\n聯想畫面 2：畫家畫肖像時，需要模特兒多次的 sittings，才能完成作品。\n\n高效擴充：sit 的名詞化，加上 ing 表示持續的狀態。\nKK 音標：[ˋsɪtɪŋz] -> 第一音節重音，注意 s 的清音。\n\n常見同義字：\n\nsessions（會議期）\n\nmeetings（會議）\n\nperiods（時段）。",
  "situation": "諧音聯想：\n拆解 / 諧音：\n拆解：sit（坐）加上uation 結尾\n\n聯想畫面 1：大家坐定位後，老闆開始分析目前公司的嚴峻處境。\n\n聯想畫面 2：這場突如其來的雨打亂了戶外婚禮的整個情況與形勢。\n\n高效擴充：字根 sit 代表位置，引申為人事物所處的狀況與局面。\nKK 音標：[͵sɪtʃuˋeʃən] -> 主重音在 a 字前的 e 所在音節 a 處。\n\n常見同義字：\n\ncondition（狀況、條件，通常指物品或身體狀態）\n\nstate（狀態、國家，指暫時的形勢）\n\nposition（位置、職位，偏向空間或社會地位）",
  "six": "諧音聯想：\n諧音：「死克斯」打電動時打出六連擊的酷炫畫面。\n\n聯想畫面 1：骰子擲出數字六，大家興奮地大喊得獎了。\n\n聯想畫面 2：桌上擺著六個精緻的馬卡龍，剛好分給六位朋友。\n\n高效擴充：英文基礎數字，常作複合字字首如 six-pack。\nKK 音標：[sɪks] -> 短音 i 搭配結尾的 ks 子音群，發音要俐落。\n\n常見同義字：\nhalf dozen（半打，也就是六個）\nnumber six（第六號，常指特定編號）\nsextet（六重奏或六人組）",
  "sixpack": "諧音聯想：\n拆解：six（六）+ pack（包）。\n\n聯想畫面 1：健身房裡的猛男，肚子上有六塊明顯的腹肌，就像包裝好的六塊肌。\n\n聯想畫面 2：在超市買啤酒時，六罐裝成一組的包裝也叫 sixpack。\n\n高效擴充：形容腹肌時常用 have a sixpack。\nKK 音標：[ˋsɪkspæk] -> 重音在第一個音節，發音要短促有力。\n\n常見同義字：\n\nabs（腹肌的簡稱，最常用）\n\nmuscles（肌肉，泛指）\n\nsix-pack abs（完整說法）。",
  "sixteen": "諧音聯想：\n諧音：「死客廳」十六個人同時塞進小客廳裡辦派對。\n\n聯想畫面 1：青春洋溢的十六歲少女正在切生日蛋糕。\n\n聯想畫面 2：這本書總共有十六個章節，厚厚一本讓人讀得好充實。\n\n高效擴充：字尾 teen 代表十幾，重音要放在後面的 teen。\nKK 音標：[sɪkˋstin] -> 重音在第二音節 teen，尾音 n 要到位。\n\n常見同義字：\nsixteen years old（十六歲的年紀）\nsixteenth（第十六，序數詞）\nsixteen-bit（十六位元的電腦術語）",
  "sixty": "諧音聯想：\n諧音：「死氣踢」老爺爺雖然六十歲了還很有活力，把壞人踢飛。\n\n聯想畫面 1：高速公路上汽車時速限制正好是六十公里。\n\n聯想畫面 2：爺爺舉辦六十大壽派對，子孫滿堂非常熱鬧。\n\n高效擴充：字尾 ty 代表整十，重音在第一個音節。\nKK 音標：[ˋsɪksti] -> 重音在第一音節 six，t 音輕聲帶過。\n\n常見同義字：\nsixtieth（第六十，序數詞）\nthe sixties（二十世紀六十年代）\nsixty-four（六十四的常見數字）",
  "size": "諧音聯想：\n諧音：「塞子」衣服尺寸買太小，像塞子一樣緊緊塞在身上。\n\n聯想畫面 1：網購衣服時要先看尺寸表，挑選最適合自己的大小。\n\n聯想畫面 2：鞋店店員拿出一雙更大尺碼的鞋子供客人試穿。\n\n高效擴充：常搭配動詞 up 形成 size up（打量、評估）。\nKK 音標：[saɪz] -> 雙母音 ai 發音飽滿，結尾 z 帶點震動。\n\n常見同義字：\ndimension（尺寸、空間維度，偏正式）\nmeasurement（測量尺寸，具體數值）\nscale（規模、比例尺）",
  "sizeable": "拆解：size（尺寸）+ able（能夠的/有價值的）\n\n諧音：「塞租寶」\n\n聯想畫面 1：這個租金花費 sizeable，空間非常大可以塞很多東西。\n\n聯想畫面 2：公司今年獲得了一筆 sizeable 的大筆資金挹注。\n\n高效擴充：由名詞 size 加上形容詞字尾 -able 構成。\nKK 音標：[ˋsaɪzəb(ə)l] -> 主重音在第一個音節 saɪz，發雙母音 /aɪ/。\n\n常見同義字：\nconsiderable（相當大的、可觀的）\nsubstantial（大量的、實質的）\nlarge（大的）",
  "skate": "諧音聯想：\n諧音：「死給它」\n\n聯想畫面 1：教練嚴格要求把溜冰動作練好，死給它看也要學會滑冰。\n\n聯想畫面 2：年輕人在溜冰場穿著四輪溜冰鞋帥氣地旋轉。\n\n高效擴充：字尾的 e 不發音，用來讓前面的 a 發長音字母音 [e]。\nKK 音標：[sket] -> 單音節，sk 結合，a 發長音的 [e]。\n\n常見同義字：\n\nslide（滑行，不一定穿冰鞋）\n\nglide（滑翔、溜行，平穩地移動）\n\nboard（滑板滑行，常指 skate 的相關活動）",
  "skeleton": "諧音聯想：\n諧音：「死客勒痛」到只剩下皮包骨的骨骼。\n\n聯想畫面 1：萬聖節教室裡掛著一具白色的人體骨骼模型。\n\n聯想畫面 2：寫文章或做企劃前先擬定一份大綱與骨架結構。\n\n高效擴充：醫學與日常用語中常用來指骨架或基本架構。\nKK 音標：[ˋskɛlətən] -> 重音在第一音節 skel，中間音節念輕聲。\n\n常見同義字：\nbones（骨頭複數，口語常替換）\nframework（框架、結構，抽象或具體皆可）\noutline（大綱、輪廓，指計畫草案）",
  "skeptical": "諧音聯想：\n諧音：「死蓋牌看扣」\n\n聯想畫面 1：魔術師表演時，觀眾抱持懷疑態度的眼神盯著看。\n\n聯想畫面 2：對於這個好得不像真的投資案，大家都充滿懷疑。\n\n高效擴充：源自希臘文 skeptic（懷疑者）。\nKK 音標：[ˋskɛptəkəl] -> 重音在第一音節 skep，注意 c 發 /k/ 音。\n\n常見同義字：\ndoubtful（懷疑的，不確定的）\nquestioning（質疑的，提問的）\nunbelieving（不相信的）",
  "sketch": "諧音聯想：\n諧音：「死給去」\n\n聯想畫面 1：畫家時間死給去（行程）很趕，只好快速畫一張人物素描草圖。\n\n聯想畫面 2：主管在白板上簡單概述提案內容，畫了幾個粗樣圖解。\n\n高效擴充：字尾 -tch 發輕快的 /tʃ/ 音，類似打勾的動作。\nKK 音標：[skɛtʃ] -> 短母音 ɛ 發音短而急促，結尾的 -tch 要輕短乾脆。\n\n常見同義字：\ndrawing（圖畫，泛指一般繪畫）\noutline（大綱，強調輪廓與結構）\ndraft（草稿，多指文章或計畫初稿）",
  "ski": "諧音聯想：\n諧音：「死騎」\n\n聯想畫面 1：在雪地裡像瘋子一樣死騎著滑雪板往下衝。\n\n聯想畫面 2：冬天的北海道滑雪度假村擠滿了來滑雪的遊客。\n\n高效擴充：源自挪威語，複數直接加 s 拼為 skis。\nKK 音標：[ski] -> 雙字母 i 發長音的「伊」，簡單好記。\n\n常見同義字：\n\nsnowboard（單板滑雪，近年流行的極限運動）\n\nsurf（衝浪，水上的滑行運動）\n\nslide（滑動，動作較為平緩）",
  "skilfully": "拆解：skill（技巧）＋fully（充滿地）。\n\n聯想畫面 1：工匠充滿技巧地雕刻木頭，每一個動作都展現出 skilfully 的專業。\n\n聯想畫面 2：廚師 skilfully 地拋起鍋中的蔬菜，動作流暢又精準。\n\n高效擴充：skill 是名詞，加上 ful 變成形容詞，再加 ly 變成副詞。\nKK 音標：[ˋskɪlfəli] -> 重音在第一音節，注意 l 的發音要清晰。\n\n常見同義字：\n\nexpertly（熟練地，強調專家水準）\n\ncleverly（巧妙地，強調聰明）\n\nadroitly（靈巧地）。",
  "skill": "諧音聯想：\n諧音：「死客樂」把專業技能練到爐火純青，客人看了都很快樂。\n\n聯想畫面 1：主廚展現精湛的切菜刀工，這就是多年累積的廚藝技能。\n\n聯想畫面 2：求職履歷表上寫滿了各種電腦軟體操作技能。\n\n高效擴充：形容詞為 skillful（熟練的、巧妙的）。\nKK 音標：[skɪl] -> s 開頭的複合子音，短 i 發音輕快。\n\n常見同義字：\nability（能力，廣泛的天賦或學到的本事）\nexpertise（專門技術、專業知識）\ntalent（天份、才能）",
  "skilled": "諧音聯想：\n諧音：「死開得」\n\n聯想畫面 1：技術熟練的修車師傅三兩下就把死板開不動的車修好。\n\n聯想畫面 2：這位資深廚師刀工非常熟練。\n\n高效擴充：由名詞 skill 加上 ed 形成形容詞，強調透過學習獲得的專長。\nKK 音標：[skɪld] -> 單音節字，sk 發結合音，d 的結尾輕聲帶過。\n\n常見同義字：\n\nexpert（內行的、專家的）\n\nproficient（精通的、熟練的）\n\nadroit（靈巧的、熟練的）",
  "skillful": "諧音聯想：\n拆解 / 諧音：「skill（技巧）加 ful（充滿的）」\n\n聯想畫面 1：他充滿各種開鎖技巧，手法十分靈巧高超。\n\n聯想畫面 2：魔術師用有技術的雙手完成精彩表演。\n\n高效擴充：與 skilled 意思相近，但 skillful 更強調動作或技巧上的靈巧與巧妙。\nKK 音標：[ˋskɪlfəl] -> 第一音節 skill 重音，ful 發輕聲 fəl。\n\n常見同義字：\n\nclever（聰明的、靈巧的）\n\nmasterly（大師級的、巧妙的）\n\ndeexterous（靈巧的、敏捷的）",
  "skim": "諧音聯想：\n諧音：死看。聯想畫麵 1：讀書考試時不要死看，要學會快速 skim 瀏覽重點。聯想畫麵 2：把牛奶上層的浮油 skim 撈去。\n\n高效擴充：雙重含義，既指快速瀏覽文章，也指撈去表面浮沫。\nKK 音標：[skɪm] -> 短 i 音，sk 連音要俐落。\n\n常見同義字：\n\nscan（掃描瀏覽）\n\nbrowse（瀏覽）\n\nread quickly（快速閱讀）。",
  "skin": "諧音聯想：\n諧音：「死啃」把炸雞的酥脆表皮剝下來死命啃乾淨。\n\n聯想畫面 1：擦完保養品後，臉部皮膚變得水嫩光滑。\n\n聯想畫面 2：遊戲角色的外觀造型換上了一套全新的皮膚特效。\n\n高效擴充：常見複合字 skincare（保養品、護膚）。\nKK 音標：[skɪn] -> sk 開頭，短音 i 加上結尾鼻音 n。\n\n常見同義字：\npeel（水果的皮或削皮動作）\nhide（獸皮，通常指大型動物的皮革）\ncomplexion（人的膚色、面色）",
  "skinny": "諧音聯想：\n諧音：「死雞內」器官太小，瘦得像沒肉一樣。\n\n聯想畫面 1：一隻瘦骨嶙峋的雞，排骨清晰可見，讓人直呼這隻雞實在太 skinny 了。\n\n聯想畫面 2：女生買了件超緊身的牛仔褲，穿上去整個人顯得非常 skinny。\n\n高效擴充：由 skin（皮膚）加上 y 轉為形容詞，指皮包骨的。\nKK 音標：[ˋskɪni] -> 重音在第一音節 ski，短音 i 念輕快短促。\n\n常見同義字：\nthin（形容一般瘦或薄，程度較中性）\nslim（形容苗條、線條好看的瘦，褒義居多）\nbone（指瘦得只剩骨頭或極度乾瘦）",
  "skip": "諧音聯想：\n諧音：「死騎跑」\n\n聯想畫面 1：小女孩開心地在路上蹦蹦跳跳地走，一路跑著跳著。\n\n聯想畫面 2：寫考卷時遇到不會的題目，只好直接跳過不做。\n\n高效擴充：與 sip 拼法僅差一個字母 k，字義完全不同。\nKK 音標：[skɪp] -> 單音節短母音，sk 子音群開頭，i 發短音。\n\n常見同義字：\n\njump（跳躍，一般的跳）\n\nleap（躍過、跳過，跨距較大的跳）\n\nomit（省略、跳過，較正式的書面用語）",
  "skirt": "諧音聯想：\n諧音：「死溝的」\n\n聯想畫面 1：走在路上看到辣妹穿著一條超漂亮的短裙，忍不住驚呼這條裙子死溝的（太美了）！\n\n聯想畫面 2：開車行經山路時，車子剛好繞開山崖邊緣的危險地帶。\n\n高效擴充：字首 sk- 常與表面、滑動或皮膚有關，skirt 也有繞開、邊緣的意思。\nKK 音標：[skɝt] -> 嘴型扁平發長音的 er，主重音在結尾，氣音要俐落。\n\n常見同義字：\n\ndress（連身裙，通常指整件式的服裝）\n\nskirt（半身裙，單指腰部以下的裙子）\n\ncircumvent（環繞、迴避，為較正式的高級用字）",
  "skull": "諧音聯想：\n諧音：「死咖」被打到頭骨，非常危險。\n\n聯想畫面 1：海賊王旗幟上面經典的骷髏頭標誌。\n\n聯想畫面 2：安全帽保護騎士的顱骨，避免發生嚴重車禍。\n\n高效擴充：與 skeleton（全身骨骼）不同，skull 專指頭部頭骨。\nKK 音標：[skʌl] -> 短母音 u 配合結尾 ll 的厚重子音。\n\n常見同義字：\ncranium（顱骨、頭蓋骨，較醫學正式的用語）\nhead（頭部，最日常通俗的詞彙）\nbone（骨頭，泛稱）",
  "sky": "諧音聯想：\n諧音：「死開」烏雲散開後，蔚藍的天空立刻露出來。\n\n聯想畫面 1：晴朗無雲的藍天白雲，讓人看了心情非常放鬆。\n\n聯想畫面 2：傍晚夕陽把整片天際染成了漂亮的橘紅色。\n\n高效擴充：常搭配介系詞 in the sky 或代換成 high in the sky。\nKK 音標：[skaɪ] -> sk 結合雙母音 ai，嘴型由寬變扁。\n\n常見同義字：\nheaven（天堂、天空，帶有宗教意味）\natmosphere（大氣層、氣氛）\nfirmament（蒼穹、穹蒼，較文學性的說法）",
  "skyscraper": "諧音聯想：\n拆解 / 諧音：\n拆解：sky（天空）加上 scraper（刮鬍刀、刮除者）\n\n聯想畫面 1：這棟摩天大樓太高了，彷彿能把天空都刮破一塊。\n\n聯想畫面 2：站在台北 101 頂樓俯瞰，四周都是高聳入雲的摩天大樓。\n\n高效擴充：由動詞 scrape（刮）衍生而來的合成字，意指「刮天者」。\nKK 音標：[ˋskaɪ͵skrepɚ] -> 主重音在第一個音節 sky，次重音在 scrape。\n\n常見同義字：\n\nhigh-rise（高樓大廈，通常指十幾層以上的建築）\n\ntower（塔樓、高樓）\n\nbuilding（建築物，最廣泛的通稱）",
  "slack": "諧音聯想：\n諧音：死，累。\n\n聯想畫面 1：工作太久，大家都覺得死累，開始 slack 偷懶。\n\n聯想畫面 2：繩子太 slack，沒綁緊，導致貨物掉落。\n\n高效擴充：slack 既是形容詞也是動詞，形容鬆弛或懶散。\nKK 音標：[slæk] -> 單音節，發音時嘴型要扁平，注意 a 的短音。\n\n常見同義字：\n\nloose（鬆的，指物理狀態）\n\nlazy（懶惰的，指人）\n\nslow（慢的，指速度）。",
  "slacken": "諧音聯想：\n諧音：死，拉肯。\n\n聯想畫面 1：繩子被死命拉著，後來因為力氣不足而 slacken，變得鬆弛了。\n\n聯想畫面 2：工作進度在週末時明顯 slacken，大家都開始懈怠，動作變慢。\n\n高效擴充：slack 是鬆的，加上 en 變成動詞，意指使變鬆或變慢。\nKK 音標：[ˋslækən] -> 重音在第一音節 sla，發音時嘴型要扁平。\n\n常見同義字：\n\nloosen（鬆開，最常用）\n\nslow down（減速，指動作）\n\nrelax（放鬆，指心態）。",
  "slam": "諧音聯想：\n諧音：「死爛」的脾氣，氣得把門砰地一聲大力關上。\n\n聯想畫面 1：生氣的青少年甩門而去，發出巨大的撞擊聲。\n\n聯想畫面 2：網球選手把球用力一扣，使勁打向對手場地。\n\n高效擴充：語音帶有強烈的動作感與撞擊聲響。\nKK 音標：[slæm] -> 扁唇的æ音，發音短促有力。\n\n常見同義字：\nbang（猛擊、發出砰的一聲）\nslam dunk（籃球中的大力灌籃）\nshut（關閉，但 slam 強調粗暴或大聲）",
  "slang": "諧音聯想：\n諧音：死狼。聯想畫麵 1：年輕人在街頭講著各種流行 slang 俚語，聽起來像死狼的低吼。聯想畫麵 2：跟長輩說話時要避免使用過多網路 slang。\n\n高效擴充：非正式用語，年輕人極愛使用。\nKK 音標：[slæŋ] -> 嘴巴張大發 æ 音，結尾鼻音 ŋ。\n\n常見同義字：\n\nidiom（慣用語）\n\ncolloquialism（口語）\n\njargon（行話）。",
  "slap": "諧音聯想：\n諧音：「死拍」一巴掌打在臉上，發出清脆聲響。\n\n聯想畫面 1：八點檔劇情中，生氣的主角狠狠甩了對方一巴掌。\n\n聯想畫面 2：蚊子叮在手臂上，趕緊用手掌用力拍打下去。\n\n高效擴充：與 slam 類似，slap 強調用平坦的手面拍擊。\nKK 音標：[slæp] -> 輕快短促的 a 音，結尾 p 閉唇。\n\n常見同義字：\nhit（打、擊打，最普遍的動作詞）\nspank（打屁股，通常指懲罰小孩）\npat（輕拍、撫拍，語氣溫和友善）",
  "slash": "諧音聯想：\n諧音：死勒許。聯想畫麵 1：拿著武士刀猛力 slash 砍劈，把敵人死勒許切開。聯想畫麵 2：公司為了節省成本，決定 slash 預算大幅削減。\n\n高效擴充：斜線符號 / 也叫做 slash。\nKK 音標：[slæʃ] -> æ 音短促，結尾 ʃ 氣音要長。\n\n常見同義字：\n\ncut（切割）\n\nreduce（減少）\n\ngash（深傷口）。",
  "slaughter": "諧音聯想：\n諧音：「死老頭」拿著刀子進行殘忍的屠宰與大屠殺。\n\n聯想畫面 1：歷史課本上記載古代戰爭中殘酷的屠殺慘劇。\n\n聯想畫面 2：體育競賽中實力懸殊，被對手徹底慘敗擊潰。\n\n高效擴充：字尾 augh 發 /ɔ/ 的音，拼寫較為特殊需特別留意。\nKK 音標：[ˋslɔtɚ] -> 重音在第一音節 slau，注意 au 的長音。\n\n常見同義字：\nmassacre（大屠殺，尤指大規模殺害無辜平民）\nbutcher（屠宰、肉販，也指殘酷殺害）\nslay（殺害、宰殺，文學或流行語常用）",
  "slave": "諧音聯想：\n諧音：「死累伏」\n\n聯想畫面 1：古代的奴隸每天過著死累還要伏地工作的悲慘生活。\n\n聯想畫面 2：現代人常常自嘲是公司的社畜，像個受控制的奴隸一樣苦幹。\n\n高效擴充：歷史上歷史名詞 slave 的字源與斯拉夫民族有關。\nKK 音標：[slev] -> 單音節，a 加上 e 發長音 [e]，v 輕咬下唇。\n\n常見同義字：\n\nservant（僕人，傭工）\n\ncaptive（俘虜，失去自由的人）\n\ndrudge（苦工，做苦力的人）",
  "slavery": "諧音聯想：\n諧音：死累微。聯想畫麵 1：古代奴隸制度 slavery 讓人每天死累微，毫無人權。聯想畫麵 2：歷史課本詳細記載了廢除蓄奴的過程。\n\n高效擴充：由 slave 奴隸加上 -ery 形成名詞。\nKK 音標：[ˋslevɚi] -> 重音在 slé，r 捲舌流暢。\n\n常見同義字：\n\nbondage（束縛）\n\nservitude（奴役）\n\nsubjugation（征服）。",
  "slay": "諧音聯想：\n諧音：「誰累」，到底是誰累得像條狗，被這項殺手級任務給震撼了。\n\n聯想畫面 1：英雄拔出寶劍英勇地把惡龍殺死。\n\n聯想畫面 2：歌后今天在演唱會上的完美造型驚豔全場，給全體歌迷留下極深的印象。\n\n高效擴充：古英文遺留下來的高頻動詞，現代口語也常引申為表現極佳或電暈眾人。\nKK 音標：[sle] -> 單音節字，發長音的 ey 音，唸起來乾脆響亮。\n\n常見同義字：\n\nkill（殺死、謀殺，最通俗的用字）\n\nmurder（謀殺、兇殺，指蓄意奪人性命）\n\nimpress（給予深刻印象、使銘記）",
  "sled": "諧音聯想：\n諧音：「死雷得」\n\n聯想畫面 1：如果在雪地裡開車死雷得（速度太快），不如改乘雪橇比較安全。\n\n聯想畫面 2：農夫用雪橇在結冰的湖面上運送砍好的木柴。\n\n高效擴充：與 sleigh 音近，sled 通常指構造較簡單、平底的雪橇。\nKK 音標：[slɛd] -> 短母音 ɛ，結尾的 d 要輕念帶過。\n\n常見同義字：\nsledge（大錘或大型雪橇，詞義較多重）\nsleigh（雪橇，多指大型馬拉雪橇）\ntoboggan（長形雪橇，常作休閒滑雪用）",
  "sledge": "諧音聯想：\n諧音：「死勒吉」\n\n聯想畫面 1：大力士用大鐵錘死勒吉（用力敲擊）牆壁，準備打通房間。\n\n聯想畫面 2：聖誕老人今年改用大型雪橇來搬運龐大的禮物山。\n\n高效擴充：當名詞時可指 sledgehammer（大鎚）。\nKK 音標：[slɛdʒ] -> 結尾為濁子音 ʒ，發音時聲帶要震動。\n\n常見同義字：\nsled（雪橇，指較小型的雪橇）\nhammer（錘子，一般日常敲打工具）\nsleigh（雪橇，專指雪地交通工具）",
  "sleep": "諧音聯想：\n諧音：「死力普」用盡全力撲到大床上準備好好睡覺。\n\n聯想畫面 1：貓咪捲在沙發上進入香甜的睡眠狀態。\n\n聯想畫面 2：熬夜加班後終於躺回床上，享受一夜好眠。\n\n高效擴充：過去式與過去分詞皆為 slept，形容詞 sleepy（想睡的）。\nKK 音標：[slip] -> 長音 ee 嘴型拉扁，發音飽滿。\n\n常見同義字：\nslumber（安眠、睡眠，較文藝的詞）\nnap（打盹、小睡片刻）\nrepose（歇息、長眠）",
  "sleeping": "拆解：sleep（睡眠）+ ing（正在...）\n\n諧音：斯力品。\n\n聯想畫面 1：貓咪趴在沙發上進入沉沉的睡眠狀態，模樣看起來非常安詳可愛。\n\n聯想畫面 2：深夜時分大家都已經睡著了，只剩路燈還靜靜亮著。\n\n高效擴充：源自動詞 sleep，加上 ing 變成現在分詞或形容詞。\nKK 音標：[ˋslipɪŋ] -> 主重音在第一個音節 [slip]，鼻音 [ŋ] 氣流要從鼻腔出來。\n\n常見同義字：\n\nasleep（睡著的，通常作表語）\n\nslumber（睡眠，較文言的說法）\n\nresting（休息的，狀態較淺）",
  "sleepless": "諧音聯想：\n拆解：sleep（睡覺）+ less（沒有）\n\n聯想畫面 1：整晚失眠，腦袋裡沒有一點睡意，只能盯著天花板數羊。\n\n聯想畫面 2：這座城市是個不夜城，燈火通明，彷彿永遠不需要休息。\n\n高效擴充：less 字尾代表「沒有」，如 homeless（無家可歸）。\nKK 音標：[ˋslipləs] -> 重音在第一個音節，後面的 less 要輕讀。",
  "sleepwalking": "拆解：sleep（睡覺）+ walking（走路）。\n\n聯想畫面 1：他半夜夢遊，像個殭屍一樣在客廳走來走去，家人都嚇壞了。\n\n聯想畫面 2：這家公司在市場競爭中毫無警覺，簡直是在夢遊般地走向倒閉。\n\n高效擴充：常與 into 連用，形容不知不覺陷入某種困境。\nKK 音標：[ˋslipwɔkɪŋ] -> 重音在第一個音節，sleep 的長母音要拉長。\n\n常見同義字：\n\nsomnambulism（醫學名詞夢遊症）\n\nsleepwalk（動詞原型）。",
  "sleepy": "諧音聯想：\n諧音：「死力皮」眼皮重得拉不開，睏得要死。\n\n聯想畫面 1：加班到半夜，眼皮重得像鉛塊，整個人超級 sleepy。\n\n聯想畫面 2：午後的小鎮街道空無一人，安靜得讓人感到 sleepy。\n\n高效擴充：由 sleep（睡覺）加上 y 形成形容詞，表示想睡的。\nKK 音標：[ˋslipi] -> 重音在第一音節 slee，ee 發長音長長的伊。\n\n常見同義字：\ndrowsy（昏昏欲睡的、打瞌睡的）\ntired（疲倦的、累的）\nasleep（睡著了的，通常作表語）",
  "sleeve": "諧音聯想：\n諧音：「死立福」\n\n聯想畫面 1：穿上長袖襯衫把手臂死立福（包覆）在袖子裡。\n\n聯想畫面 2：魔術師把撲克牌藏在衣服袖子裡準備變魔術。\n\n高效擴充：雙 e 發長音 [i]，常見片語有 up one's sleeve（別有居心／藏有一手）。\nKK 音標：[sliv] -> 單音節，ee 發長音「伊」，v 聲帶震動。\n\n常見同義字：\n\narm（手臂，廣義包含袖子覆蓋的部位）\n\ncuff（袖口，專指手腕處的收邊）\n\ngarment part（服裝配件，非正式單字）",
  "sleigh": "諧音聯想：\n諧音：「斯雷」\n\n聯想畫面 1：聖誕老公公駕著斯雷（雪橇）在夜空中發送禮物。\n\n聯想畫面 2：小朋友興奮地坐在木造雪橇上，在雪地坡道上滑行。\n\n高效擴充：字尾 -eigh 發長音 /e/，拼法特殊需特別注意。\nKK 音標：[sle] -> 長母音 e，嘴型由小微張拉大成微笑狀。\n\n常見同義字：\nsled（雪橇，較普遍的小型雪橇）\nsledge（雪橇或大錘，多功能用字）\ntoboggan（長雪橇，適合休閒娛樂）",
  "slender": "諧音聯想：\n拆解 / 諧音：死蘭燈的\n\n諧音：「死，蘭燈的」支架太細，隨時會斷。\n\n聯想畫面 1：模特兒擁有 slender 的腰身與修長的雙腿，穿禮服非常好看。\n\n聯想畫面 2：老舊的路燈桿非常 slender，在颱風天中看起來搖搖欲墜。\n\n高效擴充：字根源自古日耳曼語，專門形容人或物細長、纖細。\nKK 音標：[ˋslɛndɚ] -> 重音在第一音節 slen，ɛ 念短音短的愛。\n\n常見同義字：\nslim（苗條的、纖細的）\nthin（細的、瘦的）\nnarrow（狹窄的，多用於物體寬度）",
  "slice": "諧音聯想：\n諧音：「死賴死」\n\n聯想畫面 1：切披薩時不小心刀子太利，把一整塊薄片切得死賴死的好吃。\n\n聯想畫面 2：媽媽在廚房把吐司切成一片片薄片準備做早餐。\n\n高效擴充：字尾 ce 的 c 發軟音 [s]，因前面有長母音 i。\nKK 音標：[slaɪs] -> 單音節，i 發雙母音「愛」，c 發 s 的音。\n\n常見同義字：\n\npiece（塊、件，最普通的碎片或部分）\n\ncut（切口、切下的部分）\n\nportion（部分、一份，餐飲常用詞）",
  "slide": "諧音聯想：\n諧音：「司萊得」\n\n聯想畫面 1：遊樂場的溜滑梯太滑了，司機老李一坐上去就直接快速滑下來。\n\n聯想畫面 2：開會時切換投影片幻燈片，畫面非常流暢地滑動過去。\n\n高效擴充：結尾 -ide 通常發長 i 的音，與 slide 相關的有 glide（滑翔）、ride（騎乘）。\nKK 音標：[slaɪd] -> 雙母音 ai 要滑順飽滿，d 輕輕帶過不發出過強的子音。\n\n常見同義字：\n\nslip（滑倒、滑落，通常帶有意外意味）\n\nglide（滑翔、平穩地滑行，多用於空中或冰上）\n\nskid（打滑，通常指車輛失控）",
  "slight": "諧音聯想：\n諧音：「死賴著」\n\n聯想畫面 1：他瘦小的身軀死賴著不走，只為了表達對主管冷落他的不滿。\n\n聯想畫面 2：這場感冒症狀非常輕微，吃個藥休息一下就好了。\n\n高效擴充：可作動詞表示冷落或怠慢，常見於 feel slighted（覺得被冷落）。\nKK 音標：[slaɪt] -> 長母音 aɪ，t 音輕輕頂住上顎即可。\n\n常見同義字：\nminor（輕微的，強調不重要）\nslim（苗條的、微小的）\nslender（纖細的，多形容人體態）",
  "slightly": "諧音聯想：\n諧音：死，賴特。\n\n聯想畫面 1：他臉色死白，看起來 slightly 有點生病，但還好不嚴重。\n\n聯想畫面 2：這件衣服 slightly 有點大，但穿起來還算合身。\n\n高效擴充：slight 是輕微的，加上 ly 變成副詞。\nKK 音標：[ˋslaɪtli] -> 重音在第一音節 sli，發音時注意 i 的長音。\n\n常見同義字：\n\na little（一點點，口語常用）\n\nsomewhat（稍微，較正式）\n\nmildly（溫和地，指程度）。",
  "slim": "諧音聯想：\n諧音：「思林」\n\n聯想畫面 1：帥哥思林每天努力運動，終於變得非常苗條好看。\n\n聯想畫面 2：這件洋裝只有身材纖細的女生才穿得下。\n\n高效擴充：字尾 im 音，聯想到 image 或 limit，記住簡短有力的身形。\nKK 音標：[slɪm] -> 短音 i，嘴型扁平短促，鼻音 m 收尾。\n\n常見同義字：\nslender（優美纖細的，通常形容身材修長）\nlean（精瘦結實的，無過多脂肪）\nthin（一般的瘦或薄）",
  "slip": "諧音聯想：\n諧音：「死力怕」\n\n聯想畫面 1：地板太濕讓人死力怕會滑倒，結果一不小心真的滑倒了。\n\n聯想畫面 2：手上拿著一張小紙條備忘錄，一鬆手就從小縫隙滑落了。\n\n高效擴充：短母音 i 發音短促，加上 p 形成輕脆的爆破音。\nKK 音標：[slɪp] -> 輕快短促的 i 音，結尾的 p 閉唇發氣音。\n\n常見同義字：\n\nslide（滑動、溜滑梯，通常有接觸面持續滑行感）\n\nerror（錯誤、疏漏，對應 slip 當作小差錯時）\n\nfall（跌倒、落下，範圍較廣的動作）",
  "slipper": "諧音聯想：\n諧音：「死力怕發」\n\n聯想畫面 1：在家裡穿著舒適的拖鞋走路，死力怕發出啪嗒啪嗒的聲音。\n\n聯想畫面 2：小時候調皮被媽媽用拖鞋打屁股，嚇得死力怕發抖。\n\n高效擴充：由 slip（滑）加上字尾 -per 變成名詞，指容易套入的室內鞋。\nKK 音標：[ˋslɪpɚ] -> 主重音在第一個音節 sli，後面ɚ發輕柔的弱母音。\n\n常見同義字：\n\nsandal（涼鞋，通常指外出穿的露趾鞋）\n\nhouse-shoe（室內鞋，口語常用）\n\nflip-flops（夾腳拖鞋）",
  "slippers": "諧音聯想：\n諧音：濕（slip）＋跑（pers）。\n\n聯想畫面 1：穿著拖鞋在浴室跑，很容易滑倒，所以要小心。\n\n聯想畫面 2：回到家脫掉皮鞋，換上舒適的室內拖鞋，整個人都放鬆了。\n\n高效擴充：slip 有滑動的意思，穿著拖鞋容易滑，所以叫 slippers。\nKK 音標：[ˋslɪpɚz] -> 重音在第一個音節，注意 s 的發音要輕。\n\n常見同義字：\n\nflip-flops（夾腳拖）\n\nhouse shoes（室內鞋）\n\nslides（運動拖鞋）。",
  "slippery": "諧音聯想：\n諧音：「死力擺理」\n\n聯想畫面 1：地板太滑了，跌倒的人死命想擺出手勢維持平衡。\n\n聯想畫面 2：這家夥講話很狡猾、立場不明確，像條抓不住的泥鰍。\n\n高效擴充：由 slip（滑倒）加上 pery 形成形容詞。\nKK 音標：[ˋslɪpɚi] -> 重音在第一音節的 ˋslɪ。\n\n常見同義字：\nslick（光滑的、圓滑的）\nicy（結冰的、極滑的）\nelusive（難捉摸的、狡猾的）",
  "slipstream": "諧音聯想：\n諧音：死力跑、氣流\n\n聯想畫面 1：賽車手緊緊貼在前車的 slipstream 裡，藉此減少風阻準備超車。\n\n聯想畫面 2：這家新創公司趁著巨頭企業的 slipstream 迅速拓展市場。\n\n高效擴充：slip（滑動）加上 stream（流動），指流體滑過物體後形成的尾流。\nKK 音標：[ˋslɪpstrim] -> 重音在首音節 ˋslɪp，stream 的 ea 發長 i 音。\n\n常見同義字：\ntrail（尾隨的軌跡）\n wake（船隻或飛機過後的水或氣流尾跡）\n draft（賽車中利用前車氣流的行駛法）",
  "slit": "諧音聯想：\n諧音：撕裂（slit）\n\n聯想畫面 1：把信封撕開一個狹長的切口（slit），方便抽出裡面的信件。\n\n聯想畫面 2：因為陽光太刺眼，他把眼睛眯成一條細縫（slit）。\n\n高效擴充：slit 專指狹長的開口，比 gash 更細長。\nKK 音標：[slɪt] -> 短母音 i，發音短促有力，舌尖抵住上齒齦。",
  "slogan": "諧音聯想：\n諧音：「死漏乾」\n\n聯想畫面 1：候選人喊著競選口號，直到把喉嚨喊到死漏乾（聲音沙啞）。\n\n聯想畫面 2：廣告公司想出一個洗腦的廣告標語，讓產品大賣。\n\n高效擴充：源自蓋爾語，原意是高地人的戰鬥吶喊。\nKK 音標：[ˋsloɡən] -> 主重音在第一個音節 slo，o 發長音。\n\n常見同義字：\nmotto（座右銘、格言）\ncatchphrase（流行語、標語）\ntagline（廣告標語、宣傳口號）",
  "slope": "諧音聯想：\n諧音：「死落鋪」\n\n聯想畫面 1：滑雪場的斜坡太陡，一不小心就會死落鋪在雪地上。\n\n聯想畫面 2：山區道路有明顯的傾斜坡度，開車經過要小心減速。\n\n高效擴充：字尾的 pe 組合讓 o 發長音的 o 聲。\nKK 音標：[slop] -> 單音節，o 發長音的 [o]，p 閉口。\n\n常見同義字：\n\nincline（斜坡、傾斜，較正式）\n\nhill（小山、山丘，自然地形）\n\nramp（斜坡道、匝道，人工建造的斜面）",
  "sloppy": "諧音聯想：\n諧音：死老皮 -> 諧音聯想：死老皮做事總是懶散馬虎。\n\n聯想畫面 1：員工交出一份字跡潦草且錯誤百出的草率報告。\n\n聯想畫面 2：他穿著一件寬鬆垮大、沒精神的睡衣出門。\n\n高效擴充：字尾 py 常帶有負面、隨便的意涵。\nKK 音標：[ˋslɑpi] -> 重音在第一音節，sl 結合短 o 的 ɑ 聲。\n\n常見同義字：\n\ncareless（粗心的）\n\nmessy（凌亂的）\n\nslipshod（草率的、馬虎的）",
  "sloshed": "諧音聯想：\n諧音：死囉噓得。\n\n聯想畫面 1：他喝得醉醺醺的，走路搖搖晃晃，嘴裡還發出死囉噓得的聲音。\n\n聯想畫面 2：水桶裡的水因為晃動而濺出來，發出嘩啦的聲音。\n\n高效擴充：slosh 常用來形容液體晃動，引申為喝太多酒導致走路搖晃。\nKK 音標：[slɑʃt] -> 注意結尾的 t 輕音，發音要短促。\n\n常見同義字：\n\ndrunk（喝醉的）\n\ntipsy（微醺的）\n\nintoxicated（正式的醉酒）。",
  "slot": "諧音聯想：\n諧音：死落特。聯想畫麵 1：把投幣口 slot 視為死落特，零錢順利投進狹槽。聯想畫麵 2：經理幫我預約了一個下午的會議 slot 空檔。\n\n高效擴充：指狹長孔或是預約的時間檔期。\nKK 音標：[slɑt] -> 嘴型張大發短 o 音 ɑ。\n\n常見同義字：\n\nopening（空缺）\n\nvacancy（職缺/空房）\n\ntime slot（時間段）。",
  "slow": "諧音聯想：\n諧音：「死漏」水管破洞了，水滴出來的速度很慢。\n\n聯想畫面 1：一隻樹懶爬樹動作非常 slow（慢），半天才移動一公分。\n\n聯想畫面 2：開車行經學校門口時，告示牌提醒駕駛要 slow down（減速）。\n\n高效擴充：字尾 ow 常出現在形容速度或方向的詞彙中，如 blow、flow。\nKK 音標：[slo] -> 雙母音滑音，嘴型從圓唇 o 逐漸收小滑向尾音。\n\n常見同義字：\ngradual（漸進的，通常指過程緩慢發生）\nleisurely（悠閒的，通常指步調輕鬆）\ndelayed（延誤的，通常指航班或進度）",
  "slum": "諧音聯想：\n諧音：死狼。聯想畫麵 1：城市角落的 slum 貧民窟裡，環境髒亂得像死狼棲息地。聯想畫麵 2：政府積極推動更新計畫以改善 slum 的居住條件。\n\n高效擴充：通常用複數 slums 指大片貧民區。\nKK 音標：[slʌm] -> 短 u 音 ʌ，發短促的「阿」聲。\n\n常見同義字：\n\nshantytown（棚戶區）\n\nghetto（貧民區）\n\npoor neighborhood（貧窮社區）。",
  "slump": "諧音聯想：\n諧音：像一塊爛泥「死」攤在地上，業績「驟降」不景氣。\n\n聯想畫面 1：經濟大蕭條導致股市突然大幅下跌，投資人慘賠。\n\n聯想畫面 2：加班一整天累壞了，癱軟無力地坐倒在沙發上。\n\n高效擴充：常結合經濟市場與身體癱軟無力的情境使用。\nKK 音標：[slʌmp] -> 單音節字，母音 u 發短促的「啊」聲。\n\n常見同義字：\nplummet（暴跌、直線下降）\ndecline（下降、衰退，較正式客觀）\nsag（下垂、下陷，指結構或數值下滑）",
  "slushy": "諧音聯想：\n諧音：「死拉吸」聯想：路面積雪融化變成「死拉」著鞋子的「溼軟泥濘」路，讓人邊走邊「吸」氣。\n\n聯想畫面 1：夏天走到便利商店買一杯冰涼的草莓 slushy，暑氣全消。\n\n聯想畫面 2：冬天的街道滿是 slushy 的髒雪，走起路來非常狼狽。\n\n高效擴充：由 slush（融雪、爛泥）加上 -y 形成，亦可拼作 slushie 指冰沙飲料。\nKK 音標：[ˋslʌʃi] -> 主重音在 slʌ 音節，sl 組合音要連貫，尾音 i 輕短。\n\n常見同義字：\n slush（融雪，名詞）\nmuddy（泥濘的）\nsoggy（溼軟的）",
  "sly": "諧音聯想：\n諧音：賴 -> 諧音聯想：死賴著不走的狡猾狐狸。\n\n聯想畫面 1：奸商露出狡詐的微笑，心知肚明地看著上當的顧客。\n\n聯想畫面 2：小貓咪用詭秘的眼神盯著桌上的魚乾。\n\n高效擴充：單音節短字，常與 cunning 聯想。\nKK 音標：[slaɪ] -> 單音節，sl 開頭搭配雙母音 aɪ。\n\n常見同義字：\n\ncunning（狡猾的）\n\ncrafty（奸詐的）\n\ntricky（詭計多端的）",
  "smack": "諧音聯想：\n諧音：「死麥克」\n\n聯想畫面 1：調皮的麥克風被老師用巴掌打了一下，發出響亮的 smack 聲響。\n\n聯想畫面 2：球員在球場上不小心犯規，猛地被教練大力拍擊背部警告。\n\n高效擴充：結合 s 加上 mack 快速聯想，與 slap 都是表示打擊的手勢動作。\nKK 音標：[smæk] -> 嘴型張大唸扁扁的短音，雙唇緊閉後瞬間爆破發聲。\n\n常見同義字：\n\nslap（用巴掌打，較日常直接的動作）\n\nhit（打擊，泛指各種形式的擊打）\n\nbang（猛擊或發出砰的巨大聲響）",
  "small": "諧音聯想：\n諧音：「死摸歐」貓咪體型好小，讓人忍不住想一直摸牠。\n\n聯想畫面 1：這件衣服尺寸太小，穿起來肚子好緊。\n\n聯想畫面 2：巷子口開了一間溫馨的小咖啡館。\n\n高效擴充：相反詞為 big 或 large，常用於比較級 smaller。\nKK 音標：[smɔl] -> sm 開頭，ɔl 帶有捲舌與圓唇的厚重感。\n\n常見同義字：\nlittle（小的，常帶有情感色彩如可愛）\ntiny（極小的、微小的）\nminiature（微型的、縮小版的）",
  "smallish": "諧音聯想：\n拆解：small（小）+ ish（有點...）。\n\n聯想畫面 1：這件衣服對我來說有點 smallish，穿起來稍微緊了一點。\n\n聯想畫面 2：這間房間看起來 smallish，放一張床就滿了。\n\n高效擴充：字尾 -ish 加在形容詞後，表示程度稍微。\nKK 音標：[ˋsmɔlɪʃ] -> 重音在第一個音節，發音時嘴型由圓變扁。\n\n常見同義字：\n\ntiny（極小的）\n\nlittle（小的，基礎詞）\n\nundersized（尺寸過小的）。",
  "smallness": "諧音聯想：\n拆解：small（小的）+ ness（名詞字尾）。\n\n聯想畫面 1：站在廣闊的宇宙中，人類深刻感受到自己的 smallness。\n\n聯想畫面 2：他因為心胸的 smallness，總是為了小事跟別人斤斤計較。\n\n高效擴充：smallness 常用來形容體積小或氣度小。\nKK 音標：[ˋsmɔlnəs] -> 第一音節重音，注意 s 的發音要連貫。\n\n常見同義字：\ntininess（微小，指體積非常小）\nnarrow-mindedness（小氣，指心胸狹窄）\ninsignificance（無足輕重，指不重要）",
  "smallpox": "諧音聯想：\n諧音：「死冒、撲客死」\n\n聯想畫面 1：古代桌上遊戲撲克牌玩家臉上冒出可怕的天花水泡，不幸染病死掉。\n\n聯想畫面 2：衛生所宣導小型的病毒 (small) 冒出來會造成天花大流行。\n\n高效擴充：由 small (小的) 加上 pox (痘/疹) 組合成天花這個歷史惡疾。\nKK 音標：[ˋsmɔl͵pɑks] -> 主重音落在前段的 small，後方 pox 要短促有力。\n\n常見同義字：\n\nchickenpox（水痘，症狀較輕且多發生於兒童）\n\npox（痘疫，泛指長痘痘的傳染病）\n\nplague（瘟疫，泛指大規模致命傳染病）",
  "smart": "諧音聯想：\n諧音：「死賣特」，聰明的業務死命推銷獨特商品。\n\n聯想畫面 1：一個反應靈敏又穿著得體的業務，正死命推銷獨特的手機。\n\n聯想畫面 2：不小心被辣椒醬刺痛手指時，心裡感到一陣陣的難過。\n\n高效擴充：字尾 rt 結尾，常聯想到 art 藝術，有品味也是一種聰明。\nKK 音標：[smɑrt] -> 發音時注意嘴巴張大發 [ɑ] 音，結尾捲舌音要輕快有力。\n\n常見同義字：\n\nwell dressed（衣著得體的，強調穿搭有型）\n\nfashionably dressed（時髦打扮的，指跟上流行趨勢）\n\nstylish（時尚的，通常指非常有個人品味）",
  "smartphone": "拆解：smart（聰明的）+ phone（電話）。\n\n聯想畫面 1：現在每個人手上一台智慧型手機，隨時隨地都能上網。\n\n聯想畫面 2：這手機太聰明了，連我沒說出口的需求它都能預測。\n\n高效擴充：smart 在此指具備運算能力，非單純通訊。\nKK 音標：[ˋsmɑrtfoʊn] -> 重音在第一個音節，注意 smart 的捲舌音。\n\n常見同義字：\n\nmobile phone（手機，英式常用）\n\ncell phone（手機，美式常用）。",
  "smash": "諧音聯想：\n諧音：「死妹喜」歡這場轟動全場的演唱會，把螢光棒都打碎了。\n\n聯想畫面 1：車禍時兩車相撞，玻璃全部碎裂的嚴重慘況。\n\n聯想畫面 2：羽球高手在網前使出強力扣殺，一舉得分。\n\n高效擴充：常用於形容徹底粉碎或極度轟動的流行事物（smash hit）。\nKK 音標：[smæʃ] -> 結尾的 sh 發噓聲，母音æ要張大嘴。\n\n常見同義字：\nsmash hit（轟動一時的暢銷電影或歌曲）\nshatter（粉碎、使碎裂成細片）\ncrush（壓碎、擠壓）",
  "smell": "諧音聯想：\n諧音：「死貓餓」死掉的貓咪散發出很臭的氣味讓大家都餓不下去。\n\n聯想畫面 1：廚房飄出剛烤好的蛋糕香味，讓人忍不住流口水。\n\n聯想畫面 2：狗狗在草地上用鼻子用力聞出食物的氣味。\n\n高效擴充：過去式可拼為 smelled 或 smelt。\nKK 音標：[smɛl] -> sm 結合短音 ɛ，結尾 l 舌尖頂住上齒齦。\n\n常見同義字：\nscent（香味、氣味，通常指好聞的香氣）\nodor（氣味，中性或常指難聞的異味）\nstink（發臭、惡臭，口語常用）",
  "smile": "諧音聯想：\n諧音：「死麥」\n\n聯想畫面 1：拍照時對著死麥克風大喊起司，每個人臉上都掛滿燦爛的微笑。\n\n聯想畫面 2：服務生面對奧客無理要求時，依然保持專業的微笑點頭。\n\n高效擴充：字首 sm 常與嘴部表情有關，如 smell。\nKK 音標：[smaɪl] -> 主重音在長母音 ɑɪ，嘴角要向兩側咧開像微笑。\n\n常見同義字：\n\ngrin（露齒笑，通常指因為高興或得意而笑）\n\nbeam（眉開眼笑，形容笑容滿面且光彩）\n\nlaugh（大笑，出聲的笑）",
  "smog": "諧音聯想：\n諧音：「死馬擱」\n\n聯想畫面 1：外面的霧霾太嚴重，能見度極低，害馬車死馬擱（卡在半路）動彈不得。\n\n聯想畫面 2：工業城市上空籠罩著一層黃褐色的煙霧，讓人呼吸困難。\n\n高效擴充：由 smoke（煙）加 fog（霧）組合而成的混成詞。\nKK 音標：[smɑɡ] -> 短母音 ɑ，嘴巴張大發短促的「ㄚ」音。\n\n常見同義字：\nfog（霧，純水氣形成的自然霧）\nsmoke（煙，燃燒產生的氣體）\nhaze（霾、薄霧，多因灰塵或乾旱引起）",
  "smoke": "諧音聯想：\n諧音：「死摸客」\n\n聯想畫面 1：老菸槍在吸菸區狂抽猛送，把空氣弄得都是煙霧。\n\n聯想畫面 2：廚房燒焦冒煙時，媽媽急忙揮手把煙趕走。\n\n高效擴充：字尾 oke 家族發音相近，如 choke。\nKK 音標：[smok] -> o 是雙母音，發音時嘴型要由圓變扁。\n\n常見同義字：\n\ncigarette（香菸，指實體物品）\n\nfume（濃煙、廢氣，通常指刺鼻的煙霧）\n\nvape（吸電子菸，現代常見動詞）",
  "smooth": "諧音聯想：\n諧音：「斯慕斯的冰沙」\n\n聯想畫面 1：剛攪打好的芒果斯慕斯冰沙口感非常滑順。\n\n聯想畫面 2：用熨斗把皺巴巴的襯衫燙得平平整整、光滑平坦。\n\n高效擴充：字尾 th 發有聲的 [ð]，別忘了咬舌頭。\nKK 音標：[smuð] -> 結合長 u 音與尾音 th，發音要連貫流暢。\n\n常見同義字：\n\nflat（平坦的，沒有高低起伏）\n\neven（平穩的、均勻的）\n\nsleek（滑順發亮的，常形容毛髮或外觀）",
  "smoothly": "諧音聯想：\n諧音：「死（Smo）+ 無（oth）+ 離（ly）」\n\n聯想畫面 1：計畫執行得非常順利，就像在冰面上滑行一樣，沒有任何阻礙。\n\n聯想畫面 2：演講過程流暢自然，完全沒有卡頓，聽眾聽得非常舒服。\n\n高效擴充：源自 smooth 平滑的，加上 ly 變成副詞。\nKK 音標：[ˋsmuðli] -> 重音在第一音節，th 發音時舌尖輕觸上齒背。",
  "smother": "諧音聯想：\n諧音：「死媽折」\n\n聯想畫面 1：厚重的棉被把媽媽折起來蓋住，導致她差點窒息悶死。\n\n聯想畫面 2：廚房油鍋起火，主廚趕快拿濕毛巾把火苗悶熄撲滅。\n\n高效擴充：字首 sm 開頭常與煙霧、窒息或狹窄有關，與 suffocate 同義。\nKK 音標：[ˋsmʌðɚ] -> 主重音在第一音節 sma，th 發輕咬舌尖的濁音。\n\n常見同義字：\n\nsuffocate（窒息、悶死，較正式醫學與日常並用）\n\nstifle（抑制、喘不過氣，常用於情緒或呼吸受阻）\n\nchoke（掐住、噎住，強調喉嚨被卡住或呼吸困難）",
  "smuggle": "諧音聯想：\n諧音：「死罵狗」\n\n聯想畫面 1：走私客把違禁品藏在狗身上，被海關抓到後氣得死罵狗。\n\n聯想畫面 2：偷偷攜帶金飾通關，夾帶在行李底層。\n\n高效擴充：字根 smug (自滿的) 衍生出的偷運行為。\nKK 音標：[ˋsmʌɡəl] -> 第一音節重音，smug 發短音 u，gle 為輕聲。\n\n常見同義字：\n\nsmuggle out（偷偷運出，強調非法運送）\n\ntrafficking（走私販賣，常指毒品或人口）\n\nsmuggle in（非法偷運進口）",
  "smut": "諧音聯想：\n諧音：死罵特（用髒話罵人很不乾淨）\n\n聯想畫面 1：農田裡的麥子感染了黑色病變，整株植物長滿了黑穗病汙跡。\n\n聯想畫面 2：調皮的小孩用沾滿碳灰的手在白牆上亂抹，弄出好幾個黑色的髒跡。\n\n高效擴充：字首 sm 常與黏稠、髒汙有關，如 smear（塗抹）、smelly（臭的）。\nKK 音標：[smʌt] -> 單音節字，u 發短音 ʌ，嘴巴張大發出短促的阿音。\n\n常見同義字：\nspot（斑點、汙點）\nsmudge（塗抹出來的髒痕）\nblight（植物枯萎病、農作物病害）",
  "snack": "諧音聯想：\n諧音：「死內客」\n\n聯想畫面 1：深夜肚子餓的死內客（死奧客），一直吵著要吃宵夜零食。\n\n聯想畫面 2：下午茶時間在辦公室偷吃一口洋芋片點心。\n\n高效擴充：字首 sn- 常與鼻子或嘴巴小動作有關，如 snout（口鼻部）。\nKK 音標：[snæk] -> 寬扁的æ口型，發音短促有力。\n\n常見同義字：\n\nsnack（點心、零食，通常指正餐之間的輕食）\n\nrefreshment（茶點、點心，較正式的用詞）\n\nlight meal（簡餐、小吃）",
  "snacks": "諧音聯想：\n諧音：死拿客。\n\n聯想畫面 1：看電影時，我最喜歡死拿客，也就是抓一把零食往嘴裡塞。\n\n聯想畫面 2：下午三點肚子餓，同事們紛紛拿出抽屜裡的零嘴分享。\n\n高效擴充：源自中古荷蘭語，意指咬一口。\nKK 音標：[snæks] -> 單音節，結尾的 ks 音要發得清脆。\n\n常見同義字：\n\nrefreshments（茶點，較正式）\n\nmunchies（口語，指想吃零食的慾望）。",
  "snagged": "諧音聯想：\n諧音：死內格（死在格柵裡，被鉤住了）。\n\n聯想畫面 1：我的毛衣被樹枝 snagged 住了，結果拉出一條長長的線，心痛不已。\n\n聯想畫面 2：計畫在最後關頭被一個小問題 snagged，導致進度嚴重延誤。\n\n高效擴充：snag 原意為樹樁，引申為障礙。\nKK 音標：[snæɡd] -> 單音節，結尾的 d 發音要輕。\n\n常見同義字：\n\ncaught（被抓住）\n\nhindered（被阻礙）。",
  "snail": "諧音聯想：\n諧音：「死內歐」\n\n聯想畫面 1：卡通裡的鼻涕蟲死內歐爬得很慢，就像一隻慢吞吞的蝸牛。\n\n聯想畫面 2：形容辦事效率很差的遲鈍的人，動作跟蝸牛一樣。\n\n高效擴充：長母音 ai 組合，字尾帶 l，類似 sail（航行）、tail（尾巴）。\nKK 音標：[snel] -> 注意這是雙母音結尾，發音時嘴型由開合到閉，聲調拉長。\n\n常見同義字：\n\nslug（蛞蝓、無殼蝸牛）\n\ntortoise（烏龜，常與 snail 一起比喻緩慢）\n\nslowpoke（動作遲緩的人、慢吞吞的人）",
  "snake": "諧音聯想：\n諧音：「死內客」\n\n聯想畫面 1：森林裡一條毒蛇在草叢中安靜地蛇行前進。\n\n聯想畫面 2：山路蜿蜒得像一條蛇盤旋在山頭上。\n\n高效擴充：字尾 ake 還有 cake、lake 等好記對應字。\nKK 音標：[snek] -> e 是長母音，發音要拉長並帶有氣音。\n\n常見同義字：\n\nserpent（大蛇、巨蛇，多用於文學或神話）\n\nviper（毒蛇，較為專業的蛇類名稱）\n\ncrawler（爬行動物，泛稱）",
  "snap": "諧音聯想：\n諧音：「死捏波」筆，結果筆桿當場斷裂，發出喀嚓一聲。\n\n聯想畫面 1：用力一捏原子筆就 snap 斷裂，發出啪嗒聲。\n\n聯想畫面 2：拿出手機幫朋友拍了一張 snap 快照，動作非常突然又倉促。\n\n高效擴充：字首 sn 常聯想到鼻子或鼻息相關動作，此處結合發音直接記憶。\nKK 音標：[snæp] -> 短促有力的 a 音，發音時嘴巴微張向下，結尾的 p 輕輕閉唇爆破。\n\n常見同義字：\nbreak（斷裂、打破，較通俗廣泛）\ncrack（破裂、爆裂聲，帶有裂紋意涵）\nphotograph（照片、攝影，為正式全稱）",
  "snappily": "諧音聯想：\n諧音：死拿皮力\n\n聯想畫面 1：他因為心情不好，厲聲地對人說話，像是要死拿皮力一樣兇。\n\n聯想畫面 2：模特兒穿著時髦俐落的衣服走秀，動作非常 snappily。\n\n高效擴充：snap 有折斷、厲聲說的意思，引申為俐落。\nKK 音標：[ˋsnæpəli] -> 重音在第一個音節，唸起來要短促有力。\n\n常見同義字：\nsharply（尖銳地）\nbriskly（俐落地）\ncurtly（簡短無禮地）",
  "snare": "諧音聯想：\n諧音：「死內兒」\n\n聯想畫面 1：獵人設下隱蔽的陷阱，把山豬的內兒（內臟與腳）牢牢網住。\n\n聯想畫面 2：詐騙集團設下圈套，誘捕那些貪心的被害人上當。\n\n高效擴充：開頭 sn 常讓人聯想到鼻子嗅聞或偷偷摸摸設陷阱的動作。\nKK 音標：[snɛr] -> 舌尖頂住上顎發出鼻音後滑向短促的 er 氣音。\n\n常見同義字：\n\ntrap（陷阱，最通用的大眾字彙）\n\nnet（網子，實體抓捕網）\n\nambush（埋伏，強調暗中突襲的軍事動作）",
  "snarl": "諧音聯想：\n諧音：「死哪兒」來的野狗對著路人齜牙狂吠。\n\n聯想畫面 1：兇惡的藏獒露出尖牙，對著陌生人低吼咆哮。\n\n聯想畫面 2：下班尖峰時刻的交通打結，車陣纏結在一起動彈不得。\n\n高效擴充：動詞可指動物露牙低吼，或指線路、交通糾結在一起。\nKK 音標：[snɑrl] -> 捲舌音 ar 的發音要扎實，重音在整個字。\n\n常見同義字：\ngrowl（動物低吼、人低聲抱怨）\ntangle（糾纏、使打結）\njam（塞車、擁擠阻塞）",
  "snatch": "諧音聯想：\n諧音：「死奈曲」聽起來就像壞人死命把流行音樂的歌本奪走。\n\n聯想畫面 1：歹徒在大街上趁路人不備，一把抓住皮包就往前狂奔。\n\n聯想畫面 2：拍賣會上大家為了最後一件珍品，出手迅速搶奪。\n\n高效擴充：字首 sn- 常與鼻子或突然的動作有關，如 sneer、sniff。\nKK 音標：[snætʃ] -> 短促有力的 [æ] 音，字尾 [tʃ] 要像打噴嚏般輕輕咬牙切齒發出氣音。\n\n常見同義字：\nseizure（扣押或查封，較正式）\ngrab（隨手抓取，較口語）\ncapture（捕捉或捕獲，強調控制）",
  "sneak": "諧音聯想：\n諧音：「死匿客」代表鬼鬼祟祟躲藏起來的客人，偷偷摸摸不讓人發現。\n\n聯想畫面 1：小偷深夜穿著黑衣，像貓一樣安靜地從後門溜進屋內。\n\n聯想畫面 2：學生趁老師不注意，偷偷把手機藏在桌底下傳訊息。\n\n高效擴充：常組合成 sneak peek（搶先看、偷偷瞄一眼）。\nKK 音標：[snik] -> 長音 [i]，發音時嘴角向兩側拉開，像在微笑著說祕密。\n\n常見同義字：\nsteal（偷竊，偏向具體拿走物品）\nslip（滑行或悄悄溜走，強調動作滑順）\nprowl（潛行巡邏，多指掠奪者）",
  "sneaker": "諧音聯想：\n諧音：死匿客。\n\n聯想畫面 1：穿著運動鞋的「死匿客」鬼鬼祟祟地在暗巷偷跑，鞋底橡膠完全沒有聲音。\n\n聯想畫面 2：年輕人去打籃球時，腳上必定會踩著一雙好穿又帥氣的運動鞋。\n\n高效擴充：源自動詞 sneak（偷偷摸摸），因為橡膠鞋底走路沒聲音而得名。\nKK 音標：[ˋsnikɚ] -> 主重音在第一個音節 [sni]，發長音的「斯尼克爾」。\n\n常見同義字：\n\ntrainers（英式用法，指運動鞋）\n\nsports shoes（美式通用運動鞋說法）\n\nkicks（美式口語，指球鞋）",
  "sneakers": "諧音聯想：\n諧音：死（sne）＋客（kers）。\n\n聯想畫面 1：穿著運動鞋去跑步，速度快到像死神一樣追趕著時間。\n\n聯想畫面 2：年輕人最愛收集限量版運動鞋，穿上它感覺走路都有風。\n\n高效擴充：sneak 有偷偷摸摸的意思，因為膠底鞋走路聲音很小。\nKK 音標：[ˋsnikɚz] -> 重音在第一個音節，ee 發長音 i。\n\n常見同義字：\n\ntrainers（運動鞋，英式）\n\nrunning shoes（慢跑鞋）\n\nathletic shoes（運動鞋，正式）。",
  "sneaky": "諧音聯想：\n諧音：「死泥坑」\n\n聯想畫面 1：他鬼鬼祟祟地把垃圾偷偷丟進別人的泥坑裡。\n\n聯想畫面 2：小偷用暗中的卑鄙手段潛入屋內。\n\n高效擴充：由 sneak（偷偷摸摸）加上形容詞字尾 -y。\nKK 音標：[ˋsniki] -> 重音在第一音節 sneak，尾音為高八度的 i。\n\n常見同義字：\nunderhanded（卑鄙的，偷偷摸摸的）\ntricky（狡猾的，機警的）\nsleek（滑順的，狡猾的）",
  "sneer": "諧音聯想：\n諧音：「死泥而」\n\n聯想畫面 1：討厭鬼踩到泥巴而沾在鞋子上，站在那裡露出鄙視的冷笑。\n\n聯想畫面 2：同事開會時提出蠢建議，主管在一旁斜眼冷笑、冷言冷語。\n\n高效擴充：和 smile 拼法相似但嘴角是往下歪的，專門形容不友善的嘲笑。\nKK 音標：[snɪr] -> 鼻音 sn 搭配微笑的 i 音再拉長 r 的尾音。\n\n常見同義字：\n\nmock（嘲弄，直接模仿對方的言行來取笑）\n\nscorn（輕蔑，打從心底看不起人）\n\njeer（嘲笑，群眾對台上發出的噓聲與起鬨）",
  "sneeze": "諧音聯想：\n諧音：「死你居」\n\n聯想畫面 1：感冒打噴嚏的飛沫到處亂噴，簡直快要把同居室友死你居（害慘了）。\n\n聯想畫面 2：對花粉過敏的他在公園連續打了好幾個大噴嚏。\n\n高效擴充：字首 sn- 常與鼻子相關的動作有關（如 snore 打鼾）。\nKK 音標：[sniz] -> 長母音 i，發音時嘴角向兩側咧開。\n\n常見同義字：\ncough（咳嗽，呼吸道受刺激的另一種反應）\nsniff（嗅、抽鼻子）\nwheeze（喘鳴、喘氣）",
  "sniff": "諧音聯想：\n諧音：「死捏夫」聞到奇怪的味道，用力吸鼻子、抽鼻涕。\n\n聯想畫面 1：感冒流鼻涕時，一直用力吸鼻子的聲音。\n\n聯想畫面 2：小狗在草地上聞來聞去，偵測食物或同伴的味道。\n\n高效擴充：與鼻子動作相關的還有 snort（噴鼻息）。\nKK 音標：[snɪf] -> 短促的 [ɪ] 音，氣流從鼻腔快速送出。\n\n常見同義字：\nsmell（聞到，最普遍的感官動詞）\nscent（聞出香氣或氣味，名詞居多）\nwhiff（一縷氣味或輕輕聞一下）",
  "sniffed": "諧音聯想：\n諧音：死你夫。\n\n聯想畫面 1：小狗在草地上到處嗅來嗅去，尋找食物的味道。\n\n聯想畫面 2：感冒了，我不停地抽鼻子，感覺很不舒服。\n\n高效擴充：Sniff 是擬聲詞，模仿吸氣的聲音。\nKK 音標：[snɪft] -> 結尾的 ft 音要短促有力。\n\n常見同義字：\n\nsmelled（聞到）\n\ninhaled（吸入）。",
  "sniffing": "諧音聯想：\n諧音：死你（sniff-ing）。\n\n聯想畫面 1：狗狗在草地上到處嗅，好像在說我要聞死你。\n\n聯想畫面 2：感冒了不停地抽鼻子，發出 sniffing 的聲音。\n\n高效擴充：sniff 是短促地吸氣，sniffle 則是連續抽鼻子。\nKK 音標：[ˋsnɪfɪŋ] -> 重音在第一音節，發音要短促。\n\n常見同義字：\n\nsmelling（聞）\n\ninhaling（吸入）。",
  "snip": "諧音聯想：\n諧音：死（s）＋ 捏（nip）\n\n聯想畫面 1：裁縫師用剪刀快速剪下布料，咔嚓一聲 snip，衣服就做好了。\n\n聯想畫面 2：這件衣服打折後只要一百元，簡直是 snip（便宜貨）。\n\n高效擴充：snip 常用於形容快速的小動作，如 snip off 剪掉。\nKK 音標：[snɪp] -> 短母音 i，發音時嘴型要扁平且短促。\n\n常見同義字：\ncut（剪，最通用的動詞）\nclip（修剪，常用於指甲或紙張）\nbargain（便宜貨，指價格划算）",
  "snitched": "諧音聯想：\n諧音：死捏取。\n\n聯想畫面 1：小偷把秘密死捏在手裡，結果被同夥告密給警察。\n\n聯想畫面 2：學生在考場偷偷告密老師誰在作弊。\n\n高效擴充：snitch 是告密者的意思，加上 ed 變過去式。\nKK 音標：無 -> 重音在第一個音節，注意 sn 的鼻音連讀。\n\n常見同義字：\n\ninformed（告知）\n\nbetrayed（背叛）\n\ntattled（告狀）。",
  "snogging": "諧音聯想：\n諧音：死腦筋（snogging 聽起來像死腦筋）。\n\n聯想畫面 1：電影裡的情侶在公園長椅上忘情地親吻，完全不理會旁人。\n\n聯想畫面 2：這對熱戀中的小情侶在派對角落親熱，旁若無人。\n\n高效擴充：snog 是英式英語，指親吻或愛撫，多用於非正式場合。\nKK 音標：無提供 -> 重音在第一個音節 snog，發短促的 o 音。\n\n常見同義字：\n\nkiss 親吻，通用詞；making out 親熱，美式口語；cuddling 擁抱愛撫。",
  "snoozing": "諧音聯想：\n諧音：死奴驚。\n\n聯想畫面 1：奴隸太累了在打盹，結果被主人驚醒，嚇了一跳。\n\n聯想畫面 2：你在圖書館看書，眼皮太重忍不住 snoozing，頭一點一點的。\n\n高效擴充：snooze 是小睡，常指短暫的休息。\nKK 音標：[ˋsnuzɪŋ] -> 第一音節重音，snoo 發長音 u，像是在打呼的聲音。",
  "snore": "諧音聯想：\n諧音：「死囉」睡得跟死人一樣，鼾聲如雷打得超大聲。\n\n聯想畫面 1：爸爸在客廳沙發上睡著，發出像打雷一樣巨大的打呼聲。\n\n聯想畫面 2：室友半夜的呼嚕聲吵得整間宿舍的人都睡不著。\n\n高效擴充：動詞三態為 snore, snored, snored。\nKK 音標：[snɔr] -> 捲舌音 [ɔr]，嘴唇微圓，聲音低沉沙啞。\n\n常見同義字：\nsleep（睡眠，不一定有聲音）\nsnort（噴鼻息，常伴隨短促呼氣）\nslumber（安睡，較文學性的詞彙）",
  "snort": "諧音聯想：\n諧音：「死諾特」生氣時從鼻孔用力哼氣，發出不屑的聲音。\n\n聯想畫面 1：憤怒的公牛用前腳刨地，同時鼻孔噴出兩道白色蒸汽。\n\n聯想畫面 2：聽到荒謬的提議時，主管冷哼一聲表達不滿。\n\n高效擴充：結合了 sn-（鼻子）與 -ort（發聲尾音）。\nKK 音標：[snɔrt] -> 重音在 [ɔr] 的捲舌音，字尾 [t] 輕輕帶過。\n\n常見同義字：\ngrunt（發出呼嚕或咕噥聲）\nsniff（抽鼻子或吸氣）\nlaugh（大笑，但 snort 帶有嘲弄意味）",
  "snorted": "諧音聯想：\n諧音：死諾特。\n\n聯想畫面 1：他對這個提議嗤之以鼻，哼了一聲，表示完全不同意。\n\n聯想畫面 2：馬兒因為不耐煩，用力噴了噴鼻息，發出粗重的聲音。\n\n高效擴充：snort 的過去式，模擬噴氣聲。\nKK 音標：[snɔrtɪd] -> 重音在第一個音節，結尾的 id 要發出清晰的短音。\n\n常見同義字：\n\nSneered（冷笑，指嘲諷態度）\n\nScorned（輕蔑，指不屑一顧）\n\nSniffed（嗅聞，指動作）。",
  "snorting": "諧音聯想：\n諧音：死弄挺（snort-ing）。\n\n聯想畫面 1：豬在泥地裡噴鼻息，聲音聽起來像是在說死弄挺。\n\n聯想畫面 2：他對我的提議嗤之以鼻，發出了一聲響亮的 snorting。\n\n高效擴充：snort 是噴鼻息，常表達不屑或憤怒。\nKK 音標：[ˋsnɔrtɪŋ] -> 重音在第一音節，注意 r 的捲舌音。\n\n常見同義字：\n\nsneering（冷笑）\n\nscoffing（嘲笑）。",
  "snow": "諧音聯想：\n諧音：「死漏」\n\n聯想畫面 1：冬天高山上不斷飄雪，形成一片銀白色的積雪。\n\n聯想畫面 2：寒流來襲時，合歡山下雪吸引大批遊客上山賞景。\n\n高效擴充：與 blow、grow 同為 ow 結尾的高頻字。\nKK 音標：[sno] -> 發音時嘴型由大圓慢慢收小。\n\n常見同義字：\n\nblizzard（暴風雪，指風雪交加的惡劣天氣）\n\nsleet（雨夾雪，冰雨）\n\npowder snow（粉雪，滑雪愛好者最愛的雪質）",
  "snowy": "諧音聯想：\n諧音：「死漏異」雪花漏進異地，一片白茫茫。\n\n聯想畫面 1：聖誕節早晨拉開窗簾，外面是一個 snowy 的白色世界。\n\n聯想畫面 2：車頂覆蓋著厚厚積雪，開在 snowy 的高速公路上需要特別小心。\n\n高效擴充：由 snow（雪）加上 y 變成形容詞，指多雪的或下雪的。\nKK 音標：[ˋsnoi] -> 重音在第一音節 sno，oi 發雙母音奧伊。\n\n常見同義字：\nsnowbound（因大雪受阻的、交通中斷的）\nicey（結冰的、冰冷的）\nwintery（冬天的、寒冷的）",
  "snugly": "諧音聯想：\n諧音：「死拿給力」。\n\n聯想畫面 1：穿上這件毛衣，舒適溫暖地貼在身上。\n\n聯想畫面 2：貓咪舒適地蜷縮在沙發角落。\n\n高效擴充：snug（舒適的）+ ly（副詞字尾）。\nKK 音標：[ˋsnʌɡli] -> 重音在第一個音節，注意 u 的短母音。\n\n常見同義字：\n\ncozily（舒適地）\n\ntightly（緊密地）\n\nclosely（貼近地）。",
  "so": "諧音聯想：\n諧音：「瘦」\n\n聯想畫面 1：她最近運動成果太顯著，變得如此瘦，所以舊衣服都不能穿了。\n\n聯想畫面 2：因為想要變瘦，所以他決定每天晚上都不吃宵夜。\n\n高效擴充：常作為連接詞表示結果，也可作為副詞修飾形容詞表示極高程度。\nKK 音標：[so] -> 重音在雙元音 O，發音要從 O 圓滑過渡到 U 的嘴型。\n\n常見同義字：\n\ntherefore（因此，用於正式書面語）\n\nthus（因此/如此，語氣非常正式）\n\nvery（非常/如此，作為副詞修飾形容詞）",
  "soak": "諧音聯想：\n諧音：「搜客」把衣服泡在水盆裡徹底浸濕、洗乾淨。\n\n聯想畫面 1：週末泡在溫泉裡，全身肌肉徹底放鬆浸透熱水。\n\n聯想畫面 2：淋了一場大雨，雨水把外套和鞋子全都泡濕了。\n\n高效擴充：常搭配介系詞 soak up（吸收，如吸收陽光或知識）。\nKK 音標：[sok] -> 雙母音 [o]，嘴型由半開變為圓唇。\n\n常見同義字：\nsaturate（使飽和、濕透，較科學）\nsubmerge（沉入水中，強調完全淹沒）\nsteep（浸泡茶葉或藥材）",
  "soaked": "諧音聯想：\n諧音：濕透的、索客\n\n聯想畫面 1：一場突如其來的大雷雨把路人淋得全身 soaked。\n\n聯想畫面 2：海綿被水完全 soaked 之後，變得十分沉重飽滿。\n\n高效擴充：動詞 soak（浸泡）的過去分詞，常作形容詞使用。\nKK 音標：[soʊkt] -> 只有一個音節，oʊ 發雙母音，結尾 kt 清脆有力。\n\n常見同義字：\ndrenched（濕透的、淋透的）\n saturated（完全浸透的、飽和的）\n wet（濕漉漉的）",
  "soap": "諧音聯想：\n諧音：「瘦普」\n\n聯想畫面 1：洗澡時用香皂把全身搓出豐富的泡泡。\n\n聯想畫面 2：婆媽最愛看劇情狗血的肥皂劇。\n\n高效擴充：與 road、boat 同屬 oa 發長音 o 的字群。\nKK 音標：[sop] -> 結尾 p 輕輕閉唇，不需發出大聲。\n\n常見同義字：\n\ndetergent（洗滌劑、洗衣粉，偏化學清潔劑）\n\nbar of soap（一塊肥皂，計量說法）\n\nsoap opera（肥皂劇，固定搭配詞）",
  "soar": "諧音聯想：\n諧音：「手壓」\n\n聯想畫面 1：火箭發射時手壓按鈕，瞬間往上飛舞、暴漲急升。\n\n聯想畫面 2：老鷹在空中翱翔，股價暴漲時也像在高飛。\n\n高效擴充：與 sore (痠痛) 同音不同義，注意拼法包含 ar。\nKK 音標：[sɔr] -> 單音節字，發長音 or 的音。\n\n常見同義字：\n\nrocket（急速上升，像火箭一樣猛增）\n\nsurge（急升或洶湧，常用於價格或浪潮）\n\nfly（飛行或高飛，較為基礎廣泛）",
  "sob": "諧音聯想：\n諧音：「撒潑」\n\n聯想畫面 1：她在地上哭得一把鼻涕一把淚，不斷啜泣並向媽媽撒潑。\n\n聯想畫面 2：失戀的女子躲在房間裡傷心地抽噎，肩膀微微顫抖。\n\n高效擴充：為典型的擬聲字，模仿人在哭泣時抽氣的聲音。\nKK 音標：[sɑb] -> 短母音 ɑ，發音短促有力。\n\n常見同義字：\ncry（哭泣，最通用的泛指哭）\nweep（哭泣、淚流滿面，較具文學感）\nblubber（大哭、號啕大哭，較口語誇張）",
  "sober": "諧音聯想：\n諧音：「搜包」\n\n聯想畫面 1：警察臨檢時要求駕駛搜包檢查，確認對方完全沒喝酒、保持清醒。\n\n聯想畫面 2：開完嚴肅的晨會後，老闆整個人冷靜下來，嚴肅地交代工作。\n\n高效擴充：字首 sob- 聯想到 sober 的清醒與嚴肅感，常與 drunk（醉的）做對比。\nKK 音標：[ˋsobɚ] -> 主重音在第一個音節 so，唸長音 o，ɚ 輕念，嘴型要圓。\n\n常見同義字：\nclear-headed（頭腦清醒的，形容思緒條理分明）\nserious（嚴肅的，形容態度認真不輕浮）\ncalm（冷靜的，形容情緒平穩不慌亂）",
  "soccer": "諧音聯想：\n諧音：「灑卡」\n\n聯想畫面 1：球員在球場上踢英式足球，把汗水四處灑卡（灑開）。\n\n聯想畫面 2：世足賽期間大家聚在一起看足球轉播狂歡。\n\n高效擴充：美式英文中專指足球，英式則稱 football。\nKK 音標：[ˋsɑkɚ] -> 主重音在第一個音節 sɑ，口型要張大發短 o 音。\n\n常見同義字：\n\nfootball（美式足球或英式足球，英美用法不同）\n\nrugby（英式橄欖球）\n\npitch（足球場地、球場）",
  "sociable": "諧音聯想：\n諧音：「搜鞋柏」\n\n聯想畫面 1：社交聚會上大家在搜鞋子聊天，每個人都非常善交際。\n\n聯想畫面 2：他個性十分合群友善，在派對中很受歡迎。\n\n高效擴充：由 society（社會）衍生，指喜歡融入社會群體。\nKK 音標：[ˋsoʃəbəl] -> 重音在第一音節 so，cia 發 /ʃə/ 音。\n\n常見同義字：\nfriendly（友善的，親切的）\ngregarious（愛社交的，群居的）\noutgoing（外向的，好交際的）",
  "social": "諧音聯想：\n諧音：「手球」社交活動中大家傳球互動。\n\n聯想畫面 1：週末參加了一場大型的 social 晚會，認識了許多新朋友。\n\n聯想畫面 2：人類是群居動物，具有強烈的 social 屬性。\n\n高效擴充：由 society（社會）變化而來的形容詞，也可當名詞聯誼會。\nKK 音標：[ˋsoʃəl] -> 重音在第一音節 so，o 發長音歐。\n\n常見同義字：\npublic（公眾的、大眾的）\ncommunal（公共的、社區的）\nfriendly（友善的、好交際的）",
  "socialism": "諧音聯想：\n諧音：「搜捨力，贊姆」\n\n聯想畫面 1：政府搜集社會的財產與物資來均分，大家對這個社會主義制度按讚。\n\n聯想畫面 2：經濟學課堂上教授正在講解社會主義如何透過共享勞力來運作。\n\n高效擴充：由 social (社會的) 加上主義字尾 ism 組合而成。\nKK 音標：[ˋsoʃə͵lɪzəm] -> 主重音在第一個音節 so，後半部維持平穩語調。\n\n常見同義字：\n\ncommunism（共產主義，社會主義的更極端集中形式）\n\ncapitalism（資本主義，強調私有財產與市場機制，為其反義詞）\n\nwelfarism（福利主義，偏向社會福利政策的體制）",
  "socialist": "諧音聯想：\n諧音：「搜捨力，死特」\n\n聯想畫面 1：這位社會主義者死守著社會福利政策的特質不放。\n\n聯想畫面 2：政壇上支持社會主義改革的議員們正在發表激烈演說。\n\n高效擴充：由 socialism 去掉 m 改成 t，變成指「人」或「形容詞」。\nKK 音標：[ˋsoʃələst] -> 重音在 so，字尾的 ist 讀作短促的 斯特。\n\n常見同義字：\n\ncommunist（共產主義者）\n\ncapitalist（資本主義者）\n\nreformist（改良主義者，積極推動社會改革的人）",
  "socialize": "諧音聯想：\n諧音：「手洗賴子」\n\n聯想畫面 1：大家動手洗碗聊天，一起交際與交往。\n\n聯想畫面 2：參加派對使自己更合群，融入社交圈。\n\n高效擴充：social (社會的) 加上 ize (化)，意即社會化、交際。\nKK 音標：[ˋsoʃə͵laɪz] -> 第一音節重音，so 發長音 o，cia 發 sh 音。\n\n常見同義字：\n\nmingle（交往或混入人群，強調互動）\n\nnetwork（建立人脈或社交，現代常用）\n\ninteract（互動或交流，較中性科學）",
  "society": "諧音聯想：\n諧音：「手洗愛踢」\n\n聯想畫面 1：現代化社會裡每個人都愛乾淨，連球員踢球前都要把手洗乾淨。\n\n聯想畫面 2：加入各種公益社團和協會，對社會做出貢獻。\n\n高效擴充：字尾 -ety 是常見的名詞字尾，將形容詞轉為抽象名詞。\nKK 音標：[səˋsaɪəti] -> 主重音在第二個音節 saɪ，前後的音節要唸得輕快。\n\n常見同義字：\n\ncommunity（社群、社區，範圍較小）\n\nassociation（協會、社團）\n\npublic（大眾、公眾）",
  "socio": "諧音聯想：\n諧音：搜秀\n\n聯想畫面 1：在社會上搜集秀場資訊，這就是 socio 社會的運作方式。\n\n聯想畫面 2：我們在討論 socio-economic 社經地位，這與社會結構息息相關。\n\n高效擴充：socio 是社會學的常用前綴，源自 society。\nKK 音標：[ˋsoʊsioʊ] -> 重音在第一音節，發音要圓潤。\n\n常見同義字：\n\nsocial（社會的，形容詞形式）\n\ncommunal（公共的，社區的）",
  "sociology": "諧音聯想：\n諧音：「搜秀，老雞」\n\n聯想畫面 1：教授在社會學課堂上搜集各種選秀節目老老少少的人際關係來研究。\n\n聯想畫面 2：大學圖書館的社會學專區擺滿了探討人類社會群體行為的厚重原文書。\n\n高效擴充：字首 socio 代表社會，字尾 ology 代表某某學科（如 biology）。\nKK 音標：[͵sosiˋɑlədʒi] -> 主重音落在倒數第二音節的 ah (ɑ)，前後讀音要流暢。\n\n常見同義字：\n\nanthropology（人類學，研究人類文化與演化）\n\npsychology（心理學，研究個人心智與行為）\n\neconomics（經濟學，研究資源分配的學問）",
  "sock": "諧音聯想：\n諧音：「爽客」\n\n聯想畫面 1：運動完洗完澡穿上一雙乾淨的厚短襪，感覺真是一個爽客。\n\n聯想畫面 2：電影裡的英雄一拳猛擊壞人的臉，給他一個狠狠的重擊。\n\n高效擴充：單字極短，注意與 sack（麻袋）、sick（生病的）的拼法區分。\nKK 音標：[sɑk] -> 短促的 a 音，結尾 k 爆破有力。\n\n常見同義字：\n\nstocking（長襪、絲襪，通常較長）\n\nblow（重擊、打擊）\n\nhit（擊打、碰撞）",
  "socket": "諧音聯想：\n諧音：「塞客廳」\n\n聯想畫面 1：電線太多不夠用，只好把延長線塞客廳的牆壁插座裡。\n\n聯想畫面 2：醫學上指眼球所在的眼窩凹槽，也是一種骨骼的關節窩。\n\n高效擴充：字尾 -et 通常表示小巧的物件或容器。\nKK 音標：[ˋsɑkət] -> 主重音在第一個音節 sɑ，後面 -ket 唸輕聲。\n\n常見同義字：\noutlet（電源插座，美式常用）\nplug hole（插孔）\nreceptacle（容器、插座，較正式）",
  "soda": "諧音聯想：\n諧音：「速打」\n\n聯想畫面 1：吃炸雞時一定要來一杯冰涼暢快的汽水。\n\n聯想畫面 2：主婦用小蘇打粉快速打掃油膩的廚房。\n\n高效擴充：雙音節字，重音落在第一個音節。\nKK 音標：[ˋsodə] -> 主重音在第一個音節的 so，後面 ə 念輕短的ㄜ。\n\n常見同義字：\n\npop（汽水，美式口語常用）\n\ncola（可樂，特定碳酸飲料）\n\nsoft drink（無酒精軟性飲料的統稱）",
  "sodium": "諧音聯想：\n諧音：「掃低壓姆」\n\n聯想畫面 1：實驗室裡拿掃把把撒落的鈉金屬粉末清乾淨，避免碰到水爆炸降低壓力和危險。\n\n聯想畫面 2：營養標示上看到鈉含量過高，醫生提醒高血壓患者要少吃。\n\n高效擴充：元素週期表上的 Na，化學鍵結中常與氯結合成鹽巴 (NaCl)。\nKK 音標：[ˋsoðiəm] -> 主重音在 so，di 唸輕聲的笛，字尾 um 輕輕帶過。\n\n常見同義字：\n\nsalt（鹽巴，日常生活中最常見的鈉化合物來源）\n\nelement（化學元素，鈉屬於活性極高的金屬元素）\n\nmineral（礦物質，鈉是人體所需的電解質之一）",
  "sofa": "諧音聯想：\n諧音：「瘦發」\n\n聯想畫面 1：下班回家後整個人癱在客廳的沙發上追劇。\n\n聯想畫面 2：這張舒適的長椅沙發讓客人坐了就不想走。\n\n高效擴充：常與 couch 並用，沙發馬鈴薯常用 couch potato。\nKK 音標：[ˋsofə] -> 重音在前，尾音 fa 要念得輕短。\n\n常見同義字：\n\ncouch（沙發、長椅，美式常用）\n\nsettee（雙人小沙發或長椅，較古典）\n\nloveseat（雙人小沙發，浪漫情侶款）",
  "soft": "諧音聯想：\n諧音：「手服」，雙手摸起來讓人很舒服的柔軟觸感。\n\n聯想畫面 1：用雙手撫摸一隻毛茸茸的兔子，感覺非常軟、很好摸。\n\n聯想畫面 2：捏一下剛出爐的棉花糖蛋糕，手感十分溫柔且易彎曲。\n\n高效擴充：與硬的 hard 剛好相反，字尾 ft 結合呈現出輕柔感。\nKK 音標：[sɑft] -> 短音 [ɑ]，發音短促清脆，氣流從齒縫輕輕帶過。\n\n常見同義字：\n\nmushy（糊狀的、軟爛的，常用於形容食物質地）\n\nsquashy（軟而易壓扁的，如海綿或靠墊）\n\npulpy（果肉般濃稠柔軟的，常用於水果）",
  "soften": "諧音聯想：\n諧音：「手分」\n\n聯想畫面 1：用手把揉好的麵糰分開，感覺觸感變得非常柔軟。\n\n聯想畫面 2：原本態度很硬的客戶，聽了誠懇的道歉後，口氣終於變和藹、軟化了。\n\n高效擴充：形容詞 soft 加上動詞字尾 -en 就變成使變軟。\nKK 音標：[ˋsɑfən] -> 主重音在第一個音節 ɑf，t 不發音或輕發，en 快速帶過。\n\n常見同義字：\nmellow（使柔和，常形容音樂或光線）\ntenderize（使肉質變嫩，專指烹飪）\nrelax（放鬆，指肌肉或緊張情緒）",
  "softened": "諧音聯想：\n拆解：soft（軟的）+ en（使...化）+ ed（過去式）。\n\n聯想畫面 1：經過長時間的浸泡，乾硬的皮革終於 softened，變得柔軟好用。\n\n聯想畫面 2：聽到對方誠懇的道歉，他的態度明顯 softened，不再那麼強硬。\n\n高效擴充：soften 是動詞，加上 -ed 變成過去分詞。\nKK 音標：['sɔfənd] -> 第一音節重音，注意 t 不發音。\n\n常見同義字：\nrelaxed（放鬆的，指緊張感降低）\nmollified（緩和的，指情緒被安撫）\nweakened（減弱的，指強度降低）",
  "softening": "諧音聯想：\n諧音：受夫寧。\n\n聯想畫面 1：經過長時間的溝通，他強硬的態度終於出現了 softening，願意妥協。\n\n聯想畫面 2：洗完澡後塗抹乳液，感覺皮膚的 softening 效果很明顯。\n\n高效擴充：soft（軟）+ en（使成為）+ ing，形容詞化或動名詞化。\nKK 音標：[ˋsɔfnɪŋ] -> 第一音節 soft 重讀，注意 t 不發音，發音像「搜夫寧」。",
  "software": "諧音聯想：\n諧音：「瘦得發威」\n\n聯想畫面 1：工程師寫電腦軟體寫到廢寢忘食，人變得好瘦得發威（瘦得厲害）。\n\n聯想畫面 2：公司花大錢採購了一套全新的辦公室作業系統軟體。\n\n高效擴充：由 soft（軟的）加上 ware（器皿、製品）組合而成，與 hardware（硬體）相對。\nKK 音標：[ˋsɔf͵twɛr] -> 主重音在第一個音節 sɔf，ware 的 air 音要飽滿。\n\n常見同義字：\nprogram（程式，偏指特定功能的執行檔）\napplication（應用程式，簡稱 app）\nfirmware（韌體，介於硬體與軟體之間）",
  "soil": "諧音聯想：\n諧音：「手油」\n\n聯想畫面 1：農夫雙手沾滿肥沃的黑土與泥土來種田。\n\n聯想畫面 2：小朋友玩泥巴不小心把白襯衫弄髒了。\n\n高效擴充：字根 oi 發音組合，如 boil、coil。\nKK 音標：[sɔɪl] -> 雙母音 ɔɪ，發音時由ɔ滑向ɪ。\n\n常見同義字：\n\nearth（地球、泥土，範圍較廣）\n\nground（地面、土地，指踩得到的實地）\n\ndirty（弄髒的，形容詞型態）",
  "soiled": "諧音聯想：\n諧音：「所已的」\n\n聯想畫面 1：這件白色襯衫被醬油弄髒了，難怪洗也洗不乾淨，原來罪魁禍首就是所已的醬汁。\n\n聯想畫面 2：政客清廉的形象因為收賄醜聞而徹底被玷污、敗壞。\n\n高效擴充：由 soil（弄髒、土壤）加上 -ed 變成過去分詞當形容詞使用。\nKK 音標：[sɔɪld] -> 單音節字，包含雙母音 [ɔɪ]，字尾 [ld] 完整發音。\n\n常見同義字：\ndirty（髒的，最口語常用的說法）\nstained（有污漬的，強調留有斑點）\ntarnished（失去光澤的，常比喻名譽受損）",
  "sola": "諧音聯想：\n諧音：「搜拉（Sola）」\n\n聯想畫面 1：太陽能板在陽光下運作，sola 能量轉化為電力。\n\n聯想畫面 2：單張的紙張或單式的表格，在專業術語中常出現這個字根。\n\n高效擴充：源自拉丁文 sol，意指太陽，常見於 solar 太陽能。\nKK 音標：[ˋsolə] -> 重音在第一音節，o 發長音。",
  "solace": "諧音聯想：\n諧音：「搜（So）+ 累（lace）」\n\n聯想畫面 1：當你感到疲憊時，找個安靜的地方休息，這份寧靜就是你心靈的 solace。\n\n聯想畫面 2：在傷心時，朋友的一句安慰話語，成為了你最好的慰藉。\n\n高效擴充：字根 sol 意為孤獨，solace 就是在孤獨時給予的安慰。\nKK 音標：[ˋsɑləs] -> 重音在第一音節，s 發音清脆。",
  "solar": "諧音聯想：\n諧音：「搜囉」全屋的陽光，裝設太陽能板。\n\n聯想畫面 1：透天厝的屋頂裝滿了太陽能發電板，正吸收著強烈的日光的照射。\n\n聯想畫面 2：太空人搭乘探測器準備前往探索太陽系的奧祕。\n\n高效擴充：字根 sol 代表太陽，如 solstice (至日、至點)。\nKK 音標：[ˋsolɚ] -> 第一音節 sol 為主重音，字尾 ɚ 發輕短的爾音。\n\n常見同義字：\nsunny（陽光充足的，日常用來形容天氣晴朗）\nheliocentric（以太陽為中心的，天文學專業用語）\nsolar-powered（太陽能動力的，常作複合形容詞使用）",
  "soldier": "諧音聯想：\n諧音：「瘦得結實」\n\n聯想畫面 1：軍營裡的士兵每天接受魔鬼訓練，個個都瘦得結實、肌肉線條分明。\n\n聯想畫面 2：植物裡的兵蟻為了保護蟻巢，展現出堅忍不拔的精神。\n\n高效擴充：d 發音常被輕化為類似 j 的音，拼法容易漏掉中間的 d。\nKK 音標：[ˋsoldʒɚ] -> 主重音在第一個音節 sol，dʒer 連音要圓潤。\n\n常見同義字：\n\nmilitary (man)（軍人、武職人員）\n\ntroop（部隊、軍隊，多用複數）\n\nfighter（戰士、鬥士）",
  "sole": "諧音聯想：\n諧音：「瘦鵝」只有一隻腳站在那裡，強調唯一的、孤單的。\n\n聯想畫面 1：鞋底磨損得很嚴重，必須拿到修理店去換新鞋底。\n\n聯想畫面 2：他是這間公司唯一的合夥人，擁有絕對決策權。\n\n高效擴充：單字 sole 也可以指比目魚（sole fish）。\nKK 音標：[sol] -> 圓唇雙母音 [o]，發音時舌根往後縮。\n\n常見同義字：\nunique（獨一無二的，強調稀有）\nsingle（單身的或單一個的）\nexclusive（獨家的、專用的）",
  "solely": "諧音聯想：\n諧音：「搜（So）+ 累（le）+ 離（ly）」\n\n聯想畫面 1：這項任務 solely 由我一個人完成，沒有任何人幫忙。\n\n聯想畫面 2：這家店 solely 販售手工餅乾，不賣其他商品，強調唯一性。\n\n高效擴充：源自 sole 單一的，加上 ly 變成副詞，強調僅僅。\nKK 音標：[ˋsoəli] -> 重音在第一音節，o 發長音。",
  "solemn": "諧音聯想：\n諧音：掃人門 -> 諧音聯想：掃人門風的嚴肅神情。\n\n聯想畫面 1：校長在朝會上以極其嚴肅的表情訓話。\n\n聯想畫面 2：莊嚴的國葬典禮上，全場民眾默哀。\n\n高效擴充：字尾 mn 的 n 不發音。\nKK 音標：[ˋsɑləm] -> 重音在第一音節，sɑ 發短 o 音，ləm 輕聲。\n\n常見同義字：\n\nserious（嚴肅的、認真的）\n\ngrave（嚴重的、莊嚴的）\n\nformal（正式的、莊重的）",
  "solicit": "諧音聯想：\n諧音：「搜（So）+ 哩（li）+ 希特（cit）」\n\n聯想畫面 1：為了籌辦活動，我們四處 solicit 贊助，誠懇地向廠商請求支持。\n\n聯想畫面 2：在街頭徵求簽名，主動向路人請求協助。\n\n高效擴充：字根 cit 意為喚起，solicit 就是不斷請求以喚起對方的行動。\nKK 音標：[səˋlɪsɪt] -> 重音在第二音節，注意 cit 發音要輕快。",
  "solid": "諧音聯想：\n諧音：「手裡得」\n\n聯想畫面 1：把一塊沉甸甸的固體金塊拿在手裡，感覺非常結實可靠。\n\n聯想畫面 2：這棟房子的結構很堅固，經歷地震也毫髮無傷。\n\n高效擴充：字根固體、堅固之意，常見於 solid waste（固體廢棄物）。\nKK 音標：[ˋsɑləd] -> 重音在第一音節的 ˋsɑ。\n\n常見同義字：\nfirm（穩固的、堅定的）\nstrong（強壯的、結實的）\nrobust（強健的、結實的）",
  "solidarity": "諧音聯想：\n諧音：「撒力，打力，提」\n\n聯想畫面 1：罷工工人們把彼此的力量撒出來、團結打拼，一起把訴求提上去。\n\n聯想畫面 2：國際社會展現高度的團結一致，聲援受災國家度過難關。\n\n高效擴充：源自 solid (堅固的、團結的)，字尾 ity 變成抽象名詞。\nKK 音標：[͵sɑləˋdɛrəti] -> 主重音在 der，前後的音節要唸得輕快且有節奏感。\n\n常見同義字：\n\nunity（團結、一致，最基礎的同義字）\n\nharmony（和諧、融洽，強調人與人之間的平和相處）\n\ncohesion（凝聚力，物理或社會群體的緊密結合）",
  "solitary": "諧音聯想：\n諧音：「掃離他理」把孤僻的人掃開、離他遠一點，因為他習慣獨來獨往。\n\n聯想畫面 1：隱士獨自住在深山中的木屋，過著遠離塵囂的孤獨生活。\n\n聯想畫面 2：犯人被關在單獨監禁的黑牢裡，看不到其他人。\n\n高效擴充：字根 soli- 意指單獨、唯一。\nKK 音標：[ˋsɑlə͵tɛri] -> 主重音在第一個音節 [sɑ]，後面音節輕快唸出。\n\n常見同義字：\n孤独的 lonely（帶有感傷情緒）\nisolated（偏遠隔離的）\nremote（偏僻遙遠的）",
  "solitude": "諧音聯想：\n諧音：「瘦粒禿得」\n\n聯想畫面 1：一個人在深山隱居，瘦小的身軀孤零零地站在禿頭的山頂享受獨處。\n\n聯想畫面 2：作家搬到鄉下小屋尋找創作靈感，在安靜的孤獨中寫出偉大作品。\n\n高效擴充：字根 sol 代表單獨、孤立（如 solo 單人表演）。\nKK 音標：[ˋsɑlə͵tud] -> 主重音在第一音節 sal，後方 tude 唸短促的 tud。\n\n常見同義字：\n\nloneliness（寂寞、孤獨，帶有感傷情緒的孤獨）\n\nisolation（隔離、孤立，被動與外界隔絕的狀態）\n\nprivacy（隱私、獨處空間，不被打擾的個人時間）",
  "solo": "諧音聯想：\n諧音：「秀落」在舞台上展現個人的獨奏、單飛表演。\n\n聯想畫面 1：吉他手在演唱會中站到舞台中央，來一段精彩的個人獨奏。\n\n聯想畫面 2：飛行員第一次不帶教練，單獨駕駛飛機成功升空。\n\n高效擴充：與 solitary 同源，都包含代表單獨的字根。\nKK 音標：[ˋso͵lo] -> 主重音在第一個音節 [so]，兩個音節都要發清晰的 [o]。\n\n常見同義字：\nindividual（個人的、單獨的）\nindependent（獨立自主的）\nunaccompanied（無伴奏的、無人陪同的）",
  "soluble": "諧音聯想：\n諧音：手（so）流（lu）不（ble）住。\n\n聯想畫面 1：糖放進水裡，手一攪拌就流散不見了，這就是可溶解。\n\n聯想畫面 2：複雜的問題被解決了，就像冰塊溶於水一樣自然。\n\n高效擴充：字根 sol 有鬆開、溶解的意思。\nKK 音標：[ˋsɑljəb(ə)l] -> 重音在第一音節，注意 l 的發音位置。",
  "solution": "諧音聯想：\n諧音：「爽露休閒」\n\n聯想畫面 1：終於想出難題的完美解答，壓力全消可以爽快地放假休閒了。\n\n聯想畫面 2：化學實驗中把粉末倒入溶劑裡，攪拌均勻形成透明的溶液。\n\n高效擴充：由動詞 solve（解決）變化而來的名詞，字尾 -tion 表狀態。\nKK 音標：[səˋluʃən] -> 主重音在第二個音節 lu，shon 要輕而快。\n\n常見同義字：\n\nanswer（答案、解答，口語常用）\n\nresolution（決議、解決方案、解析度）\n\nsolvent（溶劑）",
  "solve": "諧音聯想：\n諧音：「手握」\n\n聯想畫面 1：名偵探手握重要證據，終於成功解決了懸案。\n\n聯想畫面 2：遇到數學難題時，動腦思考就能順利解答。\n\n高效擴充：字根 olv 代表洗滌或鬆開，把糾結的問題鬆開就是解決。\nKK 音標：[sɑlv] -> a 發開口音，v 要輕咬下唇發音。\n\n常見同義字：\nresolve（解決、下定決心，較正式）\nfigure out（想出、理解，口語常用）\naddress（處理、對付問題）",
  "some": "諧音聯想：\n諧音：「撒姆」，把一些零食撒在姆指旁邊。\n\n聯想畫面 1：桌上還剩下一些餅乾，你可以拿去吃。\n\n聯想畫面 2：某個神祕的朋友今天沒有來上課。\n\n高效擴充：常用於肯定句中的不定數量，否定句或疑問句通常改用 any。\nKK 音標：[sʌm] -> 短促的 [ʌ] 音，嘴巴微開，發音快速輕巧。\n\n常見同義字：\n\na few（一些，專門用來修飾可數名詞）\n\na little（一些，專門用來修飾不可數名詞）\n\nseveral（幾個、數個，強調數量比 some 再多一點點）",
  "somebody": "諧音聯想：\n諧音：「三八低」\n\n聯想畫面 1：派對裡突然走進來一個穿著顯眼的三八低（大人物），吸引全場目光。\n\n聯想畫面 2：走在路上感覺好像有人在後面跟著自己。\n\n高效擴充：由 some（某個）加 body（身體/人）組合而成的複合代名詞。\nKK 音標：[ˋsʌm͵bɑdi] -> 主重音在第一個音節 sum，後面的 body 唸輕聲。\n\n常見同義字：\n\nsomeone（某人，與 somebody 完全同義可互換）\n\nVIP（重要人物、貴賓）\n\ncelebrity（名人、知名人士）",
  "someday": "諧音聯想：\n諧音：「三D」\n\n聯想畫面 1：總有一天（Someday），電影院的螢幕會全面升級成更逼真的三D立體技術。\n\n聯想畫面 2：小男孩許下心願，有朝一日他要開著太空飛船去月球。\n\n高效擴充：由 some（某個）與 day（日子）組合而成的未來時間副詞。\nKK 音標：[ˋsʌm͵de] -> 主重音在 sum，day 發長雙母音 e，語氣充滿期待。\n\n常見同義字：\none day（有一天，常指未來或過去某日）\nin the future（在未來）\nsooner or later（遲早）",
  "somehow": "諧音聯想：\n諧音：「三號」\n\n聯想畫面 1：三號（Somehow）參賽者用某種神祕的方式，居然把魔術方塊解開了。\n\n聯想畫面 2：不知道為什麼，今天的公車竟然比平常慢了半小時才來。\n\n高效擴充：由 some（某個）與 how（如何）組合，表不知名的原因或方式。\nKK 音標：[ˋsʌm͵haʊ] -> 主重音在 sum，how 的 ow 嘴型由大收小。\n\n常見同義字：\nin some way（以某種方式）\nby some means（透過某種手段）\nsome-or-other（某種程度的）",
  "someone": "諧音聯想：\n拆解 / 諧音：「some 某些 + one 人」\n\n拆解 / 諧音：「some 某些 + one 人」\n\n聯想畫面 1：走廊盡頭好像站著某個人在看我們。\n\n聯想畫面 2：公司來了一個重要人物，大家都在猜他是誰。\n\n高效擴充：與 somebody 意思完全相同，皆指某人。\nKK 音標：[ˋsʌm͵wʌn] -> 主重音在第一個字 some。\n\n常見同義字：\n\nsomebody（某人，與 someone 完全通用）\n\nanybody（任何人，多用於否定句或疑問句）\n\nperson（具體的一個人）",
  "something": "諧音聯想：\n拆解 / 諧音：「some 某些 + thing 東西」\n\n拆解 / 諧音：「some 某些 + thing 東西」\n\n聯想畫面 1：桌上好像有放了某些東西，看起來神祕兮兮的。\n\n聯想畫面 2：他看起來非常有才華，簡直就是個狠角色（something）。\n\n高效擴充：字尾 thing 可替換為 anything、nothing。\nKK 音標：[ˋsʌmθɪŋ] -> 咬舌音 th 發輕音，重音在前。\n\n常見同義字：\n\nanything（任何事，多用於否定或疑問）\n\nnothing（沒事、什麼都沒有）\n\neverything（每件事、全部）",
  "sometime": "諧音聯想：\n諧音：「三套姆」\n\n聯想畫面 1：阿嬤改天（Sometime）要把那三套漂亮的衣服拿出來穿。\n\n聯想畫面 2：我們改天找個時間一起去喝咖啡敘舊吧。\n\n高效擴充：注意與 sometimes（有時）的差異，sometime 指不確定的某個時間點。\nKK 音標：[ˋsʌm͵taɪm] -> 主重音在 sum，taɪm 的 i 發長音。\n\n常見同義字：\nat a certain time（在特定時間）\none day（某一天）\nsooner or later（遲早）",
  "sometimes": "諧音聯想：\n諧音：「三不五時」就會發生的頻率。\n\n聯想畫面 1：他 sometimes（有時）會在週末去海邊看夕陽放空。\n\n聯想畫面 2：這家老店 sometimes（偶爾）會因為老闆去爬山而臨時休息。\n\n高效擴充：由 some 與 times 組合成的複合副詞，注意 times 帶有複數 s。\nKK 音標：[səmˋtaɪmz] -> 主重音落在第二音節的 taɪmz 上，讀音要拉長。\n\n常見同義字：\noccasionally（偶爾，比 sometimes 更具間隔性）\nfrom time to time（時常，常作片語使用）\nperiodically（定期地，指有規律的間隔）",
  "somewhat": "諧音聯想：\n諧音：「三碗挖溝」\n\n聯想畫面 1：你在餐廳一次吃了三碗飯，覺得肚子有點撐，形容程度稍微有一點多。\n\n聯想畫面 2：朋友問你今天心情如何，你回答今天有點累，心情稍微受到影響。\n\n高效擴充：由 some（一些）加上 what（什麼）組成，字面意思是有些什麼，引申為有點、稍微。\nKK 音標：[ˋsʌmˋwʌt] -> 雙重音皆在前面，sʌm 發短音 u，wʌt 發短音ʌ，唸起來像是「三姆-瓦特」。\n\n常見同義字：\na little（稍微，常用於形容詞前修飾程度）\na bit（有一點，口語常用）\nto some extent（在某種程度上，較正式）",
  "somewhere": "諧音聯想：\n諧音：「賞味回兒」\n\n聯想畫面 1：賞味期限的美味食物，一定藏在某個地方等待被發現。\n\n聯想畫面 2：鑰匙不見了，它肯定掉落在家裡的某處角落。\n\n高效擴充：由 some（某個）加上 where（地方）組合而成的複合副詞。\nKK 音標：[ˋsʌm͵wɛr] -> 重音在第一音節，where 要發輕聲。\n\n常見同義字：\n\nin some place（在某個地方，較為口語的片語說法）\n\nanywhere（任何地方，常用於否定句與疑問句）\n\nsomeplace（某處，口語中常替代 somewhere）",
  "son": "諧音聯想：\n諧音：「參」\n\n聯想畫面 1：爸爸帶著唯一的兒子一同參與家族企業。\n\n聯想畫面 2：這名慈父正驕傲地向鄰居介紹他的乖兒子。\n\n高效擴充：與 sun 同音不同義，注意拼法差異。\nKK 音標：[sʌn] -> 短母音 ʌ，嘴巴微微張開輕聲發出ㄜ。\n\n常見同義字：\n\nboy（男孩，較泛稱）\n\nchild（小孩、子女）\n\noffspring（後代、子嗣，較正式）",
  "song": "諧音聯想：\n諧音：「送」\n\n聯想畫面 1：KTV包廂裡大家輪流點歌，開心唱著流行歌曲。\n\n聯想畫面 2：街頭藝人正彈著吉他，深情演唱一首動人的情歌。\n\n高效擴充：與 long、wrong 同屬 ong 結尾字群。\nKK 音標：[sɔŋ] -> 鼻音 ŋ 結尾，聲音留在鼻腔中。\n\n常見同義字：\n\ntune（曲調、旋律）\n\ntrack（歌曲、音軌，專輯中的單曲）\n\nmelody（旋律、主旋律）",
  "soon": "諧音聯想：\n諧音：「速暈」就是坐旋轉木馬太快，馬上就會頭暈。\n\n聯想畫面 1：外送員說餐點很快就會送到，soon（不久）就會按門鈴。\n\n聯想畫面 2：考試成績很快就會公佈，大家都希望能 soon（早點）知道。\n\n高效擴充：常與 coming、after 等字搭配，形成 see you soon（待會見）。\nKK 音標：[sun] -> oo 發長元音 u，嘴唇嘟成圓形向前突起。\n\n常見同義字：\nshortly（不久，通常指時間上的短暫差距）\npromptly（迅速地，強調毫不拖延）\nearly（早地，指時間點靠前）",
  "soot": "諧音聯想：\n諧音：塑膠碳（燃燒產生的黑色煤煙）\n\n聯想畫面 1：壁爐長期使用後，煙囪內部卡滿了黑色的煤煙與菸灰。\n\n聯想畫面 2：工廠煙囪冒出大量黑色濃煙，把周遭的環境都用煤煙燻黑了。\n\n高效擴充：字尾 oot 發短 u 音，類似 foot，注意不要發成長音。\nKK 音標：[sʊt] -> 短促的單音節，雙唇微開唸出ʊ的短音。\n\n常見同義字：\nsmoke（煙霧，泛指燃燒產生的氣體）\nash（灰燼，燃燒後的粉末殘留）\ncarbon（碳，化學與環保常用詞）",
  "soothe": "諧音聯想：\n諧音：「輸死」\n\n聯想畫面 1：比賽輸死瞭，心情很差需要被安慰、哄一下來使平靜。\n\n聯想畫面 2：用溫柔的聲音減輕對方的痛苦與焦慮。\n\n高效擴充：字尾 the 發清輔音或濁輔音的差別，注意 th 咬舌音。\nKK 音標：[suð] -> 單音節字，oo 發長音 u，th 發濁音 ð。\n\n常見同義字：\n\ncalm（使平靜，最常見的日常用字）\n\ncomfort（安慰或慰藉，偏向給予溫暖）\n\nrelieve（減輕疼痛或壓力，偏向舒緩）",
  "sophisticated": "諧音聯想：\n諧音：「搜費死踢開特」\n\n聯想畫面 1：這台精密儀器花了很多費用才踢開技術門檻，變得很先進。\n\n聯想畫面 2：他穿著打扮十分老於世故、見多識廣，很有都會品味。\n\n高效擴充：字根 soph-（智慧）衍生，指老練或高度精密化。\nKK 音標：[səˋfɪstə͵ketɪd] -> 主重音在第二音節 fis，次重音在 ka。\n\n常見同義字：\ncomplex（複雜的，精密的）\nworld-wise（老於世故的）\nadvanced（先進的，高階的）",
  "sophomore": "諧音聯想：\n諧音：「掃風摸」\n\n聯想畫面 2：大學二年級的學長在宿舍裡掃風摸（輕鬆摸魚），準備迎接期末考。\n\n聯想畫面 1：這個樂團推出第二張專輯，展現出不同於新人的成熟度。\n\n高效擴充：美式學校體制中專門指高中的十年級或大學的二年級生。\nKK 音標：[ˋsɑf͵mɔr] -> 主重音在第一個音節 sɑf，第二個音節 f 輕唸。\n\n常見同義字：\nfreshman（大一新生）\njunior（大三學生）\nsenior（大四畢業生或資深者）",
  "sore": "諧音聯想：\n諧音：「搜鵝」搜到一隻腳痠痛的鵝，牠因為翅膀受傷而感到很惱火。\n\n聯想畫面 1：跑完馬拉松後肌肉非常 sore，連走路都覺得全身痛處。\n\n聯想畫面 2：提到他心中的痛處時，他的態度顯得十分 sore 且惱怒。\n\n高效擴充：常與 muscles 搭配形成 sore muscles（肌肉痠痛）。\nKK 音標：[sɔr] -> 包含捲舌的 r 音，前面的 ɔ 口型要圓而深沉。\n\n常見同義字：\ninjured（受傷的，通常指身體組織受損）\naching（痠痛的、隱隱作痛的）\nresentful（憤恨的、不滿的）",
  "soreness": "諧音聯想：\n諧音：搜兒內斯。\n\n聯想畫面 1：健身後全身 soreness，連走路都覺得痠痛。\n\n聯想畫面 2：他對那次誤會依然感到 soreness，心裡還是很不舒服。\n\n高效擴充：sore（疼痛的）+ ness（名詞後綴），形容身體或心理的痛楚。\nKK 音標：[ˋsɔrnəs] -> 重音在第一個音節，注意 s-o-r-e 的長音。\n\n常見同義字：\n\npain（疼痛，通用）\n\nache（持續的隱痛）\n\ntenderness（觸痛，醫學上常用）。",
  "sorrow": "諧音聯想：\n諧音：「搜弱」勢群體的過程充滿 sorrow，讓人看了感到無比悲傷。\n\n聯想畫面 1：經歷親人離世的 sorrow，他忍不住在房裡痛哭失聲。\n\n聯想畫面 2：這本小說的主角背負著巨大的 sorrow，情節非常悲傷感人。\n\n高效擴充：字根 sor 等同 sorrowful 的字源，表達內心痛苦與悲哀。\nKK 音標：[ˋsɑro] -> 第一音節 ˋsɑ 重讀，尾音 ro 輕柔上揚。\n\n常見同義字：\ngrief（極度悲傷、悲痛，通常指喪親之痛）\nsadness（悲傷、難過，最普遍日常的用字）\nmisery（悲慘、窮困與痛苦的綜合狀態）",
  "sorrowful": "諧音聯想：\n諧音：「撒若夫」妻離別，內心無比悲傷。\n\n聯想畫面 1：老爺爺在老伴的墓碑前流下眼淚，神情顯得無比悲痛。\n\n聯想畫面 2：聽到災區傳來親人失聯的消息，她忍不住發出令人心碎的哭聲。\n\n高效擴充：由 sorrow (悲傷) 加上 ful (充滿...) 組成，詩意或文學作品常用。\nKK 音標：[ˋsɑrofəl] -> 第一音節 sɑr 為主重音，開口呼要明顯。\n\n常見同義字：\nsad（悲傷的，最基礎且通用的詞彙）\ngrieving（悲痛的、悼念的，強調正在經歷失去的痛苦）\nmelancholy（憂鬱的、悲傷的，帶有文藝氣息的憂傷）",
  "sorry": "諧音聯想：\n諧音：「掃雷」，不小心踩到地雷覺得很抱歉。\n\n聯想畫面 1：踩錯了別人的腳，連忙說對不起並感到很尷尬。\n\n聯想畫面 2：考試考砸了，心中充滿遺憾與慚愧。\n\n高效擴充：常作為獨立感嘆詞使用，表達歉意或沒聽清楚請對方再說一次。\nKK 音標：[ˋsɑri] -> 第一音節 [ˋsɑ] 重音，發音要拉長且帶有歉意的語調。\n\n常見同義字：\n\nsad（難過的，指心情低落）\n\nsorrowful（悲傷的，較文學色彩的字眼）\n\ndistressed（苦惱的，強調內心受折磨）",
  "sort": "諧音聯想：\n諧音：「掃牠」\n\n聯想畫面 1：倉庫裡有太多雜物，管理員必須把各種物品分類並逐一掃牠（整理）清點。\n\n諧音 2：挑選出某一種特定品種的水果。\n\n高效擴充：字尾 -ort 的家族有 fort（堡壘）、port（港口）。\nKK 音標：[sɔrt] -> 發音為捲舌的 or 音，氣音飽滿。\n\n常見同義字：\n\nclassify（分類、歸類，較正式）\n\ncategory（種類、類別）\n\nkind（種類、親切的）",
  "sought": "諧音聯想：\n諧音：搜特\n\n聯想畫面 1：警察在森林裡搜特（sought）別兇手，找了整整三天三夜。\n\n聯想畫面 2：這款限量球鞋在市場上廣受歡迎，大家都在尋求（sought-after）購買機會。\n\n高效充：seek 的過去式，拼寫中 gh 不發音，注意與 fought（打架）的拼寫相似。\nKK 音標：[sɔt] -> 單音節，發音時嘴型圓潤，注意 o 的長音。\n\n常見同義字：\nsearched for（尋找，較口語）\npursued（追求，較正式）\nlooked for（尋找，最基礎用法）",
  "soul": "諧音聯想：\n諧音：「瘦喔」\n\n聯想畫面 1：減肥瘦下來之後，連靈魂跟心靈都覺得輕盈了起來。\n\n聯想畫面 2：外國人常說黑人靈魂樂充滿靈魂與激情，唱起歌來讓人瘦喔大喊好聽。\n\n高效擴充：字尾常與心靈、精神意象連結，與 body 肉體相對。\nKK 音標：[sol] -> 單音節短母音，嘴型開口小、發短促的 o 音。\n\n常見同義字：\n\nspirit（精神與靈魂，通常較具神聖或活力感）\nmind（心智與心思，偏向思考層面）\npsyche（心靈與心理，偏向心理學專業術語）",
  "sound": "諧音聯想：\n諧音：「三點」\n\n聯想畫面 1：下午三點鐘，聽到鬧鐘響起的聲音，讓人立刻清醒。\n\n聯想畫面 2：這棟房子的結構經過檢查，非常健康堅實，晚上三點有地震也很安全。\n\n高效擴充：字尾 -ound 與 round、ground 押韻，好背好記。\nKK 音標：[saʊnd] -> 雙母音 [aʊ]，發音由 a 滑向 u，鼻音 n 收尾。\n\n常見同義字：\n\nnoise（雜音或噪音，通常指不悅耳的聲音）\nhealthy（健康的，形容身體無損傷）\nreliable（可靠合理的，形容意見或結構堅實）",
  "soup": "諧音聯想：\n諧音：「速泡」\n\n聯想畫面 1：肚子餓時最快的方法就是去便利商店買一碗速泡的濃湯來喝。\n\n聯想畫面 2：改車族為了增加引擎的馬力，把車子搞得像熱湯一樣滾燙有動力。\n\n高效擴充：與 loop、group 押韻，注意 p 不發送氣音。\nKK 音標：[sup] -> 長母音 u，嘴型閉緊呈圓唇，尾音 p 輕輕閉合。\n\n常見同義字：\n\nbroth（肉湯或清湯，通常指熬煮過後的湯汁）\nvelouté（法式濃湯，較正式高檔）\nhorsepower（馬力，形容引擎動力）",
  "sour": "諧音聯想：\n諧音：「酸哦」\n\n聯想畫面 1：一口咬下未成熟的青檸檬，忍不住喊出酸哦的痛苦表情。\n\n聯想畫面 2：這罐牛奶放太久變餿變酸了，情侶之間的關係也跟著變糟。\n\n高效擴充：與 hour、flour 押韻，字尾 -our 發雙母音。\nKK 音標：[ˋsaʊɚ] -> 第一音節重音，[saʊ] 需拉長並往下掉，ɚ 捲舌收尾。\n\n常見同義字：\n\ntart（酸的，通常形容食物帶有清爽的酸味）\nacidic（酸性的，偏向化學或科學專業）\nspoil（變壞或腐敗，形容食物或關係變糟）",
  "source": "諧音聯想：\n諧音：「爽死」\n\n聯想畫面 1：爬山時找到冰涼山泉水的源頭，大口暢飲真是爽死人了。\n\n聯想畫面 2：寫論文時一定要詳細列出資料的出處與參考來源。\n\n高效擴充：與 sauce（醬汁）拼法極像，不要搞混；字尾 c 雖然不發音但決定了母音長度。\nKK 音標：[sɔrs] -> 捲舌音 or 加上清晰的 s 結尾。\n\n常見同義字：\n\norigin（起源、源頭）\n\nresource（資源，常以複數出現）\n\nreference（參考資料、出處）",
  "south": "諧音聯想：\n諧音：「掃墓」\n\n聯想畫面 1：每年清明節都要大老遠坐車往南部去掃墓。\n\n聯想畫面 2：大雁在冬天時會朝著溫暖的南方飛行，去過冬避寒。\n\n高效擴充：字尾 -outh 發輕聲摩擦音，與 mouth 嘴巴同字尾。\nKK 音標：[saʊθ] -> 雙音節核心 [saʊ]，尾音 [θ] 舌尖輕咬上下齒發輕氣音。\n\n常見同義字：\n\nsouthern（南方的，當形容詞時較常使用）\nequatorward（朝赤道方向，較正式或地理專用）\naustral（南方的，文學或天文較常出現）",
  "southern": "諧音聯想：\n諧音：「山神」住在台灣南部的高山裡。\n\n聯想畫面 1：暑假準備開車去墾丁，展開一段愉快的 southern 之旅。\n\n聯想畫面 2：這棟房子的 southern 陽台採光極佳，每天都有充足的陽光。\n\n高效擴充：由 south（南方）加上 ern 字尾形成方向形容詞。\nKK 音標：[ˋsʌðɚn] -> 重音在第一音節 sou，ʌ 發短音阿。\n\n常見同義字：\nsoutherly（向南的、南方的）\nmeridional（南方的、子午線的，較正式）\nsouthbound（往南開的、南下的）",
  "souvenir": "諧音聯想：\n諧音：「俗又味尼」\n\n聯想畫面 1：出國旅遊買的紀念品雖然看起來俗又味尼（俗氣又有當地風味），但很有紀念價值。\n\n聯想畫面 2：他把在巴黎買的艾菲爾鐵塔模型當作這次蜜月的紀念物擺在書桌上。\n\n高效擴充：源自法文，用來指幫助保留記憶的物品。\nKK 音標：[͵suvəˋnɪr] -> 主重音在最後一個音節 nɪr，前面的 suvə 發輕音。\n\n常見同義字：\nmemento（紀念物，強調觸景傷情或懷念）\nrelic（遺蹟、遺物，歷史悠久的東西）\nkeeepsake（留念物、紀念品，偏向親友贈送的小物）",
  "sovereign": "諧音聯想：\n諧音：「手握人」民權力與最高統治權的君主、國家元首。\n\n聯想畫面 1：古代國王坐在王座上，手握國家最高主權與統治大權。\n\n聯想畫面 2：台灣是一個擁有完全主權的民主獨立國家。\n\n高效擴充：拼寫較特別，注意中間有ign結尾。\nKK 音標：[ˋsɑvrən] -> 主重音在第一個音節 [sɑ]，字尾 [vrən] 念得輕快。\n\n常見同義字：\nautonomous（自治的、自主的）\nindependent（獨立的）\nsupreme（至高無上的、最高權力的）",
  "sovereignty": "諧音聯想：\n諧音：「掃富仁，提」\n\n聯想畫面 1：國家誓死捍衛主權，把外來富有的侵略仁人志士掃出去，提升國格。\n\n聯想畫面 2：外交部發表嚴正聲明，強調領土與統治權不容任何外來勢力干涉。\n\n高效擴充：字尾 -ty 形成抽象名詞，形容國家至高無上的統治權力。\nKK 音標：[ˋsɑvrənti] -> 主重音在 sav，v-r-n 之間發音要緊湊輕快。\n\n常見同義字：\n\nsupremacy（至高無上權力、霸權）\n\nautonomy（自治權、自主權）\n\nindependence（獨立、自主的國家地位）",
  "sow": "諧音聯想：\n諧音：「瘦」\n\n聯想畫面 1：農夫身材很瘦，但力氣很大，每天辛勤地在田裡播種。\n\n聯想畫面 2：母豬因為生了一窩小豬，體型變得有點瘦弱。\n\n高效擴充：注意此字雖然拼法短，但當動詞播種時發音同 so，當母豬時發音亦同。\nKK 音標：[so] -> 單音節字，母音為雙母音 o，嘴型由大圓收小。\n\n常見同義字：\nplant（種植，最常見的通用詞）\nscatter（撒播，指把種子散開）\nseed（播種，兼作動詞與名詞）",
  "soy": "諧音聯想：\n諧音：「手油」\n\n聯想畫面 1：吃水餃時不小心把醬油沾到手上，整隻手油膩膩的。\n\n聯想畫面 2：早上喝一杯香濃的豆漿（大豆製品）補充蛋白質。\n\n高效擴充：常組合成 soybean（大豆、黃豆）或 soy sauce（醬油）。\nKK 音標：[sɔɪ] -> 雙母音 oy 發音時嘴型由圓縮小向外咧開。\n\n常見同義字：\n\nsoybean（大豆、黃豆）\n\nsoy sauce（醬油）\n\ntofu（豆腐，源自中文的豆製品）",
  "soybean": "諧音聯想：\n諧音：「瘦冰」\n\n聯想畫面 1：早餐店老闆娘說喝無糖大豆黃豆漿最健康，能讓你瘦得像冰棒一樣窈窕。\n\n聯想畫面 2：炎炎夏日裡，大家喜歡把黃豆打成冰豆漿來解暑清涼。\n\n高效擴充：由 soy（大豆）加上 bean（豆子）複合而成，專指黃豆製品。\nKK 音標：[ˋsɔɪ͵bin] -> 第一音節重音在 soy，雙元音 ɔɪ 發飽滿，bin 輕短唸出。\n\n常見同義字：\nedamame（毛豆，通常指綠色鮮豆）\nbean（豆類，較廣泛的通稱）\nsoy milk（豆漿，由大豆製成的飲品）",
  "space": "諧音聯想：\n諧音：「死佩斯（太空人名字）」\n\n聯想畫面 1：死佩斯這位太空人搭乘火箭去探索無邊無際的外太空與空間。\n\n聯想畫面 2：打字時記得在兩個英文單字之間空一格、加個空格。\n\n高效擴充：字首 sp- 結合 ace（王牌），王牌在手、空間我有。\nKK 音標：[spes] -> 夾帶長母音 [e]，嘴型由扁平往兩側拉開。\n\n常見同義字：\n\nroom（房間或空間，日常生活中指可利用的空地）\narea（區域或面積，偏向平面範圍）\nuniverse（宇宙，專指整個星系空間）",
  "spacecraft": "諧音聯想：\n拆解/諧音：space（太空）加 craft（船隻/飛行器）\n\n諧音：「太空船卡費」在太空中航行的飛行器需要消耗龐大能量與費用。\n\n聯想畫面 1：巨大的載人太空船噴射出烈焰，緩緩從發射台升空。\n\n聯想畫面 2：科幻電影中，探測器降落在未知的火星表面進行採樣。\n\n高效擴充：craft 可指手工藝或飛行器，合起來就是航天器。\nKK 音標：[ˋspe͵skræft] -> 主重音在 [spe]，後面 [skræft] 短促有力。\n\n常見同義字：\nspaceship（太空船、宇宙飛船）\nsatellite（人造衛星）\nrocket（火箭）",
  "spaceship": "諧音聯想：\n拆解/諧音：space（太空）加 ship（船）\n\n諧音：「太空西普」科幻片中載著外星人的大型宇宙飛船。\n\n聯想畫面 1：外星人的圓形飛碟在夜空中高速飛行，發出耀眼的光芒。\n\n聯想畫面 2：太空人搭乘宇宙飛船準備返回地球。\n\n高效擴充：與 spacecraft 意思高度重疊，spaceship 更常出現在科幻小說中。\nKK 音標：[ˋspe͵sʃɪp] -> 主重音在第一個音節 [spe]，[sʃɪp] 連音念起。\n\n常見同義字：\nspacecraft（太空船、航天器）\nshuttle（太空梭）\nsatellite（衛星）",
  "spacious": "諧音聯想：\n諧音：「死胚死修」－修車廠空間太狹窄導致死胚子死不肯修，後來搬到一個超寬敞的新廠房。\n\n聯想畫面 1：租屋網看到一間客廳大到可以在裡面打羽球的房間，房東直誇這間客廳非常寬敞。\n\n聯想畫面 2：開車進入地下停車場，發現每個車位都超級寬敞，新手停車再也不用滿頭大汗。\n\n高效擴充：從 space（空間）衍生而來的形容詞，字尾 -cious 代表充滿...的，充滿空間的就是寬敞的。\nKK 音標：[ˋspeʃəs] -> 重音在第一音節 spe，唸長音的 A，後面 -cious 發成 shəs 的輕聲。\n\n常見同義字：\n\nroomy（空間大的，通常用於房間或車內空間）\n\nlarge（大的，範圍廣的，最基礎的通用詞）\n\nexpansive（廣闊的，強調向外擴展延伸的氣勢）",
  "spade": "諧音聯想：\n諧音：「死配得」一枝鏟子給園丁，這才配得上挖土的工作。\n\n聯想畫面 1：農夫拿著 spade 在菜園裡用力挖土種菜。\n\n聯想畫面 2：撲克牌裡的黑桃 spade 圖案就像是一支小鏟子。\n\n高效擴充：與 shovel 意義相近，但 spade 通常指扁平且金屬頭的鏟子。\nKK 音標：[sped] -> 雙重母音 e，發音時嘴型由開到閉，聲帶振動。\n\n常見同義字：\nshovel（鏟子、圓鍬，體積通常較大）\nexcavate（挖掘、開鑿，動詞用法）",
  "spaghetti": "諧音聯想：\n諧音：「死怕給踢」翻桌子，因為桌上那盤義大利麵條剛好被打翻了。\n\n聯想畫面 1：晚餐煮了一大盤香濃的 spaghetti 配肉醬。\n\n聯想畫面 2：用叉子把 spaghetti 捲成一團再放進嘴裡吃。\n\n高效擴充：源自義大利文，字尾的 tti 發音要輕快。\nKK 音標：[spəˋɡɛti] -> 重音落在第二音節 ˋɡɛ，前面 ə 發輕聲。\n\n常見同義字：\npasta（義大利麵食的總稱）\nnoodles（麵條的泛稱）",
  "spain": "諧音聯想：\n諧音：死拚。\n\n聯想畫面 1：西班牙鬥牛士在場上與公牛死拚，展現熱情。\n\n聯想畫面 2：去西班牙旅遊，一定要去馬德里看皇宮。\n\n高效擴充：Spain 是國家名，形容詞為 Spanish。\nKK 音標：[speɪn] -> 單音節，發音時注意 s 和 p 的連音。\n\n常見同義字：\n\nIberia（伊比利亞半島的代稱）\n\nMadrid（西班牙首都）。",
  "span": "諧音聯想：\n諧音：「死盤」\n\n聯想畫面 1：這個跨海大橋的橋墩跟橋墩之間的跨距很大，盤子死命撐住也不會垮。\n\n聯想畫面 2：這項歷史研究涵蓋了長達百年的時間跨度。\n\n高效擴充：發音短促有力，當動詞用時指「橫跨、持續」。\nKK 音標：[spæn] -> 嘴巴張大發短促的 æ 音，雙唇微開收尾。\n\n常見同義字：\n\nduration（持續時間、期間）\n\nbridge（橋樑，或當動詞指彌合差距）\n\nextend（延伸、擴大，強調長度的增加）",
  "spanking": "諧音聯想：\n諧音：死胖坑。\n\n聯想畫面 1：小屁孩掉進死胖坑裡，被媽媽抓出來打屁股處罰。\n\n聯想畫面 2：形容風很大時，說這風吹得 spanking new，感覺像被風拍打臉頰一樣清爽。\n\n高效擴充：spank 是打屁股，加上 ing 變成形容詞時，常形容強烈或全新的狀態。\nKK 音標：[ˋspæŋkɪŋ] -> 重音在第一個音節，發音時鼻音 spang 要飽滿。\n\n常見同義字：\n\nbeating（體罰）\n\nvigorous（強烈的）\n\nbrand-new（全新的）。",
  "spare": "諧音聯想：\n諧音：「死配爾」\n\n聯想畫面 1：死配爾（死配額）手機還有備用零件，多出來不用可以先存著。\n\n聯想畫面 2：車子爆胎時，從後車廂拿出一顆備用的輪胎來替換。\n\n高效擴充：字首 sp 代表向外散開，are 代表面積，延伸為有多餘空間或備品。\nKK 音標：[spɛr] -> 重音在 ɛr，嘴型張大念短促的「斯配兒」。\n\n常見同義字：\n\nextra（額外的，通常指多出來的物品）\n\nreserve（預備品，通常指預留的資源）\n\nbackup（備份，現代科技與資料常用詞）",
  "spark": "諧音聯想：\n諧音：「死趴客」\n\n聯想畫面 1：死趴客在派對中玩太瘋，結果打火機擦出火花引發火災。\n\n聯想畫面 2：靈感枯竭時，腦中突然閃過一個火花，觸發了全新的創業點子。\n\n高效擴充：字尾 rk 與 work 聯想，工作需要點子來引發熱情。\nKK 音標：[spɑrk] -> 重音在 ɑrk，發音時舌頭縮後，唇形微圓。\n\n常見同義字：\n\nflash（閃光，指短暫的光芒）\n\ntrigger（觸發，指引起某事的開端）\n\nglimmer（微光，指閃爍的光點）",
  "sparkle": "諧音聯想：\n諧音：「死趴客樂」\n\n聯想畫面 1：死趴客樂在其中，手上的鑽石戒指在燈光下不斷閃爍。\n\n聯想畫面 2：晴朗的湖面上，陽光照射波浪產生耀眼的光芒與神采。\n\n高效擴充：由 spark 加上表持續動作的字尾 le，變成持續閃耀。\nKK 音標：[ˋspɑrkəl] -> 主重音在第一音節 ˋspɑr，kəl 發輕聲。\n\n常見同義字：\n\nshine（發光，最普遍的光亮動詞）\n\ngleam（發微光，通常指黑暗中的亮光）\n\nshimmer（閃爍，指波光粼粼的閃耀）",
  "sparrow": "諧音聯想：\n諧音：「死怕囉」\n\n聯想畫面 1：死怕囉（死都不怕囉）的小麻雀，大膽地在路邊啄食麵包屑。\n\n聯想畫面 2：清晨窗外傳來麻雀吱喳叫的聲音，像是在催促主人起床。\n\n高效擴充：字尾 ow 常見於鳥類名詞，如 crow 烏鴉。\nKK 音標：[ˋspɛro] -> 主重音在第一音節 ˋspɛ，ro 發短促的歐音。\n\n常見同義字：\n\nbird（鳥，廣泛總稱）\n\nfinch（雀鳥，指特定小型鳥類）\n\nwarbler（鳴禽，指善鳴叫的小鳥）",
  "speak": "諧音聯想：\n諧音：「死屁」孩一直講個不停\n\n聯想畫面 1：隔壁的小孩像「死屁」孩一樣，在課堂上一直說話打擾大家。\n\n聯想畫面 2：演講者站上講台準備說話，跟大家分享他對於國際局勢的看法。\n\n高效擴充：sp 起音配合 eak，常指單向的演講或說某種語言的能力。\nKK 音標：[spik] -> ea 發長音 /i/，音節清晰，重音在唯一的母音上。\n\n常見同義字：\n\ntalk（交談、聊天，強調雙向溝通）\n\nsay（說出具體內容，後面常接說話內容）\n\naddress（向大眾致詞、發表演說，屬於正式用語）",
  "speaker": "諧音聯想：\n諧音：「死皮客」\n\n聯想畫面 1：演講者臉皮很厚，站在台上滔滔不絕講了三個小時都不會害羞。\n\n聯想畫面 2：客廳角落的藍牙喇叭正大聲播放著流行音樂，音質非常震撼。\n\n高效擴充：由 speak（說話）加上字尾 -er 形成，指「說話的人」或「會發聲的設備」。\nKK 音標：[ˋspikɚ] -> 重音在首音節 spi，sp 發音輕脆，kɚ 捲舌收尾。\n\n常見同義字：\nlecturer（演講者，多指學校講師）\nannouncer（播報員，廣播或活動主持人）\nloudspeaker（擴音器、喇叭，較完整的名稱）",
  "spear": "諧音聯想：\n諧音：「死皮兒」\n\n聯想畫面 1：原始人拿著長矛刺向獵物，把獵物身上的皮兒都戳破了。\n\n聯想畫面 2：古羅馬士兵手持標槍，整齊劃一地向前推進防守。\n\n高效擴充：字音與 ear 相近，長矛的前端就像尖尖的耳朵形狀。\nKK 音標：[spɪr] -> 重音在 ɪr，發音時由 i 滑向 r 音。\n\n常見同義字：\n\nlance（長矛，多指騎士用的長槍）\n\njavelin（標槍，指田徑運動用的投擲標槍）\n\nharpoon（魚叉，專門用來捕魚的尖器）",
  "special": "諧音聯想：\n諧音：「死陪修」，為了修好這台特別的機器，師傅死命陪伴修理。\n\n聯想畫面 1：餐廳裡推出一款特別的限量主廚特色菜。\n\n聯想畫面 2：百貨公司舉辦特別節目與特價商品促銷活動。\n\n高效擴充：字首 spe 聯想到 speak，把特別的事情說出來。\nKK 音標：[ˋspɛʃəl] -> 主重音在第一個音節 [ˋspɛ]，後面 [ʃəl] 輕聲唸出。\n\n常見同義字：\n\nexceptional（異常優秀的，高於一般水準）\n\nparticular（特定的、講究的，強調細節）\n\nunusual（不尋常的，指少見的情況）",
  "specialist": "諧音聯想：\n拆解/諧音：special（特別的、專門的）加 ist（人員）\n\n諧音：「死沛秀列死特」這個專科醫生特別厲害，能治好各種疑難雜症。\n\n聯想畫面 1：心臟科權威醫生穿著白袍，正耐心地向病人解釋病情。\n\n聯想畫面 2：公司請來了資安專家，幫忙檢測系統是否有漏洞。\n\n高效擴充：字尾 -ist 通常用來指稱某個領域的專家或從業人員。\nKK 音標：[ˋspɛʃələst] -> 主重音在第二個字母音節 [spɛ]，後面念成輕聲。\n\n常見同義字：\nexpert（專家，泛指各領域高手）\nprofessional（專業人士）\nauthority（權威人士）",
  "speciality": "諧音聯想：\n拆解：special（特別）+ ity（名詞字尾）。\n\n聯想畫面 1：這家餐廳的特色菜是烤鴨，大家都慕名而來。\n\n聯想畫面 2：我的專長是寫程式，這是我的強項。\n\n高效擴充：specialty 是美式拼法，speciality 是英式拼法。\nKK 音標：[͵speʃiˋæləti] -> 重音在第三音節，i 發長音 e。\n\n常見同義字：\n\nexpertise 專長，signature dish 招牌菜。",
  "specialize": "諧音聯想：\n諧音：「死八鞋來死」\n\n聯想畫面 1：專門研究死掉的八隻鞋子，專攻考古學。\n\n聯想畫面 2：醫生專門研究某個科別，專營特定領域。\n\n高效擴充：special (特別的) 加上 ize (化)，特別專注於某事即是專攻。\nKK 音標：[ˋspɛʃə͵laɪz] -> 第一音節重音，spe 發短音 e，cial 發 shul。\n\n常見同義字：\n\nfocus（聚焦或專注，泛指注意力集中）\n\nconcentrate（專心或集中，可用於精神或液體濃縮）\n\nexpertize（以專家身份處理，名詞轉動詞較少見）",
  "specialty": "諧音聯想：\n諧音：「是拍鞋，秀提」\n\n聯想畫面 1：鞋匠師傅拍拍他親手製作的皮鞋，這就是他開店的專業與特產。\n\n聯想畫面 2：醫生在醫學院選定了心臟外科作為自己的專長與研究領域。\n\n高效擴充：由 special (特別的) 衍生出來的名詞，專指拿手絕活或地方特產。\nKK 音標：[ˋspɛʃəlti] -> 主重音在 spe，字尾的 ty 唸輕快的 ti。\n\n常見同義字：\n\nspecialization（專業化、專攻領域）\n\nexpertise（專門技術、專業知識）\n\nsignature dish（招牌菜、拿手菜，常用於餐飲業）",
  "species": "諧音聯想：\n諧音：「死皮氣息」\n\n聯想畫面 1：不同物種的動物有著各自獨特的生存氣息與外貌。\n\n聯想畫面 2：生物學家在森林裡發現了全新種類的稀有植物物種。\n\n高效擴充：字根 spec 意為「看、種類」，與 specific 精確的同源。\nKK 音標：[ˋspiʃiz] -> 主重音在第一音節 ˋspi，ʃiz 唸輕快的「席茲」。\n\n常見同義字：\n\nkind（種類，口語常用的分類詞）\n\nsort（類別，指性質相似的一群）\n\ncategory（類別，指系統化的分類）",
  "specific": "拆解：speci（特別）＋fic（做出的）\n\n諧音：「特別飛去」\n\n聯想畫面 1：為了這個特定的目標，我們特別飛去現場查看細節。\n\n聯想畫面 2：請給我具體的說明，不要講得那麼籠統。\n\n高效擴充：與 special 同源，但 specific 強調「具體、明確、特定」。\nKK 音標：[spəˋsɪfɪk] -> 重音在第二音節的 ˋsɪ。\n\n常見同義字：\nparticular（特定的、挑剔的）\nconcrete（具體的、混凝土的）\nprecise（精確的、明確的）",
  "specification": "諧音聯想：\n拆解 / 諧音：「Specific（具體的）+ cation（名詞字尾）」\n\n聯想畫面 1：工程師拿著產品的 specification，上面詳細載明了所有零件的規格與尺寸。\n\n聯想畫面 2：購買電腦時，查看規格表，確認處理器與記憶體是否符合需求。\n\n高效擴充：由 specific 具體的轉變而來，指詳細的說明書或規範。\nKK 音標：[͵spɛsɪfɪˋkeʃən] -> 重音在第四音節 ke，發音要清晰。",
  "specify": "諧音聯想：\n諧音：「死陪死發一」\n\n聯想畫面 1：合約裡具體指定賠償金額，詳細指明條款。\n\n聯想畫面 2：明確指出規格，具體說明細節。\n\n高效擴充：字根 speci (種類、外觀) 加上 ify (使)，指明具體種類。\nKK 音標：[ˋspɛsə͵faɪ] -> 第一音節重音，spe 發短音 e，fy 發長音 i。\n\n常見同義字：\n\nstate（明確陳述，通常為書面或正式口頭）\n\nstipulate（規定或約定，法律契約常用）\n\ndesignate（指定或標出，常用於指派職務或位置）",
  "specimen": "諧音聯想：\n諧音：「死胚死門」生物實驗室裡保存著珍貴的動植物標本。\n\n聯想畫面 1：科學家將剛採集到的蝴蝶標本小心翼翼地釘在展示板上。\n\n聯想畫面 2：醫院護理師拿著試管，抽取病人的血液樣本去檢驗。\n\n高效擴充：字根 speci- 代表外觀或種類。\nKK 音標：[ˋspɛsəmən] -> 主重音在第一個音節 [spɛ]，後面為弱化母音。\n\n常見同義字：\nsample（樣本，商業或醫學常用）\npattern（樣品、模範）\nmodel（模型、範本）",
  "speck": "諧音聯想：\n諧音：死背克。\n\n聯想畫面 1：衣服上有一點點灰塵斑點，為了把它弄掉，我死背克（死命背著克制）著不讓自己生氣。\n\n聯想畫面 2：顯微鏡下，那微小的顆粒就是我們要找的病毒樣本。\n\n高效擴充：常用於形容極小的物體或汙點。\nKK 音標：[spek] -> 單音節字，發音短促有力。\n\n常見同義字：\n\nspot（斑點，較大）\n\nparticle（微粒，較科學）\n\nbit（一點點，較口語）。",
  "spectacle": "諧音聯想：\n諧音：「死八客口」看到驚人的奇觀，大家全都張大嘴巴說不出話。\n\n聯想畫面 1：尼加拉大瀑布奔騰而下的壯觀景象，讓人嘆為觀止。\n\n聯想畫面 2：跨年夜的璀璨煙火秀點亮夜空，是一場視覺的饗宴。\n\n高效擴充：字根 spect- 意指「看」，如 spectator（觀眾）。\nKK 音標：[ˋspɛktəkəl] -> 主重音在第一個音節 [spɛ]，字尾發輕短的 [əl] 音。\n\n常見同義字：\nsight（景象、視力）\nphenomenon（現象、奇觀）\ndisplay（展覽、陳列、表演）",
  "spectacular": "諧音聯想：\n諧音：「死背客，秋樓」\n\n聯想畫面 1：觀光客死背著旅遊攻略來到秋天的賞楓大樓，眼前景色真是壯觀得令人驚嘆。\n\n聯想畫面 2：跨年夜的煙火秀場面無比盛大，吸引全場觀眾驚呼連連。\n\n高效擴充：字根 spect 有「看」的意思，讓人看到目瞪口呆的視覺震撼。\nKK 音標：[spɛkˋtækjəlɚ] -> 主重音在 tack (tæ)，語調起伏大且具讚嘆感。\n\n常見同義字：\n\nmagnificent（宏偉的、壯麗的，常用於建築或自然風景）\n\nstunning（極為迷人的、令人震驚的美麗）\n\nbreathtaking（令人窒息的、美到讓人屏息的）",
  "spectator": "諧音聯想：\n諧音：「死胚客」在球場上「踏特兒」地大聲叫喊，原來他只是個不買票的免費旁觀者。\n\n聯想畫面 2：球場邊的觀眾席上，大批旁觀者正在看球賽，每個人都拿著望遠鏡狂看。\n\n高效擴充：字根 spect 代表看，加上代表人的 or，就是看的人也就是旁觀者。\nKK 音標：[ˋspɛktetɚ] -> 重音在第一音節 spe，唸時短促有力，teter 輕輕帶過。\n\n常見同義字：\nonlooker（旁觀者，通常指路過或隨性觀看的人）\nviewer（觀看者，多指電視或螢幕的觀眾）\naudience（觀眾，指聚集聽音樂會或戲劇的群眾）",
  "spectrum": "諧音聯想：\n諧音：「死背可全姆」，要死背化學實驗裡「光譜」上的全數光線波段與範圍。\n\n聯想畫面 1：物理課本翻開，彩色的光譜從紅到紫一目了然，範圍廣泛。\n\n聯想畫面 2：無線電波的頻譜圖上，各種波長高低起伏，涵蓋了所有的訊號幅度。\n\n高效擴充：字根 spect 意為看，rum 為名詞字尾，合起來就是「看得見的全貌與範圍」。\nKK 音標：[ˋspɛktrəm] -> 重音在第一音節 spe，唸短促的ㄝ，後面 trəm 輕輕帶過。\n\n常見同義字：\n\nrange（範圍，泛指各種變動的區間）\nscope（範圍，偏向活動或理解的權限與領域）\nband（頻帶，特指無線電或光譜中的特定波段）",
  "speculate": "諧音聯想：\n諧音：「死佩琪去累得」\n\n聯想畫面 1：佩琪亂猜股票走勢，推測投機搞得自己很累。\n\n聯想畫面 2：沒有證據只憑猜測與推斷來做決定。\n\n高效擴充：字根 spec (看) 引申為觀望、觀察市場後推測。\nKK 音標：[ˋspɛkjə͵let] -> 第一音節重音，spec 發短音 e，ate 發長音 a。\n\n常見同義字：\n\nguess（猜測，最口語普遍的用字）\n\nsuppose（假定或猜想，常表推測）\n\nhypothesize（假設，偏向學術或科學推論）",
  "speech": "諧音聯想：\n諧音：「死逼吃（上台壓力）」\n\n聯想畫面 1：上台發表公開演講跟言論時，緊張到快要死逼吃不下飯。\n\n聯想畫面 2：政治人物在台上的精采演說，贏得台下民眾的熱烈掌聲。\n\n高效擴充：由動詞 speak（說話）變化而來，字尾加 -ech 變成名詞。\nKK 音標：[spitʃ] -> 包含長母音 [i] 與尾音 [tʃ]，舌頭位置要靈活。\n\n常見同義字：\n\naddress（演說或致詞，通常指較正式的公開談話）\nlecture（講課或演講，偏向學術或教育性質）\noration（雄辯或正式演說，非常正式且莊嚴）",
  "speed": "諧音聯想：\n諧音：「死胚的」\n\n聯想畫面 1：高速公路上超速駕駛的車子像瘋了一樣飆過去，讓人忍不住罵一聲死胚的開這麼快。\n\n聯想畫面 2：打電動時切換到二檔加速，畫面瞬間變得非常流暢迅速。\n\n高效擴充：字首 sp 結合短母音 e，注意結尾是清脆的 d。\nKK 音標：[spid] -> 單音節字，sp 閉口氣音接著長音 i，d 輕輕咬舌收尾。\n\n常見同義字：\nvelocity（速度，物理學上的向量速度）\npace（步伐、節奏，跑步或做事的速度）\nrate（比率、速度，如 growth rate）",
  "spell": "諧音聯想：\n諧音：「死寶」貝拼錯字了\n\n聯想畫面 1：老師對著「死寶」貝無奈地笑，因為他又把簡單單字拼寫錯了。\n\n聯想畫面 2：巫師手握魔杖大聲唸出符咒，對著城堡施展強大的魔法咒語。\n\n高效擴充：雙寫 ll 結尾，既可指拼字，也可以指一段時間或魔咒。\nKK 音標：[spɛl] -> e 發短母音 /ɛ/，舌尖抵住上齒齦發出流暢的 l 音。\n\n常見同義字：\n\ncharm（符咒、魔咒，側重於吸引力或護身符）\n\nincantation（咒語，通常指念誦的神秘語言）\n\nstretch（一段時間，常用於描述持續的時間區段）",
  "spelling": "諧音聯想：\n諧音：「死賠零」\n\n聯想畫面 1：英文聽寫考試因為拼字錯太多，害全班分數死賠到只剩下零分。\n\n聯想畫面 2：老師在黑板上一字一句仔細拼寫出單字，教大家正確的拼法。\n\n高效擴充：由動詞 spell 加上 -ing 轉為名詞或現在分詞。\nKK 音標：[ˋspɛlɪŋ] -> 重音在首音節 spɛl，ɛ 短而有力，lɪŋ 鼻音輕收。\n\n常見同義字：\northography（正字法、拼字學，較正式或學術）\nword formation（字形結構，構詞法）\nwriting（書寫、文字記錄）",
  "spend": "諧音聯想：\n諧音：「死奔」波為了花錢\n\n聯想畫面 1：大家「死奔」波地加班賺錢，就是為了在假期好好花費金錢。\n\n聯想畫面 2：媽媽在沙灘上度過了一個美好的下午，覺得所有的時間消耗都很值得。\n\n高效擴充：過去式與過去分詞為 spent，主詞必須是人。\nKK 音標：[spɛnd] -> e 發短音 /ɛ/，字尾 nd 要完整唸出雙輔音。\n\n常見同義字：\n\nexpend（花費、消耗，比 spend 更正式）\n\nconsume（消耗、耗費資源或能量）\n\npass（度過時間，單純指時間流逝）",
  "spending": "諧音聯想：\n諧音：「死拼定」\n\n聯想畫面 1：為了雙十一特價，年輕人死命拼命一定要買，導致每個月的消費支出破表。\n\n聯想畫面 2：政府公布最新財政預算，大幅增加公共建設的支出與開銷。\n\n高效擴充：由動詞 spend（花費）轉變而來的動名詞。\nKK 音標：[ˋspɛndɪŋ] -> spɛn 重音，dɪŋ 輕聲結尾。\n\n常見同義字：\nexpenditure（支出、經費，通常較正式）\noutlay（經費開支、經費花費）\nconsumption（消費、消耗量）",
  "sphere": "諧音聯想：\n諧音：「死飛兒」，外星人駕駛著「球」形的幽浮在天空中死命飛著。\n\n聯想畫面 1：地球就是一個巨大的球體，完美的球形在宇宙中運轉。\n\n聯想畫面 2：他在政界與商界都擁有很大的影響範圍與社交圈子。\n\n高效擴充：字尾 ere 發長音 [ɪr]，常出現在形狀或幾何相關的單字中。\nKK 音標：[sfɪr] -> 單音節字，f 與 r 的子音連結，ɪr 發長伊爾的音。\n\n常見同義字：\n\nglobe（地球、球體，常指地理上的星球）\nball（球，偏向日常玩的圓球玩具）\nrealm（領域、範圍，抽象的勢力範圍）",
  "spice": "諧音聯想：\n諧音：「死派司」送貨員把整車的香料與調味料安全送到餐廳。\n\n聯想畫面 1：廚師在咖哩裡加入各種 spice 來增加食物的情趣與風味。\n\n聯想畫面 2：為平淡的生活加點 spice，讓日常變得不再乏味。\n\n高效擴充：形容詞形式為 spicy（辣的、辛辣的）。\nKK 音標：[spaɪs] -> 夾帶長母音 aɪ，尾音 s 清脆結尾。\n\n常見同義字：\nseasoning（調味料、佐料）\nflavor（風味、滋味）\nherb（香草、草本植物）",
  "spicy": "諧音聯想：\n諧音：「思敗細」微的辣味，原來是加了麻辣香料。\n\n聯想畫面 1：這碗四川麻辣燙又麻又辣，吃得大家直呼過癮。\n\n聯想畫面 2：泰式酸辣湯充滿各種刺激味蕾的香料，十分開胃。\n\n高效擴充：由 spice (香料、辣味) 加上 y 轉為形容詞。\nKK 音標：[ˋspaɪsi] -> 第一音節 spaɪ 為主重音，發 ai 的雙母音。\n\n常見同義字：\nhot（辣的、熱的，口語中最常使用的辣味形容詞）\npeppery（胡椒味的、辛辣的，形容帶有辛辣刺激感）\npungent（刺激性的、辛辣刺鼻的，常形容氣味或味道強烈）",
  "spider": "諧音聯想：\n諧音：「死拍牠」\n\n聯想畫面 1：牆壁上突然出現一隻大蜘蛛，嚇得我拿蒼蠅拍大喊快點死拍牠。\n\n聯想畫面 2：電腦裡的爬蟲程式正在網路上快速搜尋資料，像蜘蛛結網一樣遍布各個網站。\n\n高效擴充：結合 sp 聲母與字尾 -der，注意與 spear 等字區分。\nKK 音標：[ˋspaɪdɚ] -> 重音在首音節 spaɪ，雙元音 aɪ 要拉長，dɚ 輕念。\n\n常見同義字：\ntarantula（狼蛛、捕鳥蛛，大型毛蜘蛛）\nweb crawler（網路爬蟲，資訊工程用語）\narachnid（蛛形綱動物，生物學統稱）",
  "spike": "諧音聯想：\n諧音：「死拍客」，攝影師瘋狂搶拍明星緋聞，導致八卦新聞點閱率「猛增」。\n\n聯想畫面 1：跑道上的釘鞋帶有尖狀的金屬釘，抓地力極強。\n\n聯想畫面 2：氣溫在午後突然急升，曲線圖上出現了一個尖銳的高峰。\n\n高效擴充：字尾 ike 發長 ai 的音，與 bike、like 同韻。\nKK 音標：[spaɪk] -> 單音節字，sp 連音後接長 ai，最後閉口 k。\n\n常見同義字：\n\nsurge（急升、激增，強調數量或數據的暴漲）\npeak（頂峰、尖峰，指最高點或最高狀態）\nnail（釘子，偏向普通的鐵釘工具）",
  "spill": "諧音聯想：\n諧音：「死破漏」水管，導致滿地都是灑出的水。\n\n聯想畫面 1：不小心把咖啡 spill 在白色的桌布上。\n\n聯想畫面 2：機車過彎時不慎摔車 spill 倒在地上。\n\n高效擴充：成語 spill the beans 意指洩漏祕密。\nKK 音標：[spɪl] -> 短音 ɪ，發音短促，l 音舌尖抵住上齒齦。\n\n常見同義字：\npour（傾倒、湧出，通常為有意識的動作）\noverflow（溢出、滿出來）\ndrop（滴落、落下）",
  "spin": "諧音聯想：\n諧音：「死拼」旋轉陀螺，看誰轉得最久。\n\n聯想畫面 1：舞者在舞台上高速 spin 旋轉好幾圈。\n\n聯想畫面 2：週末開車去兜風 spin 一圈放鬆心情。\n\n高效擴充：過去分詞為 spun，衍生詞 spinner 指指尖陀螺。\nKK 音標：[spɪn] -> 短音 ɪ，鼻音 n 收尾，發音俐落。\n\n常見同義字：\nrotate（旋轉、自轉，較科學正式）\nturn（轉動、轉彎，最基礎用字）\nrevolve（公轉、環繞）",
  "spinach": "諧音聯想：\n諧音：「死拚哪去」\n\n聯想畫面 1：大力水手卜派吃了滿罐菠菜後力大無窮，大喊著看我要死拚哪去都行。\n\n聯想畫面 2：營養師提醒雖然這盤蔬菜未必很有趣，但對身體健康非常有益。\n\n高效擴充：結尾是 -nach，發音為 [nətʃ]，容易拼錯注意字尾變化。\nKK 音標：[ˋspɪnətʃ] -> 重音在首音節 spɪ，nətʃ 輕快發出。\n\n常見同義字：\ngreens（綠葉蔬菜的統稱）\nkale（羽衣甘藍，近年流行的超級食物）\nvegetable（蔬菜，廣泛泛稱）",
  "spine": "諧音聯想：\n諧音：黑道老大「死派嗯」一聲，氣得手下直發抖，連站直的骨氣與脊柱都軟了。\n\n聯想畫面 2：醫生拿著一張脊椎Ｘ光片，指著書脊般的背部曲線對病人解說脊柱結構。\n\n高效擴充：字尾 ine 發長 i 音，同類字有 wine、mine，很好拼寫。\nKK 音標：[spaɪn] -> 雙母音 ai 發長音，唸的時候嘴巴由大變小，spine。\n\n常見同義字：\nbackbone（脊椎，也引申為骨氣、堅強性格）\nspinal column（醫學專用詞彙，指脊柱）\nridge（山脊，地形上的脊狀物）",
  "spinster": "諧音聯想：\n諧音：死拼死得。\n\n聯想畫面 1：老姑娘為了守住舊時代的矜持，死命拼命地守著單身，最後死得孤單。\n\n聯想畫面 2：以前紡紗女 spinster 坐在窗邊紡紗，因為太專注工作而錯過姻緣。\n\n高效擴充：字根 spin 是紡紗，ster 是人，合起來就是紡紗的人。\nKK 音標：[ˋspɪnstər] -> 重音在第一音節，spin 發音要短促有力。\n\n常見同義字：\n\nsingle（泛指單身，中性詞）\n\nunmarried（未婚的，客觀描述）\n\nold maid（老處女，極具貶義）。",
  "spiral": "諧音聯想：\n諧音：「死拍肉」，市場攤販用機器把整塊肉切成「螺旋形」的造型。\n\n聯想畫面 1：蚊香燃燒的灰燼呈現完美的螺旋形，緩慢地向下推進。\n\n聯想畫面 2：經濟危機導致物價失控，陷入不斷惡化的惡性螺旋式上升。\n\n高效擴充：字根 spir 代表呼吸或旋轉延伸，常用於形容盤旋上升的動態。\nKK 音標：[ˋspaɪrəl] -> 重音在第一音節 spi，發長 ai 音，後面的 ral 輕念。\n\n常見同義字：\n\nhelix（螺旋，常指生物學上的DNA雙螺旋結構）\ncoil（線圈、盤繞，指一圈圈纏繞的繩索或電線）\ntwist（扭曲、旋轉，泛指轉動的動作）",
  "spire": "諧音聯想：\n諧音：「死拍兒」，觀光客冒險爬到教堂的「尖塔」頂端拍照。\n\n聯想畫面 1：古老歐洲教堂的尖頂直插雲霄，像是一根巨大的針指向天空。\n\n聯想畫面 2：山峰的最高處像尖塔般向上聳立，氣勢十分雄偉。\n\n高效擴充：與 spike 拼字相似，去掉 k 留下發長 ai 音的 spire。\nKK 音標：[spaɪr] -> 單音節字，sp 結合長 ai 加上 r 的捲舌尾音。\n\n常見同義字：\n\nsteeples（尖塔，特指教堂上帶有塔尖的高塔）\npeak（山峰、頂點，泛指高山的最高處）\ntower（塔樓，泛指高聳的建築物）",
  "spirit": "諧音聯想：\n諧音：「死胚立體」\n\n聯想畫面 1：團隊比賽時展現出不屈不撓的精神與強大心靈，把死氣沉沉的氣氛變得立體有活力。\n\n聯想畫面 2：鬼故事裡提到靈魂被偷偷帶走、秘密弄走的靈異現象。\n\n高效擴充：字根 spir 代表呼吸、生命力，如 inspire（激勵）。\nKK 音標：[ˋspɪrət] -> 重音在首音節 spɪ，rət 念成輕短的中央母音。\n\n常見同義字：\nsoul（靈魂，較偏向宗教或內在核心）\nmorale（士氣、鬥志，團體的心境情緒）\nghost（鬼魂、幽靈）",
  "spiritual": "諧音聯想：\n諧音：「死皮力秋」天修練，提升心靈層次。\n\n聯想畫面 1：瑜珈老師帶領大家進行冥想，追求內心平靜與精神的昇華。\n\n聯想畫面 2：這座古老的廟宇是當地居民重要的宗教信仰中心。\n\n高效擴充：字根 spirit (精神、靈魂) 加上形容詞字尾 ual。\nKK 音標：[ˋspɪrɪ͵tʃuəl] -> 第一音節 spɪr 為主重音，第四音節 tʃu 為次重音。\n\n常見同義字：\nmental（精神的、心理的，多指腦力或心理活動）\nimmaterial（非物質的、精神的，強調無形的特質）\nsacred（神聖的、宗教的，強調受到神明庇佑或崇敬）",
  "spit": "諧音聯想：\n諧音：「死屁」孩亂吐口水，被大人當場怒斥。\n\n聯想畫面 1：吃到難吃的東西立刻把食物 spit 吐出來。\n\n聯想畫面 2：火爐裡的木炭突然 spit 爆出火花。\n\n高效擴充：過去式與過去分詞多為 spat 或 spit。\nKK 音標：[spɪt] -> 短音 i，最後的 t 輕短爆破。\n\n常見同義字：\nexpectorate（吐痰、咳出，較醫學正式）\nvomit（嘔吐）\nsaliva（唾液、口水，為名詞原形）",
  "spite": "諧音聯想：\n諧音：「死派特」懷恨在心，出於惡意故意刁難同事。\n\n聯想畫面 1：他純粹是出於 spite 而故意把檔案刪除。\n\n聯想畫面 2：不顧 spite 的刁難，她依然完成任務。\n\n高效擴充：常組成片語 in spite of（儘管、不顧）。\nKK 音標：[spaɪt] -> 長母音 aɪ，結尾 t 輕輕收音。\n\n常見同義字：\nmalice（惡意、怨恨，較正式）\nill will（敵意、壞心眼）\nresentment（憤恨、怨恨）",
  "splash": "諧音聯想：\n諧音：「死布萊許」踩進水坑，水花四濺噴得到處都是。\n\n聯想畫面 1：小孩在泳池裡玩水，splash 水花濺濕旁人。\n\n聯想畫面 2：海浪拍打礁石發出巨大的 splash 濺落聲。\n\n高效擴充：動詞與名詞同形，常形容水花四濺的動態。\nKK 音標：[splæʃ] -> 結合 spl 與 æ 音，尾音 sh 氣音綿長。\n\n常見同義字：\nsplash out（揮霍金錢，口語用法）\nsplatter（散濺、潑灑）\nsprinkle（灑、噴灑）",
  "splendid": "諧音聯想：\n諧音：「死怕爛弟」表現不佳，這場煙火秀卻燦爛得令人驚嘆。\n\n聯想畫面 1：跨年夜的煙火在夜空中綻放，景色極為燦爛奪目。\n\n聯想畫面 2：他這次提出的企劃案非常優秀，獲得老闆的大力稱讚。\n\n高效擴充：字首 spl 往往給人鋪開、散開的視覺聯想，如 splash (濺水)。\nKK 音標：[ˋsplɛndɪd] -> 第一音節 splɛn 為主重音，短促有力。\n\n常見同義字：\nmagnificent（壯麗的、宏偉的，形容規模巨大且華麗）\nbrilliant（燦爛的、傑出的，形容光芒耀眼或才華洋溢）\nsuperb（極佳的、卓越的，最高品質的讚賞）",
  "splendor": "諧音聯想：\n諧音：「死怕冷得」皇宮裡點滿了金黃色的燈火，散發出無與倫比的光輝與壯麗。\n\n聯想畫面 2：走進歐洲古堡，滿牆的黃金雕刻與水晶吊燈，呈現出一派富麗堂皇的輝煌景象。\n\n高效擴充：字尾 dor 表名詞狀態，形容 dazzling 的華麗與光彩。\nKK 音標：[ˋsplɛndɚ] -> 重音在第一音節 splen，注意 sp 連音要輕快。\n\n常見同義字：\nmagnificence（壯麗，強調宏偉與美觀）\nbrilliance（光輝，強調耀眼的光芒與聰穎）\nglory（榮耀與壯觀，多用於歷史或讚美）",
  "splintered": "諧音聯想：\n諧音：死（splin）破（ter）了。\n\n聯想畫面 1：木頭被撞擊後裂成碎片，死破了。\n\n聯想畫面 2：原本團結的團隊因為意見不合而分裂，四分五裂。\n\n高效擴充：splint 是夾板，splinter 是碎片，形容分裂狀態。\nKK 音標：[ˋsplɪntɚd] -> 重音在第一音節，注意 sp 的連音。",
  "split": "諧音聯想：\n諧音：「死剝它」\n\n聯想畫面 1：大家意見不合導致團隊分裂，每個人都想死剝它的一塊利益。\n\n聯想畫面 2：木材中央出現了一道長長的裂縫，最後硬生生斷成了兩半。\n\n高效擴充：短母音 i 發音短促有力，象徵快速切開的動作。\nKK 音標：[splɪt] -> 重音在 ɪt，唇形扁平，發急促短音。\n\n常見同義字：\n\ndivide（分開，指將整體分成多份）\n\nseparate（分離，指拉開距離）\n\ncrack（破裂，指表面產生裂紋）",
  "spluttered": "諧音聯想：\n諧音：死不拉得。\n\n聯想畫面 1：引擎發出死不拉得的聲音，最後噴出一陣黑煙，氣急敗壞的司機結結巴巴地抱怨。\n\n聯想畫面 2：他因為太緊張，說話時口水都噴出來了，結結巴巴地解釋。\n\n高效擴充：spl- 開頭常與噴濺或爆裂聲有關，如 splash。\nKK 音標：[ˋsplʌtərd] -> 重音在第一個音節，發音時要有噴氣的感覺。\n\n常見同義字：\n\nstuttered（結巴）\n\nspat（噴出）\n\nsputtered（噴濺）。",
  "spoil": "諧音聯想：\n諧音：「死破壞」\n\n聯想畫面 1：爺爺奶奶太過寵壞小孩，把規矩全都破壞掉了。\n\n聯想畫面 2：夏天室溫太高，桌上的鮮奶沒冰結果壞掉了、餿掉了。\n\n高效擴充：常考片語 spoil one's appetite（破壞食欲）或 spoil a child（溺愛孩子）。\nKK 音標：[spɔɪl] -> 雙母音 oi 發「歐伊」，發音時嘴型由大變小。\n\n常見同義字：\n\nruin（徹底毀壞、毀掉）\n\ndamage（造成損害、受損）\n\n pamper（縱容、寵愛，通常指正面或負面的溺愛）",
  "spokesman": "諧音聯想：\n拆解 / 諧音：spoke（發言/speak的過去式） + sman（男人）\n\n諧音：「說破死男人」，男「發言人」站上台把內幕一次說破。\n\n聯想畫面 1：公司召開記者會，男發言人嚴肅地向媒體說明最新危機處理方案。\n\n聯想畫面 2：政府的官方發言人拿著麥克風，對外傳達最新的政策方針。\n\n高效擴充：由 speak 的過去式 spoke 加上代表人的 man 組合成發言人。\nKK 音標：[ˋspoksmən] -> 重音在第一音節 spoke，後面 smən 輕唸。\n\n常見同義字：\n\nspokesperson（發言人，中性的無性別稱呼）\nrepresentative（代表，泛指代表某個團體或機構的人）\nambassador（大使、使節，國家級的正式代表）",
  "spokesperson": "諧音聯想：\n拆解 / 諧音：spoke（發言） + person（人）\n\n諧音：「說破死怕生」，「發言人」面對鏡頭毫不怯場，把真相一次說破。\n\n聯想畫面 1：品牌邀請了一位知名的藝人擔任環保活動的代言人。\n\n聯想畫面 2：企業發言人冷靜地回答記者的尖銳提問，展現專業素養。\n\n高效擴充：結合 spoke 與 person，是現代最常見且兼顧性別平等的職稱。\nKK 音標：[ˋspokspɚsən] -> 重音在第一音節 spoke，第二音節 pɚ 也有次重音。\n\n常見同義字：\n\nspokesman（男發言人，限指男性）\nspokeswoman（女發言人，限指女性）\nadvocate（擁護者、提倡者，偏向理念的宣傳者）",
  "spokeswoman": "諧音聯想：\n拆解 / 諧音：spoke（發言） + woman（女人）\n\n諧音：「說破死誤曼」，女「發言人」條理分明地指正媒體的錯誤傳聞。\n\n聯想畫面 1：跨國科技公司的女發言人站在台上發表新品發表會的開場白。\n\n聯想畫面 2：外交部的女發言人針對國際爭端發表嚴正聲明。\n\n高效擴充：由 spoke 與 woman 組成，專門用來指稱女性的發言代表。\nKK 音標：[ˋspok͵swʊmən] -> 重音在第一音節 spoke，第二音節 swʊmən 輕唸。\n\n常見同義字：\n\nspokesperson（發言人，不分性別的通用稱呼）\nrepresentative（代表，泛指各行業的發言代表）\npromoter（推廣者、贊助者，偏向商業宣傳）",
  "sponge": "諧音聯想：\n諧音：「死胖橘」貓咪一屁股坐在廚房海綿上，把整塊海綿壓得扁扁的。\n\n聯想畫面 2：朋友厚著臉皮來家裡蹭飯吃，像個海綿一樣到處揩油、白吃白喝。\n\n高效擴充：結合發音記憶，p-o-n-g-e 的拼法十分特殊，注意唸法中帶有鼻音。\nKK 音標：[spʌndʒ] -> 短元音 ʌ 發短阿聲，結尾 dʒ 擦音要俐落。\n\n常見同義字：\nfreeloader（白吃白喝者、靠他人接濟的人）\nscrounger（揩油者、四處搜羅好處的人）\nabsorbent pad（吸水墊，功能類似海綿）",
  "spongy": "諧音聯想：\n諧音： sponge（海綿）+ y。\n\n聯想畫面 1：踩在沼澤地上，感覺軟綿綿的，像 spongy 的海綿。\n\n聯想畫面 2：這塊蛋糕烤得太鬆軟，口感 spongy，非常好吃。\n\n高效擴充：形容像海綿一樣多孔且有彈性。\nKK 音標：[ˋspʌndʒi] -> 重音在第一音節，gi 發輕音。\n\n常見同義字：\n\nsoft（柔軟的）\n\nporous（多孔的）。",
  "sponsor": "諧音聯想：\n諧音：「死盼索」，活動主辦方「死命期盼」企業「贊助」資金來解燃眉之急。\n\n聯想畫面 1：馬拉松選手的球衣胸前印著大大的贊助商標誌。\n\n聯想畫面 2：大型音樂祭獲得了知名飲料品牌的慷慨資助。\n\n高效擴充：字根 spon 意為承諾或保證，贊助商就是承諾給予資源的人。\nKK 音標：[ˋspɑnsɚ] -> 重音在第一音節 spɑn，發短ㄚ音，後面的 sɚ 捲舌。\n\n常見同義字：\n\npatron（贊助人、老主顧，常指對藝術或慈善的資助者）\nback-er（支持者、金主，口語常用來指資助計畫的人）\nfinancier（金融家、出資者，偏向大筆資本的提供者）",
  "sponsorship": "諧音聯想：\n拆解 / 諧音：「Sponsor（贊助者）+ ship（身分/關係）」\n\n聯想畫面 1：運動員背心上的品牌 Logo，就是 sponsorship 的最佳證明，代表企業的資助。\n\n聯想畫面 2：舉辦大型演唱會時，感謝所有提供 sponsorship 的贊助商。\n\n高效擴充：sponsor 是贊助者，加上 ship 變成贊助關係或贊助金。\nKK 音標：[ˋspɑnsɚ͵ʃɪp] -> 重音在第一音節，ship 發音要輕。",
  "spontaneous": "諧音聯想：\n諧音：「死旁貪唸死」－旁邊的人死都不肯唸稿，只好靠自己上台做一場完全自發、自然的即興演說。\n\n聯想畫面 1：週末走在街頭遇到快閃舞蹈，大家毫無預警地自發性跟著音樂一起跳舞。\n\n聯想畫面 2：朋友聚會時突然有人提議去海邊看日出，這種說走就走的行為非常自發且自然。\n\n高效擴充：字首 sp- 代表向外噴發，源自拉丁文的自願，指不經外力強迫、自然發生的行為。\nKK 音標：[spɑnˋteniəs] -> 重音落在第三音節 te，唸長音的 E，注意前兩個音節要輕快帶過。\n\n常見同義字：\n\nautomatic（自動的，強調像機器般不需思考）\n\nimpulsive（衝動的，強調一時興起不受控制）\n\ninstinctive（本能的，強調天生自然的反應）",
  "spoon": "諧音聯想：\n諧音：「死盆」\n\n聯想畫面 1：煮了一大盆湯，結果裡面竟然掉進去一隻死盆... 不對，是一隻湯匙啦。\n\n聯想畫面 2：用大湯匙把美味的咖哩一匙一匙舀進盤子裡。\n\n高效擴充：與 moon、noon 押韻，雙 o 發長音。\nKK 音標：[spun] -> 閉口音 [p] 緊接著長音 [u]，音調短促有力。\n\n常見同義字：\n\nladle（大湯勺，專門用來舀湯或羹的器具）\nscoop（勺子或冰淇淋杓，偏向圓球狀的挖勺）\ntableware（餐具總稱，包含湯匙與刀叉）",
  "sport": "諧音聯想：\n諧音：「死跑特」\n\n聯想畫面 1：上體育課時就是要在操場上死命跑步特訓，鍛鍊體能。\n\n聯想畫面 2：週末和朋友一起去戶外從事野外運動與球類競賽。\n\n高效擴充：源自 disport（消遣、娛樂），字首 sp- 加上 port（港口/搬運）。\nKK 音標：[spɔrt] -> 捲舌音 [ɔr]，嘴唇微圓，發音渾厚。\n\n常見同義字：\n\ngame（比賽或遊戲，偏向規則性的競技活動）\nathletics（田徑運動，泛指體育競技項目）\npastime（消遣或娛樂，指休閒活動）",
  "sportsman": "諧音聯想：\n諧音：「死跑死門」\n\n聯想畫面 1：運動員為了奪牌天天苦練，跑到快死在球場大門口。\n\n聯想畫面 2：這位有風度的運動家在賽後主動與對手握手致意。\n\n高效擴充：由 sport（運動）加上 man（男人/人才）組合而成。\nKK 音標：[ˋspɔrtsmən] -> 主重音在第一音節 ˋspɔrts，mən 弱化為輕聲。\n\n常見同義字：\n\nathlete（運動員，泛指專業競技選手）\n\nplayer（選手，指球類比賽參與者）\n\ncompetitor（競爭者，指賽場上的對手）",
  "sportsmanship": "諧音聯想：\n諧音：「死跑死門習普」\n\n聯想畫面 1：教練嚴格訓練選手的運動員精神，要求大家學習普及風度。\n\n聯想畫面 2：勝不驕敗不餒的態度，正是最高貴的體育精神展現。\n\n高效擴充：由 sportsman 再加上字尾 ship（表身分或精神狀態）。\nKK 音標：[ˋspɔrtsmən͵ʃɪp] -> 主重音在 ˋspɔrts，次重音在 ͵ʃɪp。\n\n常見同義字：\n\nfair play（公平競技，最常見的運動道德代稱）\n\nethics（倫理道德，指行為規範）\n\ncode of conduct（行為準則，正式規範）",
  "sportswoman": "諧音聯想：\n諧音：「死跑死烏曼」\n\n聯想畫面 1：女運動員在跑道上全力衝刺，汗水如雨下把衣服都弄濕了。\n\n聯想畫面 2：這位傑出的女運動家打破了全國女子馬拉松的紀錄。\n\n高效擴充：將 sportsman 的 man 替換為 woman 即可變成女性職稱。\nKK 音標：[ˋspɔrts͵wʊmən] -> 主重音在 ˋspɔrts，͵wʊmən 唸法類似「烏曼」。\n\n常見同義字：\n\nfemale athlete（女性運動員，最精確的描述詞）\n\nSporty girl（陽光女孩，口語常用）\n\npioneering woman（先驅女性，形容具開創性的女將）",
  "spot": "諧音聯想：\n諧音：「死趴得」\n\n聯想畫面 1：警察在某個犯罪地點的斑點血跡處，眼尖地一眼注意到嫌疑犯的蹤跡。\n\n聯想畫面 2：這家網美打卡場所太漂亮了，讓大家一到現場就忍不住死趴在地上拍照。\n\n高效擴充：短母音 o 發短促的 [ɑ]，過去分詞雙寫 t 變 spotted。\nKK 音標：[spɑt] -> 單音節短促有力，sp 接著開口向上的 ɑ，t 輕輕止音。\n\n常見同義字：\nlocation（地點、位置，較正式）\nsite（網站或特定場所）\nnotice（注意到、發現，當動詞用）",
  "spotlight": "諧音聯想：\n拆解 / 諧音：spot 斑點 + light 燈光\n\n諧音：舞台上打下一個圓圓的「spot」斑點燈光，把全場焦點聚光在歌手身上。\n\n聯想畫面 2：明星一出機場就被媒體與公眾的注意包圍，成為鎂光燈焦點。\n\n高效擴充：合成字 spot 加 light，字面直譯就是斑點燈也就是聚光燈。\nKK 音標：[ˋspɑt͵laɪt] -> 複合字，第一個音節 spot 重音，light 次重音。\n\n常見同義字：\nlimelight（鎂光燈、公眾注意的中心）\npublicity（宣傳、公眾知名度）\nfocus（焦點、集中點）",
  "spotty": "諧音聯想：\n諧音：死八弟。\n\n聯想畫面 1：這傢伙臉上長滿了青春痘，看起來 spotty 的，被朋友戲稱是死八弟。\n\n聯想畫面 2：這家餐廳的服務品質很 spotty，有時候很好，有時候卻爛到不行。\n\n高效擴充：源自 spot（斑點），加上 y 變成形容詞。\nKK 音標：[ˋpɑti] -> 重音在第一個音節，t 的發音要輕快。\n\n常見同義字：\n\nuneven（不平坦或不穩定的）\n\nirregular（不規則的）\n\npatchy（零散的，品質不一的）。",
  "spouse": "諧音聯想：\n諧音：「死怕死」，夫妻倆感情好到「死都不怕死」，這就是最佳的「配偶」寫照。\n\n聯想畫面 1：結婚證書上雙方簽下了名字，正式成為法律上的合法配偶。\n\n聯想畫面 2：海外旅遊申請簽證時，需要填寫配偶的姓名與聯絡電話。\n\n高效擴充：包含男女雙方，是一個性別中立的法律婚姻用語。\nKK 音標：[spaʊs] -> 單音節字，sp 結合 au 發「奧」的雙母音，結尾發 s 清音。\n\n常見同義字：\n\nhusband（丈夫，專指男配偶）\nwife（妻子，專指女配偶）\nmate（夥伴、伴侶，動物或人類的結伴對象）",
  "sprain": "諧音聯想：\n諧音：「死普林」彈簧跳太高，落地時不小心扭傷腳踝。\n\n聯想畫面 1：打籃球時落地沒踩好，導致腳踝 sprain 扭傷。\n\n聯想畫面 2：手腕因為搬重物不小心 sprain 痛得貼藥布。\n\n高效擴充：常搭配 ankle（腳踝）或 wrist（手腕）使用。\nKK 音標：[spren] -> 複合母音 e，發音時嘴角拉開。\n\n常見同義字：\ntwist（扭轉、扭傷，範圍較廣）\nstrain（拉傷、過度勞損）",
  "sprawl": "諧音聯想：\n諧音：「死破樓」周遭的違章建築不斷向外擴建，把市容搞得雜亂無章。\n\n聯想畫面 1: 逛街逛累了，他直接四肢攤開地癱坐在沙發上休息。\n\n聯想畫面 2: 城市周邊的無限制蔓延造成了嚴重的交通與環境負擔。\n\n高效擴充: 字尾 awl 發 [ɔl] 音，與 crawl、draw 同韻，聯想向下延伸或攤開。\nKK 音標: [sprɔl] -> 單音節字，spr 連音後接長 o 的 ɔl 音。\n\n常見同義字：\n\nstretch out（伸展、攤開身體，通常指躺著或坐得很放鬆）\nlounge（慵懶地躺或坐，偏向休閒放鬆的姿態）\nextend（延伸、擴大，偏向長度或範圍的增加）",
  "spray": "諧音聯想：\n諧音：「死盆蕾」澆花，直接拿起水管用噴霧器噴灑。\n\n聯想畫面 1：出門前在身上噴香水 spray。\n\n聯想畫面 2：拿殺蟲劑 spray 蚊蟲。\n\n高效擴充：可作名詞的噴霧與動詞的噴灑。\nKK 音標：[spre] -> 長母音 e，尾音 y 不發子音音效。\n\n常見同義字：\natomize（霧化）\nsprinkle（撒、灑）\nsplash（濺濕）",
  "spread": "諧音聯想：\n諧音：「死怕累的」\n\n聯想畫面 1：媽媽準備了草莓果醬讓小孩塗抹在吐司上，小心翼翼地把果醬均勻展開。\n\n聯想畫面 2：流感病毒在辦公室迅速蔓延擴散，大家都死怕累的被傳染到。\n\n高效擴充：三態變化特殊：spread - spread - spread（拼法不變）。\nKK 音標：[sprɛd] -> 單音節，spr 連音順暢，ɛ 短促，d 結尾。\n\n常見同義字：\nscatter（散開、撒開，通常指零散物件）\nextend（延伸、擴大，較抽象或空間範圍）\ndiffuse（擴散、彌漫，氣體或光線常用）",
  "spring": "諧音聯想：\n諧音：「死噴硬」\n\n聯想畫面 1：春天一到百花齊放，花粉到處死噴得空氣硬梆梆的充滿生氣。\n\n聯想畫面 2：沙發裡的彈簧突然老舊彈開，讓人像青蛙一樣在上面開心跳躍。\n\n高效擴充：多義字，既可指季節、彈簧，也能當動詞表示跳躍。\nKK 音標：[sprɪŋ] -> 鼻音 ng 發音時舌根要貼住軟顎，不可發出 g 的本音。\n\n常見同義字：\nbounce（彈跳、彈起）\nleap（跳躍，大步跨越）\nfountain（噴泉、泉水，自然湧出的水源）",
  "springy": "諧音聯想：\n諧音：死拼的\n\n聯想畫面 1：彈簧床墊非常有彈性，就像是為了讓你死拼的運動後能好好休息。\n\n聯想畫面 2：小兔子跳躍時步伐輕快，看起來非常有活力，這就是 springy 的感覺。\n\n高效擴充：spring（春天/彈簧）加上 y 變成形容詞。\nKK 音標：[ˋsprɪŋi] -> 重音在第一個音節，唸起來要有彈跳感。\n\n常見同義字：\nelastic（有彈性的）\nstretchy（可拉伸的）\nflexible（靈活的）",
  "sprinkle": "諧音聯想：\n諧音：「死噴溝漏」水，在花園裡到處灑水點綴。\n\n聯想畫面 1：在蛋糕上 sprinkle 一層彩色糖粉。\n\n聯想畫面 2：天空開始 sprinkle 下起稀疏小雨。\n\n高效擴充：字尾 kle 表示重複或細微動作。\nKK 音標：[ˋsprɪŋkəl] -> 重音在第一音節 ˋsprɪŋ，尾音 kl 發音輕快。\n\n常見同義字：\nscatter（撒落、散布）\nspread（展開、塗抹）\ndrizzle（毛毛雨、細雨）",
  "sprint": "諧音聯想：\n諧音：運動員在終點前「死拼的」全力衝刺，展開一場激烈的短距離賽跑。\n\n聯想畫面 2：上班快遲到時，他在捷運月台前看到車來了，立刻使出全力短跑衝刺。\n\n高效擴充：字根 sprint 衍生自跑動，與 spring 彈跳的字源相關。\nKK 音標：[sprɪnt] -> 短元音 i 發短音，spr 母音組合需連貫發音。\n\n常見同義字：\ndash（短跑、猛衝，通常距離較短）\nrun（跑步，泛指所有跑步動作）\ngallop（疾馳，多用於馬匹奔跑）",
  "spruced": "諧音聯想：\n諧音：斯普魯斯特。\n\n聯想畫面 1：他穿上筆挺的西裝，把自己打扮得整整齊齊，準備去參加晚宴。\n\n聯想畫面 2：為了迎接貴賓，大家把客廳整理得煥然一新，看起來非常乾淨。\n\n高效擴充：spruce 原意是雲杉，引申為整潔、修剪整齊。\nKK 音標：無 -> 重音在第一個音節，注意結尾的 d 發音。\n\n常見同義字：\n\ndressed up（打扮）\n\ntidied up（整理）。",
  "spun": "諧音聯想：\n諧音：死胖\n\n聯想畫面 1：因為轉圈轉得太久頭暈，結果一頭撞上那個死胖子，兩個人一起旋轉倒地。\n\n聯想畫面 2：蜘蛛在牆角忙著紡絲結網，動作快到像是一個死胖子在做極速旋轉運動。\n\n高效擴充：這是 spin 的過去式，想像 spin 的 i 變成 u，就像旋轉時模糊的影像。\nKK 音標：[spʌn] -> 發音時嘴巴微張，發出短促的ʌ音，像被嚇到短促的啊聲。\n\n常見同義字：\nrotated（旋轉，較正式的物理用語）\ntwisted（扭轉，強調繩索或纖維的纏繞）\nspun（紡紗，專指纖維加工）",
  "spur": "諧音聯想：\n諧音：「死爬兒」為了激勵自己爬上山頂，在心血來潮之下加了把勁。\n\n聯想畫面 2：教練的一番話成為最強的刺激與激勵，促使球員在場上加速進攻。\n\n高效擴充：原意指馬刺，用來刺馬腹使其加速，引申為激勵、促使。\nKK 音標：[spɝ] -> 捲舌音 ɝ 要發得扎實，嘴形微扁。\n\n常見同義字：\nstimulus（刺激、促進因素，較學術）\nincentive（獎勵、誘因，常指金錢或福利激勵）\nencourage（鼓勵、支持，動詞用法）",
  "spurn": "諧音聯想：\n諧音：「死旁」觀也不要理他，冷酷地把對方的求婚一腳踢開。\n\n聯想畫面 1：她高傲地轉身，輕蔑地拒絕了對方的追求。\n\n聯想畫面 2：老闆對低品質的提案嗤之以鼻，直接唾棄並退回。\n\n高效擴充：發音類似 scorn（輕蔑），字尾 rn 增加動作感。\nKK 音標：[spɝn] -> 單音節捲舌音，母音發 [ɝ]。\n\n常見同義字：\n\nreject（拒絕、退回）\n\nscorn（輕蔑、看不起）\n\ndespise（鄙視、看不起）",
  "sputters": "諧音聯想：\n諧音：死怕得死。\n\n聯想畫面 1：老舊引擎發出死怕得死的噗噗聲，隨時要熄火。\n\n聯想畫面 2：他緊張到說話結結巴巴，像引擎卡頓一樣噴出碎語。\n\n高效擴充：sputter 模擬液體噴濺或引擎不順的聲音。\nKK 音標：[ˋspʌtɚz] -> 重音在第一音節，發音要短促有力。\n\n常見同義字：\n\nstutter（結巴）\n\nsplutter（噴濺聲）。",
  "spy": "諧音聯想：\n諧音：「死拍」偷拍照，被暗中監視的間諜抓個正著。\n\n聯想畫面 1：電影裡的 spy 潛入敵營進行秘密監視。\n\n聯想畫面 2：拿望遠鏡 spy 遠處可疑的行蹤。\n\n高效擴充：複數形為 spies，動詞第三人稱是 spies。\nKK 音標：[spaɪ] -> 簡單的子音接長母音 aɪ，發音俐落。\n\n常見同義字：\nsecret agent（祕密特務）\ninformer（線民、告密者）\nobserver（觀察員、目擊者）",
  "squad": "諧音聯想：\n諧音：「死跨得」，特種部隊小組「死命跨過」障礙物執行任務。\n\n聯想畫面 1：警察分隊接到報案，立刻整裝出發前往現場支援。\n\n聯想畫面 2：籃球場上板凳球員組成的替補陣容在場邊蓄勢待發。\n\n高效擴充：源自軍事用語，指編制較小的班或分隊。\nKK 音標：[skwɑd] -> 單音節字，skw 連音後接短ㄚ的 ɑd 音。\n\n常見同義字：\n\nteam（團隊，泛指合作完成任務的群體）\ncrew（全體人員、工作人員，常指專業技術團隊）\nunit（小隊、單位，偏向行政或編制上的劃分）",
  "square": "諧音聯想：\n諧音：「死過兒」\n\n聯想畫面 1：古裝劇裡主角在古代的方形市集廣場上比武，笑說自己武功高強死過兒多次都不怕。\n\n聯想畫面 2：數學課本上要求畫出完美的正方形並計算其面積與平方值。\n\n高效擴充：字尾 -are 發 [ɛr] 的音，字義常與「公正、直角」相關。\nKK 音標：[skwɛr] -> 重音在尾音節，skw 組合發音滑順，ɛr 捲舌。\n\n常見同義字：\nplaza（廣場，購物或休閒用的大廣場）\nblock（街區，方塊狀的區域）\nfair（公正的、公平的，字尾發音相似）",
  "squash": "諧音聯想：\n諧音：「死跨許」，用力一腳把地上的蟲子「壓扁」。\n\n聯想畫面 1：週末跟朋友約在室內球場揮汗打壁球。\n\n聯想畫面 2：不小心把背包塞進過小的置物櫃裡，裡面的東西全被擠壓變形。\n\n高效擴充：與 squash 相關的還有黃色、綠色的各種食用南瓜屬植物。\nKK 音標：[skwɑʃ] -> 單音節字，skw 連音後接短ㄚ與 sh 的摩擦音。\n\n常見同義字：\n\ncrush（壓碎、壓毀，強調施加強大外力破壞結構）\npress（壓、按，泛指一般的壓擠動作）\npumpkin（南瓜，特指圓形橘黃色的大型食用瓜果）",
  "squashy": "諧音聯想：\n諧音：「死跨穴喜」聯想：大腳怪「死」命「跨」過那個「穴」，踩在「又溼又軟的」泥地上感到很「喜」悅。\n\n聯想畫面 1：這顆番茄已經過熟且 squashy，輕輕一捏就破了。\n\n聯想畫面 2：雨後的泥土步道變得非常 squashy，每走一步鞋子都陷了下去。\n\n高效擴充：由動詞 squash（壓扁、擠壓）加上形容詞字尾 -y，形容容易被壓壞或溼軟的特性。\nKK 音標：[ˋskwɑʃi] -> 主重音在 skwɑ 音節，注意 kw 的組合音要俐落，尾音 i 輕短。\n\n常見同義字：\nsoft（柔軟的，通用的）\nsquishy（軟乎乎的，捏起來有彈性的）\nmuddy（泥濘的，溼軟的）",
  "squat": "諧音聯想：\n諧音：「死跨特」教練要求大家在健身房裡做深蹲動作，雙腿跨開往下蹲。\n\n聯想畫面 2：流浪漢擅自佔用廢棄空屋，直接在裡面蹲坐生活，毫無合法權源。\n\n高效擴充：注意 qu 的發音為 kw，字尾 t 要輕聲收尾。\nKK 音標：[skwɑt] -> 短 o 發阿音，嘴巴張大，squat 唸起來短促。\n\n常見同義字：\ncrouch（蹲伏，身體縮起來的蹲）\nsit（坐，一般坐姿）\noccupy illegally（非法佔用，說明房屋佔領行為）",
  "squawk": "諧音聯想：\n諧音：「死跨客」大清早在那裡squawk大聲抱怨、吵死人。\n\n聯想畫面 1：農場裡的母雞突然遭到驚嚇，開始瘋狂squawk發出刺耳的叫聲。\n\n聯想畫面 2：員工們對於公司突然宣佈取消年終獎金群起squawk大聲抗議。\n\n高效擴充：擬聲字，模仿鳥類嘶啞粗厲的叫聲，延伸為人類的不滿抱怨。\nKK 音標：[skwɔk] -> 單音節字，發音時口型由 s 快速滑到 kwɔk。\n\n常見同義字：\n\ncomplain（抱怨，最通用的日常動詞）\n\nprotest（抗議、反對）\n\nscreech（發出尖銳刺耳的叫聲）",
  "squawked": "諧音聯想：\n諧音：死呱（台語：死掉的青蛙）\n\n聯想畫面 1：鸚鵡發出刺耳的叫聲，像死呱（squawked）一樣難聽。\n\n聯想畫面 2：顧客對服務大聲抱怨，那聲音像鴨子一樣 squawked 叫個不停。\n\n高效擴充：squawk 結合了 squall（尖叫）與 hawk（鷹），形容粗厲的聲音。\nKK 音標：[skwɔkt] -> 唸起來像「斯-呱-克特」。\n\n常見同義字：\nshrieked（尖叫，強調高音）\ncomplained（抱怨，強調行為）\ncried（叫喊，通用詞）",
  "squawking": "諧音聯想：\n諧音：死過客（發出尖叫）。\n\n聯想畫面 1：鸚鵡在籠子裡發出粗厲的叫聲，吵得人不得安寧。\n\n聯想畫面 2：顧客因為服務不周而大聲抱怨，引起現場一陣騷動。\n\n高效擴充：擬聲詞，模仿鳥類尖銳叫聲。\nKK 音標：[ˋskwɔkɪŋ] -> 第一音節重音，注意 squ 的嘴型。\n\n常見同義字：\n\nScreeching（尖叫的）\n\nComplaining（抱怨的）。",
  "squeaked": "諧音聯想：\n諧音：死鬼的。\n\n聯想畫面 1：老鼠踩到死鬼的拖鞋，發出吱吱的尖叫聲。\n\n聯想畫面 2：他在考試最後一秒僥倖通過，緊張得像老鼠一樣尖叫。\n\n高效擴充：squeak 結尾的 k 發音短促，模擬尖銳聲。\nKK 音標：[skwikt] -> 發音時嘴唇向兩側拉開，結尾的 t 輕輕帶過即可。\n\n常見同義字：\n\ncreaked（嘎吱作響，通常指木頭或門）\n\nnarrowly passed（勉強通過）。",
  "squealing": "諧音聯想：\n諧音：死鬼靈。\n\n聯想畫面 1：看到死鬼顯靈，嚇得發出長長的尖叫聲。\n\n聯想畫面 2：小豬被抓時發出尖銳的長叫聲，還在不斷抗議。\n\n高效擴充：squeal 比 squeak 更長、更尖銳。\nKK 音標：[ˋskwilɪŋ] -> 注意長母音 i 的發音，嘴巴要拉長。\n\n常見同義字：\n\nscreaming（尖叫）\n\ntattling（告密）。",
  "squeeze": "諧音聯想：\n諧音：死貴死貴諧音「死貴死貴的橘子，老闆幫我大力榨汁 squeeze 擠出最後一滴維他命C」。\n\n聯想畫面 1：你去市場買進口橘子覺得太貴，老闆現場幫你用力 squeeze 榨出一杯滿滿的果汁。\n\n聯想畫面 2：早上擠捷運時，你被前後的人夾在中間，感覺自己快被 squeeze 成人乾了。\n\n高效擴充：字首 sq- 常與緊縮、擠壓動作有關，如 squash。\nKK 音標：[skwiz] -> 雙唇合攏後短促唸出 sk，接著拉長主重音 wiz 的 i 音。\n\n常見同義字：\n\npress（用力按壓，通常指平面施壓）\n\npinch（用手指捏）\n\ncompress（壓縮體積）",
  "squirrel": "諧音聯想：\n諧音：「死鬼肉」\n\n聯想畫面 1：森林裡的小松鼠動作超級敏捷，把找到的橡果到處貯藏起來，生怕被別的動物搶走死鬼肉。\n\n聯想畫面 2：公園裡毛茸茸的松鼠在樹幹上不安地探尋食物。\n\n高效擴充：拼法較難，包含 -quir- 與 -rel，注意不要拼漏字母。\nKK 音標：[ˋskwɝəl] -> 重音在首音節 skwɝ，ɝ 為捲舌長元音，əl 念輕聲。\n\n常見同義字：\nchipmunk（花栗鼠，腮邊有條紋的小型鼠類）\nrodent（囓齒類動物的統稱）\nstash（藏匿、貯藏，當動詞用的口語替換）",
  "stab": "諧音聯想：\n諧音：死貼壁諧音「兇手拿著尖刀，猛力 stab 刺向緊緊貼在牆壁上的被害人」。\n\n聯想畫面 1：萬聖節鬼屋裡，工作人員突然拿著假道具刀作勢要 stab 你的胸口。\n\n聯想畫面 2：背叛的朋友在背後捅你一刀，那種痛就像被狠狠 stab 了一次。\n\n高效擴充：字尾 -ab 發短音 [æb]，注意嘴巴要張大。\nKK 音標：[stæb] -> 留意短母音 [æ] 嘴巴要開口笑到底，結尾的 b 要輕聲閉嘴。\n\n常見同義字：\n\npierce（穿透、刺破）\n\npoke（用手指或棍子輕戳）\n\nthrust（猛力刺入）",
  "stability": "諧音聯想：\n拆解 / 諧音：stable（穩定的） + ity（名詞字尾）\n\n諧音：「死貼壁了踢」，地震大到人「死死貼在壁面上踢」，才勉強維持平衡與「穩定」。\n\n聯想畫面 1：央行採取多項措施來確保國家經濟的穩定與匯率安全。\n\n聯想畫面 2：這個政治體系經過多次改革後，終於達到長期的安定與和諧。\n\n高效擴充：由形容詞 stable 去 e 加 ity 轉變為抽象名詞。\nKK 音標：[stəˋbɪlɪti] -> 重音在第二音節 bil，前面 stə 與後面 lɪti 輕唸。\n\n常見同義字：\n\nfirmness（堅固、堅定，偏向物理或態度的穩固）\nstableness（穩固性，stable的名詞形式，較少用）\nsecuring（確保、維護，動名詞用法）",
  "stabilize": "諧音聯想：\n諧音：「死得百來賴死」\n\n聯想畫面 1：疫情控制住了，死病人百來個的數據終於開始穩定、穩固下來。\n\n聯想畫面 2：經濟政策使物價穩定、使局勢平穩。\n\n高效擴充：stable (穩定的) 加上 ize (使成為)，使穩定。\nKK 音標：[ˋstebə͵laɪz] -> 第一音節重音，sta 發長音 a，bi 發短音 i。\n\n常見同義字：\n\nsteady（使穩固，強調不搖晃）\n\nbalance（使平衡，強調雙方對等）\n\nsecure（使穩固安全，強調防範風險）",
  "stable": "諧音聯想：\n諧音：「死貼波」\n\n聯想畫面 1：桌子四隻腳死死貼在地面上，非常穩固不晃動。\n\n聯想畫面 2：他的情緒很沉穩、工作狀況也很穩定。\n\n高效擴充：名詞型態也指關馬的「馬廄 (stable)」。\nKK 音標：[ˋstebəl] -> 重音在第一音節的 ˋste。\n\n常見同義字：\nsteady（穩定的、平穩的）\nfirm（穩固的）\nsecure（安全的、穩固的）",
  "stack": "諧音聯想：\n諧音：倉庫管理員把箱子「死貼客」好，疊成整整齊齊的一大堆貨物。\n\n聯想畫面 2：桌上堆滿了厚厚一疊待審閱的文件檔案，讓人看了頭皮發麻。\n\n高效擴充：a 發短æ 音，結尾 ck 發 k 音，同家族有 back、pack。\nKK 音標：[stæk] -> 單音節字，母音 a 發短音，重音在整個字上。\n\n常見同義字：\npile（堆、疊，較口語隨意）\nheap（無秩序堆積的一堆）\nbundle（捆、束，強調綁在一起）",
  "stadium": "諧音聯想：\n諧音：死爹低音諧音「球賽比數太落後，死爹的喊聲太低，全場 stadium 體育場安靜無聲」。\n\n聯想畫面 1：世足賽決賽當天，整個 stadium 體育場擠滿了穿著球衣的熱血球迷。\n\n聯想畫面 2：演唱會選在戶外大型 stadium 舉辦，全場數萬人揮舞著螢光棒。\n\n高效擴充：字尾 -ium 通常指特定場所或化學元素。\nKK 音標：[ˋstediəm] -> 主重音落在第一音節的 ste，後面的 dium 要輕快帶過。\n\n常見同義字：\n\narena（競技場、圓形劇場）\n\nfield（運動場地）\n\nbowl（碗形露天體育場）",
  "staff": "諧音聯想：\n諧音：死疊夫諧音「辦公室裡有一堆文件要處理，主管叫 staff 全體員工死命加班疊檔案」。\n\n聯想畫面 1：公司餐會上，老闆舉杯感謝全體 staff 員工這一年來的辛勞付出。\n\n聯想畫面 2：學校教職員室裡，所有 staff 正忙著準備期末考卷。\n\n高效擴充：單複數同形或可加 -s，亦可當作權杖、法杖解。\nKK 音標：[stæf] -> 發音時舌頭輕抵齒齦，短音 [æ] 配合清晰的 f 氣音。\n\n常見同義字：\n\nemployee（受雇員工，指個人）\n\npersonnel（全體人員、人事部門）\n\nworkforce（勞動力、全體工人）",
  "stage": "諧音聯想：\n諧音：「死結」\n\n聯想畫面 1：戲劇表演在舞台上進行到關鍵階段時，道具繩子居然打了死結害演員超緊張。\n\n聯想畫面 2：太空梭發射進入不同的飛行階段，主辦單位在後台準備得如火如荼。\n\n高效擴充：字尾帶有不發音的 e，字首 st- 相當常見。\nKK 音標：[stedʒ] -> 單音節，st 輕快，長元音 e，結尾是破擦音 dʒ。\n\n常見同義字：\nplatform（平台、講台，發表言論或技術的場所）\nphase（階段、時期，科學或進程上的分期）\nscene（場景，戲劇中的分場）",
  "stagger": "諧音聯想：\n諧音：喝醉酒的大叔走路「死貼個兒」牆壁，搖搖晃晃地蹣跚前進。\n\n聯想畫面 2：突如其來的壞消息讓她大受震撼，雙腿發軟，差點站不穩。\n\n高效擴充：字根 stagger 常指不穩或錯開，字尾 er 表動詞重複動作。\nKK 音標：[ˋstæɡɚ] -> 重音在第一音節 stag，第二音節 ger 輕念。\n\n常見同義字：\nstumble（絆倒、踉蹌，強調腳步不穩）\nsway（搖擺、晃動，多指受風或心智影響）\nshock（使震驚，指心理上的衝擊）",
  "stain": "諧音聯想：\n諧音：醬油滴在白襯衫上「死貼印」子，怎麼洗也洗不掉這難看的汙漬。\n\n聯想畫面 2：貪官汙吏收賄的醜聞敗壞了名聲，在清白的人生上留下了永遠洗不清的汙點。\n\n高效擴充：ai 發長 e 音，變化形為 stained（帶汙漬的）。\nKK 音標：[sten] -> 雙母音 e，嘴形由微扁轉為向兩側咧開。\n\n常見同義字：\nspot（斑點、汙點，通常較小）\nblemish（瑕疵、缺點，可用於皮膚或物品）\ndye（染料、染色，偏向主動上色）",
  "stained": "諧音聯想：\n諧音：「死貼的」\n\n聯想畫面 1：咖啡翻倒在雪白襯衫上，死死貼著布料形成一塊難洗的 stained 咖啡漬。\n\n聯想畫面 2：教堂窗戶上的 stained glass 彩色玻璃透過陽光，灑出美麗的光影。\n\n高效擴充：動詞 stain 的過去分詞，常用來形容名譽受損或物體著色。\nKK 音標：[steɪnd] -> 單音節字，注意雙母音 eɪ 的滑音與結尾的nd子音群。\n\n常見同義字：\n\ndiscolored（變色的，失去原本光彩的）\n\ntarnished（金屬失去光澤或名譽受玷汙的）\n\nspoiled（受損或變質的）",
  "stair": "諧音聯想：\n諧音：「死貼兒」\n\n聯想畫面 1：走路不看路在樓梯階級上摔倒，整個人死貼在地上。\n\n聯想畫面 2：爬公寓的樓梯時，一階一階往上走，走到腿都軟了。\n\n高效擴充：與 hair、chair 押韻，同音字為 stare（盯著看）。\nKK 音標：[stɛr] -> 包含捲舌複合母音 [ɛr]，嘴型微開並向外延伸。\n\n常見同義字：\n\nstep（階梯的單一步級或台階）\nstaircase（樓梯間或整座樓梯結構）\nladder（梯子，通常指移動式直梯）",
  "stairwell": "拆解：stair 樓梯 + well 井\n\n諧音：「死爹落威爾」\n\n聯想畫面 1：大樓的樓梯間設計得像一口深井一樣，往下看十分高聳。\n\n聯想畫面 2：火災警報響起時，大家急忙衝進安全梯的樓梯間逃生。\n\n高效擴充：由 stair（樓梯）與 well（此處指垂直天井結構）組合而成的複合名詞。\nKK 音標：[ˋstɛr͵wɛl] -> 第一個字stair重音，well 念短音 wɛl。\n\n常見同義字：\nstairway（樓梯、樓梯間，泛指上下通道）\nstaircase（有扶手的樓梯結構）\nfire escape（安全梯、防火逃生梯）",
  "stake": "諧音聯想：\n諧音：賭徒把所有「死貼客」身家的股本拿出來，準備放手一搏下注。\n\n聯想畫面 2：農夫在土地周圍打上木樁標記界線，宣示這是自己的領地範圍。\n\n高效擴充：常組成片語 at stake（生死攸關、處於危險中）。\nKK 音標：[stek] -> 長音 e，發音與 stain 相似但結尾是 k。\n\n常見同義字：\nshare（股份、分額）\npost（樁、柱子）\ngamble（賭博、冒險嘗試）",
  "stakeholder": "拆解：stake 賭注/權益 + holder 持有者\n\n諧音：「司黛克厚得」\n\n聯想畫面 1：會議室裡所有利害關係人都拿著股份與賭注，緊盯著公司的營運報告。\n\n聯想畫面 2：環評會議上，當地居民與企業老闆都是這項開發案的重要利害關係人。\n\n高效擴充：stake 代表股權或切身利益，holder 是持有的人。\nKK 音標：[ˋstek͵holdɚ] -> stek 重音，holdɚ 輕聲收尾。\n\n常見同義字：\ninterested party（利害關係人，法律與商務常用）\nshareholder（股東，專指持有公司股票的人）\nconstituent（選民、成分、相關人員）",
  "stale": "諧音聯想：\n諧音：「死透了」\n\n聯想畫面 1：這條吐司放太久變乾硬、不新鮮，簡直像死透了一樣難吃。\n\n聯想畫面 2：空氣不流通，房間裡的氣味變得非常污濁陳舊。\n\n高效擴充：與 steel（鋼鐵）拼法不同，注意發音與字義。\nKK 音標：[stel] -> 單音節字，發長雙母音 stel。\n\n常見同義字：\nnot fresh（不新鮮的）\noutdated（過時的、陳舊的）\nflat（走味的、平坦的）",
  "stalk": "諧音聯想：\n諧音：「死偷客」，跟蹤狂「死命偷窺與跟蹤」心儀的對象。\n\n聯想畫面 1：植物長長的綠色莖稈頂端開出了美麗的花朵。\n\n聯想畫面 2：獵人在森林裡放輕腳步，悄悄地潛近獵物準備出擊。\n\n高效擴充：字母 l 不發音，唸起來像 stock，注意拼字是 talk 的 a。\nKK 音標：[stɔk] -> 單音節字，st 連音後接長 ɔ 的 ɔk 音，l 不發音。\n\n常見同義字：\n\nstem（莖、幹，植物最主要的支撐部分）\ntrack（追蹤、足跡，偏向尋找動線或痕跡）\nshadow（影子、尾隨，口語常指偷偷跟在別人後面）",
  "stall": "諧音聯想：\n諧音：小販在市集「死偷歐」擺了一個小貨攤，死守著自己的販賣處。\n\n聯想畫面 2：車子開到一半引擎突然熄火拋錨，卡在馬路中間動彈不得。\n\n高效擴充：a 搭配 ll 發寬口奧音，常見於 ball、call。\nKK 音標：[stɔl] -> 圓脣音 ɔ，嘴形嘟起發深沉的奧聲。\n\n常見同義字：\nbooth（小隔間、攤位）\ndelay（拖延、延誤）\nbreakdown（拋錨、故障）",
  "stammer": "諧音聯想：\n諧音：「死呆媽，額」\n\n聯想畫面 1：死呆媽額頭冒汗，面對老師緊張得口吃、結結巴巴地說不出話。\n\n聯想畫面 2：生氣的老闆講話結巴，口吃模樣讓大家以為他有嚴重的口吃習慣。\n\n高效擴充：字首 st- 強調持續狀態，結合 hammer 敲打舌頭的感覺來記憶。\nKK 音標：[ˋstæmɚ] -> 第一音節重音，嘴巴張大唸 stæ，短促有力。\n\n常見同義字：\nstutter（指說話重複音節的結巴，如緊張時）\nhalter（指說話中途突然停頓或猶豫）\nfalter（指因不確定或膽怯而結巴、動搖）",
  "stamp": "諧音聯想：\n諧音：「死登鋪」\n\n聯想畫面 1：集郵愛好者為了買珍貴郵票，一大早死守在郵局門口登鋪排隊。\n\n聯想畫面 2：生氣的小孩在地上用力跺腳，拿著印章在作業本上用力蓋上戳記。\n\n高效擴充：字尾 mp 組合，過去式為 stamped。\nKK 音標：[stæmp] -> st 閉口，æ 發扁平的短音，mp 結尾雙唇緊閉。\n\n常見同義字：\nseal（印章、封蠟、封條）\nimprint（印記、壓印痕跡）\nstomp（重踩、跺腳，情緒激動的動作）",
  "stampede": "諧音聯想：\n諧音：死單皮的。\n\n聯想畫面 1：牛群受到驚嚇開始狂奔，跑得慢的牛死單皮的，被踩在腳下。\n\n聯想畫面 2：百貨公司週年慶，人群蜂擁而入，簡直像一場瘋狂的搶購熱潮。\n\n高效擴充：stamp 踩踏，加上 stampede 狂奔，畫面感強。\nKK 音標：[stæmˋpid] -> 重音在第二音節，結尾的 e 發長音 e。\n\n常見同義字：\n\nrush（衝）\n\nstamp（踩踏）\n\npanic（恐慌）。",
  "stance": "諧音聯想：\n諧音：「死（Stan）+ 蛋（ce）」\n\n聯想畫面 1：面對爭議問題，公司發表了明確的 stance，表示絕不妥協的態度。\n\n聯想畫面 2：運動員在起跑線上的 stance，展現出準備衝刺的姿勢。\n\n高效擴充：源自 stand 站立，引申為立場或觀點。\nKK 音標：[stæns] -> 單音節字，a 發音要飽滿。",
  "stand": "諧音聯想：\n諧音：「死店的」\n\n聯想畫面 1：店員必須在櫃檯前面死守店面、站一整天不能坐下。\n\n聯想畫面 2：他在這場辯論賽中堅定自己的立場，勇敢站出來發言。\n\n高效擴充：與 hand、land 押韻，過去式與過去分詞皆為 stood。\nKK 音標：[stænd] -> 夾帶扁唇短母音 [æ]，鼻音 nd 收尾要清晰。\n\n常見同義字：\n\nrise（起立或升起，強調動作的過程）\nwithstand（承受或禁得起，偏向忍受或抵抗）\nposition（立場或位置，指抽象或具體定位）",
  "standard": "諧音聯想：\n諧音：「死膽大得」\n\n聯想畫面 1：這家公司的服務品質標準非常嚴格，規定一般員工絕對不能死膽大得違背規範。\n\n聯想畫面 2：標準化的作業流程讓產品水準維持在正常的水平上。\n\n高效擴充：由 stand（站立）延伸而來，指「站得住腳的規範」。\nKK 音標：[ˋstændɚd] -> 重音在首音節 stænd，dɚd 念輕聲捲舌。\n\n常見同義字：\ncriterion（標準、準則，多用於評估或考試）\nnorm（規範、常態，社會或群體標準）\nbenchmark（基準、標竿，商業評比常用）",
  "standpoint": "諧音聯想：\n諧音：站點（stand-point）。\n\n聯想畫面 1：想像你站在一個高處的觀景點，從這個站點看下去，就是你對事情的觀點。\n\n聯想畫面 2：在辯論賽中，每個人都要站在自己的站點上，堅守自己的立場。\n\n高效擴充：stand（站）+ point（點），站在某個點上就是你的立場。\nKK 音標：[ˋstænd͵pɔɪnt] -> 第一音節 stand 重音，發音時注意 d 的輕微停頓。\n\n常見同義字：\n\nperspective（觀點，較抽象）\n\nviewpoint（觀點，常用）\n\nposition（立場，較正式）。",
  "stanza": "諧音聯想：\n諧音：詩人寫詩時卡關，氣得把「死蛋扎」在紙上的詩句全部重寫。\n\n聯想畫面 2：英文課本上老師要求朗讀這首詩的第一個詩節與韻腳。\n\n高效擴充：字尾 za 常見於義大利文外來語，讀音保持短促。\nKK 音標：[ˋstænzə] -> 重音在第一音節 stan，za 唸輕聲輕短的祖。\n\n常見同義字：\nverse（詩句、詩節）\nstrophe（詩的迴旋段、詩節，較文學）",
  "staple": "諧音聯想：\n諧音：「死貼堡」\n\n聯想畫面 1：把漢堡死死貼在紙上當作主要產品，這是店裡最夯的主食與核心產品。\n\n聯想畫面 2：辦公桌上最重要的消耗品就是釘書針，每份文件都必須用它訂住。\n\n高效擴充：字根概念源於固定、主要的物品，衍生出日常用品與主食。\nKK 音標：[ˋstepəl] -> 第一音節重音，ste 發長雙母音 ey。\n\n常見同義字：\nmain（常作形容詞，指主要的）\nprimary（指最基礎、首要的）\nessential（指不可或缺的核心要素）",
  "stapler": "諧音聯想：\n諧音：「死貼堡勒」\n\n聯想畫面 1：死貼著漢堡的那個機器，就是每天辦公室必備的釘書機。\n\n聯想畫面 2：行政人員拿著釘書機，用力把厚厚一疊信紙給訂起來。\n\n高效擴充：由 staple 加上表示人的字尾 -er 轉變成工具名詞（釘書機）。\nKK 音標：[ˋstepəlɚ] -> 第一音節重音，字尾 -er 發輕短的 ɚ 音。\n\n常見同義字：\npunch（打孔器，辦公室常見搭配工具）\nclip（迴紋針，另一種固定紙張的文具）\nbinder（夾子、文件夾，搭配使用）",
  "star": "諧音聯想：\n諧音：「死搭」\n\n聯想畫面 1：追星族為了見到大明星一面，死命也要搭上最早的一班車。\n\n聯想畫面 2：夜空中的星星一閃一閃，就像紅極一時的巨星在發光。\n\n高效擴充：與 car、far 押韻，字尾 -ar 發捲舌音。\nKK 音標：[stɑr] -> 開口向下的 [ɑ] 搭配捲舌 [r]，發音飽滿響亮。\n\n常見同義字：\n\ncelebrity（名人或巨星，通常指演藝圈知名人物）\nplanet（行星，夜空中常被誤認為星星的天體）\nstellar（星形的或極優秀的，形容詞形式）",
  "starch": "諧音聯想：\n諧音：「死踏其」\n\n聯想畫面 1：死命踏在馬鈴薯澱粉堆上，滿地都是白色的澱粉與漿粉。\n\n聯想畫面 2：媽媽洗完襯衫後，特別用澱粉漿幫衣服上漿，讓衣領變得很硬挺。\n\n高效擴充：發音結尾的 -rch 聽起來像「去」，吃澱粉前要想清楚熱量。\nKK 音標：[stɑrtʃ] -> 單音節字，ɑr 發長音，字尾 ch 發清脆的 tsh 音。\n\n常見同義字：\ncarbohydrate（碳水化合物，更學術的營養學詞彙）\npowder（粉末狀物質的通稱）\nthickener（增稠劑，常利用澱粉特性）",
  "stare": "諧音聯想：\n諧音：死台兒諧音「那個奇怪的台客死盯著你看，眼神讓人發毛 stare 凝視著」。\n\n聯想畫面 1：上課時你發呆不小心 stare 盯著老師的頭頂看，結果被抓包。\n\n聯想畫面 2：走在路上遇到明星，路人紛紛駐足 stare 盯著瞧。\n\n高效擴充：與 look（看）、glance（瞥一眼）不同，stare 強調目不轉睛。\nKK 音標：[stɛr] -> 長母音 [ɛr] 嘴巴微張，發音時舌尖往下。\n\n常見同義字：\n\ngaze（凝視、注視，通常帶有欣賞或驚嘆之意）\n\npeer（費力地看、凝視）\n\nwatch（注視、看守）",
  "stark": "諧音聯想：\n諧音：死打克。\n\n聯想畫面 1：這片荒涼的沙漠，簡直是死打克（stark）的荒地，寸草不生。\n\n聯想畫面 2：對比鮮明（stark）的黑白照片，讓人一眼就看出重點。\n\n高效擴充：字首 st- 常與站立、堅硬有關。\nKK 音標：[stɑrk] -> ɑ 發長母音，r 音要捲舌，發音要乾脆俐落。",
  "starkly": "諧音聯想：\n諧音：死打克力\n\n聯想畫面 1：戰場上死打克力（死得刻力），畫面嚴酷地呈現出毫無掩飾的慘狀。\n\n聯想畫面 2：這間房間裝潢得非常簡樸，牆面顏色對比明顯，簡直是 starkly（死板地）樸素到極致。\n\n高效擴充：stark 原意是荒涼的、嚴酷的，常與 contrast（對比）連用，表示強烈對比。\nKK 音標：[ˋstɑrkli] -> 第一音節 stɑrk 重音，ɑ 發長音，嘴巴張大。\n\n常見同義字：\nplainly（明顯地，強調清楚易見）\nseverely（嚴酷地，強調程度嚴重）\nutterly（完全地，強調徹底程度）",
  "start": "諧音聯想：\n諧音：「死踏它」\n\n聯想畫面 1：比賽鳴槍瞬間，選手死命踏出第一步，正式開始這場馬拉松。\n\n聯想畫面 2：引擎發動時車子劇烈震動，也是整個車程的開始。\n\n高效擴充：字首 st 代表堅定站立，加上 art 藝術，象徵藝術創作的全新起點。\nKK 音標：[stɑrt] -> 主重音在長母音ɑ上，發音時嘴巴張大，舌頭往後縮。\n\n常見同義字：\nbegin（開始，較常指過程的啟動）\ncommence（開始，正式且莊重的場合使用）\ninitiate（發起、創辦，通常指計畫或制度）",
  "startle": "拆解：star（星星）＋ tle（偷溜）\n\n諧音：「死呆偷溜」\n\n聯想畫面 1：夜晚看星星時，一隻貓咪突然竄出來，把大家嚇了一大跳。\n\n聯想畫面 2：老闆從背後無聲無息地走過來，使正在偷懶的員工驚恐萬分。\n\n高效擴充：字尾 -tle 表示反覆動作，start 代表突然開始。\nKK 音標：[ˋstɑrtəl] -> 主重音在第一個音節 stɑr，r 的音要捲舌，tl 快速帶過。\n\n常見同義字：\nsurprise（使驚奇，最常用的普通驚嚇）\nalarm（使驚恐，帶有危機警告意味）\nshock（使震驚，衝擊力道最強）",
  "startup": "諧音聯想：\n拆解：start（開始）+ up（向上）。\n\n聯想畫面 1：一家新創公司剛成立，辦公室裡充滿了活力，每個人都希望公司能快速向上發展。\n\n聯想畫面 2：創辦一家公司需要很多啟動資金，這些錢就是 startup cost，是公司起飛的燃料。\n\n高效擴充：由動詞片語 start up 轉化而來的名詞，強調新興與潛力。\nKK 音標：[ˋstɑrtʌp] -> 第一音節重音，st 發音要清晰。\n\n常見同義字：\n\nnew business（新企業，較口語）\n\nventure（風險投資企業，較正式）\n\nincipient（初期的，較學術）。",
  "starvation": "諧音聯想：\n諧音：「死踏肥軒」\n\n聯想畫面 1：快要餓死的難民在荒地裡走，因為嚴重飢餓而倒在地上。\n\n聯想畫面 2：長期營養不良導致這場可怕的飢荒，許多人面臨挨餓與餓死的危機。\n\n高效擴充：由動詞 starve（挨餓）去 e 加 -ation 變化而成的抽象名詞。\nKK 音標：[stɑrˋveʃən] -> 第三音節 veʃ 重音，ve 發長音 ey。\n\n常見同義字：\nhunger（一般的飢餓感）\nfamine（大範圍的飢荒、缺糧）\nmalnutrition（營養不良，常伴隨飢餓發生）",
  "starve": "諧音聯想：\n諧音：「死呆歪」\n\n聯想畫面 1：流浪狗好幾天沒吃東西，餓得瘦骨如柴快要餓死了。\n\n聯想畫面 2：晚餐還沒吃，現在肚子餓得發慌，簡直快餓扁了。\n\n高效擴充：常以片語 starve to death（餓死）出現，也可指對某事極度渴望。\nKK 音標：[stɑrv] -> a 發長音 [ɑ]，r 捲舌音要到位。\n\n常見同義字：\n\nfamish（使捱餓，較少用）\n\nhunger（感到飢餓、渴望）\n\ndeprive（剝奪，常指缺乏基本需求）",
  "starved": "諧音聯想：\n諧音：「死大夫的」\n\n聯想畫面 1：醫院裡的病患被限制飲食，餓得像死大夫的（starved）病人一樣緊抓著餅乾不放。\n\n聯想畫面 2：長期缺乏關愛的眼神，就像植物被剝奪水分一樣乾涸匱乏。\n\n高效擴充：常構成 be starved of 句型，表示被剝奪了某種必需品（如缺乏關愛、缺乏資訊）。\nKK 音標：[stɑrvd] -> 單音節字，包含捲舌音ɑr與結尾的vd子音群，唸「斯塔夫德」。\n\n常見同義字：\ndeprived（被剝奪的，缺乏基本需求的）\nfamished（飢餓的，強調極度缺糧）\nmalnourished（營養不良的，偏向健康層面）",
  "starving": "諧音聯想：\n諧音：「死大肥」\n\n聯想畫面 1：長期沒有東西吃導致身體瘦骨如柴，跟死大肥（starving）的胖子完全相反，正處於飢餓狀態。\n\n聯想畫面 2：流浪狗在路邊骨瘦如柴，眼神透露出極度渴望食物的痛苦。\n\n高效擴充：由動詞 starve 加上 ing 構成，口語中常用 I am starving 來誇飾自己非常餓。\nKK 音標：[ˋstɑrvɪŋ] -> 主重音在第一音節的ɑr，捲舌音要確實，唸「斯達夫-林」。\n\n常見同義字：\nfamished（飢餓的，肚子空空的正式或文學用字）\nhungry（肚子餓的，最基礎日常用字）\ndying of hunger（餓得快死掉的誇飾說法）",
  "state": "諧音聯想：\n諧音：「司黛特」\n\n聯想畫面 1：美國某個州的女參議員司黛特，在國會發表嚴正的狀態說明。\n\n聯想畫面 2：總統以國家元首的身分發表國事演說，陳述施政方針。\n\n高效擴充：字尾 ate 常為動詞字尾，名詞型態常用於表達心理或物理狀態。\nKK 音標：[stet] -> 雙母音 e 的嘴型由微開轉為扁平，發音要俐落。\n\n常見同義字：\ncondition（狀況、健康或物理狀態）\nstatus（地位、身份或系統狀態）\nexpress（表達、陳述，當動詞用時同義於 vt.）",
  "statecraft": "諧音聯想：\n拆解：state（國家）+ craft（工藝、技巧）。\n\n聯想畫面 1：治國需要高超的 statecraft，就像工匠雕刻藝術品一樣精細。\n\n聯想畫面 2：這本書詳細分析了古代帝王的 statecraft，如何運用權謀管理國家。\n\n高效擴充：craft 指的是精巧的技術，statecraft 即治理國家的藝術。\nKK 音標：[ˋsteɪtkræft] -> 重音在第一個音節，注意 craft 的結尾 f 音要輕咬。\n\n常見同義字：\n\ngovernance（統治，較正式）\n\npolitics（政治，通用）\n\nstatesmanship（政治家的風度與才能）。",
  "statement": "諧音聯想：\n諧音：「司黛特的門」\n\n聯想畫面 1：司黛特的辦公室門口貼著一張正式的書面聲明與財務結單。\n\n聯想畫面 2：嫌犯在警局門口向媒體發表簡短的案件說明。\n\n高效擴充：由 state 加上名詞字尾 ment 組合而成，表示陳述的結果。\nKK 音標：[ˋstetmənt] -> 重音落在第一音節的 stet，後面 ment 念輕聲。\n\n常見同義字：\ndeclaration（宣言、宣告，較正式）\nannouncement（公告、通知，公開給大眾）\nbill（帳單、結單，商業常用）",
  "statesman": "諧音聯想：\n拆解 / 諧音：state 國家 + man 男人\n\n諧音：管理國家（state）的男人（man），就是備受敬重的偉大政治家。\n\n聯想畫面 2：這位資深外交官一生為國奔走，被譽為當代傑出的國務活動家。\n\n高效擴充：合成字 state（國家/州）加上 man，指治國人才。\nKK 音標：[ˋstetsmən] -> 重音在第一音節 state，第二音節 smən 要輕唸。\n\n常見同義字：\npolitician（政治人物，有時帶有貶義指政客）\nnational leader（國家領導人）\npublic figure（公眾人物）",
  "statesmanship": "諧音聯想：\n拆解：statesman（政治家）+ ship（身分或能力）。\n\n聯想畫面 1：這位領袖在處理國際危機時展現了卓越的 statesmanship，贏得了各國的尊敬。\n\n聯想畫面 2：政治家不僅要有權力，更要有 statesmanship，才能為人民謀福利。\n\n高效擴充：-ship 後綴表示一種身分、地位或專業技能。\nKK 音標：[ˋsteɪtsmənʃɪp] -> 重音在第一個音節，注意中間的 s-m-n 的連音。\n\n常見同義字：\n\npolitical skill（政治技巧）\n\ndiplomacy（外交手腕）\n\nleadership（領導力）。",
  "static": "諧音聯想：\n諧音：死呆踢（靜止不動，像死掉一樣呆呆地踢）。\n\n聯想畫面 1：這個數據已經 static 了好幾個月，完全沒有成長的跡象。\n\n聯想畫面 2：收音機傳來一陣 static，干擾了原本清晰的廣播節目。\n\n高效擴充：源自希臘文 statos（站立），表示不動。\nKK 音標：[ˋstætɪk] -> 第一音節重音，注意 a 的發音要清晰。\n\n常見同義字：\nstationary（靜止的，指不動的狀態）\nstill（靜止的，指完全不動）\nunchanging（不變的，指狀態持續）",
  "stating": "諧音聯想：\n諧音：死（sta）- 聽（ting）。\n\n聯想畫面 1：法官在法庭上嚴肅地說明（stating）案情，大家都不敢出聲，只能死死地聽。\n\n聯想畫面 2：他在報告中清楚地陳述（stating）了自己的觀點。\n\n高效擴充：源自 state（狀態、陳述），加上 ing 變成現在分詞。\nKK 音標：[ˋsteɪtɪŋ] -> 重音在第一音節，stei 的長母音要發足。\n\n常見同義字：\n\ndeclaring（正式宣告）\n\nsaying（說，較口語）\n\nasserting（斷言）。",
  "station": "諧音聯想：\n諧音：「司爹省」\n\n聯想畫面 1：司爹為了省錢，每天都搭火車到市區的火車站通勤。\n\n聯想畫面 2：警察局和消防隊也是政府派駐人員的重要工作據點。\n\n高效擴充：字根 sta 代表站立，tion 為名詞字尾，意指站立的場所。\nKK 音標：[ˋsteʃən] -> 重音在第一音節 ste，shon 念輕快的念法。\n\n常見同義字：\nterminal（總站、航廈，大型交通樞紐）\nstop（公車站、中途站，範圍較小）\npost（崗位、駐地，軍警常用）",
  "stationary": "諧音聯想：\n諧音：「死爹秀呢瑞」－老爹秀出他那尊固定不動、靜止了好幾年的骨董雕像。\n\n聯想畫面 1：騎腳踏車在健身房的飛輪上狂踩，雖然汗流浹背但車子本身是靜止不動的。\n\n聯想畫面 2：路上紅燈時，所有的車輛都整齊劃一地保持靜止狀態等待綠燈。\n\n高效擴充：注意結尾是 -ary，容易和 stationery（文具，字尾是 -ery）搞混，記法是文具店賣紙（paper），所以文具用 -ery。\nKK 音標：[ˋsteʃə͵nɛri] -> 重音在第一音節 ste，唸長音的 A，注意與文具的發音完全相同但拼法不同。\n\n常見同義字：\n\nstatic（靜態的，通常指物理上的靜止或不上不下）\n\nfixed（固定的，強調被安插在某處不動）\n\nimmobile（不動的，強調完全無法移動的狀態）",
  "stationery": "諧音聯想：\n諧音：「死爹秀呢裡」\n\n聯想畫面 1：爸爸展示他剛買的一整套精美文具與信紙，笑得合不攏嘴。\n\n聯想畫面 2：文具店裡擺滿了各式各樣的筆記本、信箋與辦公小物。\n\n高效擴充：注意結尾是 -ery（文具），不要跟 stationary（固定的，結尾 -ary）搞混。\nKK 音標：[ˋsteʃə͵nɛri] -> 第一音節重音，字尾 ri 發輕聲。\n\n常見同義字：\noffice supplies（辦公用品，涵蓋範圍更廣）\nwriting materials（書寫材料，較文學或正式的說法）\nsupplies（日常消耗物資的通稱）",
  "statistic": "諧音聯想：\n諧音：「死呆踢死踢」的統計數字，讓人看了頭昏眼花。\n\n聯想畫面 1：政府官員在台上公布最新的人口統計數據，密密麻麻的統計量讓人眼花撩亂。\n\n聯想畫面 2：業務員每天要向主管回報銷售業績的統計數值，壓力非常大。\n\n高效擴充：字首 stat 代表狀態與固定，衍生出統計學。\nKK 音標：[stəˋtɪstɪk] -> 重音在第二音節 ti，發短促的 i 音。\n\n常見同義字：\nfigure（指具體的數字或金額）\ndata（指客觀的資料或數據）\nnumber（泛指一般數字或數量）",
  "statistical": "諧音聯想：\n拆解 / 諧音：statistic 的形容詞型。\n\n聯想畫面 1：學者秀出一張密密麻麻的統計學圖表。\n\n聯想畫面 2：政府公布了最新的經濟統計數據。\n\n高效擴充：字根 stat 代表狀態或數據。\nKK 音標：[stəˋtɪstɪkəl] -> 重音在第二音節 tɪ，前後弱化。\n\n常見同義字：\n\nnumerical（數字的）\n\ndemographic（人口統計的）\n\nanalytical（分析的）",
  "statistics": "諧音聯想：\n諧音：死呆踢死（sta-tis-tics）。\n\n聯想畫面 1：數學老師在黑板上寫滿統計數據，學生看著這些數字覺得很枯燥，簡直要死呆踢死。\n\n聯想畫面 2：新聞報導公布最新的民調統計，用圖表呈現社會趨勢。\n\n高效擴充：字根 stat- 代表狀態或固定，統計就是把變動的數據固定下來分析。\nKK 音標：[stəˋtɪstɪks] -> 第二音節 tis 重音，注意 s 的連音。\n\n常見同義字：\n\ndata（數據，泛指）\n\nfigures（數字，具體統計數字）\n\ncensus（人口普查，特定統計）。",
  "statue": "諧音聯想：\n諧音：死大豬諧音「公園中央立了一尊用黃金雕刻的大豬 statue 雕像」。\n\n聯想畫面 1：觀光客到自由女神 statue 前面合照留念。\n\n聯想畫面 2：博物館裡展示著希臘時代的斷臂維納斯大理石 statue 雕像。\n\n高效擴充：字根 stat- 代表站立、固定不動（類似 stand）。\nKK 音標：[ˋstætʃ͵u] -> 第一音節 stat 必須重讀，後面的 ue 唸輕音。\n\n常見同義字：\n\nsculpture（雕塑品、雕刻藝術）\n\nfigure（人物雕像、身材）\n\nmonument（紀念碑、歷史建築）",
  "stature": "諧音聯想：\n諧音：「死貼雀」\n\n聯想畫面 1：小鳥死死貼著樹枝測量身高，發現自己的身材比想像中高大。\n\n聯想畫面 2：這位教授在學術界享有崇高的聲望與地位，身材雖然不高但氣場非凡。\n\n高效擴充：字根 stat- 代表站立（stand），站立的高度延伸為人的身高與社會聲望。\nKK 音標：[ˋstætʃɚ] -> 第一音節重音，tʃɚ 發 ch-er 的音。\n\n常見同義字：\nheight（純粹指身體的高度或海拔）\nstanding（社會地位、名望）\nprestige（聲望、威望，較正式）",
  "status": "諧音聯想：\n諧音：「死台踏死」\n\n聯想畫面 1：社會地位高的人，連走路踏地板的姿態都非常神氣。\n\n聯想畫面 2：查看通訊軟體的個人狀態與上線情況。\n\n高效擴充：字根 sta 代表站立，指人或事物站穩的社會位置。\nKK 音標：[ˋstætəs] -> 主重音在第一音節 ˋstæ，təs 發輕聲。\n\n常見同義字：\n\nposition（職位或地位，指階層高低）\n\nstanding（身分地位，指社會聲望）\n\ncondition（狀況，指健康或運作情況）",
  "statutory": "諧音聯想：\n諧音：死大球瑞\n\n聯想畫面 1：法律規定像死掉的大球一樣沉重，這是法定的責任。\n\n聯想畫面 2：公司遵守法定程序，就像遵守死大球瑞的規則一樣嚴格。\n\n高效擴充：字根 stat（站立/固定），法律就是固定在那裡不動的規則。\nKK 音標：<[ˋstætʃətɔri]> -> 重音在第一個音節，唸起來要乾脆俐落。\n\n常見同義字：\nlegal（法律的，廣義的合法）\nlawful（合法的，符合法律的）\nlegislative（立法的，與制定法律相關）",
  "stay": "諧音聯想：\n諧音：「斯爹」\n\n聯想畫面 1：斯爹老爸留在家裡陪伴家人，沒有出門旅遊。\n\n聯想畫面 2：飯店櫃檯提醒房客可以免費逗留到中午再退房。\n\n高效擴充：常與介詞 put 或 at 連用，表示維持現狀或停留某處。\nKK 音標：[ste] -> 雙母音 e 收尾，聲音平穩且拉長一些。\n\n常見同義字：\nremain（保持、維持，強調狀態持續）\nlinger（逗留、徘徊，依依不舍的感覺）\nstop（停留、中斷，動態的暫停）",
  "steadfast": "諧音聯想：\n拆解 / 諧音：stead（穩定）+ fast（快速/牢固）。\n\n聯想畫面 1：一棵大樹的根部非常穩固（steadfast），就算狂風暴雨也不會動搖。\n\n聯想畫面 2：他對夢想的追求非常堅定，多年來始終如一。\n\n高效擴充：stead 源自 steady，fast 在古語中有牢固的意思。\nKK 音標：[ˋstɛd͵fæst] -> 第一音節 stead 重音，注意 d 和 f 的銜接。\n\n常見同義字：\n\nloyal（忠誠的）\n\nfaithful（守信的）\n\ncommitted（投入的）。",
  "steadily": "諧音聯想：\n諧音：死得得力\n\n聯想畫面 1：只要穩步地練習，就算遇到困難也不會死得得力，反而能逐漸進步。\n\n聯想畫面 2：經濟成長率穩步地攀升，顯示市場狀況非常穩定。\n\n高效擴充：由 steady 變化而來，字根 stead 代表地方或位置，站得穩就是 steady。\nKK 音標：[ˋstedəli] -> 重音在第一音節，發音時注意 e 的短促感。\n\n常見同義字：\nconstantly（持續地，強調不間斷）\ngradually（逐漸地，強調過程緩慢）\nfirmly（堅定地，強調態度或位置）",
  "steady": "諧音聯想：\n諧音：死低滴諧音「地震時把相機放在三腳架上，畫面要 steady 平穩才不會晃動」。\n\n聯想畫面 1：新手學開車時，教練一直提醒油門要踩得 steady 保持穩定。\n\n聯想畫面 2：兩人的感情經歷風雨後終於穩定下來，成為彼此的 steady 情侶。\n\n高效擴充：轉成副詞為 steadily（平穩地、持續地）。\nKK 音標：[ˋstɛdi] -> 主重音在 ste，尾音 dy 輕輕念出短 i。\n\n常見同義字：\n\nstable（穩固的、情緒穩定的）\n\nfirm（堅固的、堅定的）\n\nconstant（持續不斷的、恆定的）",
  "steak": "諧音聯想：\n諧音：「死貼客」\n\n聯想畫面 1：老饕對著高級餐廳的厚切牛排死貼客（死守不放），非要吃到第一口不可。\n\n聯想畫面 2：煎牛排時油花滋滋作響，香氣逼得路人死貼著玻璃窗狂流口水。\n\n高效擴充：字尾 eak 發長音 e 的音，常和 meat 或 weak 的母音組合聯想。\nKK 音標：[stek] -> 單音節字，嘴型向兩側拉開唸長 e 音，尾音 k 輕輕帶過。\n\n常見同義字：\nmeat（泛指所有肉類，比較廣泛）\ncut（指肉品切割塊，偏向肉舖用語）\nbeef（專指牛肉，不含魚排或豬排）",
  "steal": "諧音聯想：\n諧音：「死低調」\n\n聯想畫面 1：小偷行竊時總是死低調，深怕被人發現。\n\n聯想畫面 2：這場特賣會的價格便宜到簡直像用偷的一樣划算。\n\n高效擴充：字首 st 常與站立或動作有關，結合 eal 變成快速拿走。\nKK 音標：[stil] -> 長音 i，嘴型拉平發出長長的 ee 音。\n\n常見同義字：\ntheave（行竊，較古或文學用語）\npurloin（偷竊，正式書面用語）\nrob（搶劫、掠奪，通常指強行奪取）",
  "steam": "諧音聯想：\n諧音：「死踢姆」\n\n聯想畫面 1：火車汽鍋不斷冒出滾燙水蒸氣，把旁邊調皮的小孩燙得死踢姆（猛踢腳）。\n\n聯想畫面 2：冬天吃小籠包時，竹籠一掀開，滿滿的蒸汽瞬間模糊了眼鏡。\n\n高效擴充：字根 ea 發長音，常出現在以氣體或液體流動有關的字如 stream。\nKK 音標：[stim] -> 單音節字，長元音 i 嘴唇扁平，尾音 m 閉緊雙唇。\n\n常見同義字：\nvapor（泛指水汽或任何蒸發物質，較科學）\nfume（通常指有害或濃烈的煙霧氣體）\nsmoke（指燃燒產生的煙霧）",
  "steamer": "諧音聯想：\n諧音：「死踢摸」\n\n聯想畫面 1：廚師死命踢開蒸籠鍋蓋，冒出大量蒸氣，原來是美味的包子出爐了。\n\n聯想畫面 2：江面上一艘巨大的汽船正緩緩開過，船頂不斷噴出白色的蒸氣。\n\n高效擴充：由 steam（蒸氣）加上 -er 轉變為具體的蒸鍋或汽船工具。\nKK 音標：[ˋstimɚ] -> 第一音節重音，sti 發長母音 i。\n\n常見同義字：\n蒸汽船：steamboat（美式常用）\n\nsteamship（大型遠洋客輪）\n蒸籠廚具：food steamer（食物蒸鍋）\n\nbamboo steamer（竹蒸籠）",
  "steel": "諧音聯想：\n諧音：「死弟爾」\n\n聯想畫面 1：兩兄弟在工廠打造超強的鋼鐵人裝甲，弟弟說這塊鋼板硬到死弟爾（死也不會凹陷）。\n\n聯想畫面 2：高聳的摩天大樓內部都是用堅固的鋼鐵骨架支撐起來的。\n\n高效擴充：ee 發長音 e，和 feel、wheel 同韻，注意與 steal（偷竊）拼法區分。\nKK 音標：[stil] -> 單音節字，l 是輕柔的舌尖上顎音，唸起來短促扎實。\n\n常見同義字：\niron（鐵，硬度比鋼低一些）\nmetal（泛指所有金屬材質）\nalloy（合金，鋼就是一種鐵碳合金）",
  "steep": "諧音聯想：\n諧音：「死踢坡」\n\n聯想畫面 1：爬山時遇到超級陡峭的斜坡，必須死命抬腳往上踢。\n\n聯想畫面 2：這家店的價格高得離譜，讓人難以接受。\n\n高效擴充：當動詞時有「浸泡、沉浸」之意。\nKK 音標：[stip] -> 單音節字，發長母音 stip。\n\n常見同義字：\nshear（陡峭的、垂直的）\nhigh（過高的、高的）\nabrupt（急劇的、陡峭的）",
  "steepened": "諧音聯想：\n拆解：steep（陡峭）+ en（使...變）+ ed（過去式）。\n\n聯想畫面 1：登山路徑因為大雨沖刷，坡度變得更加陡峭。\n\n聯想畫面 2：經濟數據曲線突然變陡，顯示衰退加劇。\n\n高效擴充：steep 是形容詞，加上 en 字尾變成動詞。\nKK 音標：無 -> 重音在第一個音節，發音時注意長母音 i 的發音。\n\n常見同義字：\n\nsharpened（變尖銳）\n\nincreased（增加）\n\nintensified（加劇）。",
  "steer": "諧音聯想：\n諧音：「死貼」著方向盤駕駛，才能安全過彎。\n\n聯想畫面 1：教練在副駕駛座指導學員如何正確掌方向盤與駕駛汽車。\n\n聯想畫面 2：經驗豐富的老前輩給了職場新鮮人一些實用的建議與指導。\n\n高效擴充：常搭配 steer the company 意指帶領公司走向正確方向。\nKK 音標：[stɪr] -> 雙母音 ir 發長音的耳字音，注意嘴型滑動。\n\n常見同義字：\ndrive（指開車或駕駛交通工具）\nguide（指帶領或指引方向）\ndirect（指指揮或指導）",
  "stem": "諧音聯想：\n諧音：「死藤」\n\n聯想畫面 1：植物的莖就像堅韌的死藤一樣，支撐著整株花朵向上生長。\n\n聯想畫面 2：政府必須及時採取行動，來遏止疫情繼續擴散蔓延。\n\n高效擴充：與 limb、trunk 一樣，都是指植物或身體的支幹部位。\nKK 音標：[stɛm] -> 重音在 tɛm，發音短促俐落。\n\n常見同義字：\n\nstalk（花梗，專指花朵或葉子的細柄）\n\ntrunk（樹幹，指粗壯的主幹部分）\n\nstop（阻止，當動詞用時表遏止）",
  "step": "諧音聯想：\n諧音：「死貼普」\n\n聯想畫面 1：跳舞時腳步要死死貼著舞步的節奏，一步一步踏穩。\n\n聯想畫面 2：爬樓梯時跨出每一個階梯，登高望遠。\n\n高效擴充：常用成語 step by step 表示循序漸進。\nKK 音標：[stɛp] -> 短母音 ɛ 發音短促有力，嘴形呈扁平狀。\n\n常見同義字：\npace（步伐、步調，常指速度）\nstair（樓梯、階梯，實體建築物）\naction（行動、步驟，抽象概念）",
  "stepchild": "諧音聯想：\n諧音：死貼踩小孩諧音「童話故事裡的繼母對待 stepchild 繼子非常刻薄」。\n\n聯想畫面 1：重組家庭中，如何與 stepchild 建立良好的親子關係是一門學問。\n\n聯想畫面 2：這個冷門部門在公司裡就像個 stepchild 繼子一樣不受重視。\n\n高效擴充：由 step（繼）加上 child（小孩）組合而成，同系列還有 stepfather。\nKK 音標：[ˋstɛp͵tʃaɪld] -> 重音在 step，後面的 child 正常發雙母音。\n\n常見同義字：\n\nadopted child（收養的孩子）\n\nfoster child（寄養兒童）\n\noffspring（後代、子女）",
  "stepfather": "諧音聯想：\n諧音：死貼發法諧音「媽媽再婚後，新的 stepfather 繼父努力發零用錢拉近距離」。\n\n聯想畫面 1：週末時，溫柔的 stepfather 帶著全家人一起去露營。\n\n聯想畫面 2：灰姑娘的故事裡，如果多了一個慈祥的 stepfather 或許結局會不同。\n\n高效擴充：字首 step- 源自古英文，意指因姻緣而形成的親屬關係。\nKK 音標：[ˋstɛp͵fɑðɚ] -> 主重音在 step，fɑðɚ 的發音注意舌頭咬輕音。\n\n常見同義字：\n\nadoptive father（養父）\n\nfoster father（寄養父親）\n\nmale guardian（男性監護人）",
  "stephen": "諧音聯想：\n諧音：死提分。\n\n聯想畫面 1：斯蒂芬在比賽中為了得分，拚命地向前衝刺。\n\n聯想畫面 2：斯蒂芬是個很有禮貌的紳士，每次見面都會主動打招呼。\n\n高效擴充：常見的英文名，發音與 Steven 相同。\nKK 音標：[ˋstivn] -> 重音在第一個音節，注意 v 的發音要輕咬下唇。\n\n常見同義字：\n\nSteve（暱稱）\n\nStephenson（常見姓氏）。",
  "stepmother": "諧音聯想：\n諧音：死貼媽得喝諧音「白雪公主的惡毒 stepmother 繼母逼她喝下毒蘋果汁」。\n\n聯想畫面 1：故事書裡的壞 stepmother 總是虐待繼女。\n\n聯想畫面 2：現實生活中也有許多溫柔照顧非親生子女的模範 stepmother。\n\n高效擴充：對應詞為 stepfather，字尾都是 mother。\nKK 音標：[ˋstɛp͵mʌðɚ] -> 重音落在 step，mʌðɚ 的 ʌ 唸短促的阿音。\n\n常見同義字：\n\nadoptive mother（養母）\n\nfoster mother（寄養母親）\n\nfemale guardian（女性監護人）",
  "stereo": "諧音聯想：\n諧音：死得留歐諧音「發燒友為了買頂級 stereo 立體音響，花光了去歐洲旅遊的錢」。\n\n聯想畫面 1：房間角落擺著一台復古的 stereo 播放著爵士樂。\n\n聯想畫面 2：車用 stereo 立體聲環繞音效讓開車變成一種享受。\n\n高效擴充：字首 stere- 有立體、空間的概念。\nKK 音標：[ˋstɛri͵o] -> 重音在 ste，後面接 ri-o 三個音節快速滑過。\n\n常見同義字：\n\nsound system（音響系統）\n\nhi-fi（高傳真音響）\n\naudio system（音訊系統）",
  "stereotype": "諧音聯想：\n拆解 / 諧音：stereo (立體聲) + type (打字/類型)。\n\n諧音：立體聲的類型就是老一套的刻板印象。\n\n聯想畫面 1：大眾對特定族群常抱持著模式化的思想與成見。\n\n聯想畫面 2：編劇在寫劇本時不小心用了公式化人物，被觀眾吐槽太老套。\n\n高效擴充：由 stereo 混合 type 而成，形容刻板模式。\nKK 音標：[ˋstɛriə͵taɪp] -> 第一音節 ste 重讀，注意三音節的抑揚頓挫。\n\n常見同義字：\ncliche（老生常談或陳腔濫調）\nconventionality（因循守舊或傳統）\nprejudice（偏見或成見）",
  "sterling": "諧音聯想：\n諧音：死得靈。\n\n聯想畫面 1：這項服務的品質非常優秀，簡直是標準純銀般的等級，好到讓人死得靈（死而無憾）。\n\n聯想畫面 2：英國貨幣英鎊的符號是 Sterling，代表著穩定的價值。\n\n高效擴充：sterling 原指標準純銀，後來引申為品質極佳。\nKK 音標：[ˋstɝlɪŋ] -> 重音在第一音節，注意捲舌音 er。\n\n常見同義字：\n\nexcellent（優秀的）\n\npure（純淨的）\n\nBritish pound（英鎊）。",
  "stern": "諧音聯想：\n諧音：死藤 -> 諧音聯想：用死藤水來約束學生的嚴厲教官。\n\n聯想畫面 1：教官板起嚴峻的臉孔盯著違規的學生。\n\n聯想畫面 2：郵輪的船尾在波濤洶湧的海面上搖晃。\n\n高效擴充：一字多義，既可指態度嚴厲，也可指船尾。\nKK 音標：[stɝn] -> 單音節，st 結合捲舌音 ɝn。\n\n常見同義字：\n\nstrict（嚴格的）\n\nsevere（嚴厲的、嚴峻的）\n\nrigorous（嚴謹的）",
  "steroids": "諧音聯想：\n諧音：死得若。\n\n聯想畫面 1：濫用類固醇，身體機能會變差，簡直是死得若（若不節制就會死）。\n\n聯想畫面 2：運動員為了奪冠，違規使用類固醇。\n\n高效擴充：常指合成代謝類固醇。\nKK 音標：[ˋstɪrɔɪdz; ˋsterɔɪdz] -> 重音在第一音節。\n\n常見同義字：\n\nanabolic steroids（合成代謝類固醇）\n\nhormones（荷爾蒙）。",
  "steve": "諧音聯想：\n諧音：死踢夫\n\n聯想畫面 1：史蒂夫是一個調皮的男孩，總是喜歡死踢夫的足球，讓大家很頭痛。\n\n聯想畫面 2：蘋果公司的創辦人史蒂夫賈伯斯，改變了現代科技的樣貌。\n\n高效擴充：常見的男子名，通常是 Stephen 的縮寫。\nKK 音標：[stiv] -> 單音節，注意長母音 i 的發音。\n\n常見同義字：\nStephen（完整拼法）\nSteven（另一種常見拼法）\nMan's name（男子名，分類標籤）",
  "stew": "諧音聯想：\n諧音：「死兔」子被拿來慢火燉煮成美味的肉菜。\n\n聯想畫面 1：媽媽在廚房慢火煨煮一鍋香氣四溢的牛肉燉菜。\n\n聯想畫面 2：考生在考前因為進度落後而感到焦慮不安。\n\n高效擴充：常見片語 stew in one's own juice 意指自作自受。\nKK 音標：[stu] -> 發長 u 音，嘴型要縮小向前凸出。\n\n常見同義字：\nsimmer（指微滾或慢火熬煮）\nbraise（指紅燒或燜煮）\nworry（指擔憂或焦慮）",
  "steward": "諧音聯想：\n諧音：「死徒弟」被派去當男服務員和管家。\n\n聯想畫面 1：郵輪上的男乘務員親切地引導旅客走向房間。\n\n聯想畫面 2：豪宅裡的管家細心打理主人交辦的大小事務。\n\n高效擴充：字尾 ard 常指人，如 coward 膽小鬼。\nKK 音標：[ˋstuɚd] -> 重音在第一音節 stu，注意 r 的捲舌音。\n\n常見同義字：\nwaiter（餐廳的男服務生）\nattendant（服務員或隨從）\nmanager（經理或管理者）",
  "stewardess": "諧音聯想：\n拆解 / 諧音：steward (管家/男服務員) + ess (陰性字尾)。\n\n諧音：男管家加上陰性字尾就變成女服務員。\n\n聯想畫面 1：飛機上的空服員親切地為乘客送上餐點與飲料。\n\n聯想畫面 2：親切的女乘務員耐心地協助旅客放置行李。\n\n高效擴充：現代多用 gender-neutral 的 flight attendant 代替。\nKK 音標：[ˋstuɚdəs] -> 重音在第一音節，字尾 ess 念輕聲的 əs。\n\n常見同義字：\nair hostess（空姐或女性乘務員）\nflight attendant（飛行服務員，男女皆可）\nhostess（女主人或女接待員）",
  "stick": "諧音聯想：\n諧音：「死貼客」\n\n聯想畫面 1：雙面膠黏性太強，把紙張死貼客（死死黏在牆上）撕不下來。\n\n聯想畫面 2：森林裡散落許多枯樹枝和木棍，走路不小心會被樹枝絆倒。\n\n高效擴充：短母音 i 發輕短的「ㄧ」音，常與 stack 或 stock 混淆。\nKK 音標：[stɪk] -> 短促的 i 音，結尾 k 爆破音要俐落。\n\n常見同義字：\nadhere（正式用語，指黏著或堅持）\nbranch（指樹枝，比 stick 更具體）\nrod（指金屬或木製的金屬棒/竿）",
  "sticky": "諧音聯想：\n諧音：「死弟奇」\n\n聯想畫面 1：弟弟吃完糖果，手黏呼呼的死命抓著奇特的玩具不放。\n\n聯想畫面 2：外面下雨導致路面泥濘黏腳，走起路來很不舒服。\n\n高效擴充：由 stick（黏貼）加上 y 形成形容詞。\nKK 音標：[ˋstɪki] -> 重音在第一音節的 ˋstɪ。\n\n常見同義字：\ngluey（膠狀的、黏的）\ntacky（有黏性的、俗氣的）\nadhesive（具黏著力的）",
  "stiff": "諧音聯想：\n諧音：「死啼戶」\n\n聯想畫面 1：這具屍體或木頭硬梆梆的，像一戶人家死板地僵硬著。\n\n聯想畫面 2：他因為緊張，全身肌肉變得非常僵硬不自然。\n\n高效擴充：常見片語 stiff competition（激烈的競爭）。\nKK 音標：[stɪf] -> 單音節字，發短母音 stɪf。\n\n常見同義字：\nrigid（僵硬的、嚴格的）\ninflexible（不屈的、無彈性的）\nhard（硬的）",
  "stiffness": "諧音聯想：\n諧音：死鐵內斯。\n\n聯想畫面 1：這根鋼條的 stiffness 太高，完全無法彎曲，像死鐵一樣硬。\n\n聯想畫面 2：他在台上講話時顯得 stiffness，動作僵硬，一點也不自然。\n\n高效擴充：stiff（僵硬的）+ ness，形容物理上的硬度或心理上的拘謹。\nKK 音標：[ˋstɪfnəs] -> 重音在第一個音節，注意 f-n-e-s 的連音。\n\n常見同義字：\n\nrigidity（剛性，較正式）\n\nhardness（硬度，物理特性）\n\nawkwardness（笨拙，指行為不自然）。",
  "stifle": "諧音聯想：\n諧音：死（sti）＋否（fle）\n\n聯想畫面 1：在密閉空間裡空氣稀薄，感覺快要窒息（stifle）了。\n\n聯想畫面 2：他強忍住笑意，硬是把笑聲壓抑（stifle）在喉嚨裡。\n\n高效擴充：與 suffocate 同義，但 stifle 更強調抑制情緒或扼殺靈感。\nKK 音標：[ˋstaɪf(ə)l] -> 重音在首音節，結尾的 l 音要輕柔帶過。",
  "still": "諧音聯想：\n諧音：「死貼」著牆壁不動，保持靜止。\n\n聯想畫面 1：雖然外面風雨交加，但他 still（仍然）堅持去上班。\n\n聯想畫面 2：拍照時攝影師大喊保持 still（靜止），不要亂動。\n\n高效擴充：常置於動詞前或be動詞後表達持續狀態。\nKK 音標：[stɪl] -> 短元音 ɪ，發音短促輕快，舌尖抵住上齒齦。\n\n常見同義字：\nyet（還，通常放否定句或疑問句句尾）\neven（甚至，加強語氣）\nmotionless（不動的，形容外在完全沒有動作）",
  "stilted": "諧音聯想：\n諧音：死（sti）＋提（lt）＋的（ed）。\n\n聯想畫面 1：他講話像踩著高蹺一樣，僵硬又不自然。\n\n聯想畫面 2：這篇演講稿寫得太過呆板，像是架在高蹺上，讓人聽了很尷尬。\n\n高效擴充：stilt 原意是高蹺，形容詞引申為不自然。\nKK 音標：[ˋstɪltɪd] -> 重音在第一音節，結尾 ed 發 id 音。\n\n常見同義字：\n\nstiff（僵硬的）\n\nawkward（笨拙的）。",
  "stilts": "諧音聯想：\n諧音：死鐵死\n\n聯想畫面 1：踩著高蹺的人，如果摔下來，那兩根鐵棍可能會讓人死得很慘，所以一定要小心。\n\n聯想畫面 2：嘉年華會上，表演者踩著高蹺走過人群，大家都驚呼連連。\n\n高效擴充：stilt 原意指支柱，踩高蹺就是利用支柱來增高。\nKK 音標：[stɪlts] -> 單音節字，發音要短促且帶有 s 的摩擦音。\n\n常見同義字：\npoles（竿子，高蹺的結構）\nheight（高度，踩高蹺的目的）\nbalance（平衡，踩高蹺的核心技巧）",
  "stimulate": "諧音聯想：\n諧音：「死貼木來得」\n\n聯想畫面 1：用膠水死貼木頭來刺激觸覺，使人興奮。\n\n聯想畫面 2：喝咖啡來激勵精神，促使工作效率提高。\n\n高效擴充：字根 stimu (刺、戳) 衍生出的刺激意涵。\nKK 音標：[ˋstɪmjə͵let] -> 第一音節重音，stim 發短音 i，late 發長音 a。\n\n常見同義字：\n\nencourage（鼓勵，偏向給予信心支持）\n\nboost（促進或提高，常搭配經濟或信心）\n\n激发（激發，中文同義詞概念）",
  "stimulation": "諧音聯想：\n諧音：「死低美局聯」\n\n聯想畫面 1：局裡的新政策帶來強烈的刺激與興奮作用，讓大家振作起來。\n\n聯想畫面 2：咖啡因提供大腦必要的刺激，幫助我們在工作時保持清醒與激勵。\n\n高效擴充：由 stimulate（動詞：刺激）衍生而來的抽象名詞結尾 -ation。\nKK 音標：[͵stɪmjəˋleʃən] -> 第四音節 le 重音，le 前面的 mu 唸輕聲。\n\n常見同義字：\nexcitement（興奮、刺激感）\nincentive（獎勵、誘因，指實質鼓勵）\nencouragement（鼓勵、打氣）",
  "stimulus": "諧音聯想：\n諧音：「死低美吉落死」\n\n聯想畫面 1：經濟低迷時，政府發放消費券作為促進因素與刺激品來救市。\n\n聯想畫面 2：生物學實驗中，給予小白鼠微弱的電擊作為外部刺激。\n\n高效擴充：複數型為 stimuli，字尾 -us 是典型拉丁文外來語單數變化。\nKK 音標：[ˋstɪmjələs] -> 第一音節重音，stɪ 發短音。\n\n常見同義字：\ntrigger（引發某事的導火線、觸發物）\nimpetus（推動力、促進作用）\nprompt（促使行動的提示或刺激）",
  "sting": "諧音聯想：\n諧音：死釘諧音「蜜蜂狠狠給你的手臂死釘了一口，傷口開始 sting 刺痛」。\n\n聯想畫面 1：去公園草皮玩被毒蚊子叮咬，傷口又紅又癢還會 sting。\n\n聯想畫面 2：被朋友背叛的那句話像針一樣刺進心裡，讓人感到陣陣 sting。\n\n高效擴充：三態變化為 sting - stung - stung。\nKK 音標：[stɪŋ] -> 短母音 [ɪ] 搭配鼻音 [ŋ]，嘴巴微開。\n\n常見同義字：\n\nprick（刺痛、扎）\n\nsmart（刺痛、感到羞辱）\n\nburn（灼痛、燒痛）",
  "stingy": "諧音聯想：\n諧音：「死定去」要零錢，老闆真的非常小氣。\n\n聯想畫面 1：他每次聚餐結帳時都藉故去洗手間，大家私底下都覺得他很吝嗇。\n\n聯想畫面 2：這位富豪連捐一塊錢都要考慮半天，對金錢看得很緊。\n\n高效擴充：動詞 sting (刺、叮) 衍伸出像被針扎一樣不肯掏錢的吝嗇形象。\nKK 音標：[ˋstɪndʒi] -> 第一音節 stɪn 為主重音，字尾 gy 發 dʒi 的音。\n\n常見同義字：\nmean（小氣的、卑鄙的，英式口語常用來指吝嗇）\nmiserly（吝嗇的、守財奴般的，形容對錢財極度苛刻）\ntightfisted（吝嗇的、守財的，形象化指拳頭抓得很緊不肯花錢）",
  "stink": "諧音聯想：\n諧音：垃圾場發出惡臭，「死定客」人絕對不會想靠近。\n\n聯想畫面 1：打開冰箱發現過期三天的牛奶散發出令人作嘔的惡臭。\n\n聯想畫面 2：這場糟糕透頂的表現實在是令人厭惡。\n\n高效擴充：三態為 stink, stank, stunk。\nKK 音標：[stɪŋk] -> 鼻音 ng 結合 k，短促有力。\n\n常見同義字：\nsmell bad（氣味很差）\nreek（散發強烈惡臭）\nbe terrible（表現極糟糕）",
  "stir": "諧音聯想：\n諧音：死特諧音「煮咖啡時要用特製的湯匙輕輕 stir 攪拌均勻」。\n\n聯想畫面 1：媽媽在廚房煮濃湯時，拿著大湯勺不斷地 stir 攪拌以免燒焦。\n\n聯想畫面 2：這則八卦新聞一出，在網路上立刻 stir 激起軒然大波。\n\n高效擴充：三態變化為 stir - stirred - stirred（注意 r 要雙寫）。\nKK 音標：[stɝ] -> 捲舌音 [ɝ] 嘴巴微嘟，舌頭往後捲。\n\n常見同義字：\n\nmix（混合、攪拌）\n\nblend（融合成混合物）\n\nagitate（攪動、煽動）",
  "stitch": "諧音聯想：\n諧音：死結去諧音「衣服破了一個大洞，老奶奶趕快拿針線縫上 stitch 打死結去除破洞」。\n\n聯想畫面 1：醫生幫傷口縫了好幾針 stitch 才能順利癒合。\n\n聯想畫面 2：媽媽坐在窗邊一針一線地 stitch 幫你補好破掉的毛衣。\n\n高效擴充：常用片語 in stitches（笑得肚子痛、前俯後仰）。\nKK 音標：[stɪtʃ] -> 短母音 [ɪ] 結尾加上清晰的 [tʃ] 破擦音。\n\n常見同義字：\n\nsuture（外科縫合手術、縫線）\n\nsew（縫紉、做針線活）\n\ntack（固定、平縫）",
  "stock": "諧音聯想：\n諧音：「死踏客」\n\n聯想畫面 1：散戶死命踏進股市買股票，希望手上的庫存股價能大漲。\n\n聯想畫面 2：倉庫裡堆滿了滿滿的貨品庫存，老闆正忙著進貨與盤點。\n\n高效擴充：可作名詞與動詞，常出現在商業與金融英語中。\nKK 音標：[stɑk] -> 單音節字，ɑ 發短 o 音，結尾 k 清脆。\n\n常見同義字：\ninventory（詳細的庫存清單、盤點存貨）\nshares（具體的股票份額、股份）\nsupply（日常供應物資、儲備量）",
  "stockholder": "拆解：stock（股票）+ holder（持有者）。\n\n聯想畫面 1：股東大會上，大家都在討論公司未來的獲利情況。\n\n聯想畫面 2：他買了這家公司的股票，成為了小股東，每年都能領到股利。\n\n高效擴充：stock 是存貨或股票，holder 是持有者，合起來就是股東。\nKK 音標：[ˋstɑkhoʊldər] -> 重音在第一個音節 stock，holder 的 der 輕讀。\n\n常見同義字：\n\nshareholder（股東，最常用）\n\ninvestor（投資者）\n\nowner（所有者）。",
  "stocking": "諧音聯想：\n諧音：死踏金諧音「聖誕夜要把聖誕 stocking 長襪掛在床頭，期待裡面塞滿金幣」。\n\n聯想畫面 1：冬天穿靴子時一定要搭配厚實的毛料 stocking 保暖。\n\n聯想畫面 2：聖誕老人偷偷把禮物塞進小朋友的紅絲絨 stocking 裡。\n\n高效擴充：字根 stock 原意為庫存、樹幹，這裡指長筒襪。\nKK 音標：[ˋstɑkɪŋ] -> 主重音在 stɑk，後面的 ing 發鼻音。\n\n常見同義字：\n\nsock（短襪，低於腳踝或小腿肚）\n\nhose（長統襪、軟管）\n\ntights（緊身褲襪）",
  "stole": "諧音聯想：\n諧音：死偷。\n\n聯想畫面 1：小偷為了掩人耳目，披上一條華麗的長披肩，悄悄地偷走珠寶。\n\n聯想畫面 2：她穿著優雅的長袍，圍著絲綢聖帶，在舞會中悄悄地移動身形。\n\n高效擴充：steal 的過去式，不規則變化。\nKK 音標：[stoʊl] -> 發音時注意 oʊ 的雙母音，嘴型由大變小。\n\n常見同義字：\n\nShawl（披肩，指服飾）\n\nRobbed（搶劫，指暴力行為）\n\nFilched（偷竊，指小偷小摸）。",
  "stolen": "諧音聯想：\n諧音：死偷人。\n\n聯想畫面 1：那個小偷死偷人家的東西，最後被警察抓到了。\n\n聯想畫面 2：這件珠寶是被偷走的，現在成了證物。\n\n高效擴充：Steal 的過去分詞，形容詞用法表示被盜的。\nKK 音標：[ˋstoʊlən] -> 重音在第一個音節，發音時 o 的長音要飽滿。\n\n常見同義字：\n\nTheft（偷竊行為）\n\nRobbed（被搶劫的）。",
  "stomach": "諧音聯想：\n諧音：「死踏馬吃」\n\n聯想畫面 1：死命踩著馬蹄在吃東西，結果把自己的胃給撐壞了。\n\n聯想畫面 2：生氣到胃痛，直呼這口氣我實在吞不下、忍受不了。\n\n高效擴充：字尾 -mach 聯想到機器，胃就像消化食物的機器。\nKK 音標：[ˋstʌmək] -> 重音在第一音節 stʌ，唸短促的「史特」，後面 mək 念輕聲。\n\n常見同義字：\n\nbelly（指肚子或腹部，較口語日常）\n\nabdomen（指腹部，醫學或正式用法）\n\ntolerate（動詞忍受之義，比 stomach 當動詞更正式）",
  "stomachache": "諧音聯想：\n拆解：stomach（胃）＋ache（痛）。\n\n聯想畫面 1：吃太多冰淇淋導致肚子痛，抱著肚子在床上打滾。\n\n聯想畫面 2：緊張到胃痛，這就是典型的 stomachache。\n\n高效擴充：stomach 是胃，ache 是痛，合起來就是胃痛或肚子痛。\nKK 音標：[ˋstʌmək͵ek] -> 重音在第一個音節，注意 stomach 的 ch 發 k 音。\n\n常見同義字：\n\nbellyache（肚子痛，較口語）\n\nindigestion（消化不良）\n\ncramps（抽筋或腹部絞痛）。",
  "stone": "諧音聯想：\n諧音：「死動」\n\n聯想畫面 1：古代城堡的城牆是用巨大的石頭堆砌而成，怎麼推都死都不會動。\n\n聯想畫面 2：路邊撿到一顆閃閃發光的寶石，堅硬無比。\n\n高效擴充：常與 gemstone 搭配指寶石，或用 stonewalled 形容固執。\nKK 音標：[ston] -> 結合了 o 的圓唇音，發音時帶有鼻腔共鳴。\n\n常見同義字：\nrock（岩石，通常指較大或天然的岩塊）\npebble（鵝卵石，河床常見的小圓石）\ngem（寶石、珍寶，指有價值的礦石）",
  "stool": "諧音聯想：\n諧音：「死吐」\n\n聯想畫面 1：喝酒喝到坐在小凳子上，難過到快要死吐出來。\n\n聯想畫面 2：蹲在廁所的馬桶凳上，使勁想把大便排出來。\n\n高效擴充：字根 st- 開頭常與站立有關，凳子是讓人坐著但站立時常備的矮具。\nKK 音標：[stul] -> st 為子音群，ool 發長音的「嗚」，嘴型要嘟起來。\n\n常見同義字：\n\nchair（指一般有靠背的椅子）\n\nbench（指長凳，通常可坐多人）\n\nfeces（指排泄物大便，為正式醫學用語）",
  "stoop": "諧音聯想：\n諧音：「死偷撲」的賊只好彎腰駝背從低矮的門廊爬進去。\n\n聯想畫面 1：老爺爺年紀大了，走路總是有些駝背。\n\n聯想畫面 2：他為了撿起地上的零錢而俯身彎腰。\n\n高效擴充：stoop to something 意指卑躬屈膝或自甘墮落。\nKK 音標：[stup] -> 雙母音 oo 發長 u 音。\n\n常見同義字：\nbend（彎曲或彎腰）\ncrouch（蹲伏或蹲下）\nhunch（聳肩或駝背）",
  "stop": "諧音聯想：\n諧音：「死踏普」\n\n聯想畫面 1：紅燈亮起時，駕駛必須死死踏住煞車踏板讓車子停下來。\n\n聯想畫面 2：公車在站牌前停靠，讓乘客上下車。\n\n高效擴充：片語 stop doing 停止正在做的事 vs stop to do 停下來去做另一件事。\nKK 音標：[stɑp] -> 短母音 ɑ 口型張大，發音乾脆俐落不拖泥帶水。\n\n常見同義字：\nhalt（暫停、行進間的停止，較正式）\ncease（停止、終止，通常指動作或狀態的結束）\nquit（放棄、辭職，停止某種習慣或工作）",
  "storage": "諧音聯想：\n拆解 / 諧音：store (儲存) + age (名詞字尾)。\n\n諧音：把東西存起來的地方就是儲藏空間。\n\n聯想畫面 1：搬家時把暫時用不到的家具寄放在迷你倉的儲藏庫裡。\n\n聯想畫面 2：手機跳出警告通知，顯示內部儲存空間已經不足。\n\n高效擴充：動詞 store 轉名詞加上 age。\nKK 音標：[ˋstɔrədʒ] -> 重音在第一音節 sto，字尾 dʒ 念輕聲的吉。\n\n常見同義字：\nwarehouse（倉庫或貨棧）\nrepository（儲藏室或智囊庫）\nreserve（儲備或保留）",
  "store": "諧音聯想：\n諧音：「斯都噢」\n\n聯想畫面 1：斯都噢老闆把剛進貨的商品通通整齊地儲存在倉庫裡。\n\n聯想畫面 2：街角那間明亮的便利商店，販售各式各樣的生活用品。\n\n高效擴充：當動詞時常指把資料儲存在電腦記憶體中。\nKK 音標：[stɔr] -> 包含捲舌音 r，發音時嘴唇微圓向後拉。\n\n常見同義字：\nshop（商店，英式英語常用來指小店）\nwarehouse（倉庫、批發倉，大型儲存場所）\nsave（儲存、節省，電腦資料或金錢概念）",
  "storm": "諧音聯想：\n諧音：「死逃跑」\n\n聯想畫面 1：海上突然颳起恐怖的暴風雨，漁民們嚇得死逃跑（拼命往避難所奔去）。\n\n聯想畫面 2：氣象主播在電視上警告大家今晚有強烈暴風雪，不要出門。\n\n高效擴充：or 組合發低沉的「or」音，類似 born、horn。\nKK 音標：[stɔrm] -> st 音連讀，or 捲舌音要飽滿，r 帶出後鼻音。\n\n常見同義字：\ntempest（較文學色彩的猛烈暴風雨）\nblizzard（專指暴風雪）\ngale（指強風、大風）",
  "stormy": "諧音聯想：\n諧音：「死偷米」\n\n聯想畫面 1：暴風雨中農夫死命搶收稻米，風雨交加非常激烈。\n\n聯想畫面 2：會議室裡的討論氣氛非常暴風雨般激烈火爆。\n\n高效擴充：由 storm（暴風雨）加上 y 形成形容詞。\nKK 音標：[ˋstɔrmi] -> 重音在第一音節的 ˋstɔr。\n\n常見同義字：\ntempestuous（暴風雨的、劇烈的）\nrough（風浪大的、粗糙的）\nturbulent（動盪的、狂暴的）",
  "story": "諧音聯想：\n諧音：「斯兜力」\n\n聯想畫面 1：爺爺坐在搖椅上，費盡心思兜起一個精彩的故事說給孫子聽。\n\n聯想畫面 2：這棟大樓共有好幾層樓，每一層都有不同的歷史故事在發生。\n\n高效擴充：美式拼法 story，英式大樓樓層偶爾會拼作 storey。\nKK 音標：[ˋstɔri] -> 重音在第一音節 store，後面 ri 輕快短促。\n\n常見同義字：\ntale（傳說、故事，帶有神話或虛構色彩）\nnarrative（敘述、故事，文學或分析用語）\nfloor（樓層，大樓的實體層數）",
  "storybook": "拆解：story（故事）+ book（書本）\n\n諧音：思特力寶卡。\n\n聯想畫面 1：媽媽在床邊拿出一本精美的故事書，溫柔地唸給快要睡著的小孩聽。\n\n聯想畫面 2：圖書館的童書區擺滿了各種彩色插圖的故事書。\n\n高效擴充：標準的複合名詞，將 story 的 y 改成 i 再加 es 可以變成複數 stories。\nKK 音標：[ˈstɔːribʊk] -> 主重音在 [stɔː]，注意 [ɔː] 是長音。\n\n常見同義字：\n\nfairy tale（童話故事，通常指神奇魔幻的故事）\n\nfable（寓言故事，含有道德教訓）\n\nnovel（小說，篇幅較長給成人閱讀）",
  "storyline": "拆解：story（故事）+ line（線）。\n\n聯想畫面 1：電影的劇情像一條線（line）一樣串聯起整個故事（story），讓觀眾看得入迷。\n\n聯想畫面 2：這部小說的故事情節曲折離奇，讓人猜不到結局。\n\n高效擴充：把 story 和 line 組合起來，就是故事的脈絡。\nKK 音標：[ˋstɔri͵laɪn] -> 第一音節 sto 重音，注意長母音 o 的發音。\n\n常見同義字：\n\nplot（情節，較正式）\n\nnarrative（敘事，文學用語）\n\nscript（劇本）。",
  "stout": "諧音聯想：\n諧音：死踏 -> 諧音聯想：死命踏下去也很結實的胖子。\n\n聯想畫面 1：這位身材矮胖的摔角選手站得非常穩固。\n\n聯想畫面 2：大叔在酒吧裡點了一杯濃郁的烈性黑啤酒。\n\n高效擴充：常形容人體格壯碩或物品堅固。\nKK 音標：[staʊt] -> 單音節，st 結合雙母音 aʊ。\n\n常見同義字：\n\nsturdy（結實的）\n\nrobust（強健的）\n\nthickset（矮壯的）",
  "stove": "諧音聯想：\n諧音：「死偷挖」\n\n聯想畫面 1：小偷潛入廚房肚子餓，竟然把瓦斯爐死偷挖（想把整個瓦斯爐搬走變賣）。\n\n聯想畫面 2：冬天大家都圍坐在溫暖的火爐旁烤火取暖。\n\n高效擴充：字尾的 e 不發音，用來讓前面的 o 發長音 o。\nKK 音標：[stov] -> o 發長雙元音 o，v 是輕咬下唇的濁子音。\n\n常見同義字：\ncooker（常指電鍋或爐具）\nfurnace（大型暖爐或熔爐）\nheater（電暖器或加熱器）",
  "straight": "諧音聯想：\n諧音：「死追的」\n\n聯想畫面 1：賽車手在筆直的高速跑道上死追的（一直維持直線狂飆不轉彎）。\n\n聯想畫面 2：老師要求大家排隊要站直、排成一條直線，不可以歪七扭八。\n\n高效擴充：aigh 組合發長音 a，跟 weight、eight 同系列，拼字時 gh 不發音。\nKK 音標：[stret] -> aigh 發長音 e，尾音 t 輕輕咬住。\n\n常見同義字：\ndirect（直接的、筆直的，偏向方向或導引）\nright（正的、右邊或筆直的）\nline（線條，名詞居多）",
  "straighten": "諧音聯想：\n諧音：「死追聽」\n\n聯想畫面 1：老師死命追著學生聽話，終於把歪掉的桌椅全部弄直、排正。\n\n聯想畫面 2：法官抽絲剝繭，把這起複雜的案件來龍去脈徹底澄清、導向正軌。\n\n高效擴充：由形容詞 straight（直的）加上動詞字尾 -en 構成。\nKK 音標：[ˋstretən] -> 主重音在第一個音節 stre，ai 發長 e 音，t 輕念，en 弱化。\n\n常見同義字：\nunfurl（展開，指布旗等）\nalign（對齊，常指排版或機械校正）\ncorrect（糾正錯誤，使之正確）",
  "straightforward": "諧音聯想：\n拆解 / 諧音：straight（直的）加 forward（向前）。\n\n聯想畫面 1：這本說明書寫得很簡單易懂，一看就懂。\n\n聯想畫面 2：主管個性十分坦率，有話直說。\n\n高效擴充：由兩個常見基礎單字組合成的高頻複合形容詞。\nKK 音標：[ˋstretˋfɔrwɚd] -> 複合字，前段 stret 重音，後段 fɔrwɚd 次重音。\n\n常見同義字：\n\ndirect（直接的）\n\nfrank（坦率的）\n\nsimple（簡單的）",
  "straightforwardly": "拆解：straight（直的）+ forward（向前）+ -ly\n\n諧音：「直的往前走，坦率地說」\n\n聯想畫面 1：他在面試時直截了當地回答問題，態度非常坦率正直。\n\n聯想畫面 2：老闆說話向來不拐彎抹角，都是坦率地把意見講出來。\n\n高效擴充：由形容詞 straightforward 去字尾加 -ly 形成副詞。\nKK 音標：[͵streɪtˋfɔrwərdli] -> 主重音落在第二個字的中間 fɔr，長音要出來。\n\n常見同義字：\n\nopenly（公開地、坦白地）\n\nfrankly（坦白說，常用於句首作為插入語）\n\ndirectly（直接地、坦率地）",
  "strain": "諧音聯想：\n諧音：「死追因」果關係讓人感到身心焦慮與精神緊張。\n\n聯想畫面 1：運動員在比賽中不小心拉傷了肌肉，感到一陣劇痛。\n\n聯想畫面 2：期末考前的巨大壓力與負擔讓人快要喘不過氣。\n\n高效擴充：常與 muscle strain（肌肉拉傷）一起記憶。\nKK 音標：[stren] -> 雙母音 ai 發長 e 音。\n\n常見同義字：\nstress（壓力或緊張）\ntension（張力或緊繃）\nsprain（扭傷關節）",
  "strait": "諧音聯想：\n諧音：「死追特」務的船隻被迫開進狹窄的海峽。\n\n聯想畫面 1：兩艘貨輪正小心翼翼地通過狹窄的水道。\n\n聯想畫面 2：公司面臨資金周轉不靈的嚴重困境。\n\n高效擴充：常用複數 straits 來表示困境或窘境。\nKK 音標：[stret] -> 拼法雖有 i 但發長 e 音。\n\n常見同義字：\nchannel（海峽或頻道）\ndifficulty（困難或窘境）\nnarrow（狹窄的）",
  "strand": "諧音聯想：\n諧音：「死傳的」那一股繩絲，竟然是唯一的救命索。\n\n聯想畫面 1：颱風天導致班機停飛，許多旅客滯留在機場動彈不得。\n\n聯想畫面 2：一隻巨鯨不幸在沙灘上擱淺。\n\n高效擴充：a strand of hair 意指一縷頭髮。\nKK 音標：[strænd] -> 複合子音 str 開頭，夾短 a 音。\n\n常見同義字：\nlock（一綹頭髮）\nmaroon（放逐或使孤立）\nground（使擱淺或落地）",
  "strange": "諧音聯想：\n諧音：「死追緊」，對一個奇怪的陌生人死追緊跟。\n\n聯想畫面 1：在路上遇到一個打扮非常奇怪且不認識的陌生人。\n\n聯想畫面 2：聽到一件很不尋常的八卦傳聞，覺得事情不單純。\n\n高效擴充：字尾 ange 容易讓人聯想到 change，改變常會帶來陌生感。\nKK 音標：[strendʒ] -> 結合了 [str] 子音群與結尾的 [dʒ] 摩擦音，語氣要上揚。\n\n常見同義字：\n\nunusual（不尋常的，指超出常理）\n\nodd（奇特的，帶有一點古怪意味）\n\nbizarre（怪異的、荒誕的，通常形容極端不尋常的事物）",
  "stranger": "諧音聯想：\n諧音：「死追居」\n\n聯想畫面 1：走在異國的小鎮上，背後突然出現一個形跡可疑的陌生人死追居（緊追不捨）。\n\n聯想畫面 2：媽媽從小教育我們不可以跟陌生人拿糖果或上車。\n\n高效擴充：字尾 er 表示「人」，結合 strange（奇怪的）變成「奇怪的人/生面孔」。\nKK 音標：[ˋstrendʒɚ] -> 第一音節 stre 重讀，dʒ 發 j 的清脆摩擦音。\n\n常見同義字：\nforeigner（外國人、外地人）\nunknown（未知的、不明人士）\noutsider（外人、局外人）",
  "strangle": "諧音聯想：\n諧音：「死抓狗」\n\n聯想畫面 1：壞人死抓狗的脖子不放，簡直是勒死、扼住小動物。\n\n聯想畫面 2：掐住咽喉悶住呼吸，意圖謀害。\n\n高效擴充：字根 strang (緊縮、壓迫) 加上 gle。\nKK 音標：[ˋstræŋɡəl] -> 第一音節重音，stran 發短音 a，gle 為輕聲。\n\n常見同義字：\n\nchoke（哽咽或窒息、掐住，日常較常用）\n\nsuffocate（窒息，通常指缺氧而死）\n\nthrottle（節流閥或掐脖子，機械或動作皆可）",
  "strap": "諧音聯想：\n諧音：「死抓屁」股上的安全帶皮帶不放。\n\n聯想畫面 1：用皮帶把行李箱緊緊捆紮好以防散開。\n\n聯想畫面 2：背包的背帶斷了，只好先用繩子綁起來。\n\n高效擴充：bra strap 意指內衣肩帶。\nKK 音標：[stræp] -> 短 a 發音，嘴巴要上下張開。\n\n常見同義字：\nbelt（皮帶或腰帶）\nband（帶子或條紋）\nfasten（扣緊或綁牢）",
  "strapping": "諧音聯想：\n諧音：「死抓品」\n\n聯想畫面 1：搬家工人死命抓著重型物品，展現出他那高大健壯的魁梧身形。\n\n聯想畫面 2：籃球場上那位身材高大健壯的球員，輕易地搶下所有籃板球。\n\n高效擴充：由 strap（皮帶、用帶子捆紮）加上 -ing 轉為形容詞，原意指身形強壯得像能用皮帶束縛。\nKK 音標：[ˋstræpɪŋ] -> 第一音節 [stræp] 為主重音，注意æ的開口音。\n\n常見同義字：\nrobust（強健的，強調身體健康有活力）\nsturdy（結實的，強調結構或體格穩固耐操）\nsylphlike（苗條的，此為反義聯想，指輕盈瘦弱）",
  "stratagem": "諧音聯想：\n諧音：死抓他整。\n\n聯想畫面 1：為了贏得比賽，他想出一個死抓他整的計謀，讓對手防不勝防。\n\n聯想畫面 2：間諜電影裡，主角運用高超的 stratagem 成功潛入敵營。\n\n高效擴充：源自希臘文 stratos（軍隊）+ agein（帶領），指軍事上的調度計謀。\nKK 音標：[ˋstrætədʒəm] -> 第一音節 stra 重讀，發音像中文的「死抓」，後面輕讀。",
  "strategic": "諧音聯想：\n諧音：「死抓替擊可」－打電動時死命抓著替補角色攻擊對手，這就是贏遊戲的關鍵戰略。\n\n聯想畫面 1：公司高層在會議室白板前開會，詳細規畫明年度的市場拓展策略與戰略佈局。\n\n聯想畫面 2：軍事指揮官在沙盤前推演，決定在幾個重要的戰略據點部署兵力。\n\n高效擴充：由 noun strategy（戰略）變化而來的形容詞，字尾 -ic 用來表示「...的性質」。\nKK 音標：[strəˋtidʒɪk] -> 重音落在第二音節 te，唸輕柔的 i 音，注意吉字的發音像 dʒɪk。\n\n常見同義字：\n\ncalculated（經過計算的，強調有計畫的）\n\nplanned（計畫好的，較口語的說法）\n\ncrucial（關鍵的，強調具有決定性影響的）",
  "strategy": "諧音聯想：\n拆解 / 諧音：死抓特級\n\n諧音：「死抓特級」\n\n聯想畫面 1：打遊戲時死命抓著特級寶物不放，這就是我獲勝的策略。\n\n聯想畫面 2：商場上的商業戰略，必須死死抓住民眾的特級需求。\n\n高效擴充：字首 strat- 源自古希臘語的軍隊，引申為戰略。\nKK 音標：[ˋstrætədʒi] -> 主重音在第一音節 stræt，唸「史特雷」，後面字尾 -egy 唸「特吉」。\n\n常見同義字：\n\nplan（指一般計劃，範圍較廣）\n\ntactic（指具體的戰術或手段，較為細節）\n\napproach（指處理問題的方法或途徑）",
  "straw": "諧音聯想：\n諧音：「死抓」\n\n聯想畫面 1：喝珍珠奶茶時，吸管插進杯子裡，嘴巴死抓著吸管不放。\n\n聯想畫面 2：稻田收割後地上留下一捆捆乾燥的稻草，風一吹到處飛散。\n\n高效擴充：aw 組合發「ㄛ」音，類似 draw、law。\nKK 音標：[strɔ] -> st 開頭，raw 發長音 ɔ，嘴型張大。\n\n常見同義字：\nhay（乾草，通常用來餵食牲畜）\nstraw（特指吸管或稻草桿）",
  "strawberries": "拆解：straw（稻草）+ berry（莓果）\n\n諧音：死抓八粒死。\n\n聯想畫面 1：紅通通的草莓長在稻草堆旁，讓人忍不住想「死抓八粒死」通通吃下肚。\n\n聯想畫面 2：蛋糕上面放了一顆新鮮的草莓，酸酸甜甜的滋味深受大家喜愛。\n\n高效擴充：字尾 y 去掉加上 ies 形成複數形，單數為 strawberry。\nKK 音標：[ˋstrɔ͵bɛrɪz] -> 主重音在 [strɔ]，發音時嘴巴微張念長音。\n\n常見同義字：\n\nblueberries（藍莓，常見的高營養莓果）\n\nraspberries（覆盆子，也是帶有酸甜口感的莓果）\n\nblackberries（黑莓，外型類似但顏色較深）",
  "strawberry": "諧音聯想：\n諧音：「死抓貝莉」\n\n聯想畫面 1：女孩貝莉去採草莓，手上死抓著一籃鮮紅欲滴的草莓不給別人看。\n\n聯想畫面 2：生日蛋糕上鋪滿了新鮮的草莓與奶油，看起來非常誘人。\n\n高效擴充：結合 straw（稻草）和 berry（漿果）複合字，字面意思是草地上的漿果。\nKK 音標：[ˋstrɔb͵ɛri] -> 第一音節 straw 重讀，berry 輕讀唸 breezy 的 e 音。\n\n常見同義字：\nberry（泛指所有莓果類）\nraspberry（樹莓、覆盆子）\nblueberry（藍莓）",
  "stray": "諧音聯想：\n諧音：「死追」著不放的結果就是迷路走失。\n\n聯想畫面 1：路邊看到一隻毛髮凌亂的流浪動物。\n\n聯想畫面 2：登山客不小心偏離了原本的健行步道。\n\n高效擴充：stray dog 代表流浪狗。\nKK 音標：[stre] -> 結尾的 ay 發長 e 音。\n\n常見同義字：\nwandering（流浪的或漫遊的）\nhomeless（無家可歸的）\nderelict（被遺棄的）",
  "streak": "諧音聯想：\n諧音：「死追客」人拍下他身上奇特的條紋刺青。\n\n聯想畫面 1：流星劃過夜空，在天邊留下了一道明亮的條痕。\n\n聯想畫面 2：他最近運氣很好，連續贏了好幾場比賽創下連勝紀錄。\n\n高效擴充：winning streak 代表連勝紀錄。\nKK 音標：[strik] -> 長 e 的 i 音，發音拉長。\n\n常見同義字：\nstripe（條紋或斑紋）\nline（線條或痕跡）\nrun（持續的一段時間或運勢）",
  "stream": "諧音聯想：\n諧音：「死追姆」\n\n聯想畫面 1：小溪裡的水源源不絕地流動，魚兒在裡面死追姆（拼命逆流而上）。\n\n聯想畫面 2：網路直播主正在進行線上串流（stream）轉播，粉絲瘋狂刷留言。\n\n高效擴充：ea 發長音，與 steam 拼法類似，指的是流動的水氣或水流。\nKK 音標：[strim] -> st 連音，tri 緊接著長音 i，m 結尾。\n\n常見同義字：\ncreek（小溪、小河）\nbrook（小河川，較詩意）\nriver（河流，規模比 stream 大）",
  "streamline": "拆解：stream（流）+ line（線）。\n\n聯想畫面 1：跑車設計成流線型，讓空氣像水流一樣滑過，達到精簡阻力的效果。\n\n聯想畫面 2：公司為了提升效率，決定簡化繁瑣的行政流程。\n\n高效擴充：streamline 意指讓事物像流體一樣順暢，引申為簡化、精簡。\nKK 音標：[ˋstrim͵laɪn] -> 第一音節 stream 重音，注意長母音 i 的發音。\n\n常見同義字：\n\nsimplify（簡化，通用）\n\nstreamline（精簡，強調效率）\n\noptimize（優化）。",
  "street": "諧音聯想：\n諧音：「死追特」\n\n聯想畫面 1：小狗在熱鬧的街道上死命追著特技表演的球跑。\n\n聯想畫面 2：兩旁林立著商店的馬路上，車水馬龍非常熱鬧。\n\n高效擴充：常縮寫為 St. 用於地址中，如 Main Street。\nKK 音標：[strit] -> 長母音 i 聲音拉長，嘴角向兩側咧開。\n\n常見同義字：\nroad（道路，連接兩地的馬路）\navenue（林蔭大道、大街，多指寬闊的街道）\nlane（小巷、弄，較窄的街道）",
  "streetwise": "諧音聯想：\n拆解 / 諧音：街頭（street）＋智慧（wise）\n\n聯想畫面 1：在複雜的街頭混久了，自然就練就了一身生存的智慧，知道哪裡危險不能去。\n\n聯想畫面 2：他看起來很精明，一看就是那種在都市叢林中能保護自己、適應力極強的人。\n\n高效擴充：這是兩個單字的組合，street 代表街道，wise 代表聰明，合起來就是街頭生存智慧。\nKK 音標：[ˋstritwaɪz] -> 重音在第一個音節 street，發音要像街道一樣寬廣，wise 則要發出清脆的 z 音。\n\n常見同義字：\nshrewd（精明的，指看穿事物的能力）\nsavvy（有見識的，特別指對某領域很內行）\nworldly-wise（世故的，指對社會運作很了解）",
  "strength": "諧音聯想：\n諧音：「死轉硬死」\n\n聯想畫面 1：靠著超強的力量，把緊閉的鐵門死命轉開直到硬生生弄死。\n\n聯想畫面 2：大力士展現體力與實力，肌肉線條硬梆梆充滿力量。\n\n高效擴充：由形容詞 strong 變化而來的名詞，字尾加上 -gth 表示性質。\nKK 音標：[strɛŋkθ] -> strɛŋ 為鼻音結合，結尾的 -gth 要輕咬舌尖發出 θ 的摩擦音。\n\n常見同義字：\n\npower（泛指權力或能量）\n\nforce（強調物理上的衝擊力或暴力）\n\nstamina（指耐力與持久力，偏向體能）",
  "strengthen": "諧音聯想：\n拆解 / 諧音：「死得硬死得硬」\n\n諧音：每天狂做伏地挺身讓肌肉「死得硬死得硬」，徹底加強身體的強度與韌性。\n\n聯想畫面 1：情侶透過深度溝通與誠實以對，把彼此脆弱的感情關係變得更加緊密。\n\n聯想畫面 2：國家為了防範颱風來襲，動員志工用沙包加強堤防設施的結構。\n\n高效擴充：strength（力量，名詞）加上字尾 en（使成為），合起來就是動詞的使強壯與加強。\nKK 音標：[ˋstrɛŋθən] -> 重音在第一音節 strength，注意中間的 ng 發音位置。\n\n常見同義字：\nreinforce（加強，常用於建築結構或軍事增援）\nbuild up（逐步建立與增強，片語用法）\nfortify（築防強化，強調防禦力提升）",
  "strenuous": "諧音聯想：\n諧音：「死揣努力烏斯」\n\n聯想畫面 1：爬玉山是一項非常費力且艱苦的任務，必須拼命往上爬。\n\n聯想畫面 2：他積極堅決地推動改革，付出極大心力。\n\n高效擴充：字根源自力量，專門用來形容體力或心力消耗極大的艱辛狀況。\nKK 音標：[ˋstrenjuəs] -> 重音在第一音節 ˋstren，注意接 uəs 的連音。\n\n常見同義字：\n\narduous（艱辛的，費力的）\n\ntaxing（負擔沉重的，費力的）\n\nvigorous（精力充沛的，激烈的）",
  "strep": "諧音聯想：\n諧音：「死掉」。\n\n聯想畫面 1：喉嚨感染了鏈球菌，感覺喉嚨快死掉了一樣。\n\n聯想畫面 2：醫生診斷出是鏈球菌感染，開了抗生素。\n\n高效擴充：Streptococcus 的縮寫。\nKK 音標：[strep] -> 發音短促有力，重音在第一個音節。\n\n常見同義字：\n\nStreptococcus（鏈球菌，正式學名）\n\nSore throat（喉嚨痛，症狀描述）。",
  "stress": "諧音聯想：\n諧音：「死追死」\n\n聯想畫面 1：期末考壓力大到快抓狂，腦袋裡好像有兩個聲音在死追死（互相逼迫）。\n\n聯想畫面 2：老闆在會議上不斷強調（stress）這個專案的重要性，讓大家精神緊繃。\n\n高效擴充：雙寫 s 結尾，當動詞時有「強調、重讀」的意思，名詞則是壓力。\nKK 音標：[strɛs] -> st 開頭，短母音 ɛ 嘴形扁平，尾音 s 拉長。\n\n常見同義字：\npressure（具體的壓力或壓迫感）\ntension（緊張局勢、心理張力）\nemphasize（動詞，強調、著重）",
  "stretch": "諧音聯想：\n諧音：「死追奇」\n\n聯想畫面 1：早晨起床做伸展操，把筋骨死追奇（拉得開開的）才覺得舒暢。\n\n聯想畫面 2：這件運動褲非常有彈性，可以無限拉長而不破裂。\n\n高效擴充：tch 組合發輕快的「ㄔ」音，類似 watch、catch。\nKK 音標：[strɛtʃ] -> str 開頭，ɛ 短音，tch 發清脆的「區/取」尾音。\n\n常見同義字：\nextend（延長、延伸，較正式）\nelongate（拉長、變細）\nexpand（擴大、膨脹）",
  "strict": "諧音聯想：\n諧音：「死抓去特」訓導主任規定超嚴格。\n\n聯想畫面 1：這位教練對球員的要求非常 strict，每天都要加練體能。\n\n聯想畫面 2：公司有 strict 的門禁規定，遲到一分鐘都會被記點。\n\n高效擴充：字尾 ct 結尾的形容詞，名詞為 strictness。\nKK 音標：[strɪkt] -> 單音節字，str 結合音，短音 i 念力。\n\n常見同義字：\nstern（嚴厲的、嚴苛的）\nstringent（嚴格的、緊縮的，多用於法規）\nrigorous（嚴密的、嚴格的）",
  "stride": "諧音聯想：\n諧音：「死呆得」－這群人站得死呆得，突然大步跨出去，展現帥氣的步姿。\n\n聯想畫面 1：模特兒伸展台上跨著大步，展現自信的步姿。\n\n聯想畫面 2：警察大步流星跨越封鎖線，執行任務。\n\n高效擴充：字尾 de 結尾，三態為 stride, strode, stridden。\nKK 音標：[straɪd] -> 主重音在長母音 ㄞ 上，嘴型要由開到合，念得俐落有力。\n\n常見同義字：\nstep（指一般的步伐或步驟，較為日常口語）\npace（指行走的速率或節奏，強調快慢）\nwalk（最基礎的步行動作，泛指走路）",
  "strident": "諧音聯想：\n諧音：死拽（台語發音，意指強硬、拽）\n\n聯想畫面 1：那個人說話的聲音非常刺耳，態度又死拽死拽的，讓人聽了很不舒服。\n\n聯想畫面 2：抗議現場傳來尖銳激烈的口號聲，這種 strident 的聲音充滿了強硬的對抗感。\n\n高效擴充：strid 字根與 stride（大步走）有關，聯想大步走時發出的強烈聲響。\nKK 音標：[ˋstraɪd(ə)nt] -> 重音在第一音節，注意 str 的連音發音要乾脆。\n\n常見同義字：\nshrill（尖銳的，強調高頻刺耳）\nharsh（粗糙的，強調不悅耳）\nforceful（強硬的，強調力度）",
  "strike": "諧音聯想：\n諧音：「死來客」\n\n聯想畫面 1：工廠員工集體發起罷工，大喊「死來客」（老闆不加薪就死不來客氣工作）。\n\n聯想畫面 2：打保齡球時一球全倒（strike），全場開心歡呼。\n\n高效擴充：i-e 結尾的長音 i，類似 bike、like。\nKK 音標：[straɪk] -> str 音滑向長雙元音 aɪ，尾音 k 俐落收尾。\n\n常見同義字：\nhit（打、擊中，最普遍的用字）\nwalkout（名詞，指罷工抗議）\nattack（攻擊、襲擊）",
  "string": "諧音聯想：\n諧音：「死盯」\n\n聯想畫面 1：貓咪對著毛線球死盯著看，然後用爪子撥弄那條細繩。\n\n聯想畫面 2：吉他的弦（string）斷了一根，彈奏起來聲音怪怪的。\n\n高效擴充：ing 結尾鼻音，與 ring、sing 同韻，字根表示線狀或纖維物。\nKK 音標：[strɪŋ] -> st 開頭，短 i 後接後鼻音 ŋ，舌根頂住軟顎。\n\n常見同義字：\ncord（粗繩、電線）\nthread（縫衣線、細線）\nrope（粗索、繩子）",
  "strip": "諧音聯想：\n諧音：「撕直剝」\n\n聯想畫面 1：把膠帶撕成一條一條直的帶狀物。\n\n聯想畫面 2：脫衣舞孃在舞台上把衣服一層一層撕掉剝除。\n\n高效擴充：注意與 step（腳步）的拼法區分，strip 中間多了 r。\nKK 音標：[strɪp] -> 發短音的 i，結尾 p 輕輕閉氣爆破。\n\n常見同義字：\n\nremove（移除，較為通用正式）\n\npeel（專指剝果皮或表皮）\n\nband（指帶狀物，名詞時與 strip 互通）",
  "stripe": "諧音聯想：\n諧音：「死來拍」－斑馬身上的黑白條紋太好看，吸引大家死來拍個不停。\n\n聯想畫面 1：囚犯身上穿著經典的黑白條紋服裝。\n\n聯想畫面 2：老虎背上的黃黑相間斑紋非常顯眼。\n\n高效擴充：與 strip（剝去）拼法相似，多一個 e 變成條紋。\nKK 音標：[straɪp] -> 結尾的 p 要輕輕閉氣爆破，注意母音 ㄞ 的長音。\n\n常見同義字：\nline（指一般的線條或界線，範圍較廣）\nstreak（指條紋、斑紋，或指連續的一陣子）\nband（指帶狀的條紋或束帶）",
  "strive": "諧音聯想：\n諧音：「死來」活去地拼命，為了夢想不顧一切地努力奮鬥。\n\n聯想畫面 1：創業者在地下室沒日沒夜地苦幹實幹，只為了讓公司能生存下去。\n\n聯想畫面 2：選手在賽場上咬緊牙關奮力衝刺，展現永不放棄的奮鬥精神。\n\n高效擴充：和 strive 拼法類似的常考字有 stride（大步走）與 strip（剝除），注意不要混淆。\nKK 音標：[straɪv] -> 單音節字，str 子音群要連貫，v 記得咬下唇發音。\n\n常見同義字：\nstruggle（掙扎與奮鬥，強調過程艱辛）\nendeavor（努力與嘗試，較正式的書面用語）\ntry hard（努力嘗試，口語常用表達）",
  "strode": "諧音聯想：\n諧音：死（s）＋trode（拖的）。\n\n聯想畫面 1：他大步走過來，腳步聲響亮，完全沒有拖泥帶水。\n\n聯想畫面 2：巨人跨越了小溪，一步就到了對岸。\n\n高效擴充：stride 的過去式，形容自信且快速的步伐。\nKK 音標：[stroʊd] -> 單音節，注意 o 的長母音。\n\n常見同義字：\n\nwalked（走）\n\nmarched（行軍般地走）。",
  "stroke": "諧音聯想：\n諧音：「死抽客」\n\n聯想畫面 1：老爺爺突然血管阻塞中風，身體像被抽乾力氣般倒下。\n\n聯想畫面 2：溫柔地用手輕撫貓咪的頭部，讓牠舒服得呼嚕呼嚕叫。\n\n高效擴充：字首 str 有緊繃或拉扯感，與 stretch 同源。\nKK 音標：[strok] -> 重音在 trok，長母音 o 嘴型要由圓變扁。\n\n常見同義字：\n\nblow（打擊，指突發的衝擊）\n\ncaress（愛撫，指溫柔的觸摸）\n\nhit（擊打，泛指一般碰擊動作）",
  "stroll": "諧音聯想：\n諧音：「死抓肉」－減肥的人散步怕抓到身上的肥肉，只好每天去公園輕鬆閒逛。\n\n聯想畫面 1：老夫婦黃昏時在河濱公園悠閒散步。\n\n聯想畫面 2：觀光局推廣慢活旅遊，鼓勵遊客在老街散步閒逛。\n\n高效擴充：字尾 ll 發音為暗 L，雙寫 l 要注意。\nKK 音標：[strol] -> 雙唇由扁到圓發出 ㄛ 的滑音，語調輕鬆悠閒。\n\n常見同義字：\nwalk（泛指走路散步，最普遍用語）\nwandering（指漫無目的、四處流浪閒逛）\nambulate（醫學或正式用語的行走活動）",
  "strong": "諧音聯想：\n諧音：「死壯」，拼命健身練到肌肉死壯死壯的。\n\n聯想畫面 1：大力士選手展現出強壯的肌肉與強大的力量。\n\n聯想畫面 2：今天吹起了一陣強烈的颱風，把招牌都吹垮了。\n\n高效擴充：與 weak 剛好相反，字尾 ong 念起來很有共鳴感。\nKK 音標：[strɔŋ] -> 鼻音 [ŋ] 結尾，舌頭後部要抬高頂住軟顎。\n\n常見同義字：\n\npowerful（強大的，指具備強大權力或效能）\n\nmuscular（肌肉發達的，強調體格健壯）\n\nbrawny（魁梧的，通常形容身材粗壯有力）",
  "structural": "諧音聯想：\n拆解 / 諧音：structure（結構）的形容詞型。\n\n聯想畫面 1：工程師正在檢查這棟大樓的建築結構安全。\n\n聯想畫面 2：公司進行了重大的組織架構調整。\n\n高效擴充：由名詞 structure 變化而來。\nKK 音標：[ˋstrʌktʃɚəl] -> 重音在第一音節 strʌk，tʃɚəl 輕讀。\n\n常見同義字：\n\narchitectural（建築上的）\n\nfoundational（基礎的）\n\norganizational（組織上的）",
  "structure": "諧音聯想：\n拆解 / 諧音：死抓快車\n\n諧音：「死抓快車」\n\n聯想畫面 1：坐雲霄飛車時必須死抓著把手，才能維持車體結構的穩定。\n\n聯想畫面 2：建築物的結構非常扎實，就算快車撞上也不會倒塌。\n\n高效擴充：字根 struct 意思是建造，許多相關單字如 construct 都有建造之意。\nKK 音標：[ˋstrʌktʃɚ] -> 主重音在第一音節 strʌk，結尾 -ture 發「區ㄦ」的音。\n\n常見同義字：\n\nbuilding（指一般建築物）\n\nframework（指框架、結構體，常用於抽象概念）\n\norganization（組織或結構安排）",
  "struggle": "諧音聯想：\n諧音：「死抓狗」\n\n聯想畫面 1：面對兇猛的大狗，你死抓狗的脖子不放，雙方在地上痛苦掙扎與奮鬥。\n\n聯想畫面 2：出社會後為了生活三餐，每個人都在工作崗位上咬緊牙關、使勁搏鬥。\n\n高效擴充：字首 st- 代表堅定或站立，搭配 ruggle 想像用力拉扯的動作。\nKK 音標：[ˋstrʌɡəl] -> 重音在第一音節 strʌ，短母音 u 發短促的「啊」音。\n\n常見同義字：\n\nstrive（努力奮鬥，較為正式且積極）\nfight（打鬥、搏鬥，口語常用）\nconflict（衝突、鬥爭，通常指意見或利益不合）",
  "sts": "諧音聯想：\n拆解：S（特殊）T（處理）S（鋼）\n\n聯想畫面 1：這艘船的鋼板是 STS 特殊處理鋼，非常堅固耐用。\n\n聯想畫面 2：通訊系統中 STS 代表艦對岸傳輸，確保訊息準確傳達。\n\n高效擴充：這是一個縮寫，根據上下文判斷是軍事還是工業用語。\nKK 音標：<[es ti es]> -> 唸出三個字母的發音，簡潔有力。\n\n常見同義字：\nsteel（鋼，通稱）\ncommunication（通訊，指傳輸功能）\nprocess（處理，指加工過程）",
  "stubborn": "諧音聯想：\n諧音：「死大幫」\n\n聯想畫面 1：這個老大幫派成員非常頑固倔強，怎樣都不肯認錯。\n\n聯想畫面 2：這頑固的污漬很難清洗去除，讓人超級頭痛。\n\n高效擴充：stub 指樹樁，像樹樁一樣死守不動就是頑固。\nKK 音標：[ˋstʌbɚn] -> 重音在第一音節的 ˋstʌ。\n\n常見同義字：\nobstinate（頑固的、固執的，較正式）\nheadstrong（任性的、剛愎自用的）\ninflexible（固執的、不通融的）",
  "stuck": "諧音聯想：\n諧音：死打克\n\n聯想畫面 1：車子輪胎陷在泥巴裡，怎麼踩油門都死打克（stuck），完全動不了。\n\n聯想畫面 2：被困在電梯裡，就像被卡住一樣，讓人感到無助。\n\n高效擴充：stick 的過去式，想像東西被黏住、插住的樣子。\nKK 音標：[stʌk] -> 單音節，發音短促有力，像東西卡住的聲音。\n\n常見同義字：\njammed（塞住的）\nfixed（固定的）\nimmobilized（無法移動的）",
  "student": "諧音聯想：\n諧音：「死讀冷特」\n\n聯想畫面 1：期末考前苦讀的學生，在寒冷的圖書館裡死命讀書。\n\n聯想畫面 2：大學講堂裡專心聽講的學者與求學青年。\n\n高效擴充：字根 stud 代表學習，ent 為人稱字尾，指學習的人。\nKK 音標：[ˋstudənt] -> 重音在 stu，dent 念輕聲，發音清晰有精神。\n\n常見同義字：\npupil（小學生，年紀較小的學童）\nscholar（學者、獎學金得主，學術成就高的人）\nlearner（學習者，泛指任何在吸收新知的人）",
  "studied": "諧音聯想：\n諧音：死（stu）＋ 讀（died）\n\n聯想畫面 1：他為了考試徹夜苦讀，最後終於取得了優異的成績。\n\n聯想畫面 2：她那刻意的微笑讓人感到不自然，顯然是精心策劃過的表情。\n\n高效擴充：study 的過去式，形容詞用法則帶有刻意、不自然的意味。\nKK 音標：[ˋstʌdid] -> 重音在第一個音節，注意 ed 的發音為 d。\n\n常見同義字：\nlearned（學習過的，強調知識累積）\ncalculated（計算過的，強調刻意為之）\ndeliberate（深思熟慮的，強調有計畫的）",
  "studio": "諧音聯想：\n諧音：「死肚兜」\n\n聯想畫面 1：模特兒在攝影工作室裡，穿著奇特的死肚兜拍照。\n\n聯想畫面 2：藝術家在畫室工作室裡創作，地上散落著顏料。\n\n高效擴充：由 study（學習、研究）衍生而來，專指創作或工作的空間。\nKK 音標：[ˋstudi͵o] -> 主重音在第一個音節 stu，唸「史都」，後面接 o。\n\n常見同義字：\n\nworkshop（工作坊、車間）\n\natelier（藝術家的工作室，較法式優雅）\n\noffice（一般辦公室）",
  "study": "諧音聯想：\n諧音：「斯達得」\n\n聯想畫面 1：斯文的達人想要得到好成績，每天都在書房裡努力認真研究和學習。\n\n聯想畫面 2：你在咖啡廳裡仔細看著調查報告，全神貫注地攻讀每一個重點。\n\n高效擴充：字根 stu 代表用力、渴望，讀書需要投注全力。\nKK 音標：[ˋstʌdi] -> 重音在第一音節 stʌ，短母音 u 發短促的 /ʌ/ 聲。\n\n常見同義字：\n\nlearn（學習新技能，偏向實作與吸收）\n\nresearch（專門的學術研究、調查，較正式）\n\nexamine（仔細審視、檢查，與 study 的仔細看意思相通）",
  "stuff": "諧音聯想：\n諧音：「塞夫（把東西塞進包包裡）」\n\n聯想畫面 1：出門前把一堆雜七雜八的東西通通塞進行李箱裡。\n\n聯想畫面 2：把火雞肚子裡塞滿填料，準備烘烤。\n\n高效擴充：口語中常用 stuff 來代替 things（東西），泛指各種物品。\nKK 音標：[stʌf] -> 發短促的 ʌ 音，結尾 f 輕咬下唇送氣。\n\n常見同義字：\n\nthing（指具體或抽象的事物，最常用）\n\nmaterial（指材料或物質）\n\nfill（當動詞填滿時的同義字）",
  "stumble": "諧音聯想：\n諧音：「死探步」－視線不清摸黑走路，死命探步結果不小心絆倒了。\n\n聯想畫面 1：喝醉酒的人走路跌跌撞撞，差點被石階絆倒。\n\n聯想畫面 2：登山客在泥濘山路中失足，踉蹌了一下。\n\n高效擴充：字尾 ble 通常發輕聲的 寶。\nKK 音標：[ˋstʌmbəl] -> 主重音在第一音節 stum，唸得短促有力。\n\n常見同義字：\ntrip（指因為被東西勾到而絆倒或失足）\nslip（指因為地面濕滑而滑倒）\nstagger（指因疲憊或喝酒而搖晃、蹣跚）",
  "stump": "諧音聯想：\n諧音：「死探撲」－砍樹只剩樹樁，害路人死命探頭查看還往前撲倒。\n\n聯想畫面 1：伐木過後，地上留下一截粗大的樹樁。\n\n聯想畫面 2：政治人物站在樹樁上發表演說，或形容題目太難把人考倒。\n\n高效擴充：結合 stumped（困惑的）作為形容詞使用。\nKK 音標：[stʌmp] -> 短母音 ㄚ 加上鼻音與爆破音 mp，發音扎實。\n\n常見同義字：\ntrunk（指樹木的主幹，較為完整）\nstub（指短殘留物或菸蒂、票根）\nlog（指砍下的圓木或木材）",
  "stun": "諧音聯想：\n諧音：「死碳」\n\n聯想畫面 1：瓦斯外洩產生一氧化碳，把屋內的人全部毒得昏迷不醒。\n\n聯想畫面 2：聽到中樂透頭獎的消息，他當場大吃一驚，驚訝到說不出話來。\n\n高效擴充：字尾 -un 唸短促的 [ʌ]，注意與 stand 的拼法區分。\nKK 音標：[stʌn] -> 單音節字，短母音 ʌ 喉音要短促有力。\n\n常見同義字：\nstupefy（使呆滯，指震驚到無法思考）\ndaze（使茫然，多指頭部受擊或驚嚇）\nastound（使大吃一驚，強調程度極深）",
  "stunt": "諧音聯想：\n諧音：「死彈特」\n\n聯想畫面 1：特技演員表演摩托車飛越火圈的驚險特技，落地時彈了一下。\n\n聯想畫面 2：這家公司為了打知名度，故意搞了一個誇張的行銷噱頭與作秀。\n\n高效擴充：動詞用法指阻礙生長，如植物因土壤不良而長不大。\nKK 音標：[stʌnt] -> 單音節字，ʌ 發短促的 uh 音。\n\n常見同義字：\ntrick（把戲、技巧、花招）\ngimmick（商業噱頭、宣傳手法）\nfeat（高難度的功績、技藝表現）",
  "stupid": "諧音聯想：\n諧音：「死禿頭」，嘲笑別人笨得像個固執的傻瓜。\n\n聯想畫面 1：不小心把咖啡打倒在電腦上，氣自己怎麼這麼笨。\n\n聯想畫面 2：在漫畫裡常看到笨蛋主角做了一些欠考慮的傻事。\n\n高效擴充：與 intelligent 智慧剛好是完全的反義詞。\nKK 音標：[ˋstupəd] -> 第一音節 [ˋstu] 重讀，母音是長音 [u]，第二音節變弱音 [pəd]。\n\n常見同義字：\n\nunintelligent（不聰明的，較中性的描述）\n\nignorant（無知的，指缺乏知識或教育）\n\nfoolish（愚蠢的，指做事的判斷力不好）",
  "sturdy": "諧音聯想：\n諧音：死踏低 -> 諧音聯想：死命踏都踏不壞的堅固木桌。\n\n聯想畫面 1：登山客穿著一雙非常結實耐磨的登山靴。\n\n聯想畫面 2：老爺爺雖然八十歲了，身體依然十分強壯健康。\n\n高效擴充：常與 sturdy furniture 或 sturdy build 搭配。\nKK 音標：[ˋstɝdi] -> 重音在第一音節，st 帶捲舌音 ɝ。\n\n常見同義字：\n\nstrong（強壯的）\n\ndurable（耐用的）\n\nrobust（強健的）",
  "stutter": "諧音聯想：\n諧音：「死踏踏」－緊張時腳步死踏踏，嘴巴也跟著結巴起來。\n\n聯想畫面 1：上台報告的學生太緊張，一句話結結巴巴地說不清楚。\n\n聯想畫面 2：老舊引擎發動時發出突突突的聲響。\n\n高效擴充：注意雙寫 t 的拼法，與 stuttering 同源。\nKK 音標：[ˋstʌtɚ] -> 主重音在第一個音節 stu，字尾 er 發輕輕的捲舌音。\n\n常見同義字：\nstammer（指因激動或恐懼而結巴、口吃）\nfalter（指言語或腳步遲疑、畏縮）\nhesitate（指猶豫不決，偏向心理層面）",
  "style": "諧音聯想：\n諧音：「台壓（台式風格壓過全場）」\n\n聯想畫面 1：梳著獨特台客風格的髮型，展現強烈的個人時尚樣式。\n\n聯想畫面 2: 設計師正在為模特兒做造型，定出今年流行的服裝風格。\n\n高效擴充：字首 sty- 聯想 stylus（筆尖），引申為書寫的文體或風格。\nKK 音標：[staɪl] -> 雙母音 aɪ 唸得飽滿，結尾 l 舌尖頂住上齒齦。\n\n常見同義字：\n\nfashion（指時尚、流行風格）\n\ntype（指種類或典型樣式）\n\nmanner（指做事的方式或態度）",
  "stylish": "諧音聯想：\n拆解 / 諧音：style（風格）加 ish。\n\n聯想畫面 1：這位模特兒穿著一身時髦的設計師服飾走秀。\n\n聯想畫面 2：這家咖啡廳的裝潢非常有格調。\n\n高效擴充：字尾 ish 加在名詞後變成形容詞，意為具有某種風格的。\nKK 音標：[ˋstaɪlɪʃ] -> 重音在第一音節 staɪ，lɪʃ 輕讀。\n\n常見同義字：\n\nfashionable（時髦的）\n\ntrendy（流行的）\n\nchic（高雅時髦的）",
  "sub": "諧音聯想：\n諧音：「殺不」死的替補球員，隨時準備上場取代主力。\n\n聯想畫面 1：潛水艇在海中潛行，準備執行任務。\n\n聯想畫面 2：中午肚子餓，隨便買了一個巨大的潛艇堡三明治來吃。\n\n高效擴充：作為字首代表在下方、次要、副手（如 subway 地鐵）。\nKK 音標：[sʌb] -> 短促有力的單音節，母音發短聲 [ʌ]。\n\n常見同義字：\n\nsubstitute（替代者、替補，完整寫法）\n\nunderstudy（預備演員、替演）\n\nassistant（助理、助手）",
  "subcontractor": "諧音聯想：\n諧音：「下包卡特，雷特抓！」\n\n聯想畫面 1：大包商把工程往下分包，讓下包的卡特（subcontractor）在下面趕工蓋房子。\n\n聯想畫面 2：科技廠外包組裝線，把零件交給協力廠商（subcontractor）進行在地生產。\n\n高效擴充：字首 sub 代表下方、次要，結合 contract（合約、承包）再加上表示人的 or。\nKK 音標：[sʌbˋkɑntræktɚ] -> 重音在第二音節 ˋkɑn，sub 念輕聲，ɚ 捲舌。\n\n常見同義字：\n\nsupplier（供應商，範圍較廣）\n\nvendor（外包廠商，通常指提供特定商品或服務）\n\nthird-party（第三方合作夥伴，多用於商業合約）",
  "subdued": "拆解：sub（在下面）+ dued（制服）。\n\n聯想畫面 1：他被警察制服後，整個人變得沉默寡言。\n\n聯想畫面 2：房間裡的燈光柔和暗淡，營造出一種安靜的氛圍。\n\n高效擴充：subdue 是制服，形容詞 subdued 則用來形容光線或情緒低調。\nKK 音標：[səbˋdud] -> 重音在第二音節 dud，發音要深沉。\n\n常見同義字：\n\nConquered（被制服的）\n\nMuted（柔和的）。",
  "subject": "諧音聯想：\n諧音：「殺不捷」\n\n聯想畫面 1：學校裡要考的科目實在太多，殺也殺不捷（來不及處理完），讓人頭痛。\n\n聯想畫面 2：在會議中，大家把這個話題當作討論的主題，各抒己見。\n\n高效擴充：字首 sub-（在下方）加ject（投擲），原本指「投在權力之下的人或事」。\nKK 音標：[ˋsʌbdʒɪkt] -> 當名詞時重音在第一音節 sʌb；動詞發音略有不同。\n\n常見同義字：\n\ntopic（話題、主題，通常指討論的內容）\ncourse（課程、科目，學校正規學科）\ndiscipline（學科、紀律，範圍較廣且專業）",
  "subjective": "諧音聯想：\n諧音：「殺不傑提夫」－殺手傑夫做事總是帶有強烈的主觀意識，完全聽不進別人的勸。\n\n聯想畫面 1：兩位影評人對同一部電影給出極端的評價，因為每個人的審美觀都是主觀的。\n\n聯想畫面 2：主管在面試時憑著個人喜好來決定錄取與否，這種偏頗的看法太過主觀。\n\n高效擴充：由 subject（主題／主詞）延伸，sub-（在下方）加 -ject（投射），把自己的想法投射上去就是主觀。\nKK 音標：[səbˋdʒɛktɪv] -> 重音在第二音節 dʒɛk，短促有力，尾音 -tive 發輕聲的 tɪv。\n\n常見同義字：\n\npersonal（個人的，強調私領域的看法）\n\nbiased（有偏見的，強調不夠客觀中立）\n\nindividual（個人的，強調單一個體的）",
  "subjectively": "拆解：subject（主體/主觀）+ ive + ly。\n\n聯想畫面 1：每個人都從自己的主體出發，主觀地（subjectively）看待這世界。\n\n聯想畫面 2：他主觀地認為這部電影很難看，但其實很多人覺得很棒。\n\n高效擴充：subject 當形容詞時意為受制於人的，當名詞時意為主題或主體。\nKK 音標：[səbˋdʒɛktɪvli] -> 第二音節 jec 重音，注意 j 的發音。\n\n常見同義字：\n\npersonally（就個人而言）\n\nbiasedly（有偏見地）\n\nopinionatedly（固執己見地）。",
  "submarine": "諧音聯想：\n諧音：「殺布麥印」\n\n聯想畫面 1：潛水艇在海底深處安靜航行，發出殺布般的低沉引擎聲。\n\n聯想畫面 2：中午點了一個巨大的潛艇三明治（長卷三明治）來飽餐一頓。\n\n高效擴充：sub 代表在下方，marine 代表海洋，組合即為海面下之物。\nKK 音標：[ˋsʌbmɚ͵in] -> 主重音在 ˋsʌb，次重音在 ͵in。\n\n常見同義字：\n\nsub（潛艦簡稱，軍事口語常用）\n\nunderwater boat（水下船隻，字面直譯）\n\nlong sandwich（長三明治，指長條潛艇堡）",
  "submit": "拆解：sub（下面）＋ mit（送出）\n\n諧音：「下敗密特」\n\n聯想畫面 1：把履歷表送到主管的「下面」桌上，也就是正式提交報告。\n\n聯想畫面 2：敵軍在強大武力壓迫下，最終選擇向對方屈服、甘居下風。\n\n高效擴充：字根 mit 等同 send（送），sub- 代表向下。\nKK 音標：[səbˋmɪt] -> 主重音在第二個音節 mɪt，sub 唸弱音 səb。\n\n常見同義字：\npresent（呈遞，較為正式禮貌）\nyield（屈服，強調實力不敵而妥協）\nsurrender（投降，軍事或全面認輸）",
  "subordinate": "諧音聯想：\n諧音：「殺爸地納的」\n\n聯想畫面 1：這份從屬於總公司的合約，是下級單位必須完全服從的。\n\n聯想畫面 2：主管正在交代他的部屬與下級員工如何處理次要的公文。\n\n高效擴充：字首 sub- 代表在下方，ordinate 代表排序，排在下面就是下屬。\nKK 音標：[səˋbɔrdə͵net] -> 第三音節 dɪt 有次重音，bɔr 是主重音。\n\n常見同義字：\njunior（資淺的、年幼的、下級的）\ninferior（較差的、低階的，帶有價值判斷）\nassistant（助理、協助者，通常是職場直屬下級）",
  "subordination": "諧音聯想：\n拆解：sub（在下）+ ordin（順序）+ ation。諧音：薩波迪內遜。\n\n聯想畫面 1：軍隊中嚴格的 subordination，下級必須服從上級。\n\n聯想畫面 2：在公司體系中，職位的高低就是一種 subordination。\n\n高效擴充：sub- 是在下面，ordinate 是排列，排列在下面就是從屬。\nKK 音標：[sə͵bɔrdɪˋneɪʃn] -> 重音在 na，發音要拉長。\n\n常見同義字：\n\nsubjection 從屬，hierarchy 層級，submission 服從。",
  "subscribe": "諧音聯想：\n諧音：「死拜死拜」\n\n聯想畫面 1：Youtuber 叫大家死也要訂閱、點讚，支持頻道。\n\n聯想畫面 2：在雜誌社簽名、訂閱、訂購長期刊物。\n\n高效擴充：sub (在底下) 加上 scribe (寫)，在文件底下簽名即是訂閱。\nKK 音標：[səbˋskraɪb] -> 第二音節重音，sub 發弱音，scribe 發長音 i。\n\n常見同義字：\n\norder（訂購商品，較常指實體物品或餐點）\n\nregister（登記或註冊，偏向行政程序）\n\npledge（認捐或發誓，多用於慈善捐款）",
  "subscription": "諧音聯想：\n諧音：「殺爸死哭力普軒」\n\n聯想畫面 1：每個月自動從信用卡扣繳雜誌訂閱費與會費，讓人心痛得快哭出來。\n\n聯想畫面 2：線上串流平台每個月都要付費訂閱，才能解鎖所有影片內容。\n\n高效擴充：由動詞 subscribe（訂閱、簽署）變化而來的名詞型態。\nKK 音標：[səbˋskrɪpʃən] -> 第二音節 skrɪp 重音，字尾 -tion 發 shən。\n\n常見同義字：\nfee（各類服務費、手續費）\ndues（社團或俱樂部的常年會費）\nmembership（會員資格，常包含訂閱服務）",
  "subsequent": "諧音聯想：\n諧音：「殺不死抗穩」－雖然經歷了一次危機，但在隨後發生的事件中局勢終於穩定下來。\n\n聯想畫面 1：簽完合約後，隨後而來的法律義務和細節條款需要雙方逐一確認。\n\n聯想畫面 2：颱風登陸當天狂風暴雨，隨後的幾天則放晴並出現高溫炎熱的天氣。\n\n高效擴充：sub-（在後面）加上 sequ（跟隨），字面意思就是「在後面跟著發生的」。\nKK 音標：[ˋsub-sə-kwənt] -> 重音在第一音節 sub，發短音的 u，後面音節要輕聲快速唸過。\n\n常見同義字：\n\nfollowing（隨後的，最常直接修飾時間或事件）\n\nlater（後來的，較口語日常的時間副詞/形容詞）\n\nsubsequent events（後續事件，商業與法律常用搭配）",
  "subside": "拆解：sub（在下面）+ side（坐/沉）。\n\n聯想畫面 1：洪水退去，水位沉到下面（subside）去了，災情終於平息。\n\n聯想畫面 2：憤怒的情緒慢慢消退，他終於冷靜下來聽人解釋。\n\n高效擴充：sub- 是在下方，side 源自拉丁語 sedere（坐），沉下去就是消退。\nKK 音標：[səbˋsaɪd] -> 第二音節 side 重音，注意長母音 i 的發音。\n\n常見同義字：\n\nabate（減弱，較正式）\n\ndecrease（減少，通用）\n\ndiminish（縮小）。",
  "subsidiary": "拆解：sub（在下面）+ sid（坐）+ iary。\n\n聯想畫面 1：這家公司在母公司下面（sub）坐著，就是附屬的子公司。\n\n聯想畫面 2：這項計畫只是主要任務的附屬部分，次要且輔助。\n\n高效擴充：subsidiary 意指坐在下面的人，引申為輔助或附屬。\nKK 音標：[səbˋsɪdi͵ɛri] -> 第二音節 sid 重音，注意 i 的短音。\n\n常見同義字：\n\nbranch（分公司）\n\naffiliate（附屬機構）\n\nauxiliary（輔助的）。",
  "subsiding": "諧音聯想：\n拆解：sub（在下面）+ siding（側邊）。\n\n聯想畫面 1：洪水終於開始 subsiding，水位慢慢退去，街道恢復平靜。\n\n聯想畫面 2：爭吵過後，雙方的怒氣逐漸 subsiding，終於可以坐下來談判。\n\n高效擴充：字根 sub-（向下）+ side（坐），意指坐下去、沉澱下來。\nKK 音標：[səbˋsaɪdɪŋ] -> 重音在第二音節，注意 s-i-d-i-n-g 的連貫發音。\n\n常見同義字：\n\nabating（減弱，常用於風暴或痛苦）\n\ndiminishing（減少，通用）\n\nsettling（沉澱，常用於液體或紛爭）。",
  "subsidize": "拆解：sub（在下面）+ sid（坐）+ ize（動詞字尾）。\n\n聯想畫面 1：政府在經濟困難時，坐在下面給予資助（subsidize），讓產業能活下去。\n\n聯想畫面 2：公司出資支援員工進修，提供學費補助。\n\n高效擴充：subsidize 是給予金錢上的支持，讓對方能穩住。\nKK 音標：[ˋsʌbsɪ͵daɪz] -> 第一音節 sub 重音，注意 i 的短音。\n\n常見同義字：\n\nfund（資助）\n\nfinance（提供資金）\n\nsupport（支持）。",
  "subsidy": "拆解：sub（在下面）+ sid（坐）+ y。\n\n聯想畫面 1：農民領取政府的農業補貼（subsidy），讓生活能維持在基本水平。\n\n聯想畫面 2：這項能源補貼政策幫助民眾減輕電費負擔。\n\n高效擴充：subsidy 是 subsidize 的名詞形式，指具體的補助金。\nKK 音標：[ˋsʌbsɪdi] -> 第一音節 sub 重音，注意 i 的短音。\n\n常見同義字：\n\ngrant（補助金，通常指研究或教育）\n\nallowance（津貼）\n\naid（援助）。",
  "substance": "諧音聯想：\n拆解 / 諧音：殺不死坦思\n\n諧音：「殺不死坦思」\n\n聯想畫面 1：這種神祕的化學物質怎麼殺都殺不死，科學家正在沉思研究。\n\n聯想畫面 2：演講內容非常有主旨與要義，不是空洞的廢話。\n\n高效擴充：字首 sub-（在下方）加上 stance（站立），代表支撐事物的實質內容。\nKK 音標：[ˋsʌbstəns] -> 重音在第一音節 sʌb，後面 stəns 唸輕聲。\n\n常見同義字：\n\nmatter（物質、事情，範圍廣泛）\n\nmaterial（材料、實體物質）\n\nessence（本質、精髓，偏抽象）",
  "substandard": "拆解：sub（低於）+ standard（標準）\n\n諧音：「殺爆死蛋的」\n\n聯想畫面 1：這批雞蛋品質 substandard，通通被退貨銷毀。\n\n聯想畫面 2：工廠製造出不合規格的 substandard 零件，導致機器故障。\n\n高效擴充：sub- 表示在下方或次級，結合 standard 標準好記。\nKK 音標：[͵sʌbˋstændərd] -> 次重音在 sub，主重音在 stænd，發短音 /æ/。\n\n常見同義字：\ndefective（有缺陷的、瑕疵的）\ninferior（劣等的、次級的）\npoor-quality（品質低劣的）",
  "substantial": "諧音聯想：\n諧音：死爸深秀 -> 諧音聯想：爸爸留下一筆價值巨大的實在遺產。\n\n聯想畫面 1：公司今年獲得了大量的資金挹注。\n\n聯想畫面 2：這場地震造成了相當大的實質損害。\n\n高效擴充：字根 substan 源自 substance（物質、本質）。\nKK 音標：[səbˋstænʃəl] -> 重音在第二音節 stæn，前後弱化。\n\n常見同義字：\n\nconsiderable（相當大的）\n\nsignificant（重大的）\n\nsolid（牢固的）",
  "substantiate": "拆解：sub（在下面）+ stant（站）+ iate。\n\n聯想畫面 1：把證據放在下面（sub）站穩（stant），就能證實（substantiate）你的說法。\n\n聯想畫面 2：警方需要更多證據來證實嫌疑人的不在場證明。\n\n高效擴充：substance（物質/實質）的動詞形式，讓論點有實質內容。\nKK 音標：[səbˋstæntʃi͵et] -> 第二音節 stan 重音，注意 t 的連音。\n\n常見同義字：\n\nprove（證明，通用）\n\nverify（核實）\n\nconfirm（確認）。",
  "substitute": "諧音聯想：\n拆解 / 諧音：sub（下面）+ stitute（站立）\n\n諧音：「三杯死踢替」－替補球員在場邊隨時準備上場，站到主力球員的下面位置代替他。\n\n聯想畫面 1：籃球比賽中，球員因犯規被換下場，替補隊員上場代替。\n\n聯想畫面 2：廚房做菜沒有沙拉油，用橄欖油來代替。\n\n高效擴充：字首 sub 代表在下方、次要。\nKK 音標：[ˋsʌbstə͵tut] -> 主重音在第一音節 sub，次重音在尾音 tut。\n\n常見同義字：\nreplace（指替換、取代舊的人或物）\nalternative（指可供選擇的替代方案）\nproxy（指代理人或授權代表）",
  "substitution": "諧音聯想：\n諧音：「殺爸死替圖訓」\n\n聯想畫面 1：籃球教練叫暫停，用替補球員進行場上球員的代替與替換。\n\n聯想畫面 2：化學實驗中用另一種溶劑來做物質的置換與代替物實驗。\n\n高效擴充：由動詞 substitute（代替）去 e 加上 -ion 變成名詞。\nKK 音標：[͵sʌbstɪˋtuʃən] -> 第三音節 tuʃ 重音，tu 發 long u 音。\n\n常見同義字：\nreplacement（更換、替換的人或物品）\nexchange（交換、互換，雙向居多）\nalternative（替代方案、可選擇的另一種事物）",
  "subtle": "諧音聯想：\n諧音：「殺特捕囉」－特務捕捉線索時動作非常微妙、手法高明，一般人根本察覺不到。\n\n聯想畫面 1：咖啡裡帶有一絲極為微妙的花香，不仔細品嚐根本喝不出來。\n\n聯想畫面 2：他臉上表情的微小變化暗示了他其實心裡很不高興，這種轉變非常微妙。\n\n高效擴充：字母 b 不發音是拼字陷阱，字根意指細緻的，常用來形容不易察覺的差異。\nKK 音標：[ˋsʌtəl] -> 重音在第一音節 sʌt，字母 b 不發音，唸起來像 suttle。\n\n常見同義字：\n\nfaint（微弱的，通常指聲音或光線、氣味）\n\nslight（輕微的，強調程度很小）\n\nnice（細微的，較少見的精細用法）",
  "subtract": "拆解：sub（在下面）加 tract（拉）\n\n諧音：「捨不來去減」\n\n聯想畫面 1：買東西時把折價券的金額從總價中扣除。\n\n聯想畫面 2：老師在黑板上示範數學的減法與刪除多餘算式。\n\n高效擴充：sub 往下、tract 拉，把數字往下拉就是減去。\nKK 音標：[səbˋtrækt] -> 主重音在 træk 音節，æ 發大口開音。\n\n常見同義字：\n deduct（扣除、減去，常用於金額或分數）\ntake away（拿走、減掉，口語常用）\nminus（負的、減，數學常用語）",
  "subtraction": "諧音聯想：\n拆解：sub（在下面）+ traction（拉）。\n\n聯想畫面 1：數學課上把數字拉到下面減掉，這就是 subtraction。\n\n聯想畫面 2：從總額中 subtraction 一部分費用，剩下的就是淨利。\n\n高效擴充：sub 是常見字首，意為在下方。\nKK 音標：[səbˋtrækʃ(ə)n] -> 重音在第二音節，注意 tion 的發音。\n\n常見同義字：\n\ndeduction（扣除）\n\nminus（減去，數學運算符號）。",
  "suburb": "諧音聯想：\n拆解 / 諧音：殺霸\n\n諧音：「殺霸（在郊區稱霸）」\n\n聯想畫面 1：住在安靜的郊區別墅裡，生活步調悠閒自在。\n\n聯想畫面 2：每天從市區通勤到近郊的住宅區，遠離都市塵囂。\n\n高效擴充：字首 sub- 代表在下方或次要，urb 代表城市，所以是城市外圍的郊區。\nKK 音標：[ˋsʌbɚb] -> 重音在第一個音節 sʌb，結尾 ɚb 輕輕帶過。\n\n常見同義字：\n\noutskirts（指城市的邊緣或市郊）\n\nresidential area（指住宅區）\n\ncountryside（指鄉村、農村，比 suburb 更偏遠）",
  "suburban": "諧音聯想：\n諧音：「殺爸本班」－住在郊區的爸爸每天都要搭本班車進城上班。\n\n聯想畫面 1：厭倦了市區的吵雜，全家人決定搬到環境清幽的郊區展開新生活。\n\n聯想畫面 2：週末開車到郊區的大型賣場採買生活用品，那裡停車位比市區多很多。\n\n高效擴充：由 suburb（郊區）加上形容詞字尾 -an 形成，sub-（在下方/次要）加上 urb（城市），就是次於城市的郊區。\nKK 音標：[səˋbɝbən] -> 重音在第二音節 bɝ，發捲舌的 er 音，前後音節輕讀。\n\n常見同義字：\n\nresidential（住宅區的，強調以住家為主）\n\nprovincial（省份的，較偏遠鄉村的）\n\noutlying（偏遠的，離中心較遠的）",
  "subway": "諧音聯想：\n諧音：「下不為」\n\n聯想畫面 1：你趕時間上班，鑽進馬路下方不為人知的地下通道，迅速搭乘地鐵。\n\n聯想畫面 2：紐約客習慣在地鐵站裡穿梭，避開地面上擁擠可怕的塞車車潮。\n\n高效擴充：sub-（下面）＋way（道路），組合起來就是走在道路底下的交通工具。\nKK 音標：[ˋsʌb͵we] -> 主重音在第一音節 sʌb，way 念長音 e。\n\n常見同義字：\n\nunderground（地鐵，英式英語常用）\nmetro（地鐵，歐洲與許多大都市常用）\nsubterranean（地下的，較正式的形容詞）",
  "succeed": "諧音聯想：\n諧音：「速吸低」\n\n聯想畫面 1：創業家迅速吸收低谷的教訓，終於獲得巨大成功。\n\n聯想畫面 2：太子順利接替王位，繼承了整個王國。\n\n高效擴充：suc 往下一步步向前，ceed 前進，持續向前就會成功。\nKK 音標：[səkˋsid] -> 主重音在 sid，後面發長音 e。\n\n常見同義字：\n triumph（勝利、成功，帶有歡慶意味）\nprosper（繁榮、昌盛）\nachieve（達成目標）",
  "success": "諧音聯想：\n諧音：「塞克死」\n\n聯想畫面 1：經過無數次的失敗，你終於在最後一秒塞克死（扭轉局勢），獲得巨大的成功。\n\n聯想畫面 2：企業老闆站在頒獎台上，享受創業有成、名利雙收的喜悅時刻。\n\n高效擴充：動詞為 succeed，形容詞為 successful，注意拼法有兩個 c。\nKK 音標：[səkˋsɛs] -> 主重音在第二音節 sɛs，字首 su- 弱化為輕聲。\n\n常見同義字：\n\ntriumph（巨大的勝利或成功，較有史詩感）\nachievement（成就、達成，強調努力後的成果）\nprosperity（繁榮、昌盛，通常指財富上的成功）",
  "successful": "諧音聯想：\n拆解 / 諧音：死客死服\n\n諧音：「死客死服」終於把難搞的客戶搞定，創業成功了。\n\n聯想畫面 1：經過多年努力，他終於成為一家跨國企業的 successful 企業家。\n\n聯想畫面 2：這場新品發表會非常 successful，現場訂單接不完。\n\n高效擴充：由 success（成功，名詞）加上 ful（充滿...的）形成形容詞。\nKK 音標：[səkˋsɛsfəl] -> 重音在第二音節 cess，ful 念輕聲.\n\n常見同義字：\nprosperous（繁榮的、昌盛的）\ntriumphant（勝利的、得意洋洋的）\nflourishing（興旺的、茂盛的）",
  "succession": "諧音聯想：\n諧音：[səkˋsɛʃən]\n諧音：「塞車，歇息啦」\n\n聯想畫面 1：高速公路上遇到嚴重塞車，車陣綿延不斷，形成一個接一個的車潮連續景象。\n\n聯想畫面 2：古代皇帝過世後，皇位繼承權的爭奪戰也是一波接一波、連續不斷地上演。\n\n高效擴充：字首 sub-（下面）加上 ccedere（走），代表在後面接著走，也就是繼承與連續。\nKK 音標：[səkˋsɛʃən] -> 第二音節ｾˋ為主要重音，唸得較重且拉長。\n\n常見同義字：\nsequence（表示事件的先後順序或連續序列，通常用於程序）\nseries（表示同類事物的連續或系列，如電視影集）\nprogression（強調向前的發展或連續推進的過程）",
  "successive": "諧音聯想：\n諧音：「薩克塞斯夫」－薩克先生連續好幾年都拿下公司業績第一名，真是連續的成功。\n\n聯想畫面 1：球隊在今年創下了連續三場比賽都獲勝的輝煌紀錄。\n\n聯想畫面 2：這家老店在連續幾個週末都出現了大排長龍的盛況。\n\n高效擴充：由 success（成功/接著）衍生，-ive 形容詞字尾，指一個接一個發育或發生的。\nKK 音標：[səkˋsɛsɪv] -> 重音在第二音節 sɛs，發短音的 e，注意 ccess 的子音連讀。\n\n常見同義字：\n\nconsecutive（連續的，強調中間沒有中斷的數字或日期）\n\nsequential（按順序的，強調步驟的先後）\n\nserial（連載的，系列性的）",
  "successor": "諧音聯想：\n諧音：[səkˋsɛsɚ]\n諧音：「塞車、色情、而...」\n\n聯想畫面 1：前任CEO卸任後，新上任的繼承者立刻召開記者會宣布新政策。\n\n聯想畫面 2：老店的接班人接手家族事業後，成為名副其實的店鋪繼任者。\n\n高效擴充：由 succession 變化而來，字尾 -or 代表做這件事的人，即繼承人。\nKK 音標：[səkˋsɛsɚ] -> 重音在第二音節ｾˋ，字尾的 -sor 輕聲帶過。\n\n常見同義字：\nheir（法律上的合法繼承人，通常指財產或爵位）\ninheritor（指繼承財產或傳統的人）\nreplacement（指替換的人或物，語氣較不正式）",
  "such": "諧音聯想：\n諧音：「撒吃」，把這樣美味的食物全都撒在盤子裡吃。\n\n聯想畫面 1：這是一部如此好看的電影，大家都推薦。\n\n聯想畫面 2：我從沒見過這樣可愛的小動物。\n\n高效擴充：常用於 such a / an 加形容詞再加名詞的句型結構。\nKK 音標：[sʌtʃ] -> 短音 [ʌ] 搭配結尾 [tʃ] 氣音，發音俐落。\n\n常見同義字：\n\nlike this（像這樣的，通常放於名詞後面）\n\nof this kind（這類的，較口語的形容方式）\n\nsimilar（相似的，指性質相近但不完全一樣）",
  "suck": "諧音聯想：\n諧音：「殺客」\n\n聯想畫面 1：吸血鬼一口咬下去用力吸吮，把客人嚇得半死。\n\n聯想畫面 2：吸管用力一吸，把珍珠奶茶全部吸光光。\n\n高效擴充：口語中常用來形容某事很糟糕（That sucks! 遜斃了）。\nKK 音標：[sʌk] -> 閉口音的 ʌ，結尾 k 輕輕爆破。\n\n常見同義字：\n\nabsorb（吸收，多用於液體或知識）\n\ninhale（吸入，如呼吸或氣體）\n\nterrible（當形容詞糟糕時的對應語意）",
  "sudden": "諧音聯想：\n諧音：「殺的冷」\n\n聯想畫面 1：天氣原本很好，突然一陣寒風吹來，殺得大家措手不及，非常冷。\n\n聯想畫面 2：路上突然發生車禍意外，讓路過的所有行人全都嚇了一大跳。\n\n高效擴充：常組成片語 all of a sudden，意思是「突然間」。\nKK 音標：[ˋsʌdən] -> 重音在第一音節 sʌd，後面 dn 發輕聲。\n\n常見同義字：\n\nabrupt（突然的、粗魯的，強調毫無預警）\nunexpected（出乎意料的，指事前沒想到的）\nsuddenly（突然地，其副詞形式）",
  "suddenly": "諧音聯想：\n諧音：「殺跌的裡」\n\n聯想畫面 1：股市突然地大跌，讓散戶措手不及。\n\n聯想畫面 2：天空忽然下起大雨，大家出乎意料地奔跑避雨。\n\n高效擴充：由sudden加ly轉為副詞。\nKK 音標：[ˋsʌdənli] -> 主重音在第一個音節sʌd上，唸短u音。\n\n常見同義字：\n\nabruptly（突然地，常指動作唐突或中斷）\n\nall of a sudden（突然間，常用片語形式）\n\nunexpectedly（出乎意料地，強調沒人猜到）",
  "suds": "諧音聯想：\n諧音：殺死（suds 聽起來像殺死）。\n\n聯想畫面 1：洗碗時肥皂水產生了大量的泡沫，彷彿要把髒污通通殺死。\n\n聯想畫面 2：在酒吧裡，人們點了一杯啤酒，看著杯口冒出的白色泡沫。\n\n高效擴充：常用複數形 suds，形容肥皂水或啤酒上的泡沫。\nKK 音標：[sʌdz] -> 單音節，結尾的 z 音要發出震動聲。\n\n常見同義字：\n\nfoam 泡沫，泛指各種泡沫；lather 肥皂泡沫，特指洗澡或刮鬍時的泡沫；beer 啤酒，非正式用法。",
  "sue": "諧音聯想：\n諧音：輸。\n\n聯想畫面 1：如果你隨便亂告人，最後可能自己會輸，還要賠上一大筆錢。\n\n聯想畫面 2：他因為不滿意服務，決定向法院起訴這家公司。\n\n高效擴充：sue for 請求，sue someone 起訴某人。\nKK 音標：[su] -> 發長音 u，嘴型要圓。\n\n常見同義字：\n\nlitigate（訴訟）\n\nprosecute（檢控）\n\npetition（請求）。",
  "suffer": "諧音聯想：\n諧音：「殺佛」\n\n聯想畫面 1：古代苦行僧遭受種種皮肉痛楚，彷彿內心在承受極大折磨。\n\n聯想畫面 2：感冒引發嚴重頭痛，讓他在床上痛苦呻吟、受盡折磨。\n\n高效擴充：後面常接介系詞 from（suffer from 遭受……之苦，如疾病）。\nKK 音標：[ˋsʌfɚ] -> 第一音節重音，u 發短音 [ʌ]，尾音 er 輕讀。\n\n常見同義字：\n\nendure（忍受、持久，強調不屈服）\n\nundergo（經歷、承受手術或訓練等）\n\nbear（承受重量或負擔、忍受）",
  "sufferance": "拆解：suffer（受苦）+ ance。\n\n聯想畫面 1：他只是勉強容忍對方的無理，心裡其實很不舒服。\n\n聯想畫面 2：這項計畫是在長官勉強同意下進行的，隨時可能被喊停。\n\n高效擴充：強調忍受痛苦的過程，常用於被動的容忍。\nKK 音標：[ˋsʌfrəns] -> 重音在第一音節，注意輕音節的發音。\n\n常見同義字：\n\ntolerance（容忍）\n\nendurance（忍耐）\n\npermission（許可）。",
  "suffering": "諧音聯想：\n諧音：殺佛人。\n\n聯想畫面 1：古代戰亂中，人們遭受苦難，簡直像被殺佛人一樣殘忍。\n\n聯想畫面 2：這場大病讓他 suffering 了好幾個月，身體瘦了一大圈。\n\n高效擴充：suffer 由 sub（在下面）+ fer（帶）組成，意指在重擔下忍受。\nKK 音標：[ˋsʌfərɪŋ] -> 第一音節重音，suf 發音短促有力。\n\n常見同義字：\n\nmisery（極度悲慘的狀態）\n\nhardship（艱難困苦的環境）\n\npain（具體的痛感）。",
  "suffice": "諧音聯想：\n諧音：撒飛死。\n\n聯想畫面 1：只要這點錢就足夠了，不用撒飛死那麼多錢。\n\n聯想畫面 2：這份證據足以證明他的清白。\n\n高效擴充：sufficient足夠的，suffice是動詞。\nKK 音標：[səˋfaɪs] -> 重音在第二音節 fice，發音時嘴巴拉開。\n\n常見同義字：\n\nbe enough足夠，be adequate足夠的，serve滿足需求。",
  "sufficient": "諧音聯想：\n諧音：「速吸粉紅」\n\n聯想畫面 1：迅速吸取足夠的粉紅色顏料，份量剛剛好夠畫完整張圖。\n\n聯想畫面 2：倉庫裡的物資非常充足，足夠應付整個冬天。\n\n高效擴充：字尾 cient 是形容詞字尾，名詞為 sufficiency。\nKK 音標：[səˋfɪʃənt] -> 重音在第二音節的 ˋfɪ。\n\n常見同義字：\nenough（足夠的，最常用）\nadequate（足夠的、適當的）\nample（充裕的、豐富的）",
  "suffocate": "諧音聯想：\n諧音：「殺佛客得」\n\n聯想畫面 1：密室裡空氣稀薄，把客人悶死、使窒息而死。\n\n聯想畫面 2：濃煙密佈讓人喘不過氣，狠狠扼制呼吸。\n\n高效擴充：sub (往下) 加上 focate (喉嚨)，掐住喉嚨往下壓導致窒息。\nKK 音標：[ˋsʌfə͵ket] -> 第一音節重音，suf 發短音 u，cate 發長音 a。\n\n常見同義字：\n\nasphyxiate（窒息，醫學或正式用語）\n\nsmother（悶死或厚蓋掩埋，強調阻絕空氣）\n\nchoke（窒息或噎住，最口語日常）",
  "sugar": "諧音聯想：\n諧音：「休尬」\n\n聯想畫面 1：台語說休尬，你吃了一口加很多糖的甜點，覺得甜到不行。\n\n聯想畫面 2：外國人常用 sugar 來當作親密愛人的暱稱，就像叫小甜心一樣。\n\n高效擴充：字尾 ar 常作為名詞結尾，su 則對應發音的 /ʃ/。\nKK 音標：[ˋʃʊɡɚ] -> 重音在第一個音節 ʃʊ，注意 sh 發唇齒音的 /ʃ/。\n\n常見同義字：\n\nsweetener（甜味劑、糖精，統稱甜的添加物）\n\ncandy（糖果，指製成塊狀的甜食）\n\nhoney（蜂蜜，也常作親密愛人的稱呼）",
  "suggest": "諧音聯想：\n諧音：「山傑斯特」\n\n聯想畫面 1：傑斯特在山頂開會時，向大家提出一個很棒的旅遊建議。\n\n聯想畫面 2：主管面露微笑，暗示這個企劃案背後其實有更好的做法。\n\n高效擴充：後面接動名詞 V-ing 或 that 子句（that 子句中的動詞常省略 should）。\nKK 音標：[səˋdʒɛst] -> 第二音節重音，ge 發 [dʒ] 的音。\n\n常見同義字：\n\nrecommend（推薦、建議，語氣較強烈）\n\npropose（正式提議、求婚）\n\nadvise（勸告、給建議）",
  "suggestion": "諧音聯想：\n諧音：「殺局司展」\n\n聯想畫面 1：謀殺局的司長提出了破案的關鍵建議，幫助大家順利抓到兇手。\n\n聯想畫面 2：主管在會議上聆聽大家的意見，並做了一些微量的修正調整。\n\n高效擴充：由動詞 suggest 變化而來，字尾 ion 將其轉為名詞。\nKK 音標：[səˋdʒɛstʃən] -> 主重音在第二音節 ˋdʒɛs，sə 發輕聲。\n\n常見同義字：\n\nproposal（提案，通常指正式的商業計畫）\n\nadvice（忠告，指給予他人的方向指引）\n\nrecommendation（推薦，指口碑或權威建議）",
  "suicide": "諧音聯想：\n拆解 / 諧音：蘇依死愛的\n\n諧音：「蘇依死愛的」\n\n聯想畫面 1：名叫蘇依的女子因為受不了失戀打擊，選擇了結束生命。\n\n聯想畫面 2：新聞報導社會上發生的悲劇自殺事件。\n\n高效擴充：字尾 -cide 代表殺害（如 homicide 謀殺），字首 sui- 代表自己。\nKK 音標：[ˋsuə͵saɪd] -> 主重音在第一個音節 su，後面 -cide 發 saɪd 的音。\n\n常見同義字：\n\ntake one's life（片語，自我了斷）\n\nself-destruction（自我毀滅）\n\nfatal action（致命的行動）",
  "suit": "諧音聯想：\n諧音：「速得」\n\n聯想畫面 1：你走進服飾店試穿一套量身訂做的西裝，穿上去速得（馬上變帥）！\n\n聯想畫面 2：這份工作內容非常適合你的專長，各方面條件都與你完美相配。\n\n高效擴充：形容詞 suitable 代表「合適的、適當的」，後面常接介系詞 for。\nKK 音標：[sut] -> 單音節字，母音 u 發長音 oo，發音俐落短促。\n\n常見同義字：\n\noutfit（全套服裝、裝備，口語常用）\nmatch（相配、符合，動詞常用）\nfit（適合、合身，強調尺寸大小剛好）",
  "suitable": "諧音聯想：\n諧音：「速逃得包」\n\n聯想畫面 1：買東西時發現尺寸剛剛好，立刻打包帶走，這尺寸非常 suitable。\n\n聯想畫面 2：面試時穿上這套西裝，得體又適當，主管看了覺得很 suitable。\n\n高效擴充：字根 suit 代表適合、套裝，加上 able 變成形容詞可做到的。\nKK 音標：[ˋsutəbəl] -> 重音在第一音節 su，唸長音的 oo，後面接輕鬆的輕聲。\n\n常見同義字：\nappropriate（正式且得體的，常用於正式場合或規範）\nproper（合乎禮節或規矩的，指正當性）\nfit（大小或尺寸剛好的，通常較口語）",
  "suitcase": "諧音聯想：\n拆解 / 諧音：suit（西裝）+ case（箱子裝備）\n\n諧音：「帥哥客西裝箱」－帥哥出門旅遊，一定要帶裝西裝的手提箱。\n\n聯想畫面 1：商務人士拉著小型旅行箱準備搭機出差。\n\n聯想畫面 2：機場行李輸送帶上滿是各式各樣的手提箱。\n\n高效擴充：由 suit（西裝/適合）與 case（箱子）組合而成。\nKK 音標：[ˋsut͵kes] -> 主重音在 suit，次重音在 kes，念起來輕快。\n\n常見同義字：\nbaggage（泛指行李，較常指大型行李箱總稱）\nluggage（也是泛指行李，英式常用）\ntrunk（指大型行李箱或車尾行李廂）",
  "suite": "諧音聯想：\n諧音：[swit]\n諧音：「sweet（甜蜜）」\n\n聯想畫面 1：新婚夫妻入住五星級飯店的豪華套房，度過非常 sweet 的蜜月假期。\n\n聯想畫面 2：這套辦公室傢俱擺設非常協調，整組套件看起來既時尚又實用。\n\n高效擴充：源自法文，與 sweet 發音完全相同，用「甜蜜的套房」輕鬆記住。\nKK 音標：[swit] -> 單音節字，母音長音 i 發音要飽滿清晰。\n\n常見同義字：\napartment（指一般公寓住宅，不一定是飯店套房）\nset（泛指一套物品或傢俱）\ncollection（指收藏的一系列物品）",
  "sulfur": "諧音聯想：\n諧音：「三黃佛」－溫泉裡有豐富的硫磺，把石頭染成黃色，像三尊黃佛。\n\n聯想畫面 1：陽明山硫磺溫泉區冒出陣陣白煙，空氣中有濃濃的硫磺味。\n\n聯想畫面 2：火山噴發口附近堆積著黃色的硫磺結晶。\n\n高效擴充：亦可拼作 sulphur，化學元素符號為 S。\nKK 音標：[ˋsʌlfɚ] -> 主重音在 sul，字尾 fur 發輕捲舌音。\n\n常見同義字：\nmineral（指礦物質，廣泛涵義）\ncompound（指化學化合物）\nelement（指化學元素）",
  "sum": "諧音聯想：\n諧音：「山」\n\n聯想畫面 1：把整座山的石頭數量全部加起來，算出一個總和。\n\n聯想畫面 2：帳單上的金額累積成一座小山，看了讓人頭痛。\n\n高效擴充：字尾常與 summary（總結）相通，代表匯集多個部分。\nKK 音標：[sʌm] -> 短音 ʌ，結尾 m 閉雙唇發音。\n\n常見同義字：\n\ntotal（總計、總數）\n\namount（金額、數量）\n\naggregate（總計、聚集，較正式）",
  "summarize": "諧音聯想：\n諧音：「三馬來思」考，把長篇大論濃縮成三個重點來總結說明。\n\n聯想畫面 1：教授在期末總複習時，把厚厚一本書的重點快速總結給學生聽。\n\n聯想畫面 2：開會時主管要求大家發言簡明扼要，用幾句話把專案進度概述完畢。\n\n高效擴充：字根 summ（總額、最高）加上動詞字尾 ize，把零散內容整合到最高點就是總結。\nKK 音標：[ˋsʌmɚ͵aɪz] -> 重音在第一音節 sum，注意美國腔的 r 輕音。\n\n常見同義字：\nsum up（總結，最常見的日常口語片語）\noutline（概述，強調列出大綱）\nrecap（扼要重述，廣播或會議常用簡稱）",
  "summary": "諧音聯想：\n拆解 / 諧音：三嗎粒\n\n諧音：「三嗎粒（把文章濃縮成三顆米粒大小）」\n\n聯想畫面 1：將長篇大論的報告濃縮成簡短的摘要。\n\n聯想畫面 2：會議結束前，老闆快速做了一個總結性的發言。\n\n高效擴充：字根源自 sum（總和），加上 -mary 形成名詞或形容詞。\nKK 音標：[ˋsʌmɚi] -> 重音在第一音節 sʌm，後面的 ɚi 唸輕快的「兒依」。\n\n常見同義字：\n\nabstract（學術論文的摘要）\n\nsynopsis（劇情大綱或概要）\n\noverview（概覽、全貌概述）",
  "summer": "諧音聯想：\n諧音：「殺嘛」\n\n聯想畫面 1：夏天太陽太毒辣，簡直快把萬物殺嘛，大家只好去海邊避暑。\n\n聯想畫面 2：學生們最愛的季節就是夏天，放暑假可以盡情出去玩。\n\n高效擴充：雙寫 m 代表短母音後的閉音節結尾。\nKK 音標：[ˋsʌmɚ] -> 重音在第一音節 sʌ，ɚ 為捲舌輕聲。\n\n常見同義字：\n\nsummertime（夏季、盛夏時節）\n\nhot season（炎熱的季節，口語常用）\n\nvacation（假期，常與 summer 搭配指暑假）",
  "summery": "諧音聯想：\n諧音：「夏天裡」\n\n聯想畫面 1：街上的人們穿著清涼的背心短褲，整個街道充滿了濃濃的夏天裡（summery）的氣息。\n\n聯想畫面 2：這件鮮黃色的洋裝穿起來非常陽光，給人一種如夏季般充滿朝氣的感覺。\n\n高效擴充：由名詞 summer（夏天）加上字尾 y 轉為形容詞，專門用來形容具有夏日特徵或適合夏天穿的物品。\nKK 音標：[ˋsʌməri] -> 主重音在第一個音節，短音ʌ唸短促，後面直接接輕音節「姆-里」。\n\n常見同義字：\nsummerlike（如夏日的，較少見但直觀）\ntropical（熱帶的，常帶有炎熱夏日感）\nwarm（溫暖的，常與季節氛圍連結）",
  "summit": "諧音聯想：\n諧音：「山米」\n\n聯想畫面 1：山米爬到了高山的頂峰，參加世界領袖們聚集的最高級會議。\n\n聯想畫面 2：登山客站在玉山頂峰合影，慶祝成功登頂。\n\n高效擴充：字首 sum 代表最高，字尾 mit 是送出，把最高意見送出去就是峰會。\nKK 音標：[ˋsʌmət] -> 第一音節重音在 sum，唸作短促的「薩」，mət 唸輕短的「姆特」。\n\n常見同義字：\npeak（山頂、頂峰，通常指自然地形的最高點）\n đỉnh（越南語借詞，非英文）\nconference（正式會議，規模較大）\nmeeting（一般會議，泛指各種聚會）",
  "summon": "諧音聯想：\n諧音：「三門」\n\n聯想畫面 1：法庭開庭前，法警一口氣連開三扇門，大聲傳喚被告入場。\n\n聯想畫面 2：主管緊急召集各部門主管開會，發出最高規格的召喚令。\n\n高效擴充：雙寫 m，字尾 -on 唸弱音 [ən]。\nKK 音標：[ˋsʌmən] -> 主重音在第一個音節 sʌm，ʌ 發短促的屋聲。\n\n常見同義字：\ncall（召喚，最口語常見的詞）\nconvene（召集，多指會議或正式集會）\ncitation（傳票或引用，法律專有名詞相關）",
  "sun": "諧音聯想：\n諧音：「三」\n\n聯想畫面 1：天上同時出現三個太陽，大地被日光曬得滾燙。\n\n聯想畫面 2：你在海灘躺椅上做日光浴，享受陽光曬在皮膚上的感覺。\n\n高效擴充：字尾 n 結尾的單音節短母音字，如 run、fun。\nKK 音標：[sʌn] -> 只有一個音節，u 發短促的 /ʌ/ 音，結尾鼻音清晰。\n\n常見同義字：\n\nsunlight（陽光、日光，指太陽發出的光線）\n\nsunshine（日照、陽光，帶有明亮快樂的意味）\n\nsolar（太陽的、日光的，通常作形容詞使用）",
  "sunday": "諧音聯想：\n諧音：「三的」\n\n聯想畫面 1：星期日是一週當中的第三天（如果從週五算起），也是大家放假的日子。\n\n聯想畫面 2：禮拜天早上全家人一起在家吃早餐，享受悠閒的假日。\n\n高效擴充：由 sun（太陽）加上 day（日子）組成，意即太陽天。\nKK 音標：[ˋsʌn͵de] -> 第一音節 sʌ 重音，第二個字尾 day 唸輕一點的 /de/。\n\n常見同義字：\n\nweekend（周末，包含週六與週日）\n\nsabbath（安息日，宗教上的禮拜日）\n\nday off（休假日，泛指不用上班的日子）",
  "sunhat": "拆解：sun（太陽）+ hat（帽子）\n\n諧音：散黑特。\n\n聯想畫面 1：去海邊玩水時戴上一頂寬邊的遮陽帽，把強烈的陽光「散黑特」擋在外面。\n\n聯想畫面 2：農夫在田裡工作時頭上戴著草帽來防止中暑。\n\n高效擴充：複合名詞，sun 指太陽，hat 指有帽沿的帽子。\nKK 音標：[ˋsʌn͵hæt] -> 主重音在 [sʌn]，短音 [ʌ] 發音急促。\n\n常見同義字：\n\nstraw hat（草帽，通常指編織材質的帽子）\n\nvisor（遮陽帽舌，通常指只有前端帽沿的款式）\n\nbaseball cap（棒球帽，日常休閒防曬用）",
  "sunny": "諧音聯想：\n諧音：「山泥」被太陽曬到乾裂。\n\n聯想畫面 1：今天是個 sunny 的好天氣，非常適合去海邊踏浪。\n\n聯想畫面 2：她總是帶著 sunny 的笑容，給身邊的人帶來滿滿正能量。\n\n高效擴充：由 sun（太陽）字尾雙寫 n 加 y 形成形容詞。\nKK 音標：[ˋsʌni] -> 重音在第一音節 sun，ʌ 發短音阿。\n\n常見同義字：\nbright（明亮的、晴朗的）\nsunlit（陽光照射的）\ncheerful（快樂的、開朗的）",
  "super": "諧音聯想：\n諧音：「超級」市場的英文縮寫發音就源自這裡。\n\n聯想畫面 1：這部超級英雄電影 super（非常）好看，票房破紀錄。\n\n聯想畫面 2：公寓的 super（大樓管理員）正在幫住客收包裹。\n\n高效擴充：字首 super- 表示「超乎、之上、極度」，如 superman。\nKK 音標：[ˋsupɚ] -> 主重音在第一個音節 su 上，字尾 er 輕輕帶過捲舌。\n\n常見同義字：\nextremely（極度地，正式且常用）\nhighly（高度地，常修飾評價或讚賞）\nfantastic（極好的，口語常用讚美）",
  "superabundance": "諧音聯想：\n拆解 / 諧音：super（超級）+ abundance（豐富）。\n\n聯想畫面 1：超級市場裡的商品多到極點，這就是 superabundance。\n\n聯想畫面 2：大自然給予的雨水多到氾濫，這就是一種極致的過多。\n\n高效擴充：super 是超級，比 over 更強調程度之深。\nKK 音標：[͵supərəˋbʌndəns] -> 重音在 bun 上，super 的 u 發長音。\n\n常見同義字：\n\nSuperfluity（過剩，較正式）\n\nExcess（過量，通用）\n\nSurfeit（過量，強調厭膩感）",
  "superb": "諧音聯想：\n諧音：「速怕包」－這家麵包店做出來的招牌麵包實在是超級棒、一流的上乘之作。\n\n聯想畫面 1：米其林主廚端出精緻的法式料理，口感豐富完美，讓大家直呼太宏偉華麗了。\n\n聯想畫面 2：她在舞台上的歌唱表現堪稱完美，高音穩定且情感充沛，演出水準一流。\n\n高效擴充：字首 super- 代表超級、超越，字尾結合表示極佳的狀態，常讚美表現或物品。\nKK 音標：[sʊˋpɝb] -> 重音在第二音節 pɝ，發捲舌音，注意第一個音節發短促的 sʊ。\n\n常見同義字：\n\nexcellent（優秀的，最常用的讚美詞）\n\noutstanding（傑出的，表現特別突出的）\n\nmagnificent（宏偉的，強調外觀壯麗豪華）",
  "superficial": "諧音聯想：\n拆解 / 諧音：super（超級）加 facial（臉部）的諧音聯想：只看表面臉蛋的膚淺行為。\n\n聯想畫面 1：他對這本書只有粗淺的了解，無法深入討論。\n\n聯想畫面 2：醫生檢查後發現這只是個外表的皮肉傷。\n\n高效擴充：字首 super 代表在上方或表面。\nKK 音標：[͵supɚˋfɪʃəl] -> 重音在第三音節 fɪ，前兩音節次重音。\n\n常見同義字：\n\nshallow（膚淺的）\n\nsurface（表面的）\n\ncursory（粗略的）",
  "superfluity": "諧音聯想：\n拆解 / 諧音：super（超過）+ flu（流動）+ ity（名詞結尾）。\n\n聯想畫面 1：水流太多溢出來了，這些多餘之物就是 superfluity。\n\n聯想畫面 2：貴族家裡堆滿了奢侈品，多到用不完，這就是 superfluity。\n\n高效擴充：字根 flu 代表流動，superfluous 就是流動太多，即多餘的。\nKK 音標：[͵supərˋfluəti] -> 重音在 flu 上，注意 flu 的長音。\n\n常見同義字：\n\nExcess（過量，通用）\n\nSurplus（盈餘，多餘物）\n\nLuxury（奢侈品，強調昂貴多餘）",
  "superior": "諧音聯想：\n諧音：「速配立歐」\n\n聯想畫面 1：速配立歐這款新產品品質優越，立刻超越競爭對手成為上級首選。\n\n聯想畫面 2：主管站在辦公室宣佈升職名單，稱讚他是表現最好的長官與優勝者。\n\n高效擴充：字根 super 代表超越、在...之上，衍生出優越與上級的意思。\nKK 音標：[suˋpɪriɚ] -> 第二音節 pɪ 帶有主重音，唸高亢的「匹」，後面 riɚ 輕聲帶過。\n\n常見同義字：\nbetter（更好的，口語常用）\nsenior（年資較高者、資深學長，常指輩份或年齡）\nhigher（較高的，具體高度或抽象級別）",
  "superiority": "諧音聯想：\n諧音：[͵supɪriˋɔrɪti]\n諧音：「蘇菲亞力氣很大，展現優越感」\n\n聯想畫面 1：資深員工在新人面前展現出強烈的優越感，自認能力高人一等。\n\n聯想畫面 2：這支球隊在技術上擁有絕對的優勢，輕鬆擊敗對手贏得勝利。\n\n高效擴充：由 superior（較優秀的）字尾加上 -ity 形成名詞，表示優越性。\nKK 音標：[͵supɪriˋɔrɪti] -> 主重音落在第 四音節ㄛˋ，次重音在最前方。\n\n常見同義字：\nadvantage（指有利的條件或優勢）\n supremacy（指至高無上的權力或優勢）\nexcellence（指卓越與傑出，通常無貶義）",
  "supermarket": "拆解：super ＋ market\n\n拆解：「超級（super）＋ 市場（market）」\n\n聯想畫面 1：週末推著推車在超級市場裡掃貨，買齊一整個禮拜的蔬菜水果。\n\n聯想畫面 2：生鮮區裡琳瑯滿目的商品，讓人忍不住一樣接著一樣放進購物籃。\n\n高效擴充：super解作「超級的、極大的」，market則是傳統或現代市場。\nKK 音標：[ˋsupɚ͵mɑrkɪt] -> 主重音在第一音節 su，次重音在 mɑr。\n\n常見同義字：\n\ngrocery store（雜貨店、食品雜貨店，美式常用）\nhypermarket（量販店，比超級市場更大）\nmall（大型購物中心，包含多種娛樂與店家）",
  "supersonic": "諧音聯想：\n諧音：「速怕搜你客」－超級厲害的音速小子跑得比超音速還要快，把對手搜個精光。\n\n聯想畫面 1：空軍基地上空劃過一道白煙，戰鬥機突破音障發出巨大的超音速轟鳴聲。\n\n聯想畫面 2：工程師正在研發新型的超音速客機，未來從台北飛美國只要短短幾個小時。\n\n高效擴充：super-（超級、超越）加上 sonic（聲音的），合起來就是指超越聲音速度的。\nKK 音標：[͵supɚˋsɑnɪk] -> 重音在第三音節 sɑ，發開口的 o 音，前面 super 要輕讀。\n\n常見同義字：\n\nultrasonic（超音波的，注意與超音速 supersonic 的區別）\n\nlightning-fast（電光石火般快的，口語誇飾說法）\n\nswift（飛快的，文學或正式一點的形容詞）",
  "superstition": "諧音聯想：\n拆解 / 諧音：super（超級）+ stition（站立在上面）\n\n諧音：「超級死貼神」－老一輩對神明的迷信太深，認為神明超級死貼在心中。\n\n聯想畫面 1：農曆七月鬼門開，路上有許多民間迷信禁忌。\n\n聯想畫面 2：黑貓從面前走過會帶來厄運，這是一種西方迷信。\n\n高效擴充：形容詞為 superstitious（迷信的）。\nKK 音標：[͵supɚˋstɪʃən] -> 主重音在 ti 這一音節，唸法為 -stish-un。\n\n常見同義字：\nmyth（指神話或大眾迷思）\nbelief（指信念，不一定帶負面迷信色彩）\nillusion（指錯覺或幻覺）",
  "superstitious": "諧音聯想：\n諧音：「速怕死踢球死」－超級害怕輸球的人死都要踢那顆球，這種行為真是荒謬又迷信。\n\n聯想畫面 1：球員在比賽前一定要穿同一件內衣褲，這種行為顯示出他十分迷信。\n\n聯想畫面 2：老一輩的人總是警告農曆七月不要晚上出門，這些觀念在現代人看來是迷信的。\n\n高效擴充：字首 super-（在上方超越）加上 stitious（站立），代表盲目信奉超越常理的事物。\nKK 音標：[͵supɚˋstɪʃəs] -> 重音在第三音節 tɪ，發短音的 i，尾音 -tious 發成 shəs。\n\n常見同義字：\n\nirrational（不理性的，缺乏科學根據的）\n\nunfounded（無根據的，憑空想像的）\n\nmythical（神話的，帶有傳說色彩的）",
  "supervise": "拆解：super（超級）＋ vise（看）\n\n諧音：「超級視」\n\n聯想畫面 1：老闆透過超級視訊系統，隨時監督遠端員工的工作進度。\n\n聯想畫面 2：工頭在現場嚴格管理、指導工人的施工品質。\n\n高效擴充：字根 vis 源自 video（看），super- 表示在上方俯瞰。\nKK 音標：[ˋsupɚ͵vaɪz] -> 主重音在第一個音節 su，次重音在 vaɪz，ɚ 輕念。\n\n常見同義字：\noversee（監督，字面意義同為在上方看）\nmanage（管理，企業營運的統稱）\ninspect（檢查，強調細節審查）",
  "supervision": "諧音聯想：\n諧音：[͵supɚˋvɪʒən]\n諧音：「超級微整型，被醫生監督」\n\n聯想畫面 1：工廠主管在生產線上進行嚴格的管理與監督，確保品質無誤。\n\n聯想畫面 2：研究生在教授的密切監督與指導下，順利完成畢業論文。\n\n高效擴充：super-（在上方）加上 vision（視線），在上方看著就是監督管理。\nKK 音標：[͵supɚˋvɪʒən] -> 主重音在第三音節ｳﾞｨˋ，注意 sion 發 ʒən 的濁音。\n\n常見同義字：\noversight（監督、監管，有時也指疏忽）\nmanagement（管理、經營，範圍較廣）\nadministration（行政、管理，多用於機構運作）",
  "supervisor": "諧音聯想：\n拆解 / 諧音：super（超級）+ visor（看視）\n\n諧音：「超級發威者」－當上管理人的主管超級會看管下屬，隨時監督工作。\n\n聯想畫面 1：工廠裡的管理員正在巡視生產線，監督員工品質。\n\n聯想畫面 2：研究生論文口試時，指導教授在一旁嚴格監督。\n\n高效擴充：動詞形式為 supervise（監督、管理）。\nKK 音標：[ˋsupɚ͵vaɪzɚ] -> 主重音在第一音節 su，字尾 or 發輕捲舌音。\n\n常見同義字：\nmanager（指經理，偏向日常營運管理）\ndirector（指總監或董事，職級較高）\noverseer（指工頭或監督人員，偏向勞力現場）",
  "supervisory": "拆解：super（超級/上方）+ vis（看）+ ory。\n\n聯想畫面 1：主管站在上方（super）看著（vis）大家工作，這就是監督的職責。\n\n聯想畫面 2：這份工作需要具備管理能力，負責監督團隊進度。\n\n高效擴充：super-（上方）+ vis-（看），在上方看就是監督。\nKK 音標：[͵supɚˋvaɪzɚi] -> 第三音節 vi 重音，注意長母音 i 的發音。\n\n常見同義字：\n\nmanagerial（管理的）\n\noversight（監督的）\n\nadministrative（行政的）。",
  "supper": "諧音聯想：\n諧音：「殺怕」\n\n聯想畫面 1：晚餐時間大家肚子都很餓，要把桌上的菜通通殺怕、吃個精光。\n\n聯想畫面 2：深夜肚子餓吃一碗宵夜，滿足地結束一天。\n\n高效擴充：雙寫 p 同樣代表前面的 u 發短母音。\nKK 音標：[ˋsʌpɚ] -> 重音在第一音節 sʌ，p 發清脆的爆破音。\n\n常見同義字：\n\ndinner（正餐、晚餐，現代比 supper 更常用）\n\nmeal（一餐、飯食的統稱）\n\nmidnight snack（宵夜、夜宵，口語最常用的說法）",
  "supplement": "諧音聯想：\n諧音：[ˋsʌpləmənt]\n諧音：「傻噗哩賣猛的補品」\n\n聯想畫面 1：為了應付期末考，他每天早晚都吃維他命B群作為營養補品。\n\n聯想畫面 2：雜誌社發行了一本特別增刊，作為讀者了解流行趨勢的補充物。\n\n高效擴充：字首 sup-（補足）加上 -plement（填滿），合起來就是增補、補充物。\nKK 音標：[ˋsʌpləmənt] -> 當名詞時重音在第一音節ｻˋ，當動詞時重音可能移到後面。\n\n常見同義字：\naddition（增加的人或物）\nadd-on（附加物、外加程式）\nextra（額外之物）",
  "supplementary": "拆解：sup（在下面）+ ple（滿）+ ment + ary。\n\n聯想畫面 1：當原本的內容不夠滿（ple），就需要補充（supplementary）一些資料進去。\n\n聯想畫面 2：他在主餐之外，點了一份補充的湯品。\n\n高效擴充：supplement 是補充物，補充就是讓原本不足的變滿。\nKK 音標：[͵sʌpləˋmɛntɚi] -> 第三音節 men 重音，注意 e 的短音。\n\n常見同義字：\n\nadditional（額外的）\n\nextra（額外的）\n\ncomplementary（互補的，注意拼法）。",
  "supplementing": "諧音聯想：\n諧音：撒普勒門停。\n\n聯想畫面 1：為了補充營養，他在餐點裡撒了一些粉末，這就是 supplementing。\n\n聯想畫面 2：寫論文時，他補充了更多的數據來支持論點。\n\n高效擴充：字首 sup（在下面）加上 plement（填滿），在下面填滿就是補充。\nKK 音標：[ˋsʌplɪmentɪŋ] -> 重音在第一個音節，唸起來要輕快。\n\n常見同義字：\n\nadding（增加）\n\ncomplementing（互補）\n\nfilling in（填補）。",
  "supplied": "諧音聯想：\n諧音：「手補來」。\n\n聯想畫面 1：物資不足時，大家伸出手互相補給，確保每個人都有足夠的糧食。\n\n聯想畫面 2：倉庫裡堆滿了貨物，已經被供應商填得滿滿的。\n\n高效擴充：supply 的過去式，去 y 加 ied。\nKK 音標：[səˋplaɪd] -> 重音在第二音節，發音時注意 d 的結尾。\n\n常見同義字：\n\nprovided（提供）\n\nfurnished（配備）\n\ndelivered（運送）。",
  "supplier": "拆解：sup（供應）+ plier（人）。\n\n聯想畫面 1：工廠的原料供應商（supplier）準時送貨，確保生產線順利運作。\n\n聯想畫面 2：我們需要尋找更便宜的零件供應商來降低成本。\n\n高效擴充：supply（供應）變為名詞，加上 -er 變成供應者。\nKK 音標：[səpˋlaɪɚ] -> 第二音節 pli 重音，注意長母音 i 的發音。\n\n常見同義字：\n\nprovider（提供者）\n\nvendor（小販/供應商）\n\ndistributor（經銷商）。",
  "supply": "諧音聯想：\n諧音：「捨得派來」\n\n聯想畫面 1：災區缺乏物資，政府終於捨得派來大量救援物資與補給品。\n\n聯想畫面 2：後勤倉庫源源不絕地供應前線士兵所需要的一切武器與糧食。\n\n高效擴充：與 demand（需求）為一對經典的反義字商業詞彙。\nKK 音標：[səpˋlaɪ] -> 主重音在第二音節 laɪ，字首 su- 念輕聲。\n\n常見同義字：\n\nprovide（提供、供應，最常見的動詞）\nfurnish（配備、裝備，常用於房間或設施）\nstock（存貨、儲備，當動詞或名詞皆可）",
  "support": "諧音聯想：\n諧音：「捨霸氣」\n\n聯想畫面 1：老大決定收起原本的兇狠，溫柔地支持並擁護身邊受挫的小弟。\n\n聯想畫面 2：演唱會現場歌迷舉著燈牌，全力支持自己喜愛的偶像歌手。\n\n高效擴充：字首 sup-（在下方）＋port（港口/搬運），在底下幫忙撐住就是支持。\nKK 音標：[səˋpɔrt] -> 主重音在第二音節 pɔrt，ɔ發飽滿的長音。\n\n常見同義字：\n\nback（支持、背部，口語常用 back up）\nadvocate（擁護、提倡，較正式）\nmaintain（維持、維護，強調保持現狀或運作）",
  "supportive": "拆解：sup（在下面）+ port（搬運/支撐）+ ive。\n\n聯想畫面 1：朋友在背後支撐（support）你，給你鼓勵，這就是 supportive 的表現。\n\n聯想畫面 2：父母對我的決定非常支持，從不反對。\n\n高效擴充：support（支撐）+ -ive（形容詞字尾），指給予支持的。\nKK 音標：[səˋpɔrtɪv] -> 第二音節 por 重音，注意 r 的捲舌音。\n\n常見同義字：\n\nencouraging（鼓勵的）\n\nhelpful（有幫助的）\n\ncaring（關心的）。",
  "suppose": "諧音聯想：\n諧音：「想破頭的猜」\n\n聯想畫面 1：猜謎遊戲中，大家都在心裡猜想答案究竟是什麼。\n\n聯想畫面 2：假定明天放颱風假，我們現在就要把計畫提前做好。\n\n高效擴充：常用被動型態 be supposed to（應該要……、理應……）。\nKK 音標：[səˋpoz] -> 第二音節重音，o 發長音 [o]。\n\n常見同義字：\n\nassume（假定、假設，基於某些前提）\n\npresume（推測、推定，法律或正式常用）\n\nguess（猜測，口語常用）",
  "suppress": "拆解：sup（向下）＋ press（壓）\n\n諧音：「死怕瑞斯」\n\n聯想畫面 1：暴動發生時，警方出動鎮暴警察大力壓制、鎮壓抗議群眾。\n\n聯想畫面 2：他強忍著淚水，努力把內心激動的情緒給抑制下去。\n\n高效擴充：sup- 是 sub- 的變體，press 代表施壓。\nKK 音標：[səˋprɛs] -> 主重音在第二個音節 prɛs，sup 弱化為 sə。\n\n常見同義字：\nquell（平息，尤指叛亂或暴動）\nrepress（壓抑，多指心理情感控制）\ncheck（阻止，抑制蔓延）",
  "supreme": "諧音聯想：\n諧音：速拼 -> 諧音聯想：拼命追求速度成為至高無上的冠軍。\n\n聯想畫面 1：最高法院是國家司法體系的最高權力機構。\n\n聯想畫面 2：這家餐廳的招牌披薩享有至高無上的美味評價。\n\n高效擴充：字首 supr 代表最高、超越。\nKK 音標：[səˋprim] -> 重音在第二音節 prim，sə 輕讀。\n\n常見同義字：\n\nhighest（最高的）\n\nsovereign（至高無上的）\n\nparamount（至高無上的、最重要的）",
  "surcharge": "諧音聯想：\n諧音：省錢吃 -> 諧音聯想：想要省錢吃大餐，結果店家卻多收了一筆附加費。\n\n聯想畫面 1：你在餐廳結帳時發現帳單多了一筆 surcharge，氣得大喊說好想省錢吃個飯怎麼變這麼貴。\n\n聯想畫面 2：網購結帳時突然跳出運費 surcharge，讓你覺得這筆額外費用很不合理。\n\n高效擴充：字首 sur- 表示超過、在上面，加上 charge（費用），合起來就是超出原本費用的附加費。\nKK 音標：[ˋsɝtʃɑrdʒ] -> 重音在首音節的 sur，念長音的 er，後面的 charge 發 ch 發音要俐落。\n\n常見同義字：\n\nadditional fee（額外費用，口語常用且好懂）\nextra charge（額外收費，常用於商業服務）\nsupplement（補充費或增補費，較正式）",
  "sure": "諧音聯想：\n諧音：「秀兒」很有自信地舉手，確定答案一定是對的。\n\n聯想畫面 1：主管問你明天任務能完成嗎，你點頭說 I am sure（有把握的）。\n\n聯想畫面 2：朋友問你晚上要不要吃火鍋，你回答 sure（當然好）。\n\n高效擴充：常組成 make sure（確保）或 for sure（確切地）。\nKK 音標：[ʃʊr] -> 結合了 ʃ 與 ʊr 的捲舌音，嘴唇微突後向後收。\n\n常見同義字：\ncertain（確定的，語氣較正式）\nconfident（有信心的，多形容人的心態）\ndefinitely（肯定地，強調毫無疑問）",
  "surely": "諧音聯想：\n諧音：誰（sure）力（ly）\n\n聯想畫面 1：誰有力氣去懷疑這件事呢？這件事肯定是無疑的。\n\n聯想畫面 2：他看著窗外說，這天氣想必會下雨，語氣非常肯定。\n\n高效擴充：sure 的副詞形式，sure 加 ly 拼寫不變。\nKK 音標：[ˋʃʊrli] -> 重音在第一個音節，發音時嘴型要圓潤，sure 的 r 音要捲舌。\n\n常見同義字：\ncertainly（最常用，表示百分之百確定）\nassuredly（較正式，表示有把握地）\nwithout question（強調毫無疑問，語氣強烈）",
  "surf": "諧音聯想：\n諧音：「色夫」\n\n聯想畫面 1：色夫大叔邊看著海邊的辣妹衝浪，邊用手機上網搜尋帥哥美女的圖片。\n\n聯想畫面 2：半夜不睡覺在網路上衝浪看影片，結果螢幕藍光照得臉色發青。\n\n高效擴充：源自海浪與海灘的意象，網路衝浪引申自海浪滑行的動作。\nKK 音標：[sɝf] -> 單音節字，發長音的 er，氣流像海浪般輕輕吐出。\n\n常見同義字：\nbrowse（瀏覽網頁，動作較休閒）\nnavigate（導航或瀏覽複雜系統）\nwave（名詞的海浪或揮手動作用語）",
  "surface": "諧音聯想：\n諧音：「殺佛死」\n\n聯想畫面 1：神話故事裡在水面上興風作浪的妖怪，終於浮出水面被英雄殺佛死。\n\n聯想畫面 2：桌子的表面沾滿了灰塵，看起來灰濛濛的一片需要擦拭。\n\n高效擴充：sur-（在上面）＋face（臉面），在上面的臉就是表面。\nKK 音標：[ˋsɝfəs] -> 重音在第一音節 sɝ，後面的 face 念輕聲 fəs。\n\n常見同義字：\n\nexterior（外部、外表，與 interior 相對）\ncover（覆蓋物、表面，動名詞皆可）\ntop（頂端、表面，最口語的說法）",
  "surfboard": "諧音聯想：\n拆解：surf（衝浪）+ board（板子）\n\n聯想畫面 1：他背著他的 surfboard 衝向大海，準備挑戰今天最大的海浪。\n\n聯想畫面 2：這塊 surfboard 的設計非常流線，讓他在浪尖上滑行得更順暢。\n\n高效擴充：surf 是浪花，board 是板子，合起來就是衝浪板。\nKK 音標：[ˋsɝfbɔrd] -> 重音在第一個音節 surf，發音時舌頭要捲起來發 er 的音。\n\n常見同義字：\n\nboard（板子，簡稱）\n\nlongboard（長板，衝浪板的一種）\n\nshortboard（短板，衝浪板的一種）",
  "surfeit": "諧音聯想：\n諧音：色費特（surfeit）。\n\n聯想畫面 1：宴會上吃太多色費特（各式甜點），導致暴飲暴食，感到噁心。\n\n聯想畫面 2：因為過度沉溺於奢華生活，對美食感到厭膩，這就是 surfeit。\n\n高效擴充：sur（超過）+ feit（做），做得太多了，就是過量。\nKK 音標：[ˋsɝfɪt] -> 重音在第一音節，sɝ 發捲舌長音。\n\n常見同義字：\n\nExcess（過量，最常用的詞）\n\nOverabundance（過剩，強調數量極多）\n\nGlut（供過於求，常用於市場）",
  "surge": "諧音聯想：\n諧音：「色局」－股市大漲的綠色局面失控，價格瞬間激增、如巨浪般湧來。\n\n聯想畫面 1：海面上突然出現一陣巨浪，把衝浪客高高拋起。\n\n聯想畫面 2：電力需求激增，導致夏日用電量暴衝。\n\n高效擴充：動詞三態為 surge, surged, surged。\nKK 音標：[sɝdʒ] -> 捲舌音 ɝ 加上 j 的音，嘴型微嘟後向外送氣。\n\n常見同義字：\nspike（指數據短時間內暴增、急遽上升）\nrush（指匆忙湧入或衝刺）\nwave（指波浪，或指一波波的人潮與熱潮）",
  "surgeon": "諧音聯想：\n諧音：「殺珍」\n\n聯想畫面 1：外科醫生拿著手術刀，小心翼翼地切開病人的患部，就像在殺珍貴的寶石一樣精準。\n\n聯想畫面 2：技術高超的外科醫生在手術室裡專注搶救病患，汗水滴落也不敢分心。\n\n高效擴充：字首 sur- 代表上方，搭配字根源自手作動作，指動手動腳開刀的專家。\nKK 音標：[ˋsɝdʒən] -> 重音在第一音節 sur，後面接弱化的 -geon 唸輕聲。\n\n常見同義字：\ndoctor（泛指醫生，較不特定於外科）\nphysician（內科醫生，與外科 surgeon 相對）\nspecialist（專科醫師的通稱）",
  "surgery": "諧音聯想：\n諧音：「殺局綠」\n\n聯想畫面 1：外科手術的無菌室裡鋪滿綠色的手術巾，醫生準備破除病魔的殺局。\n\n聯想畫面 2：病患躺在診所的診療床上等待手術，心情緊張地看著綠色的牆壁。\n\n高效擴充：由 surgeon 衍生而來的名詞，指外科手術或診所辦公室。\nKK 音標：[ˋsɝdʒɚi] -> 重音在第一音節 sur，後面三個音節輕快唸出。\n\n常見同義字：\noperation（正式的手術醫療過程）\nprocedure（醫療程序或常規手術）\nclinic（指診所時的同義概念）",
  "surmise": "諧音聯想：\n拆解 / 諧音：sur（搜尋）+ mise（迷思）\n\n聯想畫面 1：透過搜尋各種迷思線索，偵探推測出兇手的動機。\n\n聯想畫面 2：他根據不完整的證據，猜測這場會議可能會被取消。\n\n高效擴充：sur- 字首有「在上面」或「超越」之意，這裡引申為從表面線索去猜測。\nKK 音標：[sɚˋmaɪz] -> 重音在第二個音節，maiz 發音像「麥子」，記得重音往後移。\n\n常見同義字：\nguess（最口語的猜測）\nspeculate（較正式，指基於推論的猜測）\nconjecture（正式用語，指基於不完整證據的推測）",
  "surpass": "諧音聯想：\n諧音：「賽跑死」\n\n聯想畫面 1：在賽跑中死命往前衝，終於勝過、超過對手。\n\n聯想畫面 2：銷售業績大於預期，大幅度超越去年同期。\n\n高效擴充：sur (超過) 加上 pass (通過)，超越通過即是勝過。\nKK 音標：[sɚˋpæs] -> 第二音節重音，sur 發 r 音，pass 發短音 a。\n\n常見同義字：\n\nexceed（超過，常用於數量、標準或極限）\n\noutdo（勝過或做得比……更好，口語常用）\n\ntranscend（超越，偏向思想、精神或哲學層面）",
  "surplus": "諧音聯想：\n諧音：[ˋsɝpləs]\n諧音：「殺豬普渡，拜到有剩餘」\n\n聯想畫面 1：中元普渡拜拜的供品實在太多了，家裡出現了大量的食物過剩現象。\n\n聯想畫面 2：政府今年稅收表現優異，財政預算出現了難得的盈餘。\n\n高效擴充：sur-（超過）加上 plus（更多），超過很多就是過剩與盈餘。\nKK 音標：[ˋsɝpləs] -> 重音在第一音節ｻˋ，捲舌音 ɝ 要發得扎實。\n\n常見同義字：\nexcess（超過、過量，常帶負面意涵）\nremainder（剩餘部分、其他的人事物）\nbalance（結餘、差額）",
  "surprise": "諧音聯想：\n諧音：「死豬排撕」\n\n聯想畫面 1：打開便當盒發現裡面不是排骨，竟然是一個大驚喜禮物。\n\n聯想畫面 2：朋友躲在門後大喊生日快樂，讓人嚇一大跳又驚喜。\n\n高效擴充：字首 sur 表示在上面或超越，結合 prize 獎品，意指意料之外的收獲。\nKK 音標：[sɚˋpraɪz] -> 第二音節 praɪz 為主重音，發長雙母音 ai 的音。\n\n常見同義字：\n\nashonished（指感到非常震驚與驚訝的狀態）\n\namaze（動詞，指使人讚嘆或驚奇）\n\nastonishment（名詞，表示極大的驚訝）",
  "surprised": "諧音聯想：\n諧音：色普萊斯（Surprised）。\n\n聯想畫面 1：你打開禮物盒，發現裡面竟然是一隻色普萊斯貓，讓你驚訝得下巴掉下來。\n\n聯想畫面 2：走在路上突然被朋友從背後拍肩嚇一跳，那種驚訝的表情就是surprised。\n\n高效擴充：sur-是超過，prise是抓住，意外抓住你的心就是驚訝。\nKK 音標：[sɚˋpraɪzd] -> 重音在第二音節，唸起來要像被嚇到一樣有力。\n\n常見同義字：\n\namazed（強調驚嘆不已）\n\nastonished（強調驚訝到說不出話）\n\nshocked（強調受到驚嚇或震撼）。",
  "surprisingly": "諧音聯想：\n拆解：surprise（驚喜）+ ing + ly。\n\n聯想畫面 1：他 surprisingly 出現在機場，給我一個大大的驚喜。\n\n聯想畫面 2：這道菜 surprisingly 好吃，完全出乎意料。\n\n高效擴充：由 surprise 變化而來的副詞。\nKK 音標：[sərˋpraɪzɪŋli] -> 重音在第二音節，注意 i 的長音。\n\n常見同義字：\n\namazingly（驚人地）\n\nunexpectedly（出乎意料地）\n\nsurprisingly（常用於句首）。",
  "surrender": "諧音聯想：\n諧音：「撒藍蛋」\n\n聯想畫面 1：戰場上打輸了，士兵只好把武器撒在地上舉手投降，交出藍色旗幟。\n\n聯想畫面 2：面對美食的誘惑，我終於舉手投降，把減肥計畫拋諸腦後。\n\n高效擴充：sur-（超過、往上）加上 render（給予、交出），指把主權交出去。\nKK 音標：[sɚˋɛndɚ] -> 第二音節 en 為主重音，發音要用力且清晰。\n\n常見同義字：\nyield（屈服、讓步，較常指被動妥協）\ngive in（片語動詞，無奈地妥協投降）\nsubmit（正式屈服、提交或服從）",
  "surround": "諧音聯想：\n諧音：「死軟的」\n\n聯想畫面 1：警察把嫌犯團團圍住，四周圍得水洩不通。\n\n聯想畫面 2：美麗的湖泊被群山環繞，形成一幅絕美的風景畫。\n\n高效擴充：常轉為過去分詞當形容詞 surrounding（周圍的、附近的）。\nKK 音標：[sɚˋaʊnd] -> 第二音節重音，ou 發 [aʊ] 的雙母音。\n\n常見同義字：\n\nencircle（環繞、包圍，像圓圈一樣）\n\nenviron（圍繞、包圍，較文言）\n\nambience（名詞：周圍環境氣氛）",
  "surroundings": "諧音聯想：\n諧音：「山繞釘子」\n\n聯想畫面 1：四周的環境都是山，樹上還釘著指示牌，這就是我身處的周圍環境。\n\n聯想畫面 2：搬到新家後，我花了一整天熟悉周圍的事物與鄰近的街道。\n\n高效擴充：surround（包圍）加上 -ings 變成複數名詞，專指周遭環境。\nKK 音標：[sɚˋaʊndɪŋz] -> 重音在第二音節 round，字尾的 -ings 要鼻音收尾。\n\n常見同義字：\nenvironment（自然或整體的環境、生態）\nsetting（背景、佈景或周遭情境）\natmosphere（氛圍、氣氛，偏心理感受）",
  "survey": "諧音聯想：\n諧音：「誰會喂」\n\n聯想畫面 1：誰會喂流浪貓呢？志工拿著調查報告在社區做民意調查。\n\n聯想畫面 2：工程師在建地拿著儀器進行土地考察與審視。\n\n高效擴充：sur 代表遠眺、over，vey 代表看，綜觀全局就是調查報告。\nKK 音標：[sɚˋve] -> 第二音節 ve 帶有主重音，長音「威」，sɚ 唸輕短的「瑟」。\n\n常見同義字：\npoll（民調、投票，常指政治選舉前的民意測驗）\ninvestigation（調查，通常指犯罪或深入查證）\nquestionnaire（問卷，收集資料的表格）",
  "survival": "諧音聯想：\n諧音：「死而微發」\n\n聯想畫面 1：荒島野外求生中，他差點死掉卻微弱發光，展現出驚人的生存能力。\n\n聯想畫面 2：地震過後，災民在瓦礫堆中等待救援，展現強烈的倖存意志。\n\n高效擴充：由動詞 survive 加上名詞字尾 al 變化而來，核心意象為活下來。\nKK 音標：[sɚˋvaɪvəl] -> 第二音節 vaɪ 帶有主重音，唸長音「瓦伊」，字尾 vəl 輕聲唸。\n\n常見同義字：\nliving（生計、活著的狀態）\nexistence（存在，泛指人或事物的存在）\npersistence（堅持不懈，指持續努力的過程）",
  "survive": "諧音聯想：\n諧音：「死而嗨威」\n\n聯想畫面 1：荒島求生隊員歷經危難，死裡逃生後開心大喊活下來了。\n\n聯想畫面 2：這棟老建築在強震中幸存下來，結構依然完整。\n\n高效擴充：sur 超過、vive 生命，超越死亡威脅就是生還。\nKK 音標：[sɚˋvaɪv] -> 主重音在 vaɪv，長音 i 與 v 結尾。\n\n常見同義字：\noutlive（比...活得長）\nremain（保持、殘存）\nendure（忍耐、持久）",
  "survivor": "諧音聯想：\n諧音：「死而微發兒」\n\n聯想畫面 1：那個死而微發兒的小孩奇蹟似地成為空難中的生還者。\n\n聯想畫面 2：老兵坐在椅子上講述戰場故事，他是少數歷經戰火的倖存者。\n\n高效擴充：動詞 survive 加上表人的字尾 or，專指活下來的那個人。\nKK 音標：[sɚˋvaɪvɚ] -> 第二音節 vaɪ 是主重音，發長音「瓦伊」，vaɪvɚ 語調往下掉。\n\n常見同義字：\nleftover（剩餘物、剩菜，少用來指人）\nremnant（殘存物、遺跡，通常指物品）\nVictim（受害者，但生還者不一定等於受害者）",
  "susceptible": "諧音聯想：\n拆解 / 諧音：sus（死）+ cep（接）+ tible（得）\n\n聯想畫面 1：身體太虛弱，死接病毒，變得非常容易得病。\n\n聯想畫面 2：他性格敏感，容易被感人的電影情節影響而落淚。\n\n高效擴充：字根 cept 代表「拿、取」，susceptible 就是容易被外界拿走防禦力，變得脆弱。\nKK 音標：[səˋsɛptəbəl] -> 重音在第二個音節，sɛp 的發音要短促有力。\n\n常見同義字：\nsensitive（敏感的，指情緒或生理）\nvulnerable（易受傷害的，指防禦力弱）\nprone to（傾向於，常指易患某種疾病或習慣）",
  "suspect": "諧音聯想：\n諧音：「殺死配客」\n\n聯想畫面 1：警察懷疑快遞員就是兇手，把他列為謀殺案的主要嫌疑犯。\n\n聯想畫面 2：偵探看著地上的腳印，猜想這條路非常可疑。\n\n高效擴充：字首 sus 代表下方，spect 代表看，在暗地裡偷看就是懷疑。\nKK 音標：[səˋspɛkt] -> 當動詞或形容詞時重音在第二音節 pɛkt，唸輕快的「斯佩克特」。\n\n常見同義字：\ndoubt（懷疑，偏向不相信某事為真）\ndistrust（不信任，對人不信任）\nalleged（聲稱的、涉嫌的，常用於法律報導）",
  "suspend": "拆解：sus（在下面）＋ pend（懸掛）\n\n諧音：「死死盤著」\n\n聯想畫面 1：猴子用尾巴死死盤著樹枝，整隻動物懸掛在半空中。\n\n聯想畫面 2：球賽因為突然下大雨，裁判宣佈暫停比賽、中止進行。\n\n高效擴充：pend 字根意指懸掛（如 pendant 墜飾），引申為掛置、暫緩。\nKK 音標：[səˋspɛnd] -> 主重音在第二個音節 spɛnd，sus 弱化為 sə。\n\n常見同義字：\npostpone（延期，將時間往後挪）\nhalt（暫停，短暫的停頓）\ninterrupt（打斷，中斷進行中的事）",
  "suspense": "諧音聯想：\n諧音：[səˋspɛns]\n諧音：「捨不得死，劇情好懸疑」\n\n聯想畫面 1：懸疑小說的結局高潮迭起，讓讀者在緊張焦慮中等待真相大白。\n\n聯想畫面 2：電影播到最緊張的時刻突然廣告，全場觀眾都在懸疑中議論紛紛。\n\n高效擴充：sus-（懸掛）加上 pense（懸掛著不上不下），心懸在半空中就是懸疑焦慮。\nKK 音標：[səˋspɛns] -> 第二音節ｽﾍﾟˋ是主重音，結尾的 ns 發音要輕快。\n\n常見同義字：\nuncertainty（不確定性，引發焦慮）\ntension（緊張局勢或心理壓力）\nanxiety（焦慮、掛慮，偏向心理狀態）",
  "suspension": "諧音聯想：\n諧音：[səˋspɛnʃən]\n諧音：「捨不得宣佈停職」\n\n聯想畫面 1：球員因為違規行為遭到裁判判決禁賽，面臨暫時停賽的處分。\n\n聯想畫面 2：由於豪雨不斷，捷運系統宣布暫停營運，進行安全檢查。\n\n高效擴充：由 suspense 衍生而來，將事情懸掛起來不處理就是暫停與中止。\nKK 音標：[səˋspɛnʃən] -> 主重音在第二音節ﾍﾟˋ，sion 發 ʃən 的清音。\n\n常見同義字：\ninterruption（中斷、打擾，暫時停止進行）\npostponement（延期、延緩，將活動改期）\ndelay（延遲、耽擱，時間上的拖延）",
  "suspicion": "諧音聯想：\n諧音：「殺死批瞎」\n\n聯想畫面 1：兇手充滿殺意的眼神引起大家的懷疑與不好的預感。\n\n聯想畫面 2：太太看見先生手機有曖昧訊息，心中充滿猜疑與嫉妒。\n\n高效擴充：由 suspect 變化而來的名詞，字尾 tion 代表抽象名詞。\nKK 音標：[səˋspɪʃən] -> 第二音節 ʃɪ 帶有主重音，唸「斯比許」，字尾 ən 唸輕聲。\n\n常見同義字：\ndoubt（疑心、疑問）\nmisgiving（擔憂、疑慮，對未來或計畫的不安）\nskepticism（懷疑論、猜疑心，對普遍說法的質疑）",
  "suspicious": "諧音聯想：\n諧音：「誰絲披雪」在身上？真令人懷疑。\n\n聯想畫面 1：警察看見路邊那個人鬼鬼祟祟的，眼神充滿了可疑。\n\n聯想畫面 2：她對於男友手機裡突然出現的陌生訊息感到十分猜疑。\n\n高效擴充：名詞 suspicion (懷疑) 轉換而來的形容詞，字尾 ious 表形容詞。\nKK 音標：[səˋspɪʃəs] -> 第二音節 spɪʃ 為主重音，注意 sh 的發音。\n\n常見同義字：\ndoubtful（懷疑的、不確定的，指心存疑慮）\nfishy（可疑的、不對勁的，口語常用來形容事情怪怪的）\nquestionable（可疑的、有問題的，指真實性或合法性存疑）",
  "sustain": "拆解：sus（在下面）＋ tain（拿住）\n\n諧音：「死撐」\n\n聯想畫面 1：梁柱在地震中死撐著天花板，成功支撐住整棟建築物不倒塌。\n\n聯想畫面 2：靠著微薄的薪水，他艱難地維持一家老小的生計。\n\n高效擴充：字根 tain 意指 hold（握住、保持），與 contain 同源。\nKK 音標：[səˋsten] -> 主重音在第二個音節 sten，ai 發長 e 音。\n\n常見同義字：\nsupport（支撐、支持，最常用詞）\nmaintain（維持，保持現狀或水準）\nendure（忍受、持久，強調時間考驗）",
  "sustainability": "拆解：sustain 維持 + ability 能力\n\n諧音：「誰死誰呆能補得替」\n\n聯想畫面 1：企業為了地球環境的永續性，砸重金研發綠能科技來維持生態。\n\n聯想畫面 2：這家公司的商業模式具備良好的永續性與能維持的優勢。\n\n高效擴充：由形容詞 sustainable 去 e 加 ity 轉為抽象名詞。\nKK 音標：[sə͵stenəˋbɪlətɪ] -> 主重音落在倒數第三音節 ˋbɪ。\n\n常見同義字：\n viability（可行性、生存能力）\ndurability（耐用性、持久性）\nmaintenance（維持、保養）",
  "sustenance": "諧音聯想：\n諧音：撒死騰呢死。\n\n聯想畫面 1：在荒島上，這幾顆椰子成了他唯一的食物與營養來源。\n\n聯想畫面 2：對於這家小店來說，穩定的客源就是他們維持生計的命脈。\n\n高效擴充：字根 sus（在下面）+ ten（支撐），支撐在下面就是維持生命。\nKK 音標：[ˋsʌstənəns] -> 重音在第一個音節，發音要短促有力。\n\n常見同義字：\n\nnourishment（營養，較正式）\n\nlivelihood（生計，強調謀生手段）。",
  "svelte": "諧音聯想：\n諧音：「絲薇特」的連身裙穿在身上，顯得身材無比苗條纖細。\n\n聯想畫面 1：時尚名模擁有完美流線型的苗條身段。\n\n聯想畫面 2：最新款的手機外型設計纖薄優雅，線條非常流暢。\n\n高效擴充：源自法文，特別用來形容人或物體的纖細、優雅與流線感。\nKK 音標：[svelt] -> 單音節短促有力，母音發 [ɛ] 並帶捲舌感。\n\n常見同義字：\n\nslender（苗條的）\n\ntrick（瘦削的、苗條的）\n\ngraceful（優雅的）",
  "swagger": "諧音聯想：\n諧音：死挖個\n\n聯想畫面 1：他走路大搖大擺，好像在說死挖個（swagger）坑給別人跳，一副不可一世的樣子。\n\n聯想畫面 2：模特兒在伸展台上 swagger，走起路來神氣十足，充滿自信。\n\n高效擴充：swagger 結合了 swaggering（搖擺）的動作，形容那種趾高氣揚的態度。\nKK 音標：[ˋswæɡər] -> 重音在第一音節，swæ 唸得要有搖擺感，像模特兒走路的節奏。\n\n常見同義字：\nStrut（趾高氣揚地走，強調姿勢）\nBoast（吹牛，指言語上的自誇）\nSwaggering（大搖大擺的，形容詞用法）",
  "swallow": "諧音聯想：\n諧音：「死挖落」\n\n聯想畫面 1：喉嚨痛得要命，每一次吞口水都像死挖落一樣難受。\n\n聯想畫面 2：一隻可愛的燕子在天空開心飛翔，最後停在屋簷上品嘗小蟲。\n\n高效擴充：動詞表示吞嚥，名詞同時也可以指「燕子」這個動物。\nKK 音標：[ˋswɑlo] -> 重音在第一音節 swɑ，ow 發 o 的長音。\n\n常見同義字：\n\ningest（攝取、嚥下，較為科學或醫學正式用語）\nconsume（消耗、吞噬，強調吃光用光）\nmartin（紫燕、家燕，相關鳥類總稱）",
  "swamp": "諧音聯想：\n諧音：「死汪怕」－狗狗掉進沼澤溼地裡死命哀汪，讓主人好怕。\n\n聯想畫面 1：熱帶雨林深處的沼澤地長滿了紅樹林。\n\n聯想畫面 2：工作量太多把員工壓得喘不過氣，形容工作被事務淹沒。\n\n高效擴充：常作片語 be swamped with（忙得不可開交）。\nKK 音標：[swɑmp] -> 嘴型由圓到扁，發出短促的 ɑ 鼻音與尾音 p。\n\n常見同義字：\nmash（指糊狀物，或泥濘地）\nbog（指泥炭沼澤）\nmarsh（指草本植物生長的低溼地）",
  "swan": "諧音聯想：\n諧音：「死碗」\n\n聯想畫面 1：優雅的天鵝在湖面上漫遊，姿態高貴得像是不小心打破了一個死貴的碗。\n\n聯想畫面 2：午後在公園湖畔散步，看著天鵝成雙成對地在水裡悠閒滑行。\n\n高效擴充：注意拼法為 s-w-a-n，常在童話故事（如醜小鴨）中出現。\nKK 音標：[swɑn] -> 單音節字，sw 複合子音開頭，ɑ發開口音。\n\n常見同義字：\n\ngoose（鵝，體型較天鵝粗壯且脖子較短）\nduck（鴨子，體型更小且叫聲不同）\nwander（漫遊、閒逛，動詞拼法與swan發音相近但意義不同）",
  "swank": "諧音聯想：\n諧音：死完客\n\n聯想畫面 1：他穿著華麗的衣服在派對上賣弄，直到死完客（swank）才肯罷休，就是為了出風頭。\n\n聯想畫面 2：這家飯店裝潢非常 swank，看起來高級又時髦，讓人想拍照炫耀。\n\n高效擴充：swank 既可以指炫耀的行為，也可以形容華麗時髦的風格。\nKK 音標：[swæŋk] -> 單音節，結尾的 nk 要發得乾脆，像在炫耀時的響指聲。\n\n常見同義字：\nShow off（炫耀，指行為）\nFlashy（華麗的，指外表）\nStylish（時髦的，指風格）",
  "swap": "諧音聯想：\n諧音：[swɑp]\n諧音：「死挖泡泡糖來交換」\n\n聯想畫面 1：小朋友下課時拿自己的神奇寶貝卡片跟同學互相交換。\n\n聯想畫面 2：兩家公司進行技術交流，把各自的專利互相替換使用。\n\n高效擴充：擬聲字概念，像是在手中快速甩動物品進行交換。\nKK 音標：[swɑp] -> 單音節短母音 ɑ，發音短促有力。\n\n常見同義字：\nexchange（標準的交換、交流，適用於物品或意見）\ntrade（進行商業交易或物資交換）\nreplace（用A替換B）",
  "swarm": "諧音聯想：\n諧音：「死窩嘛」－蜜蜂死守著蜂窩嘛，一大群蜂湧而出在空中飛。\n\n聯想畫面 1：公園樹上掛著一大群蜜蜂，蜂擁圍繞著蜂后。\n\n聯想畫面 2：百貨公司週年慶開門，大批顧客如蜂群般湧入。\n\n高效擴充：可用於形容昆蟲或人群的大量聚集。\nKK 音標：[swɔrm] -> 母音為 ɔr，發音時嘴巴微開向後拉。\n\n常見同義字：\ncrowd（指一般的人群聚集）\nmob（指情緒激動的暴民或聚集民眾）\nflock（指鳥類或羊群的聚集）",
  "sway": "諧音聯想：\n諧音：「水」\n\n聯想畫面 1：大樹被強風吹得左右搖晃，就像水草在水中隨波逐流。\n\n聯想畫面 2：聽著慢歌，台下的觀眾忍不住跟著節奏搖擺身體。\n\n高效擴充：字尾 ay 發長雙母音 [e]，發音短促且嘴型由寬變扁。\nKK 音標：[swe] -> 單音節字，像風吹過去的氣音，嘴型往兩側拉開。\n\n常見同義字：\nswing（擺動，幅度通常較大或呈弧形）\nrock（前後或左右輕微晃動，如搖籃）\ninfluence（抽象的影響、支配力）",
  "swear": "諧音聯想：\n諧音：「死威而鋼」發音聯想\n\n聯想畫面 1：法庭上證人舉起右手發誓，保證自己絕對說的是實話。\n\n聯想畫面 2：遇到不順心的事忍不住大聲咒罵、飆髒話。\n\n高效擴充：不規則三態為 swear, swore, sworn，常用於 swear an oath（宣誓）。\nKK 音標：[swɛr] -> 複合子音 sw 加上 ear 發 [ɛr]，注意捲舌。\n\n常見同義字：\n\npromise（承諾、答應）\n\nvow（誓言、發誓，通常指神聖的誓約）\n\npledge（發誓、保證，常指財務或忠誠承諾）",
  "sweat": "諧音聯想：\n諧音：「濕歪特」\n\n聯想畫面 1：大熱天跑步跑得濕歪特，全身都在狂流汗。\n\n聯想畫面 2：緊張的面試讓應徵者滿頭大汗，衣服都被汗水浸濕了。\n\n高效擴充：短母音 e 的發音，與 sweet（甜的）拼法容易混淆需特別注意。\nKK 音標：[swɛt] -> 單音節短促有力，嘴巴微開唸短音「斯衛特」。\n\n常見同義字：\nperspiration（汗水、流汗，較正式的醫學或書面用語）\nmoisture（水分、濕氣）\ndampness（潮濕，環境或物品的濕潤）",
  "sweater": "諧音聯想：\n諧音：「死喂他」\n\n聯想畫面 1：天氣太冷了，媽媽逼你穿上厚重毛衣，簡直像是在死喂他（塞衣服）一樣溫暖。\n\n聯想畫面 2：冬天坐在咖啡廳裡，身上穿著一件好看的針織毛線衫，非常有過節氣氛。\n\n高效擴充：從 sweat（流汗）衍生而來，因為毛衣通常穿了會保暖到流汗。\nKK 音標：[ˋswɛtɚ] -> 重音在第一音節 swɛ，tɚ 發捲舌輕聲。\n\n常見同義字：\n\ncardigan（開襟羊毛衫、針織外套）\npullover（套頭衫、套頭毛衣）\njumper（罩衫、毛衣，英式英語常用）",
  "sweep": "諧音聯想：\n諧音：「水批」\n\n聯想畫面 1：地板掃得好乾淨、水水亮亮的一批，看起來真舒服。\n\n聯想畫面 2：阿姨拿著大掃帚，把客廳地上的落葉與灰塵全部清掃乾淨。\n\n高效擴充：過去式與過去分詞皆為 swept，常組成片語 sweep away（橫掃、清除）。\nKK 音標：[swip] -> 單音節字，ee 發長母音 i。\n\n常見同義字：\n\nclean（清潔、打掃，最廣泛的動詞）\nbrush（刷、拂去，強調用刷具清理）\nwipe（擦拭、抹去，通常指用布或手擦表面）",
  "sweet": "諧音聯想：\n諧音：「絲微特」\n\n聯想畫面 1：咬下一口草莓蛋糕，口感絲滑微甜，非常美味。\n\n聯想畫面 2：男友送了一束花還甜言蜜語，讓人心裡甜滋滋的。\n\n高效擴充：字尾 eet 發長母音 i，常見於形容美好的口感或人際關係。\nKK 音標：[swit] -> 長母音 i，嘴角微向兩側咧開，發音拉長。\n\n常見同義字：\n\nsugary（形容含有過多糖分或甜味的）\n\ncandy（名詞，指糖果類零食）\n\npleasant（形容令人愉悅、親切溫柔的）",
  "sweetie": "拆解：sweet（甜的）+ ie（小可愛字尾）\n\n諧音：絲威蒂。\n\n聯想畫面 1：情侶之間互相暱稱對方為親愛的寶貝，就像吃了糖果一樣甜滋滋。\n\n聯想畫面 2：寵物狗乖乖坐好時，主人摸摸它的頭稱讚它是個小甜心。\n\n高效擴充：常加在形容詞字尾表示親暱感，如 birdie 小鳥。\nKK 音標：[ˈswiːti] -> 主重音在 [swiː]，長音 [iː] 嘴巴要拉開。\n\n常見同義字：\n\nhoney（親愛的，最經典的愛稱）\n\ndarling（親愛的，較傳統浪漫的詞）\n\nbae（網路流行語，指寶貝）",
  "swell": "諧音聯想：\n諧音：「死威而」\n\n聯想畫面 1：被蜜蜂叮到的手迅速腫脹，像死威而一樣大得嚇人。\n\n聯想畫面 2：海面上突然出現強烈的湧浪，讓小船上下劇烈晃動。\n\n高效擴充：字尾 ll 結尾的短母音字，三態變化為 swell, swelled, swollen。\nKK 音標：[swɛl] -> 單音節字，母音 e 唸短音，結尾 l 發捲舌音「斯威爾」。\n\n常見同義字：\nexpand（擴大、膨脹，體積變大）\ninflate（充氣、膨脹，打氣使之鼓起）\nbulge（凸起、腫脹，局部突出）",
  "swelling": "諧音聯想：\n諧音：死威靈。\n\n聯想畫面 1：腳踝撞傷後腫起來，看起來像死掉的威靈頓牛排，這就是 swelling。\n\n聯想畫面 2：河水因為大雨而暴漲，水位不斷上升。\n\n高效擴充：swell 是腫脹，加上 ing 變成名詞或動名詞。\nKK 音標：[ˋswelɪŋ] -> 重音在第一個音節，發音時嘴巴要像腫起來一樣圓。\n\n常見同義字：\n\ninflammation（發炎腫脹）\n\nexpansion（膨脹）\n\nenlargement（增大）。",
  "swept": "諧音聯想：\n諧音：誰普。\n\n聯想畫面 1：颱風席捲而來，誰普（誰敢說）這不是大自然的威力？\n\n聯想畫面 2：他用掃把快速掃除落葉，動作俐落。\n\n高效擴充：sweep 的過去式，形容動作快速掠過。\nKK 音標：[swept] -> 發音短促，結尾的 pt 要輕咬。\n\n常見同義字：\n\nbrushed（刷過）\n\ncleared（清除）\n\nwiped（擦拭）。",
  "swift": "諧音聯想：\n諧音：「死揮負」\n\n聯想畫面 1：武林高手出劍速度極快，刷的一聲非常 swift。\n\n聯想畫面 2：快遞員送包裹動作迅速，手腳俐落又 swift。\n\n高效擴充：聯想到 Swift 也是雨燕鳥的名字，飛行速度極快。\nKK 音標：[swɪft] -> 留意短母音 i，結尾的 ft 子音群要發清楚。\n\n常見同義字：\nfast（最常見的快，適用於速度）\nquick（動作敏捷、反應快的）\nrapid（變化或進展快速的，較正式）",
  "swim": "諧音聯想：\n諧音：「死溫」\n\n聯想畫面 1：大熱天去游泳池玩水，結果水溫太冰冷，游到一半直呼水冷得快要死溫了。\n\n聯想畫面 2：暑假跟朋友去河邊玩水，比賽誰能一口氣游到對岸，游完直呼過癮。\n\n高效擴充：三字母極簡短拼字，以 s 開頭加上 vim，注意短母音 ɪ 的發音短促有力。\nKK 音標：[swɪm] -> 重音在單字本身，s 與 w 快速連音，短元音 i 嘴型扁平短促。\n\n常見同義字：\n\nfloat（漂浮，指身體輕鬆浮在水面上而非用力划水）\n\ndive（潛水、跳水，強調頭朝下入水的動作）\n\npaddle（戲水、划槳，通常指在淺水區用手腳拍打或划動）",
  "swing": "諧音聯想：\n諧音：「死穩個」\n\n聯想畫面 1：坐在公園的鞦韆上，要想辦法死穩個（抓緊繩子），才不會盪得太高摔下來。\n\n聯想畫面 2：打高爾夫球或棒球時，用力揮動球桿與球棒的那一瞬間。\n\n高效擴充：三態變化為 swing, swung, swung，注意過去式與分詞變化。\nKK 音標：[swɪŋ] -> 單音節字，鼻音 ŋ 結尾，短母音 ɪ 發短促的「伊」。\n\n常見同義字：\n\nrock（搖晃、搖擺，通常指前後或上下輕晃）\nsay（揮動、揮舞，尤指武器或球棒）\nhang（懸掛，動詞三態變化常與 swing 混淆需注意）",
  "swished": "諧音聯想：\n諧音：水洗（swished 聽起來像水洗）。\n\n聯想畫面 1：他快速揮動球拍，發出嗖的一聲。\n\n聯想畫面 2：裙擺在風中快速甩動，發出輕微的嗖嗖聲。\n\n高效擴充：swish 模仿物體快速移動時空氣摩擦的聲音。\nKK 音標：無提供 -> 單音節，結尾的 sh 音要發出摩擦聲。\n\n常見同義字：\n\nwhooshed 嗖地移動；swung 揮動；brushed 刷過。",
  "swiss": "諧音聯想：\n諧音：水絲。\n\n聯想畫面 1：瑞士的冰川融化成水，像絲綢一樣滑順。\n\n聯想畫面 2：吃著瑞士起司，上面有許多小洞，像水絲一樣穿過。\n\n高效擴充：指瑞士人或瑞士風格，常與巧克力、起司聯想。\nKK 音標：[swɪs] -> 單音節，發音短促，像蛇吐信的聲音。",
  "switch": "諧音聯想：\n諧音：「死威奇」\n\n聯想畫面 1：走進黑暗的房間，順手按下牆上的電燈開關。\n\n聯想畫面 2：兩人突然交換座位，進行了一場意想不到的轉變。\n\n高效擴充：結合 sw 音群與 tch 結尾，常見於電源開關或工作輪班。\nKK 音標：[swɪtʃ] -> 單音節字，短母音 ɪ 唸「斯威奇」，結尾 tch 緊湊清脆。\n\n常見同義字：\nchange（改變、更換，最通用的替換詞）\nalternate（交替、輪流，依序替換）\ntoggle（切換開關，電腦介面上常見的按鈕）",
  "swollen": "諧音聯想：\n諧音：死（s）＋窩（wo）＋輪（len）。\n\n聯想畫面 1：腳踝腫得像個死掉的輪胎，又大又圓。\n\n聯想畫面 2：大雨過後，河水腫脹上漲，淹沒了河岸邊的窩。\n\n高效擴充：這是 swell 的過去分詞，形容詞用法很常見。\nKK 音標：[ˋswoʊlən] -> 第一音節 swo 發音要圓唇。\n\n常見同義字：\n\npuffy（浮腫的）\n\ninflamed（發炎紅腫的）。",
  "sword": "諧音聯想：\n諧音：「所得」\n\n聯想畫面 1：古代勇士的戰利品就是一把鋒利的寶劍，這代表他應得的所得。\n\n聯想畫面 2：國王在冊封儀式上，用寶劍輕輕點在騎士的肩膀上。\n\n高效擴充：字首 sw 後接 ord，w 不發音，唸作 sord 的音。\nKK 音標：[sɔrd] -> 單音節字，w 不發音，o 唸低沉的長音「索德」。\n\n常見同義字：\nblade（刀片、劍身，借代指刀劍）\nsaber（軍刀、馬刀，單刃微彎的刀）\nweapon（武器，泛指所有攻擊性器具）",
  "syllable": "諧音聯想：\n諧音：「洗樂伯」\n\n聯想畫面 1：英文老師教大家把單字拆成一個個音節來讀，大家快樂地洗樂伯的音樂課。\n\n聯想畫面 2：發音時算清楚每個單字有幾個音節，才不會念錯重音。\n\n高效擴充：字首 syl- 是 syn- 的變體（共同），把聲音組合在一起的單位。\nKK 音標：[ˋsɪləbəl] -> 重音在第一音節 syl，後面兩音節輕短唸過。\n\n常見同義字：\nphoneme（音位、語音中最小的單位）\nunit（泛指單位，非專指語言）\nword part（字詞組成部分）",
  "sylphlike": "諧音聯想：\n拆解 / 諧音：希爾芙萊克\n\n諧音像森林精靈「希爾芙」般苗條窈窕。\n\n聯想畫面 1：芭蕾舞者身形輕盈曼妙，宛如精靈一般優雅。\n\n聯想畫面 2：她穿著仙氣飄飄的禮服出席晚宴，身姿極其纖細窈窕。\n\n高效擴充：sylph（窈窕女子、風精靈）＋ like（像...一樣），形容極度輕盈優美。\nKK 音標：[ˋsɪlflɑɪk] -> 重音在第一音節「sɪl」，後面「flɑɪk」發輕快音。\n\n常見同義字：\n\nsvelte（苗條的、纖細優雅的）\n\nslender（纖細的）\n\nethereal（飄逸的、超凡脫俗的）",
  "symbol": "諧音聯想：\n諧音：「心不破」的信物，就是愛情的符號與永恆象徵。\n\n聯想畫面 1：情侶將刻有誓言的戒指當作彼此愛情的象徵與重要標誌。\n\n聯想畫面 2：交通標誌與數學符號在日常生活中指引方向與表達邏輯。\n\n高效擴充：源自希臘文字根 syn（共同）與 bol（丟在一起），合起來是把東西丟在一起對照產生的標記。\nKK 音標：[ˋsɪmbəl] -> 第一音節重音在 sím，短母音 i 發清脆短促音。\n\n常見同義字：\n\nsign（標誌、招牌，通常指具體路標或記號）\n\nemblem（徽章、象徵，常帶有國家或團體精神意涵）\n\nrepresentation（代表、表現，較正式抽象）",
  "symbolic": "諧音聯想：\n諧音：「新巴力克」－新開的巴力克餐廳門口擺了一座象徵發財的金牛，非常有象徵意義。\n\n聯想畫面 1：和平鴿和橄欖枝在國際社會上被公認為是和平的象徵物。\n\n聯想畫面 2：在婚禮上交換戒指不僅是個儀式，更代表著雙方永恆承諾的象徵。\n\n高效擴充：由 symbol（象徵/符號）加上形容詞字尾 -ic，指具有代表某種意義的特質。\nKK 音標：[sɪmˋbɑlɪk] -> 重音在第二音節 bɑ，發開口的 o 音，第一個音節 sim 輕讀。\n\n常見同義字：\n\nrepresentative（代表性的，強調能代表某一類群）\n\nmetaphorical（隱喻的，具詩意或比喻性質的）\n\nsignificant（具有重大意義的）",
  "symbolize": "諧音聯想：\n諧音：「新巴來者」\n\n聯想畫面 1：新巴（星巴克）來者穿著特殊制服，用咖啡杯象徵品牌的精神。\n\n聯想畫面 2：新巴來者舉起權杖，標誌著王權的確立與交接。\n\n高效擴充：由字根 symbol（符號）加上動詞字尾 ise 結合而成。\nKK 音標：[ˋsɪmbə͵laɪz] -> 主重音在第一個音節 sym，發短促的 i 音，唸起時要俐落。\n\n常見同義字：\n\nrepresent（表示或代表某事物，最常用於象徵意義）\n\nstand for（片語動詞，通常口語或日常對話中常用）\n\ncharacterize（表示……的特性，較偏向描繪特質）",
  "symmetry": "諧音聯想：\n諧音：[ˋsɪmətri]\n諧音：「細摸貼力，兩邊才對稱」\n\n聯想畫面 1：蝴蝶的翅膀花紋完美對稱，展現出大自然奇妙的幾何美感。\n\n聯想畫面 2：這棟建築物左右兩側完全對稱，看起來既莊嚴又平衡。\n\n高效擴充：sym-（共同）加上 metry（測量），兩邊測量起來一樣就是對稱。\nKK 音標：[ˋsɪmətri] -> 重音在第一音節ｼˋ，後面音節唸得輕快。\n\n常見同義字：\nbalance（平衡、均衡，不一定完全鏡像對稱）\nproportion（比例、勻稱，指各部分大小協調）\nuniformity（一致性、整齊劃一）",
  "sympathetic": "諧音聯想：\n諧音：「心破，踢客」人，但他依然很有同情心去安慰對方。\n\n聯想畫面 1：看到災民流離失所的畫面，她流下了同情的眼淚。\n\n聯想畫面 2：全公司同事都十分贊同並支援這項改革方案。\n\n高效擴充：由 sym (共同) 加 pathetic (悲傷的、受感動的) 組成，感同身受。\nKK 音標：[͵sɪmpəˋθɛtɪk] -> 第三音節 θɛt 為主重音，第一音節 sɪm 為次重音。\n\n常見同義字：\ncompassionate（具同情心的，強調發自內心的慈悲與憐憫）\nsupportive（支援的、支持的，強調給予他人實質的鼓勵與協助）\nunderstanding（體諒的、通情達理的，指能理解他人處境）",
  "sympathize": "拆解：sym（共同）＋ path（感情）＋ ize（動詞字尾）\n\n諧音：「辛帕賽」\n\n聯想畫面 1：大家一起拍拍受災戶的肩膀，心裡充滿同情與憐憫。\n\n聯想畫面 2：身為過來人，主管完全能體諒員工的辛苦，並給予支持。\n\n高效擴充：sym-（相同）加上 pathy（感情/悲傷），字面即「感同身受」。\nKK 音標：[ˋsɪmpə͵θaɪz] -> 主重音在第一個音節 sɪm，pa 輕念，thɑɪz 清子音咬舌。\n\n常見同義字：\npity（憐憫，帶有一點居高臨下的同情）\ncompassion（同情心，名詞居多）\nunderstand（理解，表達懂對方的處境）",
  "sympathy": "諧音聯想：\n諧音：「心陪戲」\n\n聯想畫面 1：朋友失戀了，我用心陪伴他演這齣悲傷的戲，給予滿滿的同情與安慰。\n\n聯想畫面 2：看到災難新聞，人們紛紛捐款表達無限的同情與哀悼。\n\n高效擴充：sym-（共同）加上 path（感情、痛苦），心意相通的同理心。\nKK 音標：[ˋsɪmpəθi] -> 重音在第一音節 sym，th 發咬舌清音。\n\n常見同義字：\ncompassion（具備慈悲心、想幫忙的同情）\npity（憐憫，有時帶有一點高高在上的意味）\ncondolences（專指喪禮上的弔唁、慰問）",
  "symphony": "諧音聯想：\n諧音：「辛風呢」\n\n聯想畫面 1：辛酸的風吹過來呢，樂團剛好在戶外演奏宏大的交響樂。\n\n聯想畫面 2：古典音樂廳裡正上演貝多芬的交響曲，旋律優美而和諧。\n\n高效擴充：sym-（共同）加上 phon（聲音），眾多樂器一起發出和諧的聲音。\nKK 音標：[ˋsɪmfəni] -> 重音在第一音節 sym，ph 發 [f] 的音。\n\n常見同義字：\norchestra（指交響樂團本身）\nharmony（和諧、融洽，可指音樂或人際）\nconcert（音樂會、演奏會總稱）",
  "symposium": "諧音聯想：\n諧音：森坡西恩。\n\n聯想畫面 1：在森坡西恩大學舉辦了一場盛大的座談會。\n\n聯想畫面 2：專家們在討論會上發表了各自的專題論文。\n\n高效擴充：sym（一起）+ pos（放置），意為聚在一起討論。\nKK 音標：[sɪmˋpoziəm] -> 重音在第二音節，po 發長母音 O。\n\n常見同義字：\n\nseminar（研討會）\n\ncolloquium（學術討論會）\n\ndiscussion（討論）。",
  "symptom": "諧音聯想：\n諧音：[ˋsɪmptəm]\n諧音：「誰普渡他？出現怪病症狀」\n\n聯想畫面 1：感冒初期出現了發燒、咳嗽和喉嚨痛等典型症狀。\n\n聯想畫面 2：經濟衰退往往伴隨著失業率上升的各種不良跡象與徵兆。\n\n高效擴充：sym-（共同）加上 ptom（落下），病痛一起降臨就是症狀與徵兆。\nKK 音標：[ˋsɪmptəm] -> 重音在第一音節ｼˋ，p 是不發音的閉口輔音技巧。\n\n常見同義字：\nsign（跡象、徵兆，可指客觀存在的現象）\nindication（表明、暗示，指某事的跡象）\nmanifestation（表現、顯現，將抽象概念具體化）",
  "synchronize": "諧音聯想：\n諧音：「信客拿來時手錶時間要同步」\n\n聯想畫面 1：跳傘隊員在空中跳傘前，必須把手錶時間完全對準同步。\n\n聯想畫面 2：剪輯影片時，必須把聲音和畫面完美同步化才不會對不上嘴形。\n\n高效擴充：syn- 表示共同，time 變來的字根代表時間，共同時間就是同步。\nKK 音標：[ˋsɪŋkrənaɪz] -> sy 發短音，重音在第一音節。\n\n常見同義字：\n\ncoincide（同時發生，指巧合或時間相符）\n\ncoordinate（協調，強調動作或步驟的一致性）\n\nmatch（相符，指事物相互吻合）",
  "synergy": "諧音聯想：\n諧音：「細泥擠在一起」\n\n聯想畫面 1：兩個部門的員工細心地把泥土擠在一起，發揮強大的團隊綜效。\n\n聯想畫面 2：企業併購後產生了極佳的協同效益，讓營收翻倍成長。\n\n高效擴充：字首 syn 代表共同，erg 代表工作能量。\nKK 音標：[ˋsɪnɚdʒɪ] -> ˋsɪn 重音，ɚdʒɪ 唸輕聲。\n\n常見同義字：\ncooperation（合作、協同）\ncollaboration（共同合作、協力）\nalliance（聯盟、聯合）",
  "synonym": "諧音聯想：\n諧音：[ˋsɪnə͵nɪm]\n諧音：「新阿姨，名字是同義字」\n\n聯想畫面 1：查字典時發現 happy 和 joyful 互為同義字，意思非常相近。\n\n聯想畫面 2：寫英文作文時，為了避免重複使用同一個詞，老師建議多找同義詞替換。\n\n高效擴充：syn-（共同）加上 onym（名字），名字意思相同就是同義字。\nKK 音標：[ˋsɪnə͵nɪm] -> 重音在第一音節ｼˋ，次重音在第三音節.\n\n常見同義字：\nequivalent（同等物、對等詞）\nalternative word（替代字眼）\nmatching term（對應詞彙）",
  "synopsize": "諧音聯想：\n諧音：「細拿拍塞」\n\n聯想畫面 1：導演要編劇細拿拍塞（synopsize）劇本梗概，把故事大綱寫出來再決定是否開拍。\n\n聯想畫面 2：老師指導學生如何為小說寫梗概與提要（synopsize），抓出核心故事線。\n\n高效擴充：由名詞 synopsis（大綱、梗概）加上動詞字尾 ise 轉變而來。\nKK 音標：[sɪˋnɑpsaɪz] -> 重音在第二音節 ɑp，結尾的 size 唸 zaɪz。\n\n常見同義字：\nsummarize（總結、概述，最常見）\noutlines（畫出大綱、概述）\nsynopsize（寫梗概、作提要，強調故事架構）",
  "synthesis": "諧音聯想：\n拆解：syn（一起）+ thesis（論點）。諧音：新塞瑟斯。\n\n聯想畫面 1：將多種觀點綜合起來，形成一個完整的 synthesis。\n\n聯想畫面 2：化學實驗中，將不同物質合成（synthesis）成新材料。\n\n高效擴充：syn- 是共同，thesis 是放置，放在一起就是綜合。\nKK 音標：[ˋsɪnθəsəs] -> 重音在第一個音節，發音要輕快。\n\n常見同義字：\n\ncombination 結合，integration 整合，fusion 融合。",
  "synthetic": "諧音聯想：\n諧音：[sɪnˋθɛtɪk]\n諧音：「新洗的鐵塊，是人造的」\n\n聯想畫面 1：這件外套採用合成纖維製成，不僅耐穿而且防水防風。\n\n聯想畫面 2：化學實驗室裡成功用人工方法合成了這種特殊的有機化合物。\n\n高效擴充：syn-（綜合）加上 thet（放置），綜合各種成分製造出來的就是人造合成物。\nKK 音標：[sɪnˋθɛtɪk] -> 主重音在第二音節ｾˋ，th 要咬舌發音。\n\n常見同義字：\nartificial（人工的、人造的，通常對應天然 natural）\nman-made（人造的、非天然產生的）\nfake（仿冒的、假的，帶有負面意味）",
  "syrup": "諧音聯想：\n諧音：「洗熱泡」\n\n聯想畫面 1：把感冒藥用熱水泡開，甜甜的藥用糖漿滑過喉嚨很舒服。\n\n聯想畫面 2：早餐的鬆餅淋上濃郁的楓糖漿，讓人看了食指大動。\n\n高效擴充：字尾 -rup 讀作 [rəp]，常出現在濃稠液體的字彙中。\nKK 音標：[ˋsɝəp] -> 重音在第一音節 sy，美式發音通常唸成 [ˋsɝəp]。\n\n常見同義字：\nsauce（泛指各種醬料、沾醬）\nhoney（天然的蜂蜜）\nmolasses（糖蜜、濃稠的蔗糖副產品）",
  "system": "諧音聯想：\n諧音：「細死疼」\n\n聯想畫面 1：公司電腦作業系統當機，細心檢查每一個步驟才不至於心疼。\n\n聯想畫面 2：學校有一套嚴格的管理制度與運作體制。\n\n高效擴充：字首 sys 代表共同，stem 代表樹幹，枝葉繁茂的大樹就是一個系統。\nKK 音標：[ˋsɪstəm] -> 第一音節 sɪ 帶主重音，唸「希斯」，字尾 təm 唸輕聲。\n\n常見同義字：\nmethod（方法、條理，做事的方式）\nscheme（方案、計畫，通常指組織或系統化的規劃）\nstructure（結構、構造，事物的組織架構）",
  "systematic": "諧音聯想：\n諧音：「細死疼媽踢客」\n\n聯想畫面 1：做事超有條理，連細節都不放過，踢客人的時候也是有系統地踢。\n\n聯想畫面 2：工程師規劃專案時，每個步驟都按步就班，非常有系統。\n\n高效擴充：字首 sys 代表共同，加上 stem 樹幹，像大樹的系統一樣枝葉分明。\nKK 音標：[͵sɪstəˋmætɪk] -> 主重音在 mæt 音節，唸起來要稍微用力拉長。\n\n常見同義字：\n\nmethodical（有方法的、有條理的，強調按部就班）\norganized（有組織的、井然有序的）\nstructured（結構化的、有架構的）",
  "systematically": "諧音聯想：\n拆解 / 諧音：system（系統）+ atically（自動化地）\n\n聯想畫面 1：工廠將生產線有系統地自動化，效率大幅提升。\n\n聯想畫面 2：他整理書桌時非常有條理，將書籍按類別系統地排列。\n\n高效擴充：由 system 演變而來，字尾 -ically 構成副詞，表示方式。\nKK 音標：[͵sɪstəˋmætɪkli] -> 重音在第三個音節 mæt，發音要清晰響亮。\n\n常見同義字：\nmethodically（有條不紊地，強調方法）\norderly（整齊地，強調順序）\norganized（有組織地，強調結構）"
});
